#include <pthread.h>
#include <curl/curl.h>
#include <json-c/json.h>
#include <stdlib.h>
#include <string.h>

#define API_URL "http://example.com/lte-phy-rach-config"
#define CACHE_SIZE 10

typedef struct {
    char *key;
    json_object *value;
} CacheEntry;

typedef struct {
    pthread_mutex_t mutex;
    CacheEntry cache[CACHE_SIZE];
    int head, tail, count;
} RACHConfigCache;

typedef struct {
    RACHConfigCache *cache;
    CURL *curl_handle;
} LTEPHYRACHManager;

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char *)userp)[size * nmemb] = '\0';
    return size * nmemb;
}

json_object* fetch_rach_config(LTEPHYRACHManager *manager) {
    CURLcode res;
    char buffer[1024];

    curl_easy_setopt(manager->curl_handle, CURLOPT_URL, API_URL);
    curl_easy_setopt(manager->curl_handle, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(manager->curl_handle, CURLOPT_WRITEDATA, buffer);

    res = curl_easy_perform(manager->curl_handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error fetching RACH config: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    json_object *json_obj = json_tokener_parse(buffer);
    if (!json_obj) {
        fprintf(stderr, "Malformed JSON response\n");
        return NULL;
    }

    return json_obj;
}

void* update_cache(void *arg) {
    LTEPHYRACHManager *manager = (LTEPHYRACHManager *)arg;

    while (1) {
        pthread_mutex_lock(&manager->cache->mutex);
        if (manager->cache->count < CACHE_SIZE) {
            json_object *config = fetch_rach_config(manager);
            if (config) {
                CacheEntry entry;
                entry.key = strdup("rach_config");
                entry.value = config;

                manager->cache->cache[manager->cache->tail++] = entry;
                manager->cache->count++;
                if (manager->cache->tail == CACHE_SIZE)
                    manager->cache->tail = 0;
            }
        }
        pthread_mutex_unlock(&manager->cache->mutex);

        sleep(60); // Poll every minute
    }

    return NULL;
}

LTEPHYRACHManager* init_ltephy_rach_manager() {
    LTEPHYRACHManager *manager = (LTEPHYRACHManager *)malloc(sizeof(LTEPHYRACHManager));
    manager->cache = (RACHConfigCache *)malloc(sizeof(RACHConfigCache));

    pthread_mutex_init(&manager->cache->mutex, NULL);
    manager->cache->head = 0;
    manager->cache->tail = 0;
    manager->cache->count = 0;

    manager->curl_handle = curl_easy_init();
    if (!manager->curl_handle) {
        fprintf(stderr, "Failed to initialize CURL\n");
        free(manager->cache);
        free(manager);
        return NULL;
    }

    pthread_t update_thread;
    pthread_create(&update_thread, NULL, update_cache, (void *)manager);

    return manager;
}

json_object* get_rach_config(LTEPHYRACHManager *manager) {
    json_object *config = NULL;

    pthread_mutex_lock(&manager->cache->mutex);
    if (manager->cache->count > 0) {
        config = manager->cache->cache[manager->cache->head].value;
        manager->cache->head++;
        if (manager->cache->head == CACHE_SIZE)
            manager->cache->head = 0;
        manager->cache->count--;
    }
    pthread_mutex_unlock(&manager->cache->mutex);

    return config;
}

void free_ltephy_rach_manager(LTEPHYRACHManager *manager) {
    curl_easy_cleanup(manager->curl_handle);
    free(manager->cache);
    free(manager);
}
```

