#include <time.h>

typedef struct {
    int value;
    time_t last_access;
    int key;
} record;

record* bulk_record_initializer(int num_records, int value_range_start, int value_range_end) {
    if (num_records <= 0 || value_range_start > value_range_end) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    long *offsets = malloc(num_records * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    int *keys = malloc(num_records * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        return NULL;
    }

    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % num_records; // Random offset
        keys[i] = rand() % (value_range_end - value_range_start + 1) + value_range_start; // Random key within specified range
        records[i].value = rand() % (value_range_end - value_range_start + 1) + value_range_start;
        records[i].last_access = time(NULL);
        records[i].key = keys[i];
    }

    return records;
}

