#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <libcurl/curl.h>

#define MAX_URLS 100
#define BUFFER_SIZE 4096

typedef struct {
    char *urls[MAX_URLS];
    int url_count;
    FILE *output_file;
    int byte_range_start;
    int byte_range_end;
} Config;

static int parse_options(int argc, char **argv, Config *config) {
    static struct option long_options[] = {
        {"manpage", no_argument, 0, 'm'},
        {"byte-range", required_argument, 0, 'b'},
        {"output-file", required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "mcs:o:b:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'm':
                printf("Usage: %s --manpage | -cs <source> | -o output_file\n", argv[0]);
                return 1;
            case 'c':
                // Add code to handle single source URL
                break;
            case 's':
                config->urls[config->url_count++] = optarg;
                if (config->url_count >= MAX_URLS) {
                    fprintf(stderr, "Error: Too many URLs\n");
                    return 1;
                }
                break;
            case 'o':
                config->output_file = fopen(optarg, "wb");
                if (!config->output_file) {
                    perror("Error opening output file");
                    return 1;
                }
                break;
            case 'b':
                if (sscanf(optarg, "%d-%d", &config->byte_range_start, &config->byte_range_end) != 2) {
                    fprintf(stderr, "Error: Invalid byte range\n");
                    return 1;
                }
                break;
            default:
                printf("Usage: %s --manpage | -cs <source> | -o output_file\n", argv[0]);
                return 1;
        }
    }

    if (config->url_count == 0) {
        fprintf(stderr, "Error: No URLs provided\n");
        return 1;
    }

    if (!config->output_file) {
        fprintf(stderr, "Error: Output file not specified\n");
        return 1;
    }

    return 0;
}

static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    fwrite(ptr, size, nmemb, (FILE *)userdata);
    return size * nmemb;
}

static CURLcode fetch_data(CURL *curl, const char *url, FILE *output_file) {
    CURLcode res;

    curl_easy_setopt(curl, CURLOPT_URL, url);
    if (config.byte_range_start != -1 && config.byte_range_end != -1) {
        char range[256];
        snprintf(range, sizeof(range), "%d-%d", config.byte_range_start, config.byte_range_end);
        curl_easy_setopt(curl, CURLOPT_RANGE, range);
    }
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, output_file);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error fetching data from %s: %s\n", url, curl_easy_strerror(res));
    }

    return res;
}

int main(int argc, char **argv) {
    Config config = {0};
    CURL *curl;

    if (parse_options(argc, argv, &config)) {
        return 1;
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error initializing libcurl\n");
        return 1;
    }

    for (int i = 0; i < config.url_count; i++) {
        fetch_data(curl, config.urls[i], config.output_file);
    }

    fclose(config.output_file);
    curl_easy_cleanup(curl);
    curl_global_cleanup();

    return 0;
}
