['```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <functional>
#include <memory>
#include <string>

class Connection {
public:
    virtual void executeQuery(const std::string& query) = 0;
    virtual ~Connection() = default;
};

class DatabaseConnection : public Connection {
public:
    void executeQuery(const std::string& query) override {
        // Simulate database query execution
        std::cout << "Executing query: " << query << std::endl;
    }
};

class ConnectionPoolManager {
private:
    std::queue<std::shared_ptr<Connection>> pool;
    std::mutex mutex;
    std::condition_variable cv;
    size_t max_size;
    bool stopped;

public:
    ConnectionPoolManager(size_t initialSize, size_t maxSize) : max_size(maxSize), stopped(false) {
        for (size_t i = 0; i < initialSize; ++i) {
            pool.push(std::make_shared<DatabaseConnection>());
        }
    }

    ~ConnectionPoolManager() {
        stop();
    }

    std::shared_ptr<Connection> getConnection() {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return !pool.empty() || stopped; });
        if (stopped) throw std::runtime_error("Connection pool is closed");
        auto conn = pool.front();
        pool.pop();
        return conn;
    }

    void returnConnection(std::shared_ptr<Connection> conn) {
        std::unique_lock<std::mutex> lock(mutex);
        if (pool.size() < max_size) {
            pool.push(conn);
            cv.notify_one();
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stopped = true;
        }
        cv.notify_all();
    }
};

void worker(ConnectionPoolManager& pool, const std::string& query) {
    auto conn = pool.getConnection();
    try {
        conn->executeQuery(query);
    } catch (...) {
        // Handle error and possibly retry
    } finally {
        pool.returnConnection(conn);
    }
}

int main() {
    ConnectionPoolManager pool(5, 10);

    std::vector<std::thread> workers;
    for (int i = 0; i < 20; ++i) {
        workers.emplace_back(worker, std::ref(pool), "SELECT * FROM table");
    }

    for (auto& worker : workers) {
        worker.join();
    }

    return 0;
}
```

