#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

#define INITIAL_ARRAY_SIZE 100
#define ARRAY_GROWTH_FACTOR 1.5

typedef struct {
    int* data;
    size_t capacity;
    size_t size;
} DynamicArray;

typedef struct {
    char url[256];
    int minRange;
    int maxRange;
    DynamicArray cache;
    CURL* curlHandle;
} APIConfig;

void initDynamicArray(DynamicArray* arr) {
    arr->data = (int*)malloc(INITIAL_ARRAY_SIZE * sizeof(int));
    arr->capacity = INITIAL_ARRAY_SIZE;
    arr->size = 0;
}

void freeDynamicArray(DynamicArray* arr) {
    free(arr->data);
}

void growDynamicArray(DynamicArray* arr) {
    size_t newSize = (size_t)(arr->capacity * ARRAY_GROWTH_FACTOR);
    int* newData = (int*)realloc(arr->data, newSize * sizeof(int));
    if (newData) {
        arr->data = newData;
        arr->capacity = newSize;
    }
}

bool isValidRange(APIConfig* config, int num) {
    return num >= config->minRange && num <= config->maxRange;
}

size_t writeCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    DynamicArray* arr = (DynamicArray*)userp;
    size_t totalSize = size * nmemb;
    if ((arr->size + 1) >= arr->capacity) {
        growDynamicArray(arr);
    }
    memcpy(&arr->data[arr->size], contents, totalSize);
    arr->size++;
    return totalSize;
}

void fetchIntegers(APIConfig* config) {
    CURLcode res = curl_easy_setopt(config->curlHandle, CURLOPT_URL, config->url);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to set URL: %s\n", curl_easy_strerror(res));
        return;
    }
    DynamicArray arr;
    initDynamicArray(&arr);
    CURLcode res2 = curl_easy_setopt(config->curlHandle, CURLOPT_WRITEFUNCTION, writeCallback);
    if (res2 != CURLE_OK) {
        fprintf(stderr, "Failed to set write callback: %s\n", curl_easy_strerror(res2));
        freeDynamicArray(&arr);
        return;
    }
    CURLcode res3 = curl_easy_setopt(config->curlHandle, CURLOPT_WRITEDATA, &arr);
    if (res3 != CURLE_OK) {
        fprintf(stderr, "Failed to set write data: %s\n", curl_easy_strerror(res3));
        freeDynamicArray(&arr);
        return;
    }
    CURLcode res4 = curl_easy_perform(config->curlHandle);
    if (res4 != CURLE_OK) {
        fprintf(stderr, "Error in fetching integers: %s\n", curl_easy_strerror(res4));
        freeDynamicArray(&arr);
        return;
    }
    for (size_t i = 0; i < arr.size; i++) {
        int num = arr.data[i];
        if (isValidRange(config, num)) {
            // Add to cache or process
        } else {
            printf("Invalid number %d\n", num);
        }
    }
    freeDynamicArray(&arr);
}

int main() {
    APIConfig config;
    strcpy(config.url, "http://example.com/api/integers");
    config.minRange = 10;
    config.maxRange = 100;
    config.cache.capacity = INITIAL_ARRAY_SIZE;
    config.cache.size = 0;
    config.cache.data = (int*)malloc(INITIAL_ARRAY_SIZE * sizeof(int));
    config.curlHandle = curl_easy_init();
    if (!config.curlHandle) {
        fprintf(stderr, "Failed to initialize CURL\n");
        return EXIT_FAILURE;
    }
    fetchIntegers(&config);
    free(config.cache.data);
    curl_easy_cleanup(config.curlHandle);
    return EXIT_SUCCESS;
}
