import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class DynamicLogger {
    private static final String LOCAL_LOG_PATH = "logs/application.log";
    private static final String REMOTE_LOG_URL = "https://remote-logger-service.com/log";
    private static boolean isRemoteLoggingEnabled = false;
    private static BlockingQueue<String> logBuffer = new LinkedBlockingQueue<>(1000);
    private static Thread bufferProcessorThread;

    public DynamicLogger() {
        bufferProcessorThread = new Thread(() -> processLogBuffer());
        bufferProcessorThread.start();
    }

    public void setRemoteLogging(boolean enable) {
        isRemoteLoggingEnabled = enable;
    }

    public void log(String level, String message) {
        try {
            StringBuilder logEntry = new StringBuilder();
            logEntry.append(LocalDateTime.now()).append(" [").append(level).append("] ").append(message);
            logBuffer.put(logEntry.toString());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void processLogBuffer() {
        while (true) {
            try {
                String logEntry = logBuffer.take();
                if (isRemoteLoggingEnabled) {
                    sendToRemoteLogger(logEntry);
                } else {
                    writeToFile(LOCAL_LOG_PATH, logEntry);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void writeToFile(String filePath, String logEntry) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(filePath, true))) {
            writer.write(logEntry);
            writer.newLine();
        } catch (IOException e) {
            handleWriteError(e);
        }
    }

    private void sendToRemoteLogger(String logEntry) {
        try {
            URL url = new URL(REMOTE_LOG_URL);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("POST");
            connection.setRequestProperty("Content-Type", "application/json");
            connection.setDoOutput(true);

            try (OutputStream os = connection.getOutputStream()) {
                byte[] input = logEntry.getBytes("utf-8");
                os.write(input, 0, input.length);
            }

            int responseCode = connection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                handleRemoteError(connection.getErrorStream());
            }
        } catch (IOException e) {
            handleSendToRemoteError(e);
        }
    }

    private void handleWriteError(IOException e) {
        // Implement error handling and recovery mechanism
    }

    private void handleRemoteError(InputStream errorStream) {
        // Implement error handling and recovery mechanism
    }

    private void handleSendToRemoteError(IOException e) {
        // Implement error handling and recovery mechanism
    }
}
