#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>

#define MAX_KEY_SIZE 32

typedef enum {
    ECB,
    EDE,
    EDE3,
    CFB
} CipherMode;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[MAX_KEY_SIZE];
    int key_length;
    CipherMode mode;
} CryptoLibrary;

CryptoLibrary* create_cipher_library(CipherMode mode, const unsigned char* key, int key_length) {
    CryptoLibrary *lib = (CryptoLibrary*)malloc(sizeof(CryptoLibrary));
    if (!lib) return NULL;

    lib->ctx = EVP_CIPHER_CTX_new();
    if (!lib->ctx) {
        free(lib);
        return NULL;
    }

    memcpy(lib->key, key, key_length);
    lib->key_length = key_length;
    lib->mode = mode;

    return lib;
}

void destroy_cipher_library(CryptoLibrary *lib) {
    EVP_CIPHER_CTX_free(lib->ctx);
    free(lib);
}

int encrypt_data(const CryptoLibrary* lib, const unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext, size_t* ciphertext_len) {
    if (!EVP_EncryptInit_ex(lib->ctx, NULL, NULL, lib->key, NULL)) return -1;
    if (!EVP_EncryptUpdate(lib->ctx, ciphertext, (int*)ciphertext_len, plaintext, plaintext_len)) return -2;
    if (!EVP_EncryptFinal_ex(lib->ctx, ciphertext + *ciphertext_len, (int*)&ciphertext_len)) return -3;

    return 0;
}

int decrypt_data(const CryptoLibrary* lib, const unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext, size_t* plaintext_len) {
    if (!EVP_DecryptInit_ex(lib->ctx, NULL, NULL, lib->key, NULL)) return -1;
    if (!EVP_DecryptUpdate(lib->ctx, plaintext, (int*)plaintext_len, ciphertext, ciphertext_len)) return -2;
    if (!EVP_DecryptFinal_ex(lib->ctx, plaintext + *plaintext_len, (int*)&plaintext_len)) return -3;

    return 0;
}

int main(int argc, char** argv) {
    // Example usage
    unsigned char key[MAX_KEY_SIZE];
    size_t key_length = sizeof(key);
    if (!RAND_bytes(key, key_length)) {
        fprintf(stderr, "Failed to generate random key\n");
        return 1;
    }

    CryptoLibrary* lib = create_cipher_library(ECB, key, key_length);
    if (!lib) {
        fprintf(stderr, "Failed to create cipher library\n");
        return 1;
    }

    unsigned char plaintext[] = "Hello, world!";
    size_t plaintext_len = strlen((char*)plaintext);
    unsigned char ciphertext[plaintext_len + EVP_CIPHER_BLOCK_SIZE];
    size_t ciphertext_len;

    if (encrypt_data(lib, plaintext, plaintext_len, ciphertext, &ciphertext_len) != 0) {
        fprintf(stderr, "Encryption failed\n");
        destroy_cipher_library(lib);
        return 1;
    }

    unsigned char decrypted_text[plaintext_len];
    size_t decrypted_text_len = plaintext_len;

    if (decrypt_data(lib, ciphertext, ciphertext_len, decrypted_text, &decrypted_text_len) != 0) {
        fprintf(stderr, "Decryption failed\n");
        destroy_cipher_library(lib);
        return 1;
    }

    printf("Original: %s\n", plaintext);
    printf("Decrypted: %s\n", decrypted_text);

    destroy_cipher_library(lib);
    return 0;
}
