['```go
package semaphore

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/go-redis/redis/v8"
)

type Semaphore struct {
	client *redis.Client
	key    string
	value  int
	mutex  sync.Mutex
}

func NewSemaphore(ctx context.Context, client *redis.Client, key string, initialValue int) (*Semaphore, error) {
	s := &Semaphore{
		client: client,
		key:    key,
		value:  initialValue,
	}

	if err := s.initialize(ctx); err != nil {
		return nil, fmt.Errorf("failed to initialize semaphore: %w", err)
	}

	return s, nil
}

func (s *Semaphore) InitializeWithRetry(ctx context.Context, retries int, delay time.Duration) error {
	for i := 0; i < retries; i++ {
		err := s.initialize(ctx)
		if err == nil {
			return nil
		}
		time.Sleep(delay)
	}
	return errors.New("failed to initialize semaphore after multiple retries")
}

func (s *Semaphore) initialize(ctx context.Context) error {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	val, err := s.client.Get(ctx, s.key).Result()
	if err != nil && err != redis.Nil {
		return fmt.Errorf("failed to get semaphore value: %w", err)
	}

	if val == "" {
		err = s.client.Set(ctx, s.key, s.value, 0).Err()
		if err != nil {
			return fmt.Errorf("failed to set initial semaphore value: %w", err)
		}
	} else {
		var intValue int
		intValue, err = strconv.Atoi(val)
		if err != nil {
			return fmt.Errorf("failed to convert semaphore value to integer: %w", err)
		}
		s.value = intValue
	}

	return nil
}

func (s *Semaphore) Acquire(ctx context.Context) error {
	for {
		err := s.client.Decr(ctx, s.key).Err()
		if err != nil && err != redis.Nil {
			return fmt.Errorf("failed to decrement semaphore value: %w", err)
		}
		val, err := s.client.Get(ctx, s.key).Result()
		if err != nil && err != redis.Nil {
			return fmt.Errorf("failed to get semaphore value after decrement: %w", err)
		}

		var intValue int
		intValue, err = strconv.Atoi(val)
		if err != nil {
			return fmt.Errorf("failed to convert semaphore value to integer after decrement: %w", err)
		}

		if intValue >= 0 {
			return nil
		}
		time.Sleep(10 * time.Millisecond) // Adjust sleep duration based on load and latency
	}
}

func (s *Semaphore) Release(ctx context.Context) error {
	err := s.client.Incr(ctx, s.key).Err()
	if err != nil && err != redis.Nil {
		return fmt.Errorf("failed to increment semaphore value: %w", err)
	}
	return nil
}

// Add more methods for managing the semaphore as needed (e.g., GetCount, Delete)

type SemaphoreManager struct {
	client *redis.Client
}

func NewSemaphoreManager(client *redis.Client) *SemaphoreManager {
	return &SemaphoreManager{client: client}
}

func (sm *SemaphoreManager) CreateSemaphore(ctx context.Context, key string, initialValue int) (*Semaphore, error) {
	semaphore, err := NewSemaphore(ctx, sm.client, key, initialValue)
	if err != nil {
		return nil, fmt.Errorf("failed to create semaphore: %w", err)
	}
	return semaphore, nil
}

func (sm *SemaphoreManager) DeleteSemaphore(ctx context.Context, key string) error {
	err := sm.client.Del(ctx, key).Err()
	if err != nil && err != redis.Nil {
		return fmt.Errorf("failed to delete semaphore: %w", err)
	}
	return nil
}

// Add more methods for managing semaphore operations as needed (e.g., GetSemaphoreStatus)

func main() {
	ctx := context.Background()
	client := redis.NewClient(&redis.Options{
		Addr: "localhost:6379",
	})
	semaphoreManager := NewSemaphoreManager(client)

	key := "my_semaphore"
	initialValue := 5

	semaphore, err := semaphoreManager.CreateSemaphore(ctx, key, initialValue)
	if err != nil {
		fmt.Println("Error creating semaphore:", err)
		return
	}

	err = semaphore.Acquire(ctx)
	if err != nil {
		fmt.Println("Error acquiring semaphore:", err)
		return
	}
	fmt.Println("Semaphore acquired")

	err = semaphore.Release(ctx)
	if err != nil {
		fmt.Println("Error releasing semaphore:", err)
		return
	}
	fmt.Println("Semaphore released")
}
```

This code snippet provides a basic implementation of a distributed semaphore system using Redis as the distributed key-value store. It includes methods for acquiring and releasing semaphores, initializing semaphores with retry logic, and managing semaphore operations through a manager. The main function demonstrates how to use the semaphore manager to create, acquire, and release a semaphore.']

