#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <random>

class AdvancedRandomGenerator {
public:
    AdvancedRandomGenerator(uint64_t seed) : generator(seed), distribution(0, 1) {}

    int32_t generateInt() {
        std::lock_guard<std::mutex> lock(mutex);
        return static_cast<int32_t>(distribution(generator));
    }

    float generateFloat() {
        std::lock_guard<std::mutex> lock(mutex);
        return static_cast<float>(distribution(generator)) / distribution.max();
    }

    bool generateBool() {
        std::lock_guard<std::mutex> lock(mutex);
        return distribution(generator) > 0.5;
    }

private:
    std::mt19937_64 generator;
    std::uniform_real_distribution<double> distribution;
    std::mutex mutex;
};

int main() {
    std::vector<AdvancedRandomGenerator> rngs;
    for (uint64_t i = 0; i < 10000; ++i) {
        rngs.emplace_back(i);
    }

    auto generateNumbers = [&](size_t start, size_t end) {
        for (size_t i = start; i < end; ++i) {
            std::cout << "Random int: " << rngs[i].generateInt() << ", "
                      << "Random float: " << rngs[i].generateFloat() << ", "
                      << "Random bool: " << (rngs[i].generateBool() ? "true" : "false") << std::endl;
        }
    };

    std::vector<std::thread> threads;
    size_t num_threads = std::thread::hardware_concurrency();
    size_t chunk_size = rngs.size() / num_threads;

    for (size_t i = 0; i < num_threads; ++i) {
        size_t start = i * chunk_size;
        size_t end = (i == num_threads - 1) ? rngs.size() : (i + 1) * chunk_size;
        threads.emplace_back(generateNumbers, start, end);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
