using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class DatabaseExecutor
{
    public async Task ExecuteParameterizedQueryAsync(string connectionString, string commandString, List<SqlParameter> parameters, Action<SqlDataReader> callback = null)
    {
        if (string.IsNullOrEmpty(connectionString))
        {
            throw new ArgumentException("Connection string cannot be null or empty.", nameof(connectionString));
        }

        if (string.IsNullOrEmpty(commandString))
        {
            throw new ArgumentException("Command string cannot be null or empty.", nameof(commandString));
        }

        if (parameters == null || parameters.Count == 0)
        {
            throw new ArgumentException("Parameters list cannot be null or empty.", nameof(parameters));
        }

        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            try
            {
                await connection.OpenAsync();
                using (SqlCommand command = new SqlCommand(commandString, connection))
                {
                    command.Parameters.AddRange(parameters.ToArray());
                    if (command.CommandType == CommandType.Text)
                    {
                        using (SqlDataReader reader = await command.ExecuteReaderAsync())
                        {
                            while (await reader.ReadAsync())
                            {
                                callback?.Invoke(reader);
                            }
                        }
                    }
                    else
                    {
                        int rowsAffected = await command.ExecuteNonQueryAsync();
                        Console.WriteLine($"{rowsAffected} rows affected.");
                    }
                }
            }
            catch (SqlException ex)
            {
                if (ex.Number == -2) // Timeout
                {
                    Console.WriteLine("Database query timed out.");
                }
                else if (ex.Number == 53) // Service Unavailable
                {
                    Console.WriteLine("Database service is unavailable.");
                }
                else
                {
                    Console.WriteLine($"SQL error: {ex.Message}");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"General error: {ex.Message}");
            }
        }
    }
}
