            var response = await _httpClient.GetAsync($"https://api.weatherapi.com/v1/current.json?key=YOUR_API_KEY&q={location}", cancellationToken);
            response.EnsureSuccessStatusCode();
            var weatherJson = await response.Content.ReadAsStringAsync();
            // Deserialize weatherJson to WeatherData and store in cache with sliding expiration
            var weather = DeserializeWeather(weatherJson);
            _cache.Set(cacheKey, weather, new MemoryCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(15)
            });
            return weather;
        }
        catch (HttpRequestException)
        {
            // Handle network issues or rate limits by returning cached data if available
            if (_cache.TryGetValue(cacheKey, out WeatherData fallbackWeather))
            {
                return fallbackWeather;
            }
            throw;
        }
