using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Xml.Linq;
using System.Threading.Tasks;

public class DynamicXMLParser
{
    private readonly ConcurrentDictionary<string, XNamespace> _namespaces = new ConcurrentDictionary<string, XNamespace>();
    private readonly ConcurrentDictionary<XDocument, CachedData> _cache = new ConcurrentDictionary<XDocument, CachedData>();
    private readonly ILogger _logger;
    private readonly IConfigurationManager _configManager;

    public DynamicXMLParser(ILogger logger, IConfigurationManager configManager)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _configManager = configManager ?? throw new ArgumentNullException(nameof(configManager));
    }

    public void AddNamespace(string prefix, string uri)
    {
        var ns = XNamespace.Get(uri);
        _namespaces.TryAdd(prefix, ns);
    }

    public XElement GetElement(XDocument document, string elementName, string namespacePrefix = null)
    {
        var ns = namespacePrefix != null ? _namespaces[namespacePrefix] : XNamespace.None;
        return document.Root.Element(ns + elementName);
    }

    public IEnumerable<XElement> QueryElements(XDocument document, string xpathExpression)
    {
        try
        {
            return document.Root.XPathSelectElements(xpathExpression);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error executing XPath query.");
            throw;
        }
    }

    public async Task ParseAsync(string xmlContent)
    {
        var document = XDocument.Parse(xmlContent);
        await CacheDataAsync(document);
    }

    private async Task CacheDataAsync(XDocument document)
    {
        if (!_cache.ContainsKey(document))
        {
            _cache.TryAdd(document, new CachedData { LastAccessed = DateTime.UtcNow });
        }
    }

    public void InvalidateCache()
    {
        _cache.Clear();
    }

    public class CachedData
    {
        public DateTime LastAccessed { get; set; }
        // Additional properties and methods for cache management
    }
}

public interface ILogger
{
    void LogError(Exception ex, string message);
    void LogWarning(string message);
}

public interface IConfigurationManager
{
    T GetConfiguration<T>(string key);
    bool ValidateConfiguration<T>(T config);
}
```

