import java.util.concurrent.*;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class StateLoaderService {
    private static final int MAX_RETRIES = 3;
    private static final long EXPIRY_TIME = 10 * 60 * 1000; // 10 minutes in milliseconds
    private static final long CACHE_EXPIRY_TIME = 5 * 60 * 1000; // 5 minutes in milliseconds
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final ConcurrentMap<String, Future<MoSTState>> fileLoadCache = new ConcurrentHashMap<>();
    private final ConcurrentMap<String, MoSTState> metadataCache = new ConcurrentHashMap<>();
    private final Lock lock = new ReentrantLock();

    public MoSTState loadStateFromFile(String filePath) {
        Future<MoSTState> future = fileLoadCache.get(filePath);
        if (future != null && !future.isDone()) {
            try {
                return future.get();
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
                return null;
            }
        }

        Callable<MoSTState> task = () -> loadStateFromFileInternal(filePath);
        Future<MoSTState> newFuture = executor.submit(task);
        fileLoadCache.putIfAbsent(filePath, newFuture);
        future = fileLoadCache.get(filePath);

        try {
            return future.get();
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
            return null;
        }
    }

    private MoSTState loadStateFromFileInternal(String filePath) {
        File file = new File(filePath);
        if (!file.exists() || !file.canRead()) {
            logError("File not found or not readable: " + filePath);
            return null;
        }

        for (int i = 0; i < MAX_RETRIES; i++) {
            try {
                MoSTState state = new ObjectMapper().readValue(file, MoSTState.class);
                fetchMetadata(state);
                fileLoadCache.remove(filePath);
                return state;
            } catch (IOException e) {
                if (i == MAX_RETRIES - 1) {
                    logError("Failed to load state from file after " + MAX_RETRIES + " attempts: " + filePath, e);
                } else {
                    logWarning("Attempt " + (i + 1) + " failed. Retrying in " + (1 << i) + " seconds.");
                    try {
                        Thread.sleep((1 << i) * 1000);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        return null;
                    }
                }
            }
        }

        return null;
    }

    private void fetchMetadata(MoSTState state) {
        String apiUrl = "https://api.example.com/metadata/" + state.getId();
        try {
            URL url = new URL(apiUrl);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                String metadata = readMetadataFromConnection(connection);
                lock.lock();
                try {
                    metadataCache.put(state.getId(), new MoSTStateWithMetadata(state, metadata));
                } finally {
                    lock.unlock();
                }
            } else {
                logWarning("Failed to fetch metadata for state " + state.getId() + ", received response code: " + responseCode);
                handleRateLimiting(connection.getResponseMessage());
            }
        } catch (IOException e) {
            logError("Failed to fetch metadata for state " + state.getId(), e);
            handleRateLimiting(e.getMessage());
        }
    }

    private String readMetadataFromConnection(HttpURLConnection connection) throws IOException {
        // Implement logic to read metadata from the connection
        return "metadata";
    }

    private void handleRateLimiting(String message) {
        if (message != null && message.contains("Too Many Requests")) {
            // Implement logic for handling rate limiting
        }
    }

    private void logError(String message, Throwable e) {
        // Implement error logging
    }

    private void logWarning(String message) {
        // Implement warning logging
    }

    public static class MoSTState {
        // Define the MoSTState class
    }

