const fs = require('fs').promises;
const path = require('path');
const Ajv = require('ajv');

class ConfigService {
  constructor(configDir, fallbackConfig, mergeStrategy) {
    this.configDir = configDir;
    this.fallbackConfig = fallbackConfig || {};
    this.mergeStrategy = mergeStrategy || 'deepMerge';
    this.configCache = {};
    this.ajv = new Ajv();
  }

  async loadAndMergeConfigs() {
    const files = await fs.readdir(this.configDir);
    const configs = await Promise.all(files.map(file => this.loadConfig(file)));
    return this.mergeConfigs(configs);
  }

  async loadConfig(filename) {
    try {
      const fileContent = await fs.readFile(path.join(this.configDir, filename), 'utf8');
      const config = JSON.parse(fileContent);
      const isValid = this.ajv.validate({ type: 'object' }, config);
      if (!isValid) throw new Error('Invalid configuration structure');
      return config;
    } catch (error) {
      console.error(`Error loading or validating ${filename}:`, error);
      return this.fallbackConfig;
    }
  }

  mergeConfigs(configs) {
    const mergedConfig = { ...this.fallbackConfig };
    configs.forEach(config => {
      if (this.mergeStrategy === 'deepMerge') {
        Object.assign(mergedConfig, config);
      } else if (this.mergeStrategy === 'lastWins') {
        for (const key in config) {
          mergedConfig[key] = config[key];
        }
      }
    });
    return mergedConfig;
  }

  async updateConfigProvider(configProviderUrl, credentials) {
    try {
      const response = await fetch(configProviderUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(credentials)
      });
      if (!response.ok) throw new Error('Failed to update configuration provider');
      return true;
    } catch (error) {
      console.error('Error updating configuration provider:', error);
      return false;
    }
  }

  async handleConcurrency() {
    const sem = require('semaphore')(10); // Limit concurrent requests
    const updatePromises = this.configCache.map(config => 
      sem.acquire().then(() => {
        return this.updateConfigProvider(config.providerUrl, config.credentials)
          .finally(sem.release);
      })
    );
    await Promise.all(updatePromises);
  }

  async main() {
    try {
      await this.loadAndMergeConfigs();
      await this.handleConcurrency();
      console.log('Configuration updated successfully');
    } catch (error) {
      console.error('Error updating configuration:', error);
    }
  }
}

const configService = new ConfigService('/path/to/configs', { default: 'value' }, 'deepMerge');
configService.main();
