function renderFooterScripts(scripts, config = {}) {
    const defaultConfig = {
        maxConcurrent: 50,
        retryAttempts: 3,
        timeout: 10000,
        debug: false
    };
    const mergedConfig = { ...defaultConfig, ...config };

    function loadScript(script) {
        return new Promise((resolve, reject) => {
            const scriptElement = document.createElement('script');
            scriptElement.src = script.url;
            scriptElement.async = true;
            scriptElement.defer = true;

            scriptElement.onload = () => resolve();
            scriptElement.onerror = (error) => reject(error);

            document.body.appendChild(scriptElement);
        });
    }

    function loadScriptsConcurrently(scripts, maxConcurrent) {
        const loadPromises = [];
        let currentLoadCount = 0;

        for (const script of scripts) {
            if (loadPromises.length < maxConcurrent) {
                loadPromises.push(loadScript(script));
                currentLoadCount++;
            }
        }

        return Promise.all(loadPromises).catch((error) => {
            if (mergedConfig.debug) console.error('Failed to load scripts:', error);
            throw error;
        });
    }

    async function retryLoadingScripts(scripts, attempts) {
        for (let attempt = 0; attempt < attempts; attempt++) {
            try {
                await loadScriptsConcurrently(scripts, mergedConfig.maxConcurrent);
                break;
            } catch (error) {
                if (attempt === attempts - 1) {
                    throw error;
                }
                if (mergedConfig.debug) console.log(`Retrying script loading... Attempt ${attempt + 2}`);
            }
        }
    }

    scripts.sort((a, b) => a.priority - b.priority);
    const promises = [];

    for (const script of scripts) {
        promises.push(retryLoadingScripts([script], mergedConfig.retryAttempts));
    }

    return Promise.all(promises).then(() => {
        return `
            <footer>
                <!-- Scripts will be loaded here dynamically -->
            </footer>
        `;
    }).catch((error) => {
        if (mergedConfig.debug) console.error('Failed to load all scripts:', error);
        return `
            <footer>
                <p>Error loading scripts. Please try again later.</p>
            </footer>
        `;
    });
}
