function refreshFormFields(fieldNames) {
  return new Promise((resolve, reject) => {
    const parentWindow = window.parent;

    // Asynchronously communicate with the parent window
    if (parentWindow && typeof parentWindow.updateFormField === 'function') {
      parentWindow.updateFormField(fieldNames)
        .then(updatedData => {
          // Filter and parse the updated data for Old Testament book references
          const bookReferences = parseBookReferences(updatedData, fieldNames);
          resolve(bookReferences);
        })
        .catch(error => {
          reject(error);
        });
    } else {
      reject(new Error('Parent window does not support required function'));
    }
  });
}

function parseBookReferences(data, fieldNames) {
  const bookRegex = /(?:\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy)\b)/gi;
  const bookCounts = {};

  Object.keys(data).forEach(fieldName => {
    if (fieldNames.includes(fieldName)) {
      const fieldValue = data[fieldName];
      const matches = fieldValue.match(bookRegex);
      if (matches) {
        matches.forEach(match => {
          match = match.toLowerCase();
          bookCounts[match] = (bookCounts[match] || 0) + 1;
        });
      }
    }
  });

  return bookCounts;
}

// Example usage:
refreshFormFields(['field1', 'field2'])
  .then(bookCounts => console.log(bookCounts))
  .catch(error => console.error(error));
```

