import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class UserInteractionService {

    private final UnionFind unionFind;
    private final ConcurrentHashMap<UserPair, Boolean> cache = new ConcurrentHashMap<>();
    private final AtomicInteger initializationTime;
    private final AtomicInteger processingTime;
    private final AtomicInteger cachingHits;
    private final AtomicInteger cachingMisses;

    public UserInteractionService() {
        this.unionFind = new UnionFind();
        this.initializationTime = new AtomicInteger(0);
        this.processingTime = new AtomicInteger(0);
        this.cachingHits = new AtomicInteger(0);
        this.cachingMisses = new AtomicInteger(0);

        long startTime = System.currentTimeMillis();
        // Initialize user interaction data from external database
        // Example: unionFind.loadDataFromDatabase();
        long endTime = System.currentTimeMillis();
        initializationTime.set(endTime - startTime);
    }

    public void processEvent(UserEvent event) {
        long startTime = System.currentTimeMillis();
        try {
            UserPair pair = new UserPair(event.getUser1(), event.getUser2());
            if (cache.containsKey(pair)) {
                Boolean result = cache.get(pair);
                cachingHits.incrementAndGet();
                if (!result) {
                    unionFind.union(pair.getUser1(), pair.getUser2());
                }
            } else {
                boolean isNewDisjointPair = unionFind.find(pair.getUser1()) != unionFind.find(pair.getUser2());
                cachingMisses.incrementAndGet();
                cache.put(pair, isNewDisjointPair);
                if (isNewDisjointPair) {
                    unionFind.union(pair.getUser1(), pair.getUser2());
                }
            }
        } catch (Exception e) {
            // Log error message
            System.err.println("Error processing event: " + e.getMessage());
        }
        long endTime = System.currentTimeMillis();
        processingTime.addAndGet(endTime - startTime);
    }

    public void reportMetrics() {
        System.out.println("Initialization Time: " + initializationTime.get() + " ms");
        System.out.println("Processing Time: " + processingTime.get() + " ms");
        System.out.println("Caching Hits: " + cachingHits.get());
        System.out.println("Caching Misses: " + cachingMisses.get());
    }
}

