use hyper::{Client, Uri};
use hyper_tls::HttpsConnector;
use tokio::sync::Mutex;
use std::time::Duration;
use std::env;

type HttpClient = Client<HttpsConnector, hyper::Body>;

async fn create_http_client() -> HttpClient {
    let connector = HttpsConnector::new();
    Client::builder()
        .redirect(hyper::client::Redirect::limited(10))
        .build(connector)
}

async fn send_request(client: Mutex<HttpClient>, url: &str, headers: hyper::header::HeaderMap) -> Result<String, Box<dyn std::error::Error>> {
    let mut client = client.lock().await;
    let uri = url.parse::<Uri>()?;
    let request = hyper::Request::builder()
        .method("GET")
        .uri(uri)
        .headers(headers)
        .body(hyper::Body::empty())?;

    let start_time = std::time::Instant::now();
    let response = client.request(request).await?;
    let latency = start_time.elapsed();

    if response.status().is_success() {
        let body = hyper::body::to_bytes(response.into_body()).await?;
        Ok(String::from_utf8(body.to_vec())?)
    } else {
        Err(format!("Request failed with status: {}", response.status()).into())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let client = Mutex::new(create_http_client().await);
    let url = env::var("API_URL")?;
    let api_key = env::var("API_KEY")?;
    let headers = hyper::header::HeaderMap::from_iter(vec![
        (hyper::header::AUTHORIZATION, format!("Bearer {}", api_key).parse()?),
    ]);

    tokio::runtime::Runtime::new().unwrap().block_on(async move {
        match send_request(client, &url, headers).await {
            Ok(body) => println!("Response: {}", body),
            Err(e) => eprintln!("Error: {}", e),
        }
    });

    Ok(())
}
