        let mut sys = System::new_all();

        // Capture resident set size before building
        let initial_memory_usage = sys.process(std::process::id()).unwrap().memory();

        Command::new("cargo")
            .arg("build")
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .output()
            .map_err(|_| Error::BuildFailed)?;

        // Capture resident set size after building
        sys.refresh_all();
        let final_memory_usage = sys.process(std::process::id()).unwrap().memory();

        let compilation_time = start_time.elapsed().as_secs_f64();
        println!("Compilation time: {:.2}s", compilation_time);
        println!("Memory usage increased by {} bytes", final_memory_usage - initial_memory_usage);

        Ok(0)
    }
}

fn main() {
    match build_manager::build_project() {
        Ok(result) => std::process::exit(result),
        Err(e) => {
            eprintln!("Build failed: {:?}", e);
            std::process::exit(1);
        }
    }
}
