<?php

use Redis;
use Exception;

class SecureSessionManager {
    private $redis;
    private $encryptionKey;
    private $sessionTimeout = 86400; // 24 hours in seconds
    private $softExpiryTime = 3600; // 1 hour in seconds

    public function __construct($redisHost, $redisPort, $encryptionKey) {
        $this->redis = new Redis();
        if (!$this->redis->connect($redisHost, $redisPort)) {
            throw new Exception("Failed to connect to Redis server");
        }
        $this->encryptionKey = $encryptionKey;
    }

    public function generateSessionToken($userId) {
        return bin2hex(random_bytes(32));
    }

    public function storeSessionData($sessionToken, $data) {
        $encryptedData = openssl_encrypt(json_encode($data), 'AES-256-CBC', $this->encryptionKey);
        if ($encryptedData === false) {
            throw new Exception("Failed to encrypt session data");
        }
        $this->redis->setex($sessionToken, $this->sessionTimeout, $encryptedData);
    }

    public function retrieveSessionData($sessionToken) {
        $data = $this->redis->get($sessionToken);
        if ($data === false) {
            return null;
        }
        $decryptedData = openssl_decrypt($data, 'AES-256-CBC', $this->encryptionKey);
        if ($decryptedData === false) {
            throw new Exception("Failed to decrypt session data");
        }
        return json_decode($decryptedData, true);
    }

    public function regenerateSessionToken($sessionToken, $newToken = null) {
        $data = $this->retrieveSessionData($sessionToken);
        if ($data === null) {
            throw new Exception("Session token not found");
        }
        if ($newToken === null) {
            $newToken = $this->generateSessionToken($data['userId']);
        }
        $this->storeSessionData($newToken, $data);
        return $newToken;
    }

    public function invalidateSession($sessionToken) {
        $this->redis->del($sessionToken);
    }

    public function handleErrors() {
        // Implement error handling and logging logic here
        // Example: Log errors to a file or use an external logging service
    }
}

// Usage example:
try {
    $sessionManager = new SecureSessionManager('localhost', 6379, 'your_encryption_key_here');
    $userId = 123;
    $sessionToken = $sessionManager->generateSessionToken($userId);
    $sessionData = ['userId' => $userId, 'lastActivity' => time()];
    $sessionManager->storeSessionData($sessionToken, $sessionData);

    // Simulate session renewal
    $newSessionToken = $sessionManager->regenerateSessionToken($sessionToken);

    // Retrieve and use session data
    $data = $sessionManager->retrieveSessionData($newSessionToken);
    echo "User ID: " . $data['userId'] . "\n";

    // Invalidate session upon logout
    $sessionManager->invalidateSession($newSessionToken);
} catch (Exception $e) {
    echo "Error: " . $e->getMessage() . "\n";
}
