#[derive(Debug)]
enum OAuthCertGenError {
    Io(std::io::Error),
    ParseFailed,
}

impl From<std::io::Error> for OAuthCertGenError {
    fn from(err: std::io::Error) -> Self {
        OAuthCertGenError::Io(err)
    }
