async fn generate_certificate_and_ir(oauth_request: &str) -> Result<String, Box<dyn Error>> {
    let file_paths = parse_oauth_request(oauth_request)?;
    info!("File paths parsed successfully: {:?}", file_paths);

    if let Some(cached_cert) = check_cache(&file_paths)? {
        debug!("Certificate found in cache. Returning cached version.");
        return Ok(cached_cert);
    }

    let cert_content = read_to_string(file_paths.cert_path).await?;
    let key_content = read_to_string(file_paths.key_path).await?;

    info!("Certificate and private key read successfully.");

    let combined_pem = format!("{}{}", cert_content, key_content);
    let mut cache = CERT_CACHE.lock().await;
    cache.push((file_paths.cert_path.clone(), combined_pem.clone()));

    Ok(combined_pem)
}

