import json
import threading
from abc import ABC, abstractmethod

class LogParser(ABC):
    @abstractmethod
    def parse(self, log_entry: str) -> int:
        pass

class SimpleLogParser(LogParser):
    def parse(self, log_entry: str) -> int:
        return int(log_entry.split()[-1])

class FileSequenceManager:
    _instance = None
    _lock = threading.Lock()

    @staticmethod
    def get_instance():
        with FileSequenceManager._lock:
            if FileSequenceManager._instance is None:
                FileSequenceManager._instance = FileSequenceManager()
            return FileSequenceManager._instance

    def __init__(self):
        self.sequence = []
        self.parser = SimpleLogParser()
        self.lock = threading.Lock()

    def update_parser(self, new_parser: LogParser):
        with self.lock:
            self.parser = new_parser

    def add_log_entry(self, log_entry: str):
        try:
            with self.lock:
                sequence_number = self.parser.parse(log_entry)
                self.sequence.append(sequence_number)
                self.sequence.sort(reverse=True)  # Sort in descending order
        except Exception as e:
            print(f"Error parsing log entry: {e}")

    def get_latest_sequence(self) -> int:
        with self.lock:
            if not self.sequence:
                return None
            return self.sequence[0]

    def serialize_state(self) -> str:
        state = {
            'sequence': self.sequence,
            'parser_type': type(self.parser).__name__
        }
        return json.dumps(state)

    @classmethod
    def deserialize_state(cls, state_json: str):
        state = json.loads(state_json)
        manager = cls.get_instance()
        manager.sequence = state['sequence']
        manager.update_parser(globals()[state['parser_type']]())
        return manager

# Example usage:
manager = FileSequenceManager.get_instance()
manager.add_log_entry("Timestamped entry 12345")
print(manager.get_latest_sequence())  # Output: 12345
