// Define custom error codes
#define ERR_NO_MEMORY 1
#define ERR_INVALID_INPUT 2
#define ERR_DB_FAILURE 3

// Define a state structure for the FSA
typedef struct {
    int id;
    // Add other state properties here
} State;

// Define a state list structure
typedef struct {
    State* states;
    int count;
    int capacity;
    pthread_mutex_t lock;
} StateList;

// Function to create a new state list
StateList* create_state_list(int initial_capacity) {
    if (initial_capacity <= 0) {
        errno = ERR_INVALID_INPUT;
        return NULL;
    }

    StateList* list = (StateList*)malloc(sizeof(StateList));
    if (!list) {
        errno = ERR_NO_MEMORY;
        return NULL;
    }

    list->states = (State*)malloc(initial_capacity * sizeof(State));
    if (!list->states) {
        free(list);
        errno = ERR_NO_MEMORY;
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to add a state to the state list
int add_state_to_list(StateList* list, State new_state) {
    if (!list || !new_state.id) {
        errno = ERR_INVALID_INPUT;
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    // Resize list if necessary
    if (list->count == list->capacity) {
        int new_capacity = list->capacity * 2;
        State* new_states = (State*)realloc(list->states, new_capacity * sizeof(State));
        if (!new_states) {
            pthread_mutex_unlock(&list->lock);
            errno = ERR_NO_MEMORY;
            return -1;
        }
        list->states = new_states;
        list->capacity = new_capacity;
    }

    list->states[list->count++] = new_state;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to save the state list to a database
int save_state_list_to_db(StateList* list) {
    // Implement database saving logic here
    // Return 0 on success, or an error code on failure
    // Example: if (db_save(list)) { return ERR_DB_FAILURE; }
    return 0;
}

// Wrapper function for simplified usage
int manage_state_list(StateList** list_ptr, State new_state) {
    int result;

    pthread_mutex_lock(&list_ptr->lock);

    if (!*list_ptr) {
        *list_ptr = create_state_list(1);
        if (!*list_ptr) {
            result = ERR_NO_MEMORY;
            goto cleanup;
        }
    }

    if ((result = add_state_to_list(*list_ptr, new_state)) != 0) {
        goto cleanup;
    }

    if ((result = save_state_list_to_db(*list_ptr)) != 0) {
        goto cleanup;
    }

cleanup:
    pthread_mutex_unlock(&list_ptr->lock);
    return result;
}

// Example usage in another module
int main() {
    StateList* state_list = NULL;

    State new_state = { .id = 1, /* other properties */ };

    int result = manage_state_list(&state_list, new_state);
    if (result != 0) {
        switch (result) {
            case ERR_NO_MEMORY:
                printf("Error: Insufficient memory.\n");
                break;
            case ERR_INVALID_INPUT:
                printf("Error: Invalid input.\n");
                break;
            case ERR_DB_FAILURE:
                printf("Error: Database failure.\n");
                break;
            default:
                printf("Error: Unknown error.\n");
        }
    }

    // Clean up resources
    if (state_list) {
        free(state_list->states);
        pthread_mutex_destroy(&state_list->lock);
        free(state_list);
    }

    return 0;
}
