public enum DistributionType { Uniform, Normal, Exponential }

public class DataSimulator
{
    private Dictionary<Type, object> distributionParams = new Dictionary<Type, object>();

    public void SetDistribution<T>(T min, T max, DistributionType type)
        where T : struct
    {
        distributionParams[typeof(T)] = (min, max, type);
    }

    public IEnumerable<T> GenerateData<T>(int count, int seed = 0) where T : struct
    {
        Random random = new Random(seed);
        var paramTuple = (dynamic)distributionParams[typeof(T)];
        for (int i = 0; i < count; i++)
        {
            yield return GenerateValue(paramTuple.min, paramTuple.max, paramTuple.type, random);
        }
    }

    private T GenerateValue<T>(T min, T max, DistributionType type, Random random) where T : struct
    {
        switch (type)
        {
            case DistributionType.Uniform:
                // Implement uniform distribution logic here
                break;
            case DistributionType.Normal:
