int load_config(const char* filename, struct config* config) {
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        perror("Failed to open configuration file");
        return 0;
    }

    json_object* root = json_tokener_parse_file(filename);
    if (!root) {
        fprintf(stderr, "Failed to parse JSON file\n");
        fclose(fp);
        return 0;
    }

    json_object* log_level_obj = NULL;
    if (json_object_object_get_ex(root, "log_level", &log_level_obj)) {
        config->log_level = json_object_get_int(log_level_obj);
    } else {
        fprintf(stderr, "Log level not specified in configuration\n");
        json_object_put(root);
        fclose(fp);
        return 0;
    }

    json_object* api_endpoint_obj = NULL;
    if (json_object_object_get_ex(root, "api_endpoint", &api_endpoint_obj)) {
        config->api_endpoint = strdup(json_object_get_string(api_endpoint_obj));
    } else {
        fprintf(stderr, "API endpoint not specified in configuration\n");
        json_object_put(root);
        fclose(fp);
        return 0;
    }

    // Load other parameters from the JSON file
    // ...

    json_object_put(root);
    fclose(fp);
    return 1;
}

double calculate_average(double* values, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }
    return sum / count;
}
