#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <dirent.h>

#define MAX_FILENAME_LENGTH 256

int generate_filename(const char *input_filename, const char *extension, char **output_filename) {
    if (strlen(input_filename) + strlen(extension) > MAX_FILENAME_LENGTH - 10) {
        return -1; // Filename too long
    }

    char directory[MAX_FILENAME_LENGTH];
    strncpy(directory, input_filename, MAX_FILENAME_LENGTH);
    directory[strlen(directory)] = '\0';

    char *base_name = strrchr(directory, '/');
    if (base_name == NULL) {
        base_name = directory;
    } else {
        base_name++;
    }

    time_t current_time = time(NULL);
    struct tm *local_time = localtime(&current_time);

    char version_str[20];
    strftime(version_str, sizeof(version_str), "%Y%m%d%H%M%S", local_time);

    int version = 1;
    while (1) {
        snprintf(*output_filename, MAX_FILENAME_LENGTH, "%s_%d.%s", base_name, version, extension);
        DIR *dir = opendir(".");
        if (dir == NULL) {
            return -2; // Could not open directory
        }
        struct dirent *entry;
        int file_exists = 0;
        while ((entry = readdir(dir)) != NULL) {
            if (strcmp(entry->d_name, *output_filename) == 0) {
                file_exists = 1;
                break;
            }
        }
        closedir(dir);
        if (!file_exists) {
            return 0; // Filename generated successfully
        }
        version++;
    }
}

int main() {
    const char *input_filename = "example";
    const char *extension = "txt";
    char output_filename[MAX_FILENAME_LENGTH];

    int result = generate_filename(input_filename, extension, &output_filename);
    if (result == 0) {
        printf("Generated filename: %s\n", output_filename);
    } else {
        printf("Failed to generate filename with error code: %d\n", result);
    }

    return 0;
}
```

