void aes_set_key_iv(AESContext *ctx, const unsigned char *key, const unsigned char *iv) {
    EVP_CIPHER_CTX_init(ctx->encrypt_ctx);
    EVP_EncryptInit_ex(ctx->encrypt_ctx, EVP_aes_256_cbc(), NULL, key, iv);

    EVP_CIPHER_CTX_init(ctx->decrypt_ctx);
    EVP_DecryptInit_ex(ctx->decrypt_ctx, EVP_aes_256_cbc(), NULL, key, iv);
}

int aes_encrypt(AESContext *ctx, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len;
    if (EVP_EncryptUpdate(ctx->encrypt_ctx, ciphertext, &len, plaintext, plaintext_len) != 1 ||
        EVP_EncryptFinal_ex(ctx->encrypt_ctx, ciphertext + len, &len) != 1) {
        return -1; // Error
    }
    return len;
}

int aes_decrypt(AESContext *ctx, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    int len;
    if (EVP_DecryptUpdate(ctx->decrypt_ctx, plaintext, &len, ciphertext, ciphertext_len) != 1 ||
        EVP_DecryptFinal_ex(ctx->decrypt_ctx, plaintext + len, &len) != 1) {
        return -1; // Error
    }
    return len;
}

void aes_free_context(AESContext *ctx) {
    if (ctx->encrypt_ctx) EVP_CIPHER_CTX_free(ctx->encrypt_ctx);
    if (ctx->decrypt_ctx) EVP_CIPHER_CTX_free(ctx->decrypt_ctx);
    free(ctx);
