#define MAX_COMMANDS 100
#define MAX_CMD_LENGTH 256

typedef enum {
    COMMAND_SUCCESS,
    COMMAND_TIMEOUT,
    COMMAND_ERROR
} CommandStatus;

typedef struct {
    char cmd[MAX_CMD_LENGTH];
    int timeout;
    CommandStatus status;
} Command;

void execute_command(Command *cmd) {
    pid_t pid = fork();
    if (pid == -1) {
        cmd->status = COMMAND_ERROR;
        perror("Fork failed");
        return;
    } else if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", cmd->cmd, NULL);
        perror("Exec failed");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        time_t start_time = time(NULL);

        while (waitpid(pid, &status, WNOHANG) == 0 && (time(NULL) - start_time < cmd->timeout)) {
            sleep(1); // Poll every second
        }

        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            cmd->status = COMMAND_SUCCESS;
        } else if (time(NULL) - start_time >= cmd->timeout) {
            cmd->status = COMMAND_TIMEOUT;
        } else {
            cmd->status = COMMAND_ERROR;
            kill(pid, SIGKILL);
        }
    }
}

int run_command_set(Command commands[], int num_commands) {
    for (int i = 0; i < num_commands; i++) {
        execute_command(&commands[i]);
        if (commands[i].status != COMMAND_SUCCESS) {
            return (commands[i].status == COMMAND_TIMEOUT) ? 0 : -2;
        }
    }
    return 1;
}

int main() {
    Command commands[MAX_COMMANDS] = {
        {"echo 'Hello, World!'", 5},
        {"sleep 3", 2},
        {"ls /nonexistent_directory", 5}
    };

    int num_commands = sizeof(commands) / sizeof(commands[0]);
    return run_command_set(commands, num_commands);
}
