public class FileDeletionMicroservice {

    private ExecutorService executorService = Executors.newFixedThreadPool(100);
    private AtomicInteger activeRequests = new AtomicInteger();
    private CircuitBreaker circuitBreaker = new CircuitBreaker();

    public void deleteFile(String filePath) {
        if (circuitBreaker.isOpen()) {
            handleCircuitBreakerOpen(filePath);
        } else {
            executeDeletion(filePath);
        }
    }

    private void executeDeletion(String filePath) {
        executorService.submit(() -> {
            try {
                circuitBreaker.incrementActiveRequests();
                activeRequests.incrementAndGet();
                if (activeRequests.get() > 50000) {
                    handleHighLoadCondition(filePath);
                } else {
                    performFileDeletion(filePath);
                }
            } catch (Exception e) {
                circuitBreaker.recordFailure();
                logger.log(Level.SEVERE, "Error deleting file: " + filePath, e);
            } finally {
                circuitBreaker.decrementActiveRequests();
                activeRequests.decrementAndGet();
