using System;
using System.Data;
using System.Data.Common;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using NServiceBus;

public class DataProcessingService : IHandleMessages<DataRequest>
{
    private readonly IMemoryCache _cache;
    private readonly IDbConnection _databaseConnection;

    public DataProcessingService(IMemoryCache cache, IDbConnection databaseConnection)
    {
        _cache = cache;
        _databaseConnection = databaseConnection;
    }

    public async Task Handle(DataRequest message, IMessageHandlerContext context)
    {
        try
        {
            var cachedData = await GetCachedData(message.QueryKey);
            if (cachedData != null)
            {
                await SendResponse(cachedData, context);
                return;
            }

            var processedData = await ProcessDataAsync(message.Query);
            await CacheData(processedData, message.QueryKey);
            await SendResponse(processedData, context);
        }
        catch (Exception ex)
        {
            // Log exception and retry logic here
            Console.WriteLine($"Error processing data: {ex.Message}");
        }
    }

    private async Task<DataTable> GetCachedData(string queryKey)
    {
        if (_cache.TryGetValue(queryKey, out var cachedData))
        {
            return (DataTable)cachedData;
        }
        return null;
    }

    private async Task CacheData(DataTable data, string queryKey)
    {
        _cache.Set(queryKey, data, new MemoryCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
        });
    }

    private async Task<DataTable> ProcessDataAsync(string query)
    {
        await _databaseConnection.OpenAsync();
        using (var command = _databaseConnection.CreateCommand())
        {
            command.CommandText = query;
            using (var reader = await command.ExecuteReaderAsync(CommandBehavior.Default))
            {
                return ConvertReaderToDataTable(reader);
            }
        }
    }

    private async Task SendResponse(DataTable data, IMessageHandlerContext context)
    {
        var response = new DataResponse { DataTable = data };
        await context.Reply(response);
    }

    private static DataTable ConvertReaderToDataTable(DbDataReader reader)
    {
        var dataTable = new DataTable();
        for (int i = 0; i < reader.FieldCount; i++)
        {
            dataTable.Columns.Add(reader.GetName(i), reader.GetFieldType(i));
        }
        while (await reader.ReadAsync())
        {
            var row = dataTable.NewRow();
            for (int i = 0; i < reader.FieldCount; i++)
            {
                row[i] = reader.GetValue(i);
            }
            dataTable.Rows.Add(row);
        }
        return dataTable;
    }
}
