using System.Threading.Tasks;

class DecryptionService : IHostedService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentQueue<int> _integersQueue = new();
    private CancellationTokenSource _cancellationTokenSource;
    private Task _backgroundTask;

    public IConfiguration Configuration { get; }

    public DecryptionService(IConfiguration configuration)
    {
        Configuration = configuration;
        _httpClient = new HttpClient();
    }

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        _cancellationTokenSource = new CancellationTokenSource(cancellationToken);
        _backgroundTask = Task.Run(async () => await ProcessMessagesAsync(), _cancellationTokenSource.Token);
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        _cancellationTokenSource.Cancel();
        await _backgroundTask;
    }

    private async Task ProcessMessagesAsync()
    {
        try
        {
            var concurrencyLevel = int.Parse(Configuration["ConcurrencyLevel"]);
            var tasks = new List<Task>();

            while (!_cancellationTokenSource.IsCancellationRequested)
            {
                if (_integersQueue.TryDequeue(out var integer))
                {
                    tasks.Add(DecryptMessageAsync(integer));
                }

                if (tasks.Count >= concurrencyLevel || _integersQueue.Count == 0)
                {
                    await Task.WhenAll(tasks);
                    tasks.Clear();
                }
            }

            await Task.WhenAll(tasks); // Ensure all tasks are completed before stopping
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing messages: {ex}");
        }
    }

    private async Task DecryptMessageAsync(int integer)
    {
        try
        {
            var response = await _httpClient.GetAsync("https://api.example.com/decrypt?integer=" + integer);
            if (!response.IsSuccessStatusCode)
            {
                throw new InvalidOperationException("Failed to decrypt message");
            }

            var encryptedData = await response.Content.ReadAsStringAsync();
            var decryptedMessage = Decrypt(encryptedData);

            Console.WriteLine($"Decrypted Message: {decryptedMessage}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error decrypting message for integer {integer}: {ex}");
        }
    }

    private string Decrypt(string encryptedData)
    {
        // Implement decryption logic here
        return "Decrypted Message";
    }

    public void AddInteger(int integer)
    {
        _integersQueue.Enqueue(integer);
    }
}

class Program
