using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class HashingLibrary
{
    private readonly ConcurrentDictionary<string, string> _hashCache = new ConcurrentDictionary<string, string>();
    private readonly HttpClient _httpClient;
    private const int MaxConcurrentRequests = 10;

    public HashingLibrary()
    {
        _httpClient = new HttpClient();
    }

    public string GetHash(string data, HashAlgorithmName algorithm)
    {
        return algorithm switch
        {
            HashAlgorithmName.MD5 => ComputeMD5(data),
            HashAlgorithmName.SHA256 => ComputeSHA256(data),
            _ => throw new ArgumentException("Unsupported hash algorithm")
        };
    }

    public async Task<bool> ValidateHashAsync(string data, string hash, HashAlgorithmName algorithm)
    {
        var computedHash = GetHash(data, algorithm);
        return await VerifyAsync(hash, computedHash);
    }

    public async IAsyncEnumerable<string> BulkGenerateHashesAsync(IEnumerable<string> dataList, HashAlgorithmName algorithm)
    {
        using (var semaphore = new SemaphoreSlim(MaxConcurrentRequests))
        {
            foreach (var data in dataList)
            {
                await semaphore.WaitAsync();
                try
                {
                    yield return GetHash(data, algorithm);
                }
                finally
                {
                    semaphore.Release();
                }
            }
        }
    }

    public async Task<bool> ExternalAuthValidationAsync(string username, string password)
    {
        var url = "https://example.com/api/authenticate";
        var content = new StringContent($"username={username}&password={password}", System.Text.Encoding.UTF8, "application/x-www-form-urlencoded");
        try
        {
            var response = await _httpClient.PostAsync(url, content);
            if (response.IsSuccessStatusCode)
            {
                return true;
            }
        }
        catch (HttpRequestException ex)
        {
            LogError(ex);
        }
        return false;
    }

    private string ComputeMD5(string input)
    {
        using (var md5 = MD5.Create())
        {
            var inputBytes = System.Text.Encoding.UTF8.GetBytes(input);
            var hashBytes = md5.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    private string ComputeSHA256(string input)
    {
        using (var sha256 = SHA256.Create())
        {
            var inputBytes = System.Text.Encoding.UTF8.GetBytes(input);
            var hashBytes = sha256.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    private async Task<bool> VerifyAsync(string storedHash, string computedHash)
    {
        if (string.IsNullOrEmpty(storedHash) || string.IsNullOrEmpty(computedHash))
        {
            return false;
        }

        var isMatch = await _hashCache.GetOrAdd(storedHash.ToLower(), async h =>
        {
            var url = $"https://example.com/api/verify?hash={h}";
            try
            {
                var response = await _httpClient.GetAsync(url);
                if (response.IsSuccessStatusCode)
                {
                    return true;
                }
            }
            catch (HttpRequestException ex)
            {
                LogError(ex);
            }
            return false;
        });

        return isMatch && computedHash.ToLower() == storedHash.ToLower();
    }

    private void LogError(Exception ex)
    {
        // Implement error logging logic here
        Console.WriteLine($"Error: {ex.Message}");
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var hashingLibrary = new HashingLibrary();
        var dataList = new List<string> { "data1", "data2", "data3" };

        // Example usage
        var hashes = await hashingLibrary.BulkGenerateHashesAsync(dataList, HashAlgorithmName.SHA256);
        foreach (var hash in hashes)
        {
            Console.WriteLine(hash);
        }

        var isValid = await hashingLibrary.ValidateHashAsync("testData", "expectedHash", HashAlgorithmName.MD5);
        Console.WriteLine(isValid);

        var authResult = await hashingLibrary.ExternalAuthValidationAsync("user", "password");
        Console.WriteLine(authResult);
    }
}
