public class BinaryDataProcessingService : IHostedService
{
    private readonly ILogger<BinaryDataProcessingService> _logger;
    private readonly IAmazonS3 _s3Client;
    private readonly IServiceBusClient _serviceBusClient;
    private readonly IConnectionStringProvider _connectionStringProvider;
    private readonly IDatabaseContext _dbContext;

    public BinaryDataProcessingService(
        ILogger<BinaryDataProcessingService> logger,
        IAmazonS3 s3Client,
        IServiceBusClient serviceBusClient,
        IConnectionStringProvider connectionStringProvider,
        IDatabaseContext dbContext)
    {
        _logger = logger;
        _s3Client = s3Client;
        _serviceBusClient = serviceBusClient;
        _connectionStringProvider = connectionStringProvider;
        _dbContext = dbContext;
    }

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        var topicClient = _serviceBusClient.CreateTopicClient("data-processing");
        await topicClient.Subscriber.ReceiveMessagesAsync(ReceiveMessages);
    }

    private async Task ReceiveMessages(IMessage message, CancellationToken cancellationToken)
    {
        try
        {
            var bucketName = "your-bucket-name";
            var objectKey = message.Properties["ObjectKey"] as string;
            if (string.IsNullOrEmpty(objectKey))
                throw new InvalidOperationException("Object key not found in message properties");

            var getObjectRequest = new GetObjectRequest
            {
                BucketName = bucketName,
                Key = objectKey
            };

            using (var response = await _s3Client.GetObjectAsync(getObjectRequest, cancellationToken))
            using (var stream = response.ResponseStream)
            {
                var data = await ReadBinaryDataAsync(stream);
                var entities = DeserializeData(data);

                _dbContext.Database.Connection.Open();
                await _dbContext.Database.BeginTransactionAsync(IsolationLevel.Serializable);
                try
                {
                    foreach (var entity in entities)
                    {
                        _dbContext.Entities.Add(entity);
                    }
                    await _dbContext.SaveChangesAsync(cancellationToken);
                    await _dbContext.Database.CommitTransactionAsync(cancellationToken);
                }
                catch (Exception ex)
                {
                    await _dbContext.Database.RollbackTransactionAsync(cancellationToken);
                    _logger.LogError(ex, "Error processing data: {ObjectKey}", objectKey);
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to receive and process message");
        }

        // Acknowledge the message
        await message.CompleteAsync();
    }

    private async Task<byte[]> ReadBinaryDataAsync(Stream stream)
    {
        using (var memoryStream = new MemoryStream())
        {
            await stream.CopyToAsync(memoryStream);
            return memoryStream.ToArray();
        }
    }

