import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

public class ExternalDataDeserializer {

    private static final ConcurrentHashMap<String, Class<?>> classCache = new ConcurrentHashMap<>();
    private final String defaultClassName;

    public ExternalDataDeserializer(String defaultClassName) {
        this.defaultClassName = defaultClassName;
    }

    public List<Object> deserialize(byte[] data, Class<?> targetClass) throws IOException, ClassNotFoundException {
        List<Object> resultList = new ArrayList<>();
        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data));

        try {
            while (true) {
                try {
                    Object obj = ois.readObject();
                    if (targetClass.isAssignableFrom(obj.getClass())) {
                        resultList.add(obj);
                    } else if (classCache.containsKey(targetClass.getName())) {
                        resultList.add(classCache.get(targetClass.getName()).cast(obj));
                    } else {
                        resultList.add(instantiateDefaultClass(obj));
                    }
                } catch (EOFException e) {
                    break;
                } catch (InvalidClassException | ClassCastException e) {
                    logDeserializationFailure(e);
                } catch (IOException | ClassNotFoundException e) {
                    throw new IOException("Error deserializing object", e);
                }
            }
        } finally {
            ois.close();
        }

        return resultList;
    }

    private Object instantiateDefaultClass(Object obj) throws IOException, ClassNotFoundException {
        try {
            Class<?> defaultClass = Class.forName(defaultClassName);
            if (defaultClass.isAssignableFrom(obj.getClass())) {
                return defaultClass.cast(obj);
            } else {
                throw new InvalidClassException("Invalid class type", null);
            }
        } catch (ClassNotFoundException e) {
            logDeserializationFailure(e);
            throw new IOException("Default class not found", e);
        }
    }

    private void logDeserializationFailure(Throwable e) {
        System.err.println("Deserialization failed: " + e.getClass().getSimpleName() + " - " + e.getMessage());
        // Add more detailed logging as needed
    }
}

// Example usage:
public class Main {
    public static void main(String[] args) {
        ExternalDataDeserializer deserializer = new ExternalDataDeserializer("com.example.DefaultClass");

        try {
            byte[] data = ...; // Obtain the byte array containing serialized objects
            List<Object> entities = deserializer.deserialize(data, TargetClass.class);
            for (Object entity : entities) {
                System.out.println(entity);
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }
}
```

