// Middleware for logging
app.use((req, res, next) => {
    const start = Date.now();
    res.on('finish', () => {
        logger.info(`${req.method} ${req.url} ${res.statusCode} ${Date.now() - start}ms`);
    });
    next();
});

// Route to handle file upload
app.post('/upload', upload.single('file'), async (req, res) => {
    const { originalname, mimetype } = req.file;
    const metadata = {
        size: req.file.size,
        timestamp: new Date().toISOString(),
        userId: req.body.userId,
        customAttributes: req.body.customAttributes
    };

    // Validate MIME type
    if (!['image/png', 'application/pdf'].includes(mimetype)) {
        return res.status(400).json({ error: 'Invalid file type' });
    }

    try {
        const response = await axios.put(`https://your-metadata-service.com/upload`, metadata);
        const uploadUrl = `https://${s3.config.region}.amazonaws.com/your-bucket/${originalname}`;

        const params = {
            Bucket: 'your-bucket',
            Key: originalname,
            Body: req.file.buffer,
            ContentType: mimetype
        };

        await s3.upload(params).promise();
        res.status(201).json({ uploadUrl });
    } catch (error) {
        logger.error(`Upload failed: ${error.message}`);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Route to get file status
app.get('/status/:id', async (req, res) => {
    const id = req.params.id;
    try {
        // Fetch upload status from your database or external service
        const status = await axios.get(`https://your-metadata-service.com/status/${id}`);
        res.json(status.data);
    } catch (error) {
        logger.error(`Status retrieval failed: ${error.message}`);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Start the server
app.listen(3000, () => {
    console.log('Server is running on port 3000');
});
