use tokio::sync::{mpsc, RwLock};
use std::collections::HashMap;
use serde::{Deserialize, Serialize};
use log::{error, info};

#[derive(Serialize, Deserialize)]
struct Config {
    tasks: Vec<TaskConfig>,
}

#[derive(Serialize, Deserialize)]
struct TaskConfig {
    name: String,
    priority: u8,
    resource_limit: usize,
    interval: std::time::Duration,
}

struct TaskManager {
    config: RwLock<Config>,
    task_queues: HashMap<String, mpsc::Sender<Task>>,
}

impl TaskManager {
    async fn new(config_path: &str) -> Result<Self, String> {
        let config = Self::load_config(config_path).await?;
        Ok(Self {
            config: RwLock::new(config),
            task_queues: HashMap::new(),
        })
    }

    async fn load_config(path: &str) -> Result<Config, String> {
        use std::fs;
        let config_str = fs::read_to_string(path).map_err(|e| e.to_string())?;
        serde_yaml::from_str(&config_str).map_err(|e| e.to_string())
    }

    async fn add_task_queue(&self, task_name: &str) -> Result<(), String> {
        if self.task_queues.contains_key(task_name) {
            return Err("Task queue already exists".to_string());
        }
        let (tx, rx) = mpsc::channel(32);
        tokio::spawn(self.execute_tasks(task_name, rx));
        self.task_queues.insert(task_name.to_string(), tx);
        Ok(())
    }

    async fn enqueue_task(&self, task: Task) -> Result<(), String> {
        if let Some(queue) = self.task_queues.get(task.name.as_str()) {
            queue.send(task).await.map_err(|e| e.to_string())
        } else {
            Err("Task queue not found".to_string())
        }
    }

    async fn execute_tasks(&self, task_name: &str, mut rx: mpsc::Receiver<Task>) {
        while let Some(task) = rx.recv().await {
            info!("Executing task: {}", task.name);
            // Execute the task
        }
    }
}

struct Task {
    name: String,
    data: Vec<u8>,
}

#[tokio::main]
async fn main() -> Result<(), String> {
    env_logger::init();
    let manager = TaskManager::new("config.yaml").await?;
    manager.add_task_queue("file_processing").await?;
    manager.add_task_queue("network_requests").await?;
    manager.add_task_queue("database_interactions").await?;

    let task1 = Task { name: "process_file".to_string(), data: vec![1, 2, 3] };
    let task2 = Task { name: "fetch_data".to_string(), data: vec![4, 5, 6] };
    let task3 = Task { name: "update_db".to_string(), data: vec![7, 8, 9] };

    manager.enqueue_task(task1).await?;
    manager.enqueue_task(task2).await?;
    manager.enqueue_task(task3).await?;

    Ok(())
}
