use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub struct EnvironmentVariableManager {
    variables: Arc<Mutex<HashMap<String, String>>>,
}

impl EnvironmentVariableManager {
    pub fn new() -> Self {
        EnvironmentVariableManager {
            variables: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn set_variable(&self, key: &str, value: &str) -> Result<(), std::sync::PoisonError<MutexGuard<'static, HashMap<String, String>>>> {
        let mut variables = self.variables.lock()?;
        variables.insert(key.to_string(), value.to_string());
        Ok(())
    }

    pub fn get_variable(&self, key: &str) -> Option<String> {
        let variables = self.variables.lock().ok()?;
        variables.get(key).cloned()
    }
}
