// src/retry_strategy.rs

use std::time::Duration;
use exponential_backoff::{self, ExponentialBackoff};

pub struct RetryStrategy {
    backoff: ExponentialBackoff,
}

impl RetryStrategy {
    pub fn new() -> Self {
        RetryStrategy {
            backoff: ExponentialBackoff::default(),
        }
    }

    pub async fn retry<F, Fut>(&self, mut task: F) -> Result<(), std::io::Error>
    where
        F: FnMut() -> Fut,
        Fut: std::future::Future<Output = std::result::Result<(), std::io::Error>>,
    {
        let mut attempt = 0;
        loop {
            match task().await {
                Ok(_) => break,
                Err(e) if attempt < self.backoff.max_retries() => {
                    tokio::time::sleep(self.backoff.next_backoff()).await;
                    attempt += 1;
                }
                Err(e) => return Err(e),
            }
        }
        Ok(())
    }
}
