// src/notification_service.rs

use std::sync::{Arc, Mutex};
use tokio_amqp::{Channel, Connection};

pub struct NotificationService {
    channel: Arc<Mutex<Channel>>,
}

impl NotificationService {
    pub async fn new(amqp_url: &str) -> Result<Self, Box<dyn std::error::Error>> {
        let connection = Connection::connect(amqp_url).await?;
        let channel = Channel::open(&connection).await?;
        Ok(NotificationService {
            channel: Arc::new(Mutex::new(channel)),
        })
    }

    pub async fn send_notification(&self, message: &str) -> Result<(), Box<dyn std::error::Error>> {
        let mut channel = self.channel.lock()?;
        channel.basic_publish(
            "",
            "notifications",
            b"",
            Some(message.as_bytes()),
            None,
        )?;
        Ok(())
    }
}
