// src/main.rs

use std::env;
use tokio;

mod directory_manager;
mod environment_variable_manager;
mod external_service_integration;
mod retry_strategy;
mod notification_service;
mod rollback_mechanism;
mod metrics_and_logging;
mod configuration_management;
mod security_validation;

use directory_manager::*;
use environment_variable_manager::*;
use external_service_integration::*;
use retry_strategy::*;
use notification_service::*;
use rollback_mechanism::*;
use metrics_and_logging::*;
use configuration_management::*;

#[tokio::main]
async fn main() {
    env_logger::init();
    MetricsAndLogging::setup();

    let config = configuration_management::Config::load_from_env().unwrap();
    let directory_manager = DirectoryManager::new(env::temp_dir());
    let environment_variable_manager = EnvironmentVariableManager::new();
    let external_service_integration = ExternalServiceIntegration::new();
    let retry_strategy = RetryStrategy::new();
    let notification_service = NotificationService::new("amqp://guest:guest@localhost/").await.unwrap();
    let rollback_mechanism = RollbackMechanism::new(env::temp_dir());

    // Example usage
    let directory_path = PathBuf::from("example_directory");
    if validate_directory_name(directory_path.to_str().unwrap()).is_ok() {
        match retry_strategy.retry(|| async move {
            directory_manager.create_directory(&directory_path).await?;
            environment_variable_manager.set_variable("EXAMPLE_VAR", "example_value").map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;
            external_service_integration.call_service("http://example.com").await?;
            notification_service.send_notification("Directory created successfully").await?;
            Ok(())
        }).await {
            Ok(_) => info!("Operation successful."),
            Err(e) => error!("Operation failed: {:?}", e),
        }
    } else {
        error!("Invalid directory name.");
    }

    // Example rollback
    match retry_strategy.retry(|| async move {
        rollback_mechanism.rollback_directory(&directory_path).await?;
        notification_service.send_notification("Directory rolled back successfully").await?;
        Ok(())
    }).await {
        Ok(_) => info!("Rollback successful."),
        Err(e) => error!("Rollback failed: {:?}", e),
    }
}
