import json
from abc import ABC, abstractmethod
from threading import Lock

class Serializer(ABC):
    @abstractmethod
    def serialize(self, data):
        pass

class Deserializer(ABC):
    @abstractmethod
    def deserialize(self, data):
        pass

class JSONSerializer(Serializer):
    def serialize(self, data):
        return json.dumps(data)

class JSONDeserializer(Deserializer):
    def deserialize(self, data):
        try:
            return json.loads(data)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON: {e}")

class Registry:
    _registry = {}
    _lock = Lock()

    @staticmethod
    def register(factory_id, factory_func):
        with Registry._lock:
            if factory_id in Registry._registry:
                raise ValueError(f"Factory ID '{factory_id}' already exists.")
            Registry._registry[factory_id] = factory_func

    @staticmethod
    def get_factory(factory_id):
        factory = Registry._registry.get(factory_id)
        if not factory:
            raise ValueError(f"No factory found for ID: {factory_id}")
        return factory

class DynamicFactory:
    def __init__(self, serializer, deserializer):
        self.serializer = serializer
        self.deserializer = deserializer

    def create_instance(self, data, factory_id):
        factory_func = Registry.get_factory(factory_id)
        serialized_data = self.serializer.serialize(data)
        factory_args = self.deserializer.deserialize(serialized_data)
        return factory_func(*factory_args)

# Example usage:
def custom_data_type_factory(arg1, arg2):
    return CustomDataType(arg1, arg2)

Registry.register("custom_data_type", custom_data_type_factory)

serializer = JSONSerializer()
deserializer = JSONDeserializer()

dynamic_factory = DynamicFactory(serializer, deserializer)
instance = dynamic_factory.create_instance({"arg1": "value1", "arg2": 42}, "custom_data_type")
