// Define the Transaction class to represent a financial transaction
public class Transaction {
    private String id;
    private double amount;
    private Date timestamp;

    // Getters and setters for id, amount, and timestamp

    public boolean isRecent(Date referenceTime, int days) {
        return (new java.util.concurrent.TimeUnit.DAYS.convert(referenceTime.getTime() - this.timestamp.getTime(), java.util.concurrent.TimeUnit.MILLISECONDS)) <= days;
    }

    public double weightedSum(double factor) {
        return this.amount * factor;
    }
}

// Define the TransactionFilter interface to handle dynamic filtering criteria
public interface TransactionFilter {
    boolean filter(Transaction transaction);
}

// Implement a concrete TransactionFilter for age-based criteria
public class AgeBasedTransactionFilter implements TransactionFilter {
    private int maxAgeDays;

    public AgeBasedTransactionFilter(int maxAgeDays) {
        this.maxAgeDays = maxAgeDays;
    }

    @Override
    public boolean filter(Transaction transaction) {
        return !transaction.isRecent(new Date(), maxAgeDays);
    }
}

// Define a TransactionProcessor microservice to consume and process transactions
@RestController
public class TransactionProcessor {

    @Autowired
    private TransactionService transactionService;

    @PostMapping("/transactions")
    public ResponseEntity<String> processTransaction(@RequestBody Transaction transaction) {
        try {
            transactionService.process(transaction);
            return ResponseEntity.ok("Transaction processed successfully");
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body("Failed to process transaction");
        }
    }
}

// Define a TransactionService class to handle transaction processing logic
@Service
public class TransactionService {

    @Autowired
    private RedisTemplate<String, Transaction> redisTemplate;

    @Autowired
    private RabbitTemplate rabbitTemplate;

    private TransactionFilter currentFilter;
    private double maxWeightedSum = 0.0;
    private String transactionIdWithMaxSum = "";

    public void process(Transaction transaction) {
        if (currentFilter != null && !currentFilter.filter(transaction)) {
            return; // Skip processing based on the current filter
        }

        double weightedSum = transaction.weightedSum(1.5); // Example factor
        if (weightedSum > maxWeightedSum) {
            maxWeightedSum = weightedSum;
            transactionIdWithMaxSum = transaction.getId();
        }

        // Store transaction in Redis with versioning
        redisTemplate.opsForValue().set("transaction:" + transaction.getId(), transaction, 30, TimeUnit.MINUTES);

        // Send transaction to the message broker for further processing
        rabbitTemplate.convertAndSend("transactions", transaction);
    }

    public void updateFilter(TransactionFilter newFilter) {
        this.currentFilter = newFilter;
    }
}

// Define a RabbitMQ configuration class to setup the message broker
@Configuration
public class RabbitConfig {

    @Bean
    public Queue transactionsQueue() {
        return new Queue("transactions");
    }

    @Bean
    public TopicExchange transactionExchange() {
        return new TopicExchange("transactionExchange");
    }

    @Bean
    public Binding binding(Queue transactionsQueue, TopicExchange transactionExchange) {
        return BindingBuilder.bind(transactionsQueue).to(transactionExchange).with("transactions.*");
    }
}

// Define a Redis configuration class to setup the distributed caching layer
@Configuration
public class RedisConfig {

    @Value("${spring.redis.host}")
    private String host;

    @Value("${spring.redis.port}")
    private int port;

    @Bean
    public LettuceConnectionFactory redisConnectionFactory() {
        return new LettuceConnectionFactory(host, port);
    }

    @Bean
    public RedisTemplate<String, Transaction> redisTemplate(LettuceConnectionFactory redisConnectionFactory) {
        RedisTemplate<String, Transaction> template = new RedisTemplate<>();
        template.setConnectionFactory(redisConnectionFactory);
        template.setValueSerializer(new GenericJackson2JsonRedisSerializer());
        return template;
    }
}

// Define a Logback configuration class to setup the centralized logging system
@Configuration
public class LoggingConfig {

    @Value("${logging.level.root}")
    private String rootLevel;

    @Bean
    public LoggerContext loggerContext() {
        return (LoggerContext) LoggerFactory.getILoggerFactory();
    }

    @PostConstruct
    public void init() {
        ch.qos.logback.classic.Logger logger = loggerContext.getLogger(Logger.ROOT_LOGGER_NAME);
        logger.setLevel(Level.toLevel(rootLevel));
    }
}
