<?php

require 'vendor/autoload.php';

use Illuminate\Database\Capsule\Manager as Capsule;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\Validator;
use Symfony\Component\HttpFoundation\JsonResponse;
use Symfony\Component\HttpFoundation\Request;

function handleUserAccountRequests(Request $request) {
    $payload = $request->all();
    $action = $payload['action'] ?? null;

    if (!in_array($action, ['create', 'update', 'delete'])) {
        return new JsonResponse(['status' => 'error', 'message' => 'Invalid action'], 400);
    }

    // Validate input data
    $validator = Validator::make($payload, [
        'name' => 'required|string',
        'email' => 'required|email',
        'password' => 'required|string|min:8'
    ]);

    if ($validator->fails()) {
        return new JsonResponse(['status' => 'error', 'message' => $validator->errors()], 422);
    }

    // Connect to the database
    $capsule = new Capsule;
    $capsule->addConnection([
        'driver' => 'mysql',
        'host' => 'localhost',
        'database' => 'your_database',
        'username' => 'your_username',
        'password' => 'your_password',
        'charset' => 'utf8',
        'collation' => 'utf8_unicode_ci',
        'prefix' => ''
    ]);
    $capsule->setAsGlobal();
    $capsule->bootEloquent();

    // Use caching
    Cache::setDefaultDriver('redis');

    try {
        switch ($action) {
            case 'create':
                $user = new User;
                $user->name = $payload['name'];
                $user->email = $payload['email'];
                $user->password = password_hash($payload['password'], PASSWORD_BCRYPT);
                $user->save();
                break;

            case 'update':
                $userId = $payload['id'] ?? null;
                if (!$userId) {
                    return new JsonResponse(['status' => 'error', 'message' => 'User ID is required for update'], 400);
                }
                $user = User::find($userId);
                if ($user) {
                    $user->name = $payload['name'] ?? $user->name;
                    $user->email = $payload['email'] ?? $user->email;
                    if (isset($payload['password'])) {
                        $user->password = password_hash($payload['password'], PASSWORD_BCRYPT);
                    }
                    $user->save();
                } else {
                    return new JsonResponse(['status' => 'error', 'message' => 'User not found'], 404);
                }
                break;

            case 'delete':
                $userId = $payload['id'] ?? null;
                if (!$userId) {
                    return new JsonResponse(['status' => 'error', 'message' => 'User ID is required for deletion'], 400);
                }
                $user = User::find($userId);
                if ($user && Auth::user()->isAdmin()) {
                    $user->delete();
                } else {
                    // Log unauthorized attempts
                    Log::warning('Unauthorized delete attempt by user: ' . Auth::id());
                    return new JsonResponse(['status' => 'error', 'message' => 'Unauthorized deletion'], 403);
                }
                break;
        }

        Cache::flush(); // Clear cache after updating data

        return new JsonResponse(['status' => 'success', 'message' => 'Action performed successfully'], 200);

    } catch (\Exception $e) {
        Log::error('Error handling user account request: ' . $e->getMessage());
        return new JsonResponse(['status' => 'error', 'message' => 'An error occurred'], 500);
    }
}
