#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_RANGE 1000

typedef struct {
    int* data;
    size_t size;
    sem_t lock;
} DataBuffer;

void init_data_buffer(DataBuffer* buffer) {
    buffer->data = malloc(0);
    buffer->size = 0;
    sem_init(&buffer->lock, 0, 1);
}

void free_data_buffer(DataBuffer* buffer) {
    sem_wait(&buffer->lock);
    free(buffer->data);
    sem_post(&buffer->lock);
    sem_destroy(&buffer->lock);
}

int add_to_buffer(DataBuffer* buffer, int value) {
    if (value <= 0 || value > MAX_RANGE) return -1; // Validation
    sem_wait(&buffer->lock);
    buffer->data = realloc(buffer->data, (buffer->size + 1) * sizeof(int));
    if (!buffer->data) {
        sem_post(&buffer->lock);
        return -2; // Memory allocation failed
    }
    buffer->data[buffer->size++] = value;
    sem_post(&buffer->lock);
    return 0;
}

void* worker_thread(void* arg) {
    DataBuffer* buffer = (DataBuffer*)arg;
    int value;
    while (1) {
        // Simulate reading from network stream
        if ((value = read_from_network()) < 0) break;
        if (add_to_buffer(buffer, value) != 0) {
            // Handle error: log or retry
            printf("Error processing value %d\n", value);
        }
    }
    return NULL;
}

int main() {
    DataBuffer buffer;
    init_data_buffer(&buffer);

    pthread_t threads[10]; // Example with 10 worker threads
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, worker_thread, &buffer);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    free_data_buffer(&buffer);

    return 0;
}
```

