    std::condition_variable paymentCV;
    bool paymentProcessed = false;

    std::mutex stockMutex;
    std::condition_variable stockCV;
    bool stockUpdated = false;

    void simulateNetworkLatency() {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    std::future<bool> processPayment(const PurchaseOrder& order) {
        auto paymentFuture = std::async(std::launch::async, [order]() -> bool {
            // Simulate payment processing with network latency
            simulateNetworkLatency();
            return true; // Payment processed successfully
        });
        return paymentFuture;
    }

    std::future<bool> updateStock(const PurchaseOrder& order) {
        auto stockFuture = std::async(std::launch::async, [order]() -> bool {
            // Simulate stock update with network latency
            simulateNetworkLatency();
            return true; // Stock updated successfully
        });
        return stockFuture;
    }

    void notifyCustomer(const PurchaseOrder& order, const std::string& message) {
