typedef struct {
    int id;
    time_t timestamp;
    char* key;
} record;

void bulk_record_initializer(long** offsets, int** keys, record*** records, int count) {
    srand(time(NULL));

    *offsets = (long*)malloc(count * sizeof(long));
    *keys = (int*)malloc(count * sizeof(int));
    *records = (record**)malloc(count * sizeof(record*));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        // Handle memory allocation failure
        return;
    }

    for (int i = 0; i < count; i++) {
        (*offsets)[i] = rand() % 1000;
        (*keys)[i] = rand();
        (*records)[i] = (record*)malloc(sizeof(record));
        (*records)[i]->id = rand();
        (*records)[i]->timestamp = time(NULL);
        (*records)[i]->key = (char*)malloc(20 * sizeof(char));
        sprintf((*records)[i]->key, "key%d", i);
    }
}
