#include <iostream>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class Cache {
public:
    struct CacheEntry {
        std::string value;
        std::time_t expirationTime;
    };

private:
    std::unordered_map<std::string, CacheEntry> cache;
    mutable std::mutex mtx;
    std::condition_variable cv;

public:
    void put(const std::string& key, const std::string& value, std::time_t ttl) {
        std::lock_guard<std::mutex> lock(mtx);
        CacheEntry entry{value, std::chrono::system_clock::to_time_t(std::chrono::system_clock::now() + std::chrono::seconds(ttl))};
        cache[key] = entry;
        cv.notify_all();
    }

    std::string get(const std::string& key) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, &key]{ return !cache.empty() || std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()) > cache[key].expirationTime; });

        auto it = cache.find(key);
        if (it != cache.end() && std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()) < it->second.expirationTime) {
            return it->second.value;
        } else {
            cache.erase(it);
            throw std::runtime_error("Key not found or expired");
        }
    }

    void invalidate(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        cache.erase(key);
        cv.notify_all();
    }
};

class KeyValueStoreClient {
public:
    virtual ~KeyValueStoreClient() = default;
    virtual std::string get(const std::string& key) = 0;
    virtual void put(const std::string& key, const std::string& value, std::time_t ttl) = 0;
    virtual void notifyChange(const std::string& key) = 0;
};

class DistributedCache {
public:
    DistributedCache(KeyValueStoreClient* kvClient) : kvClient(kvClient), cache() {}

    std::string getValue(const std::string& key) {
        try {
            return cache.get(key);
        } catch (...) {
            // Handle cache miss or expiration
            auto value = kvClient->get(key);
            cache.put(key, value, 3600); // TTL of 1 hour
            return value;
        }
    }

    void setValue(const std::string& key, const std::string& value) {
        kvClient->put(key, value, 3600); // TTL of 1 hour
        cache.put(key, value, 3600);
    }

    void handleChangeNotification(const std::string& key) {
        invalidateCacheEntry(key);
        kvClient->notifyChange(key);
    }

private:
    Cache cache;
    KeyValueStoreClient* kvClient;

    void invalidateCacheEntry(const std::string& key) {
        cache.invalidate(key);
    }
};

int main() {
    // Example usage
    class MockKeyValueStoreClient : public KeyValueStoreClient {
    public:
        std::string get(const std::string& key) override {
            return "value";
        }

        void put(const std::string& key, const std::string& value, std::time_t ttl) override {}

        void notifyChange(const std::string& key) override {}
    };

    MockKeyValueStoreClient kvClient;
    DistributedCache distributedCache(&kvClient);

    std::cout << distributedCache.getValue("key") << std::endl;

    return 0;
}
