}

// Function to process the resource bundle based on the reduction type
double processResourceBundle(ResourceBundle* bundle, ReductionType reductionType) {
    double result = 0.0;

    switch (reductionType) {
        case SUM:
            for (size_t i = 0; i < bundle->dataSize; ++i) {
                result += bundle->data[i];
            }
            break;
        case PRODUCT:
            result = 1.0;
            for (size_t i = 0; i < bundle->dataSize; ++i) {
                result *= bundle->data[i];
            }
            break;
        case MIN:
            result = bundle->data[0];
            for (size_t i = 1; i < bundle->dataSize; ++i) {
                if (bundle->data[i] < result) {
                    result = bundle->data[i];
                }
            }
            break;
        case MAX:
            result = bundle->data[0];
            for (size_t i = 1; i < bundle->dataSize; ++i) {
                if (bundle->data[i] > result) {
                    result = bundle->data[i];
                }
            }
            break;
    }

    return result;
}
