#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_THREADS 10

typedef struct {
    char *input_file;
    char *output_file;
} Task;

void* process_file(void* arg) {
    Task *task = (Task*)arg;
    FILE *in = fopen(task->input_file, "r");
    if (!in) {
        perror("Error opening input file");
        return NULL;
    }

    FILE *out = fopen(task->output_file, "w");
    if (!out) {
        perror("Error opening output file");
        fclose(in);
        return NULL;
    }

    char line[1024];
    while (fgets(line, sizeof(line), in)) {
        // Process the line here
        fprintf(out, "%s", line);
    }

    fclose(in);
    fclose(out);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s -i input_file -o output_file\n", argv[0]);
        return 1;
    }

    Task tasks[MAX_THREADS];
    int task_count = 0;

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-i") && i + 1 < argc) {
            tasks[task_count].input_file = argv[i + 1];
        } else if (!strcmp(argv[i], "-o") && i + 1 < argc) {
            tasks[task_count].output_file = argv[i + 1];
        }
        task_count++;
    }

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < task_count; i++) {
        if (pthread_create(&threads[i], NULL, process_file, &tasks[i]) != 0) {
            perror("Error creating thread");
            return 1;
        }
    }

    for (int i = 0; i < task_count; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
