class LogProcessor {
public:
    void addInputDirectory(const std::string& path) {
        std::lock_guard<std::mutex> lock(mutex_);
        input_directories_.push_back(path);
    }

    void removeInputDirectory(const std::string& path) {
        std::lock_guard<std::mutex> lock(mutex_);
        input_directories_.erase(std::remove(input_directories_.begin(), input_directories_.end(), path), input_directories_.end());
    }

    void startProcessing() {
        for (size_t i = 0; i < num_threads_; ++i) {
            threads_.emplace_back([this]() { worker(); });
        }
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        cv_.notify_all();
        for (auto& thread : threads_) {
            thread.join();
        }
    }

private:
    void worker() {
        while (true) {
            std::string file_path;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return !stop_ && !input_queue_.empty(); });
                if (stop_) return;
                file_path = input_queue_.front();
                input_queue_.pop();
            }
            processFile(file_path);
        }
    }

