            strm.zalloc = Z_NULL;
            strm.zfree = Z_NULL;
            strm.opaque = Z_NULL;
            inflateInit2(&strm, 15 + 32); // Gzip decompression
            char buffer[1024];
            while (true) {
                strm.avail_in = file.read(buffer, sizeof(buffer)).gcount();
                if (strm.avail_in == 0) break;
                strm.next_in = reinterpret_cast<Bytef*>(buffer);
                do {
                    strm.avail_out = sizeof(buffer);
                    strm.next_out = reinterpret_cast<Bytef*>(buffer);
                    int ret = inflate(&strm, Z_NO_FLUSH);
                    if (ret != Z_OK && ret != Z_STREAM_END) {
                        std::cerr << "Decompression error" << std::endl;
                        return;
                    }
                    std::string decompressed_data(buffer, sizeof(buffer) - strm.avail_out);
                    // Parse JSON here using rapidjson
                } while (strm.avail_out == 0);
            }
            inflateEnd(&strm);
        }
    }

    std::vector<std::string> input_directories_;
    std::queue<std::string> input_queue_;
    std::vector<std::thread> threads_;
    size_t num_threads_ = std::thread::hardware_concurrency();
    std::mutex mutex_;
    std::condition_variable cv_;
    bool stop_ = false;
