#include <iostream>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <thread>
#include <queue>

// Define a simple LRU Cache with TTL support
template<typename Key, typename Value>
class LRUCache {
private:
    struct Node {
        Key key;
        Value value;
        std::shared_ptr<Node> prev;
        std::shared_ptr<Node> next;
        size_t timestamp;

        Node(Key k, Value v) : key(k), value(v), timestamp(std::chrono::system_clock::now().time_since_epoch().count()) {}
    };

    std::unordered_map<Key, std::shared_ptr<Node>> cache;
    std::shared_ptr<Node> head;
    std::shared_ptr<Node> tail;
    size_t capacity;

    std::mutex mutex;
    std::condition_variable cv;

public:
    LRUCache(size_t max_size) : capacity(max_size), head(std::make_shared<Node>(std::numeric_limits<Key>::max(), Value())), tail(head) {}

    void put(Key key, Value value, size_t ttl) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);

        if (it != cache.end()) {
            // Update existing node
            it->second->value = value;
            it->second->timestamp = std::chrono::system_clock::now().time_since_epoch().count();
            moveToHead(it->second);
        } else {
            // Insert new node
            auto newNode = std::make_shared<Node>(key, value);
            newNode->timestamp = std::chrono::system_clock::now().time_since_epoch().count();
            insert(newNode);
        }

        // Remove expired nodes
        removeExpiredNodes(ttl);
    }

    Value get(Key key) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);

        if (it != cache.end()) {
            // Move accessed node to the head
            moveToHead(it->second);
            return it->second->value;
        } else {
            throw std::runtime_error("Key not found");
        }
    }

private:
    void insert(std::shared_ptr<Node> newNode) {
        newNode->prev = tail;
        newNode->next = head;
        tail->next = newNode;
        head->prev = newNode;
        cache[newNode->key] = newNode;
        if (cache.size() > capacity) {
            auto nodeToRemove = tail->prev;
            remove(nodeToRemove);
            cache.erase(nodeToRemove->key);
        }
    }

    void moveToHead(std::shared_ptr<Node> node) {
        if (node == head) return;

        // Remove node
        node->prev->next = node->next;
        node->next->prev = node->prev;

        // Insert at the head
        insert(node);
    }

    void removeExpiredNodes(size_t ttl) {
        auto now = std::chrono::system_clock::now().time_since_epoch().count();

        while (!cache.empty() && cache.begin()->second->timestamp + ttl < now) {
            auto nodeToRemove = tail->prev;
            remove(nodeToRemove);
            cache.erase(nodeToRemove->key);
        }
    }

    void remove(std::shared_ptr<Node> node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
};

int main() {
    LRUCache<int, std::string> cache(3);

    cache.put(1, "one", 5);
    cache.put(2, "two", 5);
    cache.put(3, "three", 5);

    std::cout << cache.get(1) << std::endl; // Output: one
    std::cout << cache.get(2) << std::endl; // Output: two

    std::this_thread::sleep_for(std::chrono::seconds(6));
    try {
        std::cout << cache.get(1) << std::endl; // Should throw exception, key expired
    } catch (const std::runtime_error& e) {
        std::cout << e.what() << std::endl;
    }

    return 0;
}
```

This code snippet demonstrates a basic LRU Cache implementation with TTL support in C++. It includes methods for putting and getting items, as well as handling expiration based on time-to-live. The cache uses a doubly linked list to maintain the order of elements based on their usage, allowing efficient removal of least recently used items when the capacity is reached.']

