class CryptoFunction {
public:
    virtual ~CryptoFunction() = default;
    virtual void initialize(int securityStrength) = 0;
    virtual void cleanup() = 0;
    virtual std::string getName() const = 0;
    virtual void updatePerformanceMetrics() = 0;
    virtual bool checkCompliance() const = 0;
};

// Base class for cryptographic algorithms
class CryptoAlgorithm {
public:
    virtual ~CryptoAlgorithm() = default;
    virtual void encrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) = 0;
    virtual void decrypt(const std::vector<uint8_t>& input, std::vector<uint8_t>& output) = 0;
};

// Dependency injection model for cryptographic modules
class CryptoModule {
public:
    virtual ~CryptoModule() = default;
    virtual std::unique_ptr<CryptoFunction> createCryptoFunction(int securityStrength) = 0;
    virtual std::unique_ptr<CryptoAlgorithm> createCryptoAlgorithm() = 0;
};

// Singleton class to manage loaded cryptographic modules
class CryptoManager {
private:
    static std::mutex mutex_;
    static std::map<std::string, std::unique_ptr<CryptoModule>> modules_;

    CryptoManager() {}
    ~CryptoManager() {}

public:
    static void loadModule(std::string moduleName, std::unique_ptr<CryptoModule> module) {
        std::lock_guard<std::mutex> lock(mutex_);
        modules_[moduleName] = std::move(module);
    }

    static std::unique_ptr<CryptoFunction> createCryptoFunction(const std::string& moduleName, int securityStrength) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = modules_.find(moduleName);
        if (it != modules_.end()) {
            return it->second->createCryptoFunction(securityStrength);
        }
        throw std::runtime_error("Module not found");
    }

    static std::unique_ptr<CryptoAlgorithm> createCryptoAlgorithm(const std::string& moduleName) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = modules_.find(moduleName);
        if (it != modules_.end()) {
            return it->second->createCryptoAlgorithm();
        }
        throw std::runtime_error("Module not found");
    }
};

