from typing import List
import redis
from kafka import KafkaProducer, KafkaConsumer
from kafka.admin import KafkaAdminClient

class SemaphoreManager:
    def __init__(self, kv_store_config: dict, kafka_config: dict):
        self.kv_store = redis.Redis(**kv_store_config)
        self.kafka_producer = KafkaProducer(**kafka_config)
        self.kafka_consumer = KafkaConsumer(**kafka_config)
        self.kafka_admin_client = KafkaAdminClient(**kafka_config)

    def create_semaphore(self, semaphore_id: str, initial_count: int):
        # Create a semaphore in the KV store
        self.kv_store.set(semaphore_id, initial_count)
        # Publish an event to inform other services about the new semaphore
        self.kafka_producer.send('semaphore_events', key=semaphore_id.encode(), value=f"CREATE:{initial_count}".encode())

    def acquire_semaphore(self, semaphore_id: str) -> bool:
        # Try to decrement the semaphore count atomically
        current_value = self.kv_store.decr(semaphore_id)
        if current_value >= 0:
            return True
        else:
            # If the value goes negative, increment it back and return False
            self.kv_store.incr(semaphore_id)
            return False

    def release_semaphore(self, semaphore_id: str):
        # Increment the semaphore count atomically
        self.kv_store.incr(semaphore_id)

    def delete_semaphore(self, semaphore_id: str):
        # Delete the semaphore from the KV store
        self.kv_store.delete(semaphore_id)
        # Publish an event to inform other services about the deletion of the semaphore
        self.kafka_producer.send('semaphore_events', key=semaphore_id.encode(), value="DELETE".encode())

    def get_semaphore_count(self, semaphore_id: str) -> int:
        return int(self.kv_store.get(semaphore_id))

# Example usage
kv_store_config = {
    'host': 'localhost',
    'port': 6379,
    'db': 0
}

kafka_config = {
    'bootstrap_servers': 'localhost:9092'
}

semaphore_manager = SemaphoreManager(kv_store_config, kafka_config)
semaphore_manager.create_semaphore('my_semaphore', 10)

if semaphore_manager.acquire_semaphore('my_semaphore'):
    print("Semaphore acquired")
else:
    print("Failed to acquire semaphore")

semaphore_manager.release_semaphore('my_semaphore')

semaphore_manager.delete_semaphore('my_semaphore')
