public:
    void addServiceInstance(std::shared_ptr<ServiceInstance> instance) {
        instances_.push_back(instance);
    }

    std::shared_ptr<ServiceInstance> getInstance() {
        // Round-robin load balancing
        static size_t index = 0;
        return instances_[index++ % instances_.size()];
    }

private:
    std::vector<std::shared_ptr<ServiceInstance>> instances_;
};

// Class representing a client instance
class Client {
public:
    Client(RequestHandler* handler, ServiceInstanceManager& manager) 
        : request_handler_(handler), service_manager_(manager) {}

    void processRequest(const Request& request) {
        // Queue the request and handle it later
        std::lock_guard<std::mutex> lock(mutex_);
        request_queue_.push(request);
        cv_.notify_one();
    }

