class RNGSystem {
public:
    struct Config {
        uint64_t seed;
        int numInstances;
    };

    RNGSystem(const Config& config) : config_(config), instances_(config.numInstances) {
        for (int i = 0; i < config_.numInstances; ++i) {
            instances_[i].engine.seed(config_.seed + i);
        }
    }

    double generateDouble() {
        std::lock_guard<std::mutex> lock(mutex_);
        return instances_[nextInstance_++ % instances_.size()].distribution(engine_);
    }

    int32_t generateInt32() {
        std::lock_guard<std::mutex> lock(mutex_);
        return instances_[nextInstance_++ % instances_.size()].distribution_int32(engine_);
    }

    bool generateBool() {
        std::lock_guard<std::mutex> lock(mutex_);
        return instances_[nextInstance_++ % instances_.size()].distribution_bool(engine_);
    }

private:
    struct Instance {
        std::mt19937 engine;
        std::uniform_real_distribution<double> distribution;
        std::uniform_int_distribution<int32_t> distribution_int32;
        std::bernoulli_distribution distribution_bool;
    };

    Config config_;
    std::vector<Instance> instances_;
    int nextInstance_ = 0;
    std::mutex mutex_;
};

int main() {
    RNGSystem::Config config{std::random_device{}(), 10};
    RNGSystem rng(config);

    std::vector<std::thread> threads;
    for (int i = 0; i < 1000; ++i) {
        threads.emplace_back([&rng]() {
            for (int j = 0; j < 1000; ++j) {
                double randomDouble = rng.generateDouble();
                int32_t randomInt32 = rng.generateInt32();
