using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

public class AsyncQueryExecutionService
{
    private readonly string _connectionStringPattern = @"^Server=\w+;\Database=\w+;User ID=\w+;Password=\w+$";

    public async Task ExecuteParameterizedQueryAsync(
        string connectionString,
        string sqlCommand,
        List<SqlParameter> parameters,
        Action<IDataReader> postExecutionCallback = null)
    {
        // Validate connection string
        if (!Regex.IsMatch(connectionString, _connectionStringPattern))
        {
            throw new ArgumentException("Invalid connection string.");
        }

        try
        {
            using (var connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();

                using (var command = new SqlCommand(sqlCommand, connection))
                {
                    command.Parameters.AddRange(parameters.ToArray());

                    if (!command.CommandText.StartsWith("SELECT") && !command.CommandText.StartsWith("INSERT") && !command.CommandText.StartsWith("UPDATE") && !command.CommandText.StartsWith("DELETE"))
                    {
                        throw new ArgumentException("Invalid SQL command. Only SELECT, INSERT, UPDATE, and DELETE statements are allowed.");
                    }

                    using (var reader = await command.ExecuteReaderAsync(CommandBehavior.CloseConnection))
                    {
                        if (postExecutionCallback != null)
                        {
                            while (await reader.ReadAsync())
                            {
                                postExecutionCallback(reader);
                            }
                        }
                    }
                }
            }
        }
        catch (SqlException ex)
        {
            // Log the error and provide user-friendly message
            Console.WriteLine($"Database error: {ex.Message}");
            throw new InvalidOperationException("Failed to execute query.", ex);
        }
        catch (Exception ex)
        {
            // Log the error and provide general error message
            Console.WriteLine($"An error occurred: {ex.Message}");
            throw new InvalidOperationException("An unexpected error occurred.", ex);
        }
    }
}
