using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

namespace DynamicRESTClient
{
    public class ApiRequest
    {
        public HttpMethod Method { get; set; }
        public string Url { get; set; }
        public Dictionary<string, string> Headers { get; set; } = new();
        public Dictionary<string, string> QueryParameters { get; set; } = new();
        public object Body { get; set; }
    }

    public class ApiResponse<T>
    {
        public int StatusCode { get; set; }
        public T Data { get; set; }
        public string Error { get; set; }
    }

    public interface IApiClient
    {
        Task<ApiResponse<T>> SendAsync<T>(ApiRequest request);
    }

    public class ApiClient : IApiClient
    {
        private readonly HttpClient _httpClient;

        public ApiClient(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        public async Task<ApiResponse<T>> SendAsync<T>(ApiRequest request)
        {
            var response = await _httpClient.SendAsync(request);
            if (response.IsSuccessStatusCode)
            {
                try
                {
                    return new ApiResponse<T> { Data = await response.Content.ReadAsAsync<T>() };
                }
                catch (Exception ex)
                {
                    return new ApiResponse<T> { Error = $"Failed to parse response: {ex.Message}" };
                }
            }
            else
            {
                var errorResponse = await response.Content.ReadAsStringAsync();
                return new ApiResponse<T> { StatusCode = response.StatusCode, Error = errorResponse };
            }
        }
    }

    public class ApiClientFactory
    {
        public static IApiClient CreateHttpClient(string baseUrl)
        {
            var httpClient = new HttpClient
            {
                BaseAddress = new Uri(baseUrl),
                Timeout = TimeSpan.FromSeconds(10)
            };

            return new ApiClient(httpClient);
        }
    }
}
