// JavaScript function in Angular
function updateFormFields(fieldNames: string[]) {
    const parentWindow = window.opener;
    if (!parentWindow) return;

    fieldNames.forEach(fieldName => {
        const field = parentWindow.document.getElementById(fieldName);
        if (field) {
            const content = field.value;
            const bookRegex = /\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Moses|Joshua|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah |Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b/gi;
            const matches = content.match(bookRegex);
            if (matches) {
                const bookFrequency: { [key: string]: number } = {};
                matches.forEach(match => {
                    const normalizedMatch = match.replace(/[^\w]/g, '').toLowerCase();
                    if (bookFrequency[normalizedMatch]) {
                        bookFrequency[normalizedMatch]++;
                    } else {
                        bookFrequency[normalizedMatch] = 1;
                    }
                });
                parentWindow.console.log(bookFrequency);
            }
        }
    });

    // Retry mechanism with exponential backoff
    function retry() {
        setTimeout(() => {
            updateFormFields(fieldNames);
        }, Math.pow(2, retries++) * 1000); // Exponential backoff
    }

    let retries = 0;
    retry();
}
