const express = require('express');
const bodyParser = require('body-parser');
const stream = require('stream');
const fs = require('fs');
const path = require('path');
const { Pool } = require('pg');
const sharp = require('sharp');

const app = express();
app.use(bodyParser.json());

// Database pool for handling connections
const dbPool = new Pool({
  user: 'user',
  host: 'host',
  database: 'database',
  password: 'password',
  port: 5432,
});

// Cache directory and theme settings
const CACHE_DIR = path.join(__dirname, 'cache');
const DEFAULT_THEME = 'default';

if (!fs.existsSync(CACHE_DIR)) {
  fs.mkdirSync(CACHE_DIR);
}

let isPaused = false;
let workerQueue = [];

function processWorker() {
  if (workerQueue.length === 0 || isPaused) return;

  const data = workerQueue.shift();
  processData(data, () => {
    setImmediate(processWorker); // Process next item asynchronously
  });
}

async function processData(data, callback) {
  try {
    // Example processing: save to database and cache
    await dbPool.query('INSERT INTO data_stream (data) VALUES ($1)', [data]);
    fs.writeFileSync(path.join(CACHE_DIR, 'latest_data.json'), JSON.stringify(data));
    callback();
  } catch (error) {
    console.error('Error processing data:', error);
    callback();
  }
}

app.post('/stream', (req, res) => {
  if (isPaused) return res.status(503).send('Service is paused');

  const dataStream = new stream.PassThrough();

  req.on('data', chunk => {
    if (!isPaused) {
      workerQueue.push(chunk.toString());
      processWorker();
    }
  });

  req.on('end', () => {
    dataStream.end();
  });

  res.status(202).send('Data accepted for processing');
});

app.get('/resume', (req, res) => {
  isPaused = false;
  processWorker();
  res.send('Processing resumed');
});

app.post('/pause', (req, res) => {
  isPaused = true;
  res.send('Processing paused');
});

// Theme management
app.get('/theme/:name', (req, res) => {
  const themeName = req.params.name || DEFAULT_THEME;
  const themePath = path.join(__dirname, 'themes', `${themeName}.png`);

  if (!fs.existsSync(themePath)) {
    return res.status(404).send('Theme not found');
  }

  sharp(themePath)
    .resize({ width: req.query.width, height: req.query.height })
    .toBuffer()
    .then(buffer => {
      res.set('Content-Type', 'image/png');
      res.send(buffer);
    })
    .catch(error => {
      console.error('Error processing theme:', error);
      res.status(500).send('Failed to process theme');
    });
});

app.post('/theme/upload', (req, res) => {
  if (!req.files || Object.keys(req.files).length === 0) {
    return res.status(400).send('No files were uploaded.');
  }

  const imageFile = req.files.image;
  const outputPath = path.join(__dirname, 'themes', `${DEFAULT_THEME}.png`);

  imageFile.mv(outputPath, err => {
    if (err) {
      console.error('Error uploading theme:', err);
      return res.status(500).send('Failed to upload theme');
    }
    res.send('Theme uploaded successfully');
  });
});

// Error handling
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
