### 4. Error Handling and Retries

```javascript
// ErrorHandler.js
class ErrorHandler {
    static retry(fn, retries = 3, delay = 1000) {
        return new Promise(async (resolve, reject) => {
            for (let i = 0; i < retries; i++) {
                try {
                    const result = await fn();
                    resolve(result);
                    break;
                } catch (error) {
                    if (i === retries - 1) {
                        reject(error);
                    }
                    await new Promise(resolve => setTimeout(resolve, delay));
                }
            }
        });
    }

    static exponentialBackoff(fn, maxRetries = 5, initialDelay = 1000) {
        return new Promise(async (resolve, reject) => {
            let delay = initialDelay;
            for (let i = 0; i < maxRetries; i++) {
                try {
                    const result = await fn();
                    resolve(result);
                    break;
                } catch (error) {
                    if (i === maxRetries - 1) {
                        reject(error);
                    }
                    delay *= 2;
                    await new Promise(resolve => setTimeout(resolve, delay));
                }
            }
        });
    }
}

export default ErrorHandler;
```

### 5. Semaphore Implementation in C

```c
// semaphore.c
#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>

typedef struct {
    sem_t *sem;
    int max_count;
} Semaphore;

Semaphore* create_semaphore(int initial_value) {
    Semaphore *s = (Semaphore *)malloc(sizeof(Semaphore));
    s->max_count = initial_value;
    s->sem = (sem_t *)malloc(sizeof(sem_t));
    sem_init(s->sem, 0, initial_value);
    return s;
}

void semaphore_wait(Semaphore *s) {
    sem_wait(s->sem);
}

void semaphore_signal(Semaphore *s) {
    if (sem_getvalue(s->sem, NULL) < s->max_count) {
        sem_post(s->sem);
    }
}

void destroy_semaphore(Semaphore *s) {
    sem_destroy(s->sem);
    free(s->sem);
    free(s);
}
```

