import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DistributedFileSystemResolver {
    private UnionFind unionFind;
    private ConcurrentHashMap<String, String> cache;
    private ExecutorService executorService;
    private Logger logger;
    private boolean cachingEnabled;

    public DistributedFileSystemResolver(boolean cachingEnabled) {
        this.unionFind = new UnionFind();
        this.cache = new ConcurrentHashMap<>();
        this.executorService = Executors.newFixedThreadPool(10);
        this.logger = LoggerFactory.getLogger(DistributedFileSystemResolver.class);
        this.cachingEnabled = cachingEnabled;
    }

    public String resolve(String filePath) {
        if (cachingEnabled && cache.containsKey(filePath)) {
            return cache.get(filePath);
        }

        long startTime = System.currentTimeMillis();
        try {
            // Simulate API call
            String directoryMetadata = fetchDirectoryMetadata(filePath);

            // Resolve using Union-Find
            String rootFileSystem = unionFind.find(directoryMetadata);

            if (cachingEnabled) {
                cache.put(filePath, rootFileSystem);
            }
            return rootFileSystem;
        } catch (Exception e) {
            logError(e.getMessage());
            throw new RuntimeException("Failed to resolve file path: " + filePath, e);
        } finally {
            long endTime = System.currentTimeMillis();
            logger.info(String.format("File path resolved in %d ms", endTime - startTime));
        }
    }

    private String fetchDirectoryMetadata(String filePath) throws Exception {
        // Simulate API call
        return "metadata";
    }

    private void logError(String message) {
        if (logger.isErrorEnabled()) {
            logger.error(message);
        }
    }

    public void shutdown() {
        executorService.shutdown();
    }
}

class UnionFind {
    Map<String, String> parent;

    public UnionFind() {
        this.parent = new HashMap<>();
    }

    public String find(String x) {
        if (!parent.containsKey(x)) {
            parent.put(x, x);
            return x;
        }
        if (!x.equals(parent.get(x))) {
            parent.put(x, find(parent.get(x)));
        }
        return parent.get(x);
    }

    public void union(String x, String y) {
        parent.put(find(x), find(y));
    }
}
