import io.grpc.Server;
import io.grpc.ServerBuilder;
import io.grpc.stub.StreamObserver;

public class BackgroundProcessingService {

    private Server server;

    public void start() throws IOException {
        int port = 50051;
        server = ServerBuilder.forPort(port)
                .addService(new BackgroundProcessingServiceImpl())
                .build()
                .start();
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            // Use stderr here since the logger may have been reset by its JVM shutdown hook.
            System.err.println("*** shutting down gRPC server since JVM is shutting down");
            BackgroundProcessingService.this.stop();
            System.err.println("*** server shut down");
        }));
    }

    public void stop() {
        if (server != null) {
            server.shutdown();
        }
    }

    private static class BackgroundProcessingServiceImpl extends BackgroundProcessingServiceGrpc.BackgroundProcessingServiceImplBase {

        @Override
        public void processTasks(BackgroundProcessingRequest req, StreamObserver<BackgroundProcessingResponse> responseObserver) {
            // Implement task processing logic here
            BackgroundProcessingResponse response = BackgroundProcessingResponse.newBuilder()
                    .setResult("Task processed successfully")
                    .build();
            responseObserver.onNext(response);
            responseObserver.onCompleted();
        }
    }

    private void blockUntilShutdown() throws InterruptedException {
        if (server != null) {
            server.awaitTermination();
        }
    }

    public static void main(String[] args) throws IOException, InterruptedException {
        final BackgroundProcessingService service = new BackgroundProcessingService();
        service.start();
        System.out.println("Server started, listening on 50051");
        service.blockUntilShutdown();
    }
}
