use reqwest::ClientBuilder;
use tokio::sync::{Mutex, RwLock};
use tower_http::{
    limits::LimitLayer,
    trace::{TraceLayer, TraceLayerBuilder},
    retry::{RetryLayer, RetryIf},
};
use std::{
    env,
    time::{Duration, Instant},
};

struct Config {
    base_url: String,
    api_key: Option<String>,
    oauth_token: Option<String>,
}

struct HttpClient {
    client: ClientBuilder,
    config: RwLock<Config>,
    retry_policy: RwLock<Option<RetryIf>>,
}

impl HttpClient {
    async fn new() -> Self {
        let mut config = Config {
            base_url: env::var("API_BASE_URL").unwrap_or_else(|_| "https://api.example.com".to_string()),
            api_key: env::var("API_KEY").ok(),
            oauth_token: env::var("OAUTH_TOKEN").ok(),
        };

        let retry_policy = Some(RetryIf::new_default());

        HttpClient {
            client: ClientBuilder::new()
                .redirect(reqwest::RedirectPolicy::limited(5))
                .timeout(Duration::from_secs(10)),
            config: RwLock::new(config),
            retry_policy: RwLock::new(retry_policy),
        }
    }

    async fn fetch(&self, endpoint: &str) -> Result<String, reqwest::Error> {
        let config = self.config.read().await;
        let mut client = self.client.build()?;

        if let Some(api_key) = &config.api_key {
            client = client.header("Authorization", format!("Bearer {}", api_key));
        }

        if let Some(oauth_token) = &config.oauth_token {
            client = client.header("Authorization", format!("Bearer {}", oauth_token));
        }

        let start_time = Instant::now();
        let response = client
            .get(&format!("{}/{}", config.base_url, endpoint))
            .send()
            .await?
            .text()
            .await?;

        tracing::info!(
            status = %response.status(),
            latency_ms = ?start_time.elapsed().as_millis(),
            "Fetched data from endpoint"
        );

        Ok(response)
    }
}

