// Define a Rust module for orchestrating microservices builds
mod microservice_build {
    use std::collections::{HashMap, HashSet};
    use std::process::{Command, Stdio};
    use std::sync::{Arc, Mutex};
    use std::time::Instant;

    pub struct BuildOrchestrator {
        services: HashMap<String, Service>,
        dependencies: HashMap<String, Vec<String>>,
        build_cache: Arc<Mutex<HashMap<String, bool>>>,
    }

    impl BuildOrchestrator {
        pub fn new() -> Self {
            BuildOrchestrator {
                services: HashMap::new(),
                dependencies: HashMap::new(),
                build_cache: Arc::new(Mutex::new(HashMap::new())),
            }
        }

        pub fn add_service(&mut self, name: String, service: Service) {
            self.services.insert(name, service);
        }

        pub fn add_dependency(&mut self, service_name: &str, dependency_name: &str) {
            self.dependencies.entry(service_name.to_string()).or_insert_with(Vec::new).push(dependency_name.to_string());
        }

        pub fn build_all_services(&self) -> Result<(), BuildError> {
            let mut built_services = HashSet::new();
            let build_cache = Arc::clone(&self.build_cache);

            for service_name in self.services.keys().cloned() {
                if !built_services.contains(&service_name) && self.build_service(&service_name, &built_services, build_cache.clone())? {
                    built_services.insert(service_name);
                }
            }

            Ok(())
        }

        fn build_service(
            &self,
            service_name: &str,
            built_services: &HashSet<String>,
            build_cache: Arc<Mutex<HashMap<String, bool>>>,
        ) -> Result<bool, BuildError> {
            if let Some(&is_cached) = self.build_cache.lock().unwrap().get(service_name) {
                return Ok(is_cached);
            }

            let start_time = Instant::now();
            let service = self.services.get(service_name).ok_or(BuildError::ServiceNotFound(service_name.to_string()))?;
            let mut env_vars = std::env::vars().collect::<Vec<_>>();
            env_vars.push(("SERVICE_NAME".to_string(), service_name.to_string()));

            let output = Command::new("cargo")
                .args(&["build"])
                .current_dir(&service.path)
                .envs(env_vars.iter().cloned())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .output()
                .map_err(|e| BuildError::CargoCommandFailed(e.to_string()))?;

            if !output.status.success() {
                return Err(BuildError::CompilationFailed(output.stderr));
            }

            let compilation_time = start_time.elapsed();
            println!("Service {} built in {:?}", service_name, compilation_time);

            // Cache build result
            self.build_cache.lock().unwrap().insert(service_name.to_string(), true);
            Ok(true)
        }
    }

    #[derive(Debug)]
    pub struct Service {
        pub path: String,
    }

    #[derive(Debug)]
    pub enum BuildError {
        ServiceNotFound(String),
        CargoCommandFailed(String),
        CompilationFailed(Vec<u8>),
    }

    impl std::fmt::Display for BuildError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            match self {
                BuildError::ServiceNotFound(service_name) => write!(f, "Service not found: {}", service_name),
                BuildError::CargoCommandFailed(message) => write!(f, "Cargo command failed: {}", message),
                BuildError::CompilationFailed(stderr) => write!(f, "Compilation failed:\n{}", String::from_utf8_lossy(stderr)),
            }
        }
    }

    impl std::error::Error for BuildError {}
}
