#include <iostream>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <future>
#include <chrono>
#include <atomic>

class KeyValueStore {
    std::unordered_map<std::string, std::pair<std::string, std::time_t>> store;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void set(const std::string& key, const std::string& value, std::time_t ttl) {
        std::lock_guard<std::mutex> lock(mtx);
        auto expireTime = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now() + std::chrono::seconds(ttl));
        store[key] = {value, expireTime};
        cv.notify_one();
    }

    std::string get(const std::string& key) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, &key]{ return store.count(key) > 0 && store[key].second > std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()); });
        if (store[key].second <= std::chrono::system_clock::to_time_t(std::chrono::system_clock::now())) {
            store.erase(key);
            return "";
        }
        return store[key].first;
    }

    void notifyChange(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mtx);
        store[key] = {value, std::time_t(std::numeric_limits<std::time_t>::max())};
        cv.notify_one();
    }
};

class CacheManager {
    KeyValueStore* kvStore;
    std::unordered_map<std::string, std::future<std::string>> cache;

public:
    CacheManager(KeyValueStore* kvStore) : kvStore(kvStore) {}

    void addToCache(const std::string& key, const std::string& value, std::time_t ttl) {
        if (cache.count(key)) {
            cache[key].get();
        }
        auto future = std::async(std::launch::async, [this, key, value, ttl]{ return kvStore->set(key, value, ttl); });
        cache[key] = std::move(future);
    }

    std::string getFromCache(const std::string& key) {
        if (cache.count(key)) {
            try {
                auto result = cache[key].get();
                addToCache(key, result, std::chrono::seconds(60)); // Refresh TTL
                return result;
            } catch (...) {
                cache.erase(key);
            }
        }
        return kvStore->get(key);
    }

    void notifyChangeInKey(const std::string& key, const std::string& value) {
        if (cache.count(key)) {
            cache[key].get();
        }
        addToCache(key, value, std::chrono::seconds(60));
    }
};

class GeolocationService {
    CacheManager* cacheManager;

public:
    GeolocationService(CacheManager* cacheManager) : cacheManager(cacheManager) {}

    void updateLocation(const std::string& userId, const std::string& location) {
        cacheManager->notifyChangeInKey(userId, location);
    }

    std::string getLocation(const std::string& userId) {
        return cacheManager->getFromCache(userId);
    }
};

int main() {
    KeyValueStore kvStore;
    CacheManager cacheManager(&kvStore);
    GeolocationService geolocationService(&cacheManager);

    // Example usage
    geolocationService.updateLocation("user1", "New York");
    std::cout << "User 1 location: " << geolocationService.getLocation("user1") << std::endl;

    return 0;
}
