class SecureSessionManager {
    private $sessionToken;
    private $lastActivityTime;
    private $themeCache;
    private $encryptionKey;
    private $redisClient;

    public function __construct($encryptionKey, $redisConfig) {
        $this->encryptionKey = $encryptionKey;
        $this->redisClient = new Redis();
        if (!$this->redisClient->connect($redisConfig['host'], $redisConfig['port'])) {
            throw new Exception("Failed to connect to Redis");
        }
    }

    public function generateSessionToken($length = 64) {
        $this->sessionToken = bin2hex(random_bytes($length / 2));
        $this->lastActivityTime = time();
        $this->storeSessionData(['token' => $this->sessionToken, 'theme' => null]);
    }

    public function regenerateSessionToken() {
        if (time() - $this->lastActivityTime < 3600) {
            return;
        }
        $this->generateSessionToken();
    }

    private function storeSessionData($data) {
        try {
            $this->redisClient->set('session:' . $this->sessionToken, $this->encrypt(json_encode($data)), 'EX', 86400);
        } catch (Exception $e) {
            // Retry logic or circuit breaking mechanism
        }
    }

    private function retrieveSessionData() {
        try {
            $data = $this->redisClient->get('session:' . $this->sessionToken);
            if ($data) {
                return $this->decrypt($data);
            }
        } catch (Exception $e) {
            // Retry logic or circuit breaking mechanism
        }
        return null;
    }

    private function encrypt($data) {
        return openssl_encrypt($data, 'AES-256-CBC', $this->encryptionKey, 0, $this->encryptionKey);
    }

    private function decrypt($data) {
        return openssl_decrypt($data, 'AES-256-CBC', $this->encryptionKey, 0, $this->encryptionKey);
    }

    public function updateTheme($theme) {
        $sessionData = $this->retrieveSessionData();
        if ($sessionData && is_array($sessionData)) {
            $sessionData['theme'] = $theme;
            $this->storeSessionData($sessionData);
        }
    }

    public function logout() {
        $this->redisClient->del('session:' . $this->sessionToken);
    }

    private function checkAndSetDefaultTheme() {
        $sessionData = $this->retrieveSessionData();
        if ($sessionData && is_array($sessionData) && empty($sessionData['theme'])) {
            $sessionData['theme'] = 'default_theme';
            $this->storeSessionData($sessionData);
        }
    }

    public function getSessionToken() {
        return $this->sessionToken;
    }

