import threading
import json
from abc import ABC, abstractmethod

class LogAnalyzer(ABC):
    def __init__(self, config):
        self.config = config
        self.lock = threading.Lock()

    @abstractmethod
    def parse_entry(self, entry):
        pass

    @abstractmethod
    def validate_entry(self, entry):
        pass

    @abstractmethod
    def process_entry(self, entry):
        pass

    def add_log_entry(self, entry):
        with self.lock:
            if self.validate_entry(entry):
                parsed_entry = self.parse_entry(entry)
                self.process_entry(parsed_entry)

class JsonLogAnalyzer(LogAnalyzer):
    def parse_entry(self, entry):
        return json.loads(entry)

    def validate_entry(self, entry):
        try:
            json.dumps(entry)
            return True
        except ValueError:
            return False

    def process_entry(self, entry):
        # Process JSON log entry
        pass

class CSVLogAnalyzer(LogAnalyzer):
    def parse_entry(self, entry):
        import csv
        reader = csv.reader([entry])
        return next(reader)

    def validate_entry(self, entry):
        import csv
        try:
            csv.reader([entry])
            return True
        except csv.Error:
            return False

    def process_entry(self, entry):
        # Process CSV log entry
        pass

class XMLLogAnalyzer(LogAnalyzer):
    def parse_entry(self, entry):
        import xml.etree.ElementTree as ET
        return ET.fromstring(entry)

    def validate_entry(self, entry):
        try:
            import xml.etree.ElementTree as ET
            ET.fromstring(entry)
            return True
        except ET.ParseError:
            return False

    def process_entry(self, entry):
        # Process XML log entry
        pass

class LogAnalyzerFactory:
    @staticmethod
    def create_analyzer(log_type, config):
        if log_type == 'json':
            return JsonLogAnalyzer(config)
        elif log_type == 'csv':
            return CSVLogAnalyzer(config)
        elif log_type == 'xml':
            return XMLLogAnalyzer(config)
        else:
            raise ValueError("Unsupported log type")

class LogProcessor:
    def __init__(self, analyzer_factory):
        self.analyzer_factory = analyzer_factory
        self.analyzers = {}

    def process_log_file(self, log_type, config, entries):
        if log_type not in self.analyzers:
            self.analyzers[log_type] = self.analyzer_factory.create_analyzer(log_type, config)
        analyzer = self.analyzers[log_type]
        for entry in entries:
            analyzer.add_log_entry(entry)

# Example usage
factory = LogAnalyzerFactory()
processor = LogProcessor(factory)
json_config = {'schema': 'json'}
csv_config = {'schema': 'csv'}
processor.process_log_file('json', json_config, ['{"name": "Alice", "age": 30}', '{"name": "Bob", "age": 25}'])
processor.process_log_file('csv', csv_config, ['name,age\nAlice,30', 'Bob,25'])
```']

