#include <iostream>
#include <thread>
#include <mutex>
#include <unordered_map>
#include <condition_variable>

class KeyValueStore {
public:
    bool Get(const std::string& key, std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = data_.find(key);
        if (it != data_.end()) {
            value = it->second;
            return true;
        }
        return false;
    }

    bool Set(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        data_[key] = value;
        cv_.notify_all();
        return true;
    }

    void WaitUntilUpdated() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this]{ return !data_.empty(); });
    }

private:
    std::unordered_map<std::string, std::string> data_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
};

class GeolocationCache {
public:
    GeolocationCache(KeyValueStore& kv_store) : kv_store_(kv_store) {}

    void UpdateLocation(const std::string& user_id, const std::string& location) {
        kv_store_.Set(user_id, location);
    }

    bool GetLocation(const std::string& user_id, std::string& location) {
        return kv_store_.Get(user_id, location);
    }

private:
    KeyValueStore& kv_store_;
};

class CacheManager {
public:
    CacheManager(GeolocationCache& cache) : cache_(cache) {}

    void Start() {
        for (int i = 0; i < num_threads_; ++i) {
            threads_.emplace_back(&CacheManager::Worker, this);
        }
    }

    void Stop() {
        stop_ = true;
        for (auto& t : threads_) {
            t.join();
        }
    }

private:
    void Worker() {
        while (!stop_) {
            std::string user_id;
            std::string location;
            if (cache_.GetLocation(user_id, location)) {
                // Process the location data
                std::cout << "User ID: " << user_id << ", Location: " << location << std::endl;
            }
        }
    }

private:
    GeolocationCache& cache_;
    int num_threads_ = 10;
    std::vector<std::thread> threads_;
    bool stop_ = false;
};

int main() {
    KeyValueStore kv_store;
    GeolocationCache cache(kv_store);
    CacheManager manager(cache);

    manager.Start();

    // Simulate updates
    for (int i = 0; i < 100; ++i) {
        std::string user_id = "user_" + std::to_string(i);
        std::string location = "lat:34.0522,lng:-118.2437"; // Example coordinates
        cache.UpdateLocation(user_id, location);
    }

    manager.Stop();

    return 0;
}
