# Define a modular, scalable document processing service in a cloud-native environment

import os
import json
from flask import Flask, request, jsonify
from google.cloud import storage
from transformers import pipeline
from PIL import Image
from pdfminer.high_level import extract_text
from cachetools import cached, TTLCache

app = Flask(__name__)

# Configure caching mechanism with eviction policies
cache = TTLCache(maxsize=100, ttl=3600)

@app.route('/process-document', methods=['POST'])
def process_document():
    file = request.files['document']
    document_type = file.filename.split('.')[-1]

    if document_type == 'pdf':
        return extract_pdf_metadata(file)
    elif document_type in ['docx', 'txt']:
        return extract_text_from_file(file)
    elif document_type in ['png', 'jpg']:
        return analyze_image(file)
    elif document_type == 'html':
        return extract_html_metadata(file)
    else:
        return jsonify({"error": "Unsupported file format"}), 415

@cached(cache)
def extract_pdf_metadata(pdf_file):
    # Extract PDF metadata and embedded fonts, images
    text = extract_text(pdf_file)
    metadata = {"text": text}
    return jsonify(metadata)

@cached(cache)
def extract_text_from_file(file):
    # Extract text from Word documents, plain text files
    text = file.read().decode('utf-8')
    return jsonify({"text": text})

@cached(cache)
def analyze_image(image_file):
    # Analyze images and extract metadata
    image = Image.open(image_file)
    metadata = {"width": image.width, "height": image.height}
    return jsonify(metadata)

@cached(cache)
def extract_html_metadata(html_file):
    # Extract metadata from HTML content
    html_text = html_file.read().decode('utf-8')
    pipeline_instance = pipeline("summarization")
    summary = pipeline_instance(html_text)
    metadata = {"summary": summary[0]['summary_text']}
    return jsonify(metadata)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=True)
```

This code snippet defines a modular document processing service using Flask and caching with cachetools. It supports PDF, Word, image, and HTML document formats for metadata extraction. The service uses Google Cloud Storage for file storage, Google Cloud Vision API for image analysis, and transformers library for summarizing HTML content. Error handling and retry mechanisms are included for transient failures. Additionally, a simple user interface can be developed using Flask-Admin or any other suitable framework to manage service settings and monitor performance.

