// Component 1: Filename Manipulation
char* update_filename_extension(const char* filename, const char* preferred_extension) {
    if (filename == NULL || preferred_extension == NULL) {
        return NULL; // Handle null inputs
    }

    size_t len = strlen(filename);
    size_t dot_pos = len;
    for (int i = 0; i < len; i++) {
        if (filename[i] == '.') {
            dot_pos = i;
            break;
        }
    }

    char* new_filename = malloc(len + strlen(preferred_extension) - dot_pos);
    if (new_filename == NULL) {
        return NULL; // Handle memory allocation failure
    }

    strncpy(new_filename, filename, dot_pos);
    strcpy(new_filename + dot_pos, preferred_extension);

    return new_filename;
}

