// Import necessary modules
const express = require('express');
const axios = require('axios');
const CircuitBreaker = require('opossum-circuitbreaker');
const rateLimit = require('express-rate-limit');
const bodyParser = require('body-parser');
const morgan = require('morgan');

// Initialize Express app
const app = express();

// Middleware setup
app.use(bodyParser.json());
app.use(morgan('combined'));

// Configure circuit breaker for a microservice
const microserviceBreaker = new CircuitBreaker(() => axios.get('http://microservice.example.com'), {
  timeout: 2000,
  errorThresholdPercentage: 50,
  resetTimeout: 30000
});

app.get('/api/data', (req, res) => {
  microserviceBreaker.fire()
    .then(response => res.status(200).send(response.data))
    .catch(error => res.status(500).send('Microservice failure'));
});

// Implement rate limiting
const limiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use('/api', limiter);

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

// Feature flags
const featureFlags = {
  newFeatureEnabled: false
};

if (featureFlags.newFeatureEnabled) {
  app.get('/api/new-feature', (req, res) => {
    res.send('New Feature Enabled');
  });
}

// Versioned API
app.get('/api/v1/data', (req, res) => {
  res.status(200).send({ version: 'v1', data: 'Data from v1' });
});

app.get('/api/v2/data', (req, res) => {
  res.status(200).send({ version: 'v2', data: 'Data from v2' });
});

// Health checks
app.get('/health', (req, res) => {
  const status = {
    microservice: microserviceBreaker.isOpen() ? 'Down' : 'Up',
    rateLimiting: limiter.stack.length === 0 ? 'OK' : 'Warning'
  };
  res.status(200).json(status);
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`API Gateway running on port ${PORT}`);
});
