import os
import json
from typing import Dict, Any, Union, Optional
from requests.exceptions import RequestException

class ConfigManager:
    def __init__(self):
        self._config = {}
        self._sources = {
            'env': os.environ,
            'api': self._fetch_api_config,
            'file': self._load_file_config
        }

    def load(self) -> None:
        for source, loader in self._sources.items():
            try:
                config_part = loader()
                if config_part:
                    self._merge_configs(config_part)
            except Exception as e:
                print(f"Failed to load configuration from {source}: {e}")

    def get_config(self, key: str) -> Any:
        return self._config.get(key)

    def _fetch_api_config(self) -> Dict[str, Any]:
        # Simulate fetching config from an API
        try:
            response = requests.get('https://api.example.com/config')
            response.raise_for_status()
            return response.json()
        except RequestException as e:
            print(f"Failed to fetch configuration from API: {e}")
            return {}

    def _load_file_config(self) -> Dict[str, Any]:
        # Simulate loading config from a file
        try:
            with open('config.json', 'r') as file:
                return json.load(file)
        except FileNotFoundError:
            print("Configuration file not found.")
            return {}
        except json.JSONDecodeError as e:
            print(f"Failed to decode JSON in configuration file: {e}")
            return {}

    def _merge_configs(self, new_config: Dict[str, Any]) -> None:
        for key, value in new_config.items():
            if key in self._config and isinstance(value, dict):
                self._merge_configs({key: self._config[key]})
            else:
                self._config[key] = value

if __name__ == "__main__":
    config_manager = ConfigManager()
    config_manager.load()
    print(config_manager.get_config('api_key'))
```

