            printf("Deadlock detected. Recovering...\n");
            sem_post(&db_semaphore);
        }

        sleep(60); // Check every minute
    }

    return NULL;
}

void signalHandler(int signum) {
    printf("Received signal %d\n", signum);
    exit(signum);
}

int main() {
    pthread_t db_thread, health_check_thread;
    ClinicStatusUpdate update = {1, "Open", "192.168.1.1", time(NULL)};

    // Initialize semaphore and mutex
    sem_init(&db_semaphore, 0, DB_MAX_CONNECTIONS);
    pthread_mutex_init(&cache_mutex, NULL);

    // Set up signal handler for graceful exit
    signal(SIGINT, signalHandler);

    // Create threads for database update and health check
    pthread_create(&db_thread, NULL, updateClinicStatus, &update);
    pthread_create(&health_check_thread, NULL, healthCheck, NULL);

    // Wait for threads to complete (not applicable in this example)

