Json::Value sendDataSecurely(const Json::Value& input) {
    // Simulate secure data transmission using TLS/SSL
    std::string data = input.asString();

    std::string encryptedData = encryptData(data);
    if (encryptedData.empty()) {
        return {"success": false, "error": "Encryption failed"};
    }

    Json::Value output;
    output["success"] = true;
    output["encryptedData"] = encryptedData;

    return output;
}

std::string encryptData(const std::string& data) {
    // Simulate encryption using OpenSSL
    unsigned char key[32], iv[16];
    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, sizeof(iv));

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    int len;
    unsigned char ciphertext[data.length() + 16];
    EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*)data.c_str(), data.length());
    int ciphertext_len = len;

    EVP_EncryptFinal_ex(ctx, ciphertext + len, &len);
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    // Base64 encode the encrypted data
    return base64_encode(ciphertext, ciphertext_len);
}

std::string base64_encode(const unsigned char* in, size_t length) {
    BIO* bio, * b64;
    BUF_MEM* bufferPtr;

    b64 = BIO_new(BIO_f_base64());
    bio = BIO_new(BIO_s_mem());
    bio = BIO_push(b64, bio);

    BIO_write(bio, in, length);
    BIO_flush(bio);
    BIO_get_mem_ptr(bio, &bufferPtr);
    BIO_set_close(bio, BIO_NOCLOSE);
    BIO_free_all(bio);

    std::string result(bufferPtr->data, bufferPtr->length);
    OPENSSL_free(bufferPtr->data);
    return result;
}

