### C Function Refactoring for Thread Safety

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int value;
    time_t timestamp;
    char key[256];
} Record;

long* offsets;
int* keys;
Record** records;
size_t count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* bulk_record_initializer(void* arg) {
    size_t n = (size_t)arg;

    pthread_mutex_lock(&mutex);

    // Allocate memory
    offsets = realloc(offsets, n * sizeof(long));
    keys = realloc(keys, n * sizeof(int));
    records = realloc(records, n * sizeof(Record*));

    if (!offsets || !keys || !records) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Populate fields with random values
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = rand() % 1000000L;
        keys[i] = rand();

        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        records[i]->value = rand() % 1000;
        records[i]->timestamp = time(NULL);
        snprintf(records[i]->key, sizeof(records[i]->key), "key%d", i);
    }

    count = n;

    pthread_mutex_unlock(&mutex);

    return NULL;
}
```

