#define MAX_FILES 1024
#define METADATA_SERVICE_URL "http://example.com/metadata"
#define LOG_FILE "rename_log.txt"

typedef struct {
    char directory_path[256];
    int file_count;
    pthread_mutex_t lock;
} DirectoryInfo;

void log_error(const char* message) {
    FILE* log = fopen(LOG_FILE, "a");
    if (log) {
        time_t now = time(NULL);
        fprintf(log, "%s: %s\n", ctime(&now), message);
        fclose(log);
    }
}

void rename_files(DirectoryInfo* dir_info) {
    DIR* dir;
    struct dirent* entry;
    char old_path[512], new_path[512];
    int file_index = 0;

    if ((dir = opendir(dir_info->directory_path)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG) {
                pthread_mutex_lock(&dir_info->lock);
                snprintf(old_path, sizeof(old_path), "%s/%s", dir_info->directory_path, entry->d_name);
                time_t now = time(NULL);
                struct tm* tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", tm_info);

                do {
                    file_index++;
                    snprintf(new_path, sizeof(new_path), "%s/%s_%d_%s", dir_info->directory_path, entry->d_name, file_index, timestamp);
                } while (access(new_path, F_OK) == 0); // Check if the new path already exists

                if (rename(old_path, new_path) != 0) {
                    log_error("Failed to rename file: %s", old_path);
                }
                pthread_mutex_unlock(&dir_info->lock);

                // Simulate metadata update
                printf("Updating metadata for %s\n", new_path);
            }
        }
        closedir(dir);
    } else {
        log_error("Unable to open directory");
    }
}

void* process_directory(void* arg) {
    DirectoryInfo* dir_info = (DirectoryInfo*)arg;
    rename_files(dir_info);
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return 1;
    }

    DirectoryInfo dir_info = { .directory_path = argv[1], .file_count = 0 };
    pthread_mutex_init(&dir_info.lock, NULL);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, process_directory, &dir_info) != 0) {
        log_error("Failed to create thread");
        return 1;
    }

    pthread_join(thread_id, NULL);
    pthread_mutex_destroy(&dir_info.lock);

    printf("Processing complete.\n");
    return 0;
}
```

