void renameFile(char* fileName) {
    char digits[3];
    char fileType[10];

    // Assuming file type is determined by the last three characters
    strncpy(fileType, &fileName[strlen(fileName) - 3], sizeof(fileType));

    // Counting digits in the filename
    int digitCount = 0;
    for (int i = 0; i < strlen(fileName); i++) {
        if (isdigit(fileName[i])) {
            digitCount++;
        }
    }

    // Formatting digits and appending to the new file name
    sprintf(digits, "%d", digitCount);
    strcat(fileName, "_");
    strcat(fileName, digits);
    strcat(fileName, ".");
    strcat(fileName, fileType);
}
