const axios = require('axios');
const { Queue } = require('queue');

class DataAggregationService {
  constructor(apiEndpoints, maxConcurrency) {
    this.apiEndpoints = apiEndpoints;
    this.maxConcurrency = maxConcurrency;
    this.queue = new Queue({ concurrency: maxConcurrency });
  }

  async fetchUserProfile(userId) {
    const results = [];
    for (const endpoint of this.apiEndpoints) {
      try {
        const response = await axios.get(`${endpoint}/${userId}`);
        results.push(response.data);
      } catch (error) {
        if (axios.isCancel(error)) {
          console.log('Request canceled', error.message);
        } else {
          console.error(`Error fetching user profile from ${endpoint}:`, error);
        }
      }
    }

    // Merge and deduplicate results based on overlapping identifiers
    const mergedResults = {};
    results.forEach(result => {
      Object.keys(result).forEach(key => {
        if (!mergedResults[key]) {
          mergedResults[key] = result[key];
        }
      });
    });

    return mergedResults;
  }

  async handleRequest(userId) {
    try {
      const profile = await this.fetchUserProfile(userId);
      console.log(`User profile for ${userId}:`, profile);
    } catch (error) {
      console.error('Failed to fetch user profile:', error);
    }
  }

  start() {
    // Simulate incoming requests
    setInterval(() => {
      const userId = Math.floor(Math.random() * 1000).toString();
      this.queue.push(this.handleRequest.bind(this, userId));
    }, 500);
  }
}

// Usage example
const apiEndpoints = [
  'https://api.example1.com/users',
  'https://api.example2.com/users',
  'https://api.example3.com/users'
];
const maxConcurrency = 10;
const service = new DataAggregationService(apiEndpoints, maxConcurrency);
service.start();
```

