void* fetch_keys(void* arg) {
    // Simulate fetching unique keys from an external data source
    for (int i = 0; i < MAX_KEYS; i++) {
        sem_wait(&semaphore);
        if (record_count >= MAX_RECORDS) break;
        records[record_count].value = rand() % 100; // Example random value generation
        record_count++;
        sem_post(&semaphore);
    }
    return NULL;
}

void* process_records(void* arg) {
    FILE *log_file = fopen("output.log", "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < record_count; i++) {
        fprintf(log_file, "Record %d: Value = %d\n", i, records[i].value);
    }
    fclose(log_file);

    return NULL;
}

int main() {
    pthread_t key_fetcher, record_processor;
    sem_init(&semaphore, 0, 1); // Initialize semaphore for mutex-like behavior

    if (pthread_create(&key_fetcher, NULL, fetch_keys, NULL) != 0) {
        perror("Failed to create key fetcher thread");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&record_processor, NULL, process_records, NULL) != 0) {
        perror("Failed to create record processor thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(key_fetcher, NULL);
    pthread_join(record_processor, NULL);

    sem_destroy(&semaphore); // Clean up semaphore

    return 0;
}
