void* process_records(void *arg) {
    int batch_size = *(int*)arg;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    Record records[BATCH_SIZE];
    int i, j;

    for (i = 0; i < MAX_RECORDS / batch_size; i++) {
        pthread_mutex_lock(&lock);
        for (j = 0; j < batch_size && (batch_size * i + j) < MAX_RECORDS; j++) {
            records[j].key = batch_size * i + j;
            records[j].offset = batch_size * i + j * 100;
            if (!validate_record(&records[j])) {
                pthread_mutex_unlock(&lock);
                fprintf(stderr, "Validation failed for record %d\n", j);
                return NULL;
            }
        }
        pthread_mutex_unlock(&lock);

        // Process records here
        printf("Processed batch %d\n", i + 1);
    }

    return NULL;
}

int main() {
    int batch_size = BATCH_SIZE;
    pthread_t threads[batch_size];
    int thread_ids[batch_size];

    for (int i = 0; i < batch_size; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, process_records, &thread_ids[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return 1;
        }
    }

