@SpringBootApplication
@EnableDiscoveryClient
public class TransactionProcessingService {

    public static void main(String[] args) {
        SpringApplication.run(TransactionProcessingService.class, args);
    }

    @Autowired
    private PaymentGatewayService paymentGatewayService;

    @Autowired
    private BillingSystemService billingSystemService;

    @Autowired
    private FraudDetectionService fraudDetectionService;

    @Autowired
    private RateLimiter rateLimiter;

    @Autowired
    private CacheManager cacheManager;

    @PostMapping("/processTransaction")
    public ResponseEntity<String> processTransaction(@RequestBody TransactionRequest request) {
        if (!rateLimiter.tryAcquire()) {
            return new ResponseEntity<>("Rate limit exceeded", HttpStatus.TOO_MANY_REQUESTS);
        }

        try {
            if (fraudDetectionService.isFraudulent(request)) {
                return new ResponseEntity<>("Fraud detected", HttpStatus.PAYMENT_REQUIRED);
            }

            TransactionResponse response = paymentGatewayService.processTransaction(request);

            cacheManager.updateCache(request, response);

            billingSystemService.chargeCustomer(request, response);

            return new ResponseEntity<>(response.getMessage(), HttpStatus.OK);
        } catch (ApiThrottlingException e) {
            // Handle retry logic
        } catch (ApiFailureException e) {
            // Retry later with exponential backoff
        } catch (FraudDetectionException e) {
            // Log and send alert
        } catch (Exception e) {
            // Log error and retry later
        }

        return new ResponseEntity<>("Transaction failed", HttpStatus.INTERNAL_SERVER_ERROR);
    }
}
