    if (strcmp(argv[1], "ecb") == 0) {
        mode = ECB;
    } else if (strcmp(argv[1], "cbc") == 0) {
        mode = CBC;
    } else if (strcmp(argv[1], "gcm") == 0) {
        mode = GCM;
    } else if (strcmp(argv[1], "ctr") == 0) {
        mode = CTR;
    }
    // Initialize key management service
    KeyManagementService *key_service = init_key_management_service();
    if (!key_service) {
        return 1;
    }
    // Initialize cryptographic library
    CryptographicLibrary *lib = init_library(mode, key_service);
    if (!lib) {
        destroy_key_management_service(key_service);
        return 1;
    }
    // Perform encryption/decryption based on command-line arguments and options
    // Destroy cryptographic library and key management service
    destroy_library(lib);
    destroy_key_management_service(key_service);
    return 0;
}
