#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_THREADS 20

typedef struct {
    char *filename;
    int thread_id;
} FileProcessingData;

void* process_file(void* arg) {
    FileProcessingData *data = (FileProcessingData*)arg;
    // Simulate file processing
    printf("Thread %d is processing %s\n", data->thread_id, data->filename);
    sleep(2); // Simulate processing time
    free(data);
    return NULL;
}

void process_files(const char* filenames[], int num_files) {
    pthread_t threads[MAX_THREADS];
    FileProcessingData *data[MAX_THREADS];

    for (int i = 0; i < num_files; ++i) {
        if (i >= MAX_THREADS) {
            printf("Cannot handle more than %d files concurrently.\n", MAX_THREADS);
            return;
        }
        data[i] = malloc(sizeof(FileProcessingData));
        data[i]->filename = strdup(filenames[i]);
        data[i]->thread_id = i;

        if (pthread_create(&threads[i], NULL, process_file, data[i]) != 0) {
            perror("Failed to create thread");
            free(data[i]);
        }
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    const char* output_file = NULL;
    int parallel_threads = 4;
    char** filenames = NULL;
    int num_files = 0;

    while ((opt = getopt(argc, argv, "hcs:o:p:")) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s [options] file1 [file2 ...]\n", argv[0]);
                printf("Options:\n");
                printf("  -h, --help\tShow this help message\n");
                printf("  -cs\tEnable compression\n");
                printf("  -o output_file\tSpecify the output file\n");
                printf("  -p parallel_threads\tSpecify the number of parallel threads (default: 4)\n");
                return 0;
            case 'c':
                // Enable compression
                break;
            case 's':
                output_file = optarg;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'p':
                parallel_threads = atoi(optarg);
                if (parallel_threads <= 0 || parallel_threads > MAX_THREADS) {
                    fprintf(stderr, "Invalid number of parallel threads.\n");
                    return 1;
                }
                break;
            default:
                printf("Unknown option: %c\n", optopt);
                return 1;
        }
    }

    for (int i = optind; i < argc; ++i) {
        filenames = realloc(filenames, (num_files + 1) * sizeof(char*));
        filenames[num_files++] = argv[i];
    }

    if (num_files == 0) {
        fprintf(stderr, "No files specified.\n");
        return 1;
    }

    process_files(filenames, num_files);

    free(filenames);
    return 0;
}
