#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_CHILD_PROCESSES 100

typedef struct {
    int pid;
    char service_provider[256];
    char api_key[256];
} ChildProcess;

ChildProcess children[MAX_CHILD_PROCESSES];
int child_count = 0;

void start_child_process(const char *service_provider, const char *api_key) {
    if (child_count >= MAX_CHILD_PROCESSES) {
        fprintf(stderr, "Maximum number of child processes reached\n");
        return;
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Child process
        execlp("./child_process", "./child_process", service_provider, api_key, NULL);
        perror("execlp");
        exit(EXIT_FAILURE);
    } else {
        children[child_count].pid = pid;
        strncpy(children[child_count].service_provider, service_provider, sizeof(children[child_count].service_provider));
        strncpy(children[child_count].api_key, api_key, sizeof(children[child_count].api_key));
        child_count++;
    }
}

void wait_for_child_processes() {
    for (int i = 0; i < child_count; i++) {
        int status;
        pid_t pid = waitpid(children[i].pid, &status, 0);
        if (pid == -1) {
            perror("waitpid");
            exit(EXIT_FAILURE);
        }
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            fprintf(stderr, "Child process %d terminated with status %d\n", pid, WEXITSTATUS(status));
        } else {
            printf("Child process %d terminated successfully\n", pid);
        }
    }
}

int main() {
    // Start child processes
    start_child_process("provider1", "api_key1");
    start_child_process("provider2", "api_key2");

    // Wait for child processes to complete
    wait_for_child_processes();

    return 0;
}
