#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <sqlite3.h>
#include <amqp.h>

#define MAX_CLIENTS 100
#define BUFFER_SIZE 256

typedef struct {
    int* data;
    size_t length;
    pthread_mutex_t lock;
} SharedArray;

SharedArray shared_array = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void* process_data(void* arg) {
    int client_socket = *(int*)arg;
    free(arg);

    char buffer[BUFFER_SIZE];
    while (1) {
        ssize_t bytes_read = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_read <= 0) break;

        buffer[bytes_read] = '\0';
        int number = atoi(buffer);

        pthread_mutex_lock(&shared_array.lock);
        shared_array.data = realloc(shared_array.data, ++shared_array.length * sizeof(int));
        shared_array.data[shared_array.length - 1] = number;
        pthread_mutex_unlock(&shared_array.lock);

        // TODO: Integrate with message broker and real-time analytics platform
    }

    close(client_socket);
    return NULL;
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(12345);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int* client_socket = malloc(sizeof(int));
        *client_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);

        pthread_t thread;
        pthread_create(&thread, NULL, process_data, client_socket);
    }

    return 0;
}
