class ConnectionPoolManager {
public:
    using Connection = std::shared_ptr<void>; // Placeholder for database connection type

    ConnectionPoolManager(size_t initialSize, size_t maxSize) 
        : pool(initialSize), maxPoolSize(maxSize) {}

    Connection getConnection() {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return !pool.empty(); });
        Connection conn = pool.front();
        pool.pop();
        return conn;
    }

    void releaseConnection(Connection conn) {
        std::lock_guard<std::mutex> lock(mutex);
        if (pool.size() < maxPoolSize) {
            pool.push(conn);
            cv.notify_one();
        }
    }

private:
    std::queue<Connection> pool;
    size_t maxPoolSize;
    std::mutex mutex;
    std::condition_variable cv;
};

// Example usage
int main() {
    ConnectionPoolManager pool(5, 10);

    auto conn = pool.getConnection();
    // Use the connection for database operations

    pool.releaseConnection(conn);

    return 0;
}
