// Head of the linked list to hold all algorithms
Algorithm *algorithmList = NULL;

// Function to add an algorithm to the list
void addAlgorithm(const char *name, void (*hashFunc)(unsigned char *, unsigned int), void (*cipherFunc)(unsigned char *, unsigned char *)) {
    Algorithm *newAlgo = (Algorithm *)malloc(sizeof(Algorithm));
    strcpy(newAlgo->name, name);
    newAlgo->hashFunction = hashFunc;
    newAlgo->cipherFunction = cipherFunc;
    newAlgo->next = algorithmList;
    algorithmList = newAlgo;
}

// Function to remove an algorithm from the list
void removeAlgorithm(const char *name) {
    Algorithm *current = algorithmList;
    Algorithm *previous = NULL;

    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            if (previous == NULL) {
                algorithmList = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to find an algorithm by name
Algorithm *findAlgorithm(const char *name) {
    Algorithm *current = algorithmList;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
