// Define a structure for a cryptographic algorithm
typedef struct CryptoAlgorithm {
    char* name;
    void (*encrypt)(char*, char*);
    void (*decrypt)(char*, char*);
    struct CryptoAlgorithm* next;
} CryptoAlgorithm;

// Global head of the list of algorithms
CryptoAlgorithm* head = NULL;

// Function to add an algorithm to the list
void addAlgorithm(char* name, void (*encrypt)(char*, char*), void (*decrypt)(char*, char*)) {
    CryptoAlgorithm* newAlg = (CryptoAlgorithm*)malloc(sizeof(CryptoAlgorithm));
    if (newAlg == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newAlg->name = strdup(name);
    newAlg->encrypt = encrypt;
    newAlg->decrypt = decrypt;
    newAlg->next = head;
    head = newAlg;
}

// Function to remove an algorithm from the list
void removeAlgorithm(char* name) {
    CryptoAlgorithm** current = &head;
    while (*current != NULL) {
        if (strcmp((*current)->name, name) == 0) {
            CryptoAlgorithm* temp = *current;
            *current = (*current)->next;
            free(temp->name);
            free(temp);
            break;
        }
        current = &(*current)->next;
    }
}

// Function to encrypt data using a specific algorithm
void encryptData(char* name, char* data) {
    CryptoAlgorithm* current = head;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            current->encrypt(data, data);
            return;
        }
        current = current->next;
    }
    fprintf(stderr, "Algorithm not found: %s\n", name);
}

