#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

// Define the maximum key length for demonstration purposes
#define MAX_KEY_LENGTH 32

// Function to generate a random key using OpenSSL
int generate_random_key(unsigned char *key, int key_length) {
    return RAND_bytes(key, key_length);
}

// Function to encrypt data using a symmetric encryption algorithm
int encrypt_data(const unsigned char *plaintext, int plaintext_len,
                 const unsigned char *key, const unsigned char *iv,
                 unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len, ciphertext_len;

    // Create and initialize the context
    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto end;

    // Update the ciphertext
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        goto end;
    ciphertext_len = len;

    // Finalize the encryption
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        goto end;
    ciphertext_len += len;

    end:
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

// Function to decrypt data using a symmetric encryption algorithm
int decrypt_data(const unsigned char *ciphertext, int ciphertext_len,
                 const unsigned char *key, const unsigned char *iv,
                 unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len, plaintext_len;

    // Create and initialize the context
    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        goto end;

    // Update the plaintext
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        goto end;
    plaintext_len = len;

    // Finalize the decryption
    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len))
        goto end;
    plaintext_len += len;

    end:
    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

// Example usage of the encryption and decryption functions
int main() {
    unsigned char key[MAX_KEY_LENGTH], iv[16];
    unsigned char plaintext[] = "This is a secret message";
    unsigned char ciphertext[128], decryptedtext[128];
    int ciphertext_len, decryptedtext_len;

    // Generate a random key and IV
    if (generate_random_key(key, MAX_KEY_LENGTH) != 1)
        return -1;
    if (RAND_bytes(iv, sizeof(iv)) != 1)
        return -1;

    // Encrypt the plaintext
    ciphertext_len = encrypt_data(plaintext, strlen((char *)plaintext),
                                  key, iv, ciphertext);
    if (ciphertext_len < 0) {
        printf("Encryption failed\n");
        return -1;
    }

    // Decrypt the ciphertext
    decryptedtext_len = decrypt_data(ciphertext, ciphertext_len,
                                       key, iv, decryptedtext);
    if (decryptedtext_len < 0) {
        printf("Decryption failed\n");
        return -1;
    }
    decryptedtext[decryptedtext_len] = '\0';

    // Print the results
    printf("Plaintext: %s\n", plaintext);
    printf("Ciphertext: ");
    for (int i = 0; i < ciphertext_len; i++)
        printf("%02x", ciphertext[i]);
    printf("\n");
    printf("Decryptedtext: %s\n", decryptedtext);

    return 0;
}
