#include <iostream>
#include <unordered_map>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>

class KeyValueStore {
private:
    std::unordered_map<std::string, std::pair<std::string, size_t>> store;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void set(const std::string& key, const std::string& value, size_t ttl) {
        std::lock_guard<std::mutex> lock(mtx);
        store[key] = {value, ttl};
        cv.notify_one();
    }

    bool get(const std::string& key, std::string& value) {
        std::unique_lock<std::mutex> lock(mtx);
        while (true) {
            if (store.find(key) == store.end()) {
                return false;
            }
            auto& entry = store[key];
            if (entry.second > 0 && std::this_thread::sleep_until(std::chrono::system_clock::now() + std::chrono::seconds(entry.second)) != std::cv_status::timeout) {
                value = entry.first;
                store.erase(key);
                return true;
            } else if (entry.second == 0) {
                value = entry.first;
                return true;
            }
        }
    }

    void remove(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        store.erase(key);
        cv.notify_one();
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mtx);
        return store.size();
    }
};

int main() {
    KeyValueStore kv_store;
    std::thread t1([&kv_store]() {
        kv_store.set("key1", "value1", 5);
    });
    std::thread t2([&kv_store]() {
        std::string value;
        if (kv_store.get("key1", value)) {
            std::cout << "Value: " << value << std::endl;
        }
    });

    t1.join();
    t2.join();

    return 0;
}
