    if (!EVP_EncryptUpdate(ctx->ctx, *ciphertext, ciphertext_len, plaintext, plaintext_len)) {
        // Handle error
    }
    return EVP_EncryptFinal_ex(ctx->ctx, (*ciphertext) + *ciphertext_len, ciphertext_len);
}

// Function to perform decryption
int decrypt_data(EncryptionContext *ctx, const unsigned char *ciphertext, int ciphertext_len, unsigned char **plaintext, int *plaintext_len) {
    if (!EVP_DecryptUpdate(ctx->ctx, *plaintext, plaintext_len, ciphertext, ciphertext_len)) {
        // Handle error
    }
    return EVP_DecryptFinal_ex(ctx->ctx, (*plaintext) + *plaintext_len, plaintext_len);
}

// Function to free encryption context
void free_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
