impl GrammarProcessor {
    fn new(repo_path: &str) -> Result<Self, git2::Error> {
        let repo = Repository::open(repo_path)?;
        Ok(GrammarProcessor { repo })
    }

    fn process_files(&self, output_dir: &str) -> Result<(), Box<dyn std::error::Error>> {
        let status = self.repo.statuses(None)?;

        for entry in status.iter() {
            match entry.status() {
                Status::INDEX_NEW => {
                    let path = entry.path().unwrap();
                    if path.extension().and_then(|ext| ext.to_str()) == Some("ll") {
                        self.process_file(&path, output_dir)?;
                    }
                }
                _ => {}
            }
        }

        Ok(())
    }

    fn process_file(&self, file_path: &Path, output_dir: &str) -> Result<(), Box<dyn std::error::Error>> {
        let content = fs::read_to_string(file_path)?;
        let optimized_ir = self.optimize_llvm_ir(&content)?;

        let module_name = file_path.file_stem().and_then(|stem| stem.to_str()).unwrap();
        let output_file = Path::new(output_dir).join(format!("{}.ll", module_name));

        fs::write(output_file, optimized_ir)?;

        Ok(())
    }

    fn optimize_llvm_ir(&self, ir: &str) -> Result<String, Box<dyn std::error::Error>> {
        // Placeholder for LLVM IR optimization logic
        let context = Context::create();
        let module = Module::new("optimized_module", &context);
        // Parse IR and apply optimizations
        Ok(module.to_string())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    env_logger::init();

    let repo_path = "/path/to/repo";
    let output_dir = "/path/to/output";

