#include <iostream>
#include <thread>
#include <mutex>
#include <random>
#include <fstream>
#include <string>

class MersenneTwisterGenerator {
public:
    static MersenneTwisterGenerator& getInstance(unsigned seed = 42) {
        std::lock_guard<std::mutex> lock(mutex);
        if (!instance) {
            instance = new MersenneTwisterGenerator(seed);
        }
        return *instance;
    }

    ~MersenneTwisterGenerator() {
        delete instance;
        instance = nullptr;
    }

    int generateRandomInt(int min, int max) {
        std::lock_guard<std::mutex> lock(mutex);
        std::uniform_int_distribution<int> dist(min, max);
        return dist(generator);
    }

    double generateRandomDouble(double min, double max) {
        std::lock_guard<std::mutex> lock(mutex);
        std::uniform_real_distribution<double> dist(min, max);
        return dist(generator);
    }

    bool generateRandomBool() {
        std::lock_guard<std::mutex> lock(mutex);
        std::bernoulli_distribution dist(0.5);
        return dist(generator);
    }

    void reset(unsigned seed) {
        std::lock_guard<std::mutex> lock(mutex);
        generator.seed(seed);
    }

private:
    MersenneTwisterGenerator(unsigned seed) : generator(seed) {}
    static MersenneTwisterGenerator* instance;
    std::mt19937 generator;
    static std::mutex mutex;

    MersenneTwisterGenerator(const MersenneTwisterGenerator&) = delete;
    void operator=(const MersenneTwisterGenerator&) = delete;
};

MersenneTwisterGenerator* MersenneTwisterGenerator::instance = nullptr;
std::mutex MersenneTwisterGenerator::mutex;

int main() {
    // Example usage
    unsigned seed = 12345;
    MersenneTwisterGenerator& generator = MersenneTwisterGenerator::getInstance(seed);

    for (int i = 0; i < 10; ++i) {
        std::cout << "Random int: " << generator.generateRandomInt(1, 100) << "\n";
        std::cout << "Random double: " << generator.generateRandomDouble(0.0, 1.0) << "\n";
        std::cout << "Random bool: " << (generator.generateRandomBool() ? "true" : "false") << "\n";
    }

    return 0;
}
```

