    public async Task ExecuteParameterizedQueryAsync(string connectionString, string sqlCommand, List<SqlParameter> parameters = null, Action<DataTable> callback = null)
    {
        try
        {
            using (var connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();
                using (var command = new SqlCommand(sqlCommand, connection))
                {
                    if (parameters != null)
                    {
                        command.Parameters.AddRange(parameters.ToArray());
                    }

                    var result = await command.ExecuteReaderAsync(CommandBehavior.Default);
                    var dataTable = new DataTable();
                    dataTable.Load(result);

                    if (callback != null)
                    {
                        callback(dataTable);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw; // Re-throw the exception to be handled by the caller
        }
    }

