public class WeatherService : IWeatherService
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly IOptions<WeatherSettings> _settings;
    private readonly IAnalyticsService _analyticsService;

    public WeatherService(HttpClient httpClient, IDistributedCache cache, IOptions<WeatherSettings> settings, IAnalyticsService analyticsService)
    {
        _httpClient = httpClient;
        _cache = cache;
        _settings = settings;
        _analyticsService = analyticsService;
    }

    public async Task<WeatherData> GetWeatherAsync(string location)
    {
        var cachedWeather = await _cache.GetStringAsync($"weather:{location}");
        if (cachedWeather != null)
        {
            return JsonConvert.DeserializeObject<WeatherData>(cachedWeather);
        }

        try
        {
            var apiResponse = await _httpClient.GetAsync($"{_settings.Value.ApiUrl}/{location}");
            apiResponse.EnsureSuccessStatusCode();
            var weatherData = await apiResponse.Content.ReadAsAsync<WeatherData>();
            await _cache.SetStringAsync($"weather:{location}", JsonConvert.SerializeObject(weatherData), new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(_settings.Value.CacheDurationInMinutes)
            });

            _analyticsService.TrackWeatherRequest(location);
            return weatherData;
        }
        catch (HttpRequestException)
        {
            // Fallback logic for local cache or historical data
            var fallbackData = GetFallbackWeatherData(location);
            return fallbackData;
        }
    }

    private WeatherData GetFallbackWeatherData(string location)
    {
        // Implement logic to retrieve fallback weather data from local cache or historical data
        return new WeatherData { Location = location, Temperature = 20.0 };
    }

