using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

public class DynamicRESTClient : IDisposable
{
    private readonly HttpClient _httpClient;
    private readonly ILogger _logger;
    private readonly ICacheManager _cacheManager;
    private readonly IConfigurationService _configurationService;

    public DynamicRESTClient(ILogger logger, ICacheManager cacheManager, IConfigurationService configurationService)
    {
        _httpClient = new HttpClient();
        _logger = logger;
        _cacheManager = cacheManager;
        _configurationService = configurationService;
    }

    public async Task<T> GetAsync<T>(string url, string apiVersion)
    {
        var cachedResponse = await _cacheManager.GetCachedData<T>(url);
        if (cachedResponse != null)
            return cachedResponse;

        var response = await MakeRequestAsync(url, HttpMethod.Get, apiVersion);
        var result = await response.Content.ReadAsAsync<T>();

        await _cacheManager.CacheData(url, result);
        return result;
    }

    public async Task PostAsync<T>(string url, T data, string apiVersion)
    {
        var response = await MakeRequestAsync(url, HttpMethod.Post, apiVersion, data);
        if (!response.IsSuccessStatusCode)
            _logger.LogError(response.ReasonPhrase);

        _cacheManager.InvalidateCache(url);
    }

    public async Task PutAsync<T>(string url, T data, string apiVersion)
    {
        var response = await MakeRequestAsync(url, HttpMethod.Put, apiVersion, data);
        if (!response.IsSuccessStatusCode)
            _logger.LogError(response.ReasonPhrase);

        _cacheManager.InvalidateCache(url);
    }

    public async Task DeleteAsync(string url, string apiVersion)
    {
        var response = await MakeRequestAsync(url, HttpMethod.Delete, apiVersion);
        if (!response.IsSuccessStatusCode)
            _logger.LogError(response.ReasonPhrase);

        _cacheManager.InvalidateCache(url);
    }

    private async Task<HttpResponseMessage> MakeRequestAsync(string url, HttpMethod method, string apiVersion, object data = null)
    {
        var fullUrl = $"{_configurationService.BaseUrl}/{apiVersion}{url}";
        var request = new HttpRequestMessage(method, fullUrl);

        if (data != null)
        {
            request.Content = new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json");
            request.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
        }

        try
        {
            var response = await _httpClient.SendAsync(request);
            if (!response.IsSuccessStatusCode)
                _logger.LogError(response.ReasonPhrase);

            return response;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex.Message);
            throw;
        }
    }

    public void Dispose()
    {
        _httpClient.Dispose();
    }
}
