#include <iostream>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <condition_variable>

class KeyValueStore {
    std::unordered_map<std::string, std::pair<std::string, time_t>> cache;
    mutable std::mutex mutex;

public:
    bool get(const std::string& key, std::string& value) const {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it != cache.end() && time(nullptr) < it->second.second) {
            value = it->second.first;
            return true;
        }
        return false;
    }

    void set(const std::string& key, const std::string& value, time_t ttl) {
        std::lock_guard<std::mutex> lock(mutex);
        cache[key] = {value, time(nullptr) + ttl};
    }

    void evictExpired() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::lock_guard<std::mutex> lock(mutex);
            for (auto it = cache.begin(); it != cache.end();) {
                if (time(nullptr) >= it->second.second) {
                    it = cache.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }
};

int main() {
    KeyValueStore store;
    std::thread evictionThread(&KeyValueStore::evictExpired, &store);

    // Simulate concurrent requests
    auto reader = [](const KeyValueStore& store) {
        while (true) {
            std::string value;
            if (store.get("key", value)) {
                std::cout << "Read: " << value << std::endl;
            } else {
                std::cout << "Not found" << std::endl;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
        }
    };

    auto writer = [](KeyValueStore& store) {
        while (true) {
            store.set("key", "value", 10);
            std::cout << "Written: value" << std::endl;
            std::this_thread::sleep_for(std::chrono::seconds(2));
        }
    };

    std::thread readerThread(reader, std::ref(store));
    std::thread writerThread(writer, std::ref(store));

    readerThread.join();
    writerThread.join();
    evictionThread.join();

    return 0;
}
