import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class FinancialTransactionProcessor {
    private final ConcurrentHashMap<String, Transaction> transactionCache;
    private final ScheduledExecutorService cacheRefreshScheduler;
    private final ExternalAPIService externalAPIService;
    private final ConnectionPool connectionPool;
    private final RateLimiter rateLimiter;

    public FinancialTransactionProcessor() {
        this.transactionCache = new ConcurrentHashMap<>();
        this.cacheRefreshScheduler = Executors.newScheduledThreadPool(1);
        this.externalAPIService = new ExternalAPIService();
        this.connectionPool = new ConnectionPool();
        this.rateLimiter = new RateLimiter();

        // Schedule TTL-based cache refreshes
        cacheRefreshScheduler.scheduleAtFixedRate(this::refreshCache, 0, 60, TimeUnit.SECONDS);

        // Initialize connection pool with dynamic resource allocation
        connectionPool.initialize();
    }

    public void processTransaction(Transaction transaction) {
        if (rateLimiter.isAllowed()) {
            String transactionId = transaction.getId();
            Transaction cachedTransaction = transactionCache.get(transactionId);
            if (cachedTransaction == null || isCacheStale(cachedTransaction)) {
                cachedTransaction = externalAPIService.fetchTransaction(transactionId, connectionPool.getConnection());
                if (cachedTransaction != null) {
                    transactionCache.put(transactionId, cachedTransaction);
                }
            }

            // Process the transaction
            processBusinessLogic(cachedTransaction);

            // Update cache with new data if available
            Transaction updatedTransaction = externalAPIService.fetchUpdatedTransaction(transactionId, connectionPool.getConnection());
            if (updatedTransaction != null) {
                transactionCache.put(transactionId, updatedTransaction);
            }
        } else {
            handleRateLimiting();
        }
    }

    private void refreshCache() {
        for (String key : transactionCache.keySet()) {
            Transaction transaction = externalAPIService.fetchTransaction(key, connectionPool.getConnection());
            if (transaction != null) {
                transactionCache.put(key, transaction);
            }
        }
    }

    private boolean isCacheStale(Transaction transaction) {
        return System.currentTimeMillis() - transaction.getLastUpdatedTime() > transaction.getTTL();
    }

    private void processBusinessLogic(Transaction transaction) {
        // Implement business logic for processing transactions
    }

    private void handleRateLimiting() {
        // Handle rate limiting (e.g., log, alert, retry)
    }

    public void shutdown() {
        cacheRefreshScheduler.shutdown();
        connectionPool.shutdown();
    }
}
