#include <string.h>

char* appendSlashIfWithinSizeLimit(const char* input, int sizeLimit) {
    if (strlen(input) < sizeLimit) {
        char* result = malloc(strlen(input) + 2); // +1 for '/', +1 for null terminator
        if (result != NULL) {
            strcpy(result, input);
            result[strlen(input)] = '/';
            result[strlen(input) + 1] = '\0';
            return result;
        }
    }
    return NULL; // Return NULL if the string exceeds the size limit or memory allocation fails
}

int main() {
    const char* testString = "Hello";
    int sizeLimit = 10;

    char* modifiedString = appendSlashIfWithinSizeLimit(testString, sizeLimit);
    if (modifiedString != NULL) {
        printf("Modified string: %s\n", modifiedString);
        free(modifiedString); // Don't forget to free the allocated memory
    } else {
        printf("Failed to modify string.\n");
    }

    return 0;
}
