// Microservices Architecture Code (Highly available, scalable, and secure)

const express = require('express');
const axios = require('axios');
const redis = require('redis');
const rateLimit = require('express-rate-limit');

const app = express();
const client = redis.createClient();

app.use(express.json());
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
}));

// External APIs Integration
async function getMarketData(symbol) {
  try {
    const response = await axios.get(`https://api.example.com/market/${symbol}`);
    return response.data;
  } catch (error) {
    console.error('Error fetching market data:', error);
    throw new Error('Failed to fetch market data');
  }
}

async function placeOrder(orderDetails) {
  try {
    const response = await axios.post(`https://api.example.com/orders`, orderDetails);
    return response.data;
  } catch (error) {
    console.error('Error placing order:', error);
    throw new Error('Failed to place order');
  }
}

// Caching Strategies
app.get('/market/:symbol', async (req, res) => {
  const { symbol } = req.params;
  try {
    let cachedData = await client.get(symbol);
    if (cachedData) {
      return res.json(JSON.parse(cachedData));
    }
    const marketData = await getMarketData(symbol);
    await client.setex(symbol, 300, JSON.stringify(marketData)); // Cache for 5 minutes
    res.json(marketData);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Robust Retry Logic and Fallback Mechanisms
const maxRetries = 3;
function retryWithExponentialBackoff(fn, retries = 0) {
  return async (...args) => {
    try {
      return await fn(...args);
    } catch (error) {
      if (retries < maxRetries) {
        setTimeout(() => retryWithExponentialBackoff(fn, retries + 1), Math.pow(2, retries) * 100);
      } else {
        throw error;
      }
    }
  };
}

// Role-Based Access Control and Fine-Grained Permissions
const permissions = {
  admin: ['create', 'read', 'update', 'delete'],
  user: ['read']
};

function checkPermissions(userRole, action) {
  return permissions[userRole].includes(action);
}

app.post('/orders', async (req, res) => {
  const { userRole } = req.headers;
  const { action } = req.body;
  if (checkPermissions(userRole, action)) {
    try {
      await placeOrder(req.body);
      res.json({ message: 'Order placed successfully' });
    } catch (error) {
      res.status(500).json({ error: error.message });
    }
  } else {
    res.status(403).json({ error: 'Permission denied' });
  }
});

// Monitoring and Logging
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

app.use((err, req, res, next) => {
  logger.error(err.stack);
  res.status(500).send('Something broke!');
});

// Edge Cases Handling
async function gracefulDegradation() {
  try {
    // Perform critical operations
  } catch (error) {
    console.log('Edge case detected:', error.message);
    // Implement recovery logic here
  }
}

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
