["```java
import java.util.HashMap;
import java.util.Map;

public class UserInteractionService {
    private Map<Integer, Integer> parentMap;
    private Map<Integer, Integer> sizeMap;

    public UserInteractionService() {
        parentMap = new HashMap<>();
        sizeMap = new HashMap<>();
    }

    public int find(int user) {
        if (!parentMap.containsKey(user)) {
            parentMap.put(user, user);
            sizeMap.put(user, 1);
            return user;
        } else {
            if (parentMap.get(user) == user) {
                return user;
            } else {
                parentMap.put(user, find(parentMap.get(user)));
                return parentMap.get(user);
            }
        }
    }

    public void union(int user1, int user2) {
        int root1 = find(user1);
        int root2 = find(user2);

        if (root1 != root2) {
            if (sizeMap.get(root1) < sizeMap.get(root2)) {
                parentMap.put(root1, root2);
                sizeMap.put(root2, sizeMap.get(root1) + sizeMap.get(root2));
            } else {
                parentMap.put(root2, root1);
                sizeMap.put(root1, sizeMap.get(root1) + sizeMap.get(root2));
            }
        }
    }

    public boolean areDisjoint(int user1, int user2) {
        return find(user1) != find(user2);
    }
}
```

This code snippet represents a basic implementation of the Union-Find algorithm in Java. It includes methods for finding the root of a user's set, unioning two sets together, and checking if two users are disjoint (i.e., they have not interacted before). The `parentMap` stores the parent of each user, while the `sizeMap` keeps track of the size of each set to optimize union operations. This implementation is designed for efficient processing of real-time user interaction events in a distributed system, with considerations for memory usage and concurrent access."]

