// Import required modules
const express = require('express');
const jwt = require('jsonwebtoken');
const axios = require('axios');
const Redis = require('ioredis');

// Initialize Express app
const app = express();
app.use(express.json());

// Configure Redis for caching
const redis = new Redis();

// Middleware to authenticate and authorize requests using JWT
function authenticate(req, res, next) {
  const token = req.headers['authorization'];
  if (!token) return res.status(401).send('Access denied');

  try {
    const decoded = jwt.verify(token, 'secretKey');
    req.user = decoded;
    next();
  } catch (error) {
    res.status(400).send('Invalid token');
  }
}

// Route handler for API gateway
app.get('/api/*', authenticate, async (req, res) => {
  const serviceUrl = determineServiceUrl(req);

  try {
    const response = await axios({
      method: req.method,
      url: serviceUrl + req.path,
      headers: { ...req.headers, 'Authorization': null },
      data: req.body
    });

    // Cache the response in Redis for 10 seconds
    redis.setex(req.url, 10, JSON.stringify(response.data));

    res.status(response.status).send(response.data);
  } catch (error) {
    if (error.response) {
      res.status(error.response.status).send(error.response.data);
    } else {
      res.status(500).send('Internal server error');
    }
  }
});

// Function to determine the backend service URL based on request headers and query parameters
function determineServiceUrl(req) {
  const version = req.headers['api-version'] || 'v1';
  const service = req.query.service || 'default';

  return `http://backend-${version}-${service}`;
}

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`API gateway listening on port ${PORT}`);
});
