["```sql
CREATE PROCEDURE GetEmployeeProfilesBySupervisorID(
    @SupervisorID INT,
    @ConnectionString NVARCHAR(MAX),
    @LogFilePath NVARCHAR(MAX)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @StartTime DATETIME = GETDATE();
    DECLARE @ErrorMessage NVARCHAR(255);

    BEGIN TRY
        -- Establish a connection using the provided connection string
        DECLARE @Connection INT;
        EXEC sp_OACreate 'ADODB.Connection', @Connection OUT;
        EXEC sp_OAMethod @Connection, 'Open', NULL, @ConnectionString;

        -- Execute the query to retrieve comprehensive employee profiles
        DECLARE @SQL NVARCHAR(MAX) = N'
            SELECT e.EmployeeID, e.Name, e.City, e.Address, d.DepartmentName, m.ManagerName
            FROM Employees e
            JOIN Departments d ON e.DepartmentID = d.DepartmentID
            LEFT JOIN (SELECT EmployeeID, ManagerID, Name AS ManagerName 
                      FROM Employees WHERE EmployeeID IN (SELECT EmployeeID FROM Employees WHERE ManagerID = @SupervisorID)) m ON e.EmployeeID = m.ManagerID
            WHERE e.SupervisorID = @SupervisorID AND e.Address IS NOT NULL';

        EXEC sp_OAMethod @Connection, 'CommandText', NULL, @SQL;
        EXEC sp_OAPropertySet @Connection, 'Parameters', @SupervisorID;

        DECLARE @Recordset INT;
        EXEC sp_OAMethod @Connection, 'Execute', @Recordset OUT;

        -- Fetch and return the results
        DECLARE @Output NVARCHAR(MAX) = N'';
        WHILE (1=1)
        BEGIN
            DECLARE @Row INT;
            EXEC sp_OAMethod @Recordset, 'MoveNext', NULL, @Row OUT;
            IF (@Row = 0) BREAK;

            DECLARE @EmployeeID INT, @Name NVARCHAR(255), @City NVARCHAR(255), @Address NVARCHAR(MAX), @DepartmentName NVARCHAR(255), @ManagerName NVARCHAR(255);
            EXEC sp_OAMethod @Recordset, 'Fields', NULL, @EmployeeID;
            EXEC sp_OAMethod @Recordset, 'Fields', NULL, @Name;
            EXEC sp_OAMethod @Recordset, 'Fields', NULL, @City;
            EXEC sp_OAMethod @Recordset, 'Fields', NULL, @Address;
            EXEC sp_OAMethod @Recordset, 'Fields', NULL, @DepartmentName;
            EXEC sp_OAMethod @Recordset, 'Fields', NULL, @ManagerName;

            SET @Output += N'EmployeeID: ' + CAST(@EmployeeID AS NVARCHAR(10)) + N', Name: ' + @Name + N', City: ' + @City + N', Address: ' + @Address + N', DepartmentName: ' + @DepartmentName + N', ManagerName: ' + ISNULL(@ManagerName, N'N/A') + CHAR(13) + CHAR(10);
        END

        -- Close and clean up the connection
        EXEC sp_OAMethod @Recordset, 'Close';
        EXEC sp_OADestroy @Recordset;
        EXEC sp_OADestroy @Connection;

        PRINT @Output;

    BEGIN CATCH
        SET @ErrorMessage = ERROR_MESSAGE();
        RAISERROR (@ErrorMessage, 16, 1);
    END CATCH

    DECLARE @EndTime DATETIME = GETDATE();
    DECLARE @ExecutionTime INT = DATEDIFF(SECOND, @StartTime, @EndTime);

    -- Log the operation details
    DECLARE @LogMessage NVARCHAR(MAX) = N'Operation: GetEmployeeProfilesBySupervisorID, SupervisorID: ' + CAST(@SupervisorID AS NVARCHAR(10)) + N', ExecutionTime: ' + CAST(@ExecutionTime AS NVARCHAR(10)) + N's';
    INSERT INTO OperationLogs (LogMessage, LogFilePath) VALUES (@LogMessage, @LogFilePath);
END
```

