<?php

namespace UserPasswordService;

use PDO;
use GuzzleHttp\Client as HttpClient;
use Psr\Log\LoggerInterface;

class UserPasswordService
{
    private $pdo;
    private $httpClient;
    private $logger;
    private $passwordPolicyCache;

    public function __construct(PDO $pdo, HttpClient $httpClient, LoggerInterface $logger)
    {
        $this->pdo = $pdo;
        $this->httpClient = $httpClient;
        $this->logger = $logger;
        $this->passwordPolicyCache = [];
    }

    public function updatePassword(int $userId, string $newPassword): bool
    {
        try {
            // Fetch current password policy from cache or API
            if (empty($this->passwordPolicyCache)) {
                $policyResponse = $this->httpClient->get('https://api.passwordpolicy.com/rules');
                $this->passwordPolicyCache = json_decode($policyResponse->getBody(), true);
            }

            // Validate new password against policy
            if (!$this->isValidPassword($newPassword, $this->passwordPolicyCache)) {
                throw new \InvalidArgumentException('Password does not meet policy requirements.');
            }

            // Update user password in database
            $stmt = $this->pdo->prepare('UPDATE users SET password = :hashed_password WHERE id = :user_id');
            $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);
            $stmt->execute(['hashed_password' => $hashedPassword, 'user_id' => $userId]);

            // Log successful password update
            $this->logger->info('User password updated successfully', ['user_id' => $userId]);
            return true;
        } catch (\Exception $e) {
            // Log error and handle exception appropriately
            $this->logger->error($e->getMessage(), ['exception' => $e]);
            throw $e;
        }
    }

    private function isValidPassword(string $password, array $policy): bool
    {
        foreach ($policy as $rule) {
            if (!$this->$rule['type']($password, $rule['params'])) {
                return false;
            }
        }
        return true;
    }

    // Implement password validation rules here
    private function lengthCheck(string $password, array $params): bool
    {
        return strlen($password) >= $params['minLength'];
    }

    private function containsUppercase(string $password, array $params): bool
    {
        return preg_match('/[A-Z]/', $password) > 0;
    }

    // Add more rules as needed

    public function setPasswordPolicyCache(array $cache)
    {
        $this->passwordPolicyCache = $cache;
    }
}
