class ConfigParser {
public:
    virtual std::map<std::string, std::string> parse(const std::string& configData) = 0;
};

class JsonConfigParser : public ConfigParser {
public:
    std::map<std::string, std::string> parse(const std::string& configData) override {
        // Implement JSON parsing logic here
        return {};
    }
};

class YamlConfigParser : public ConfigParser {
public:
    std::map<std::string, std::string> parse(const std::string& configData) override {
        // Implement YAML parsing logic here
        return {};
    }
};

class DynamicConfigManager {
private:
    std::map<std::string, std::string> cache;
    std::mutex cacheMutex;

public:
    void loadConfigFromSource(const std::string& sourceType, const std::string& configData) {
        std::unique_lock<std::mutex> lock(cacheMutex);
        ConfigParser* parser = getParserForSourceType(sourceType);
        if (parser) {
            std::map<std::string, std::string> parsedConfig = parser->parse(configData);
            cache.insert(parsedConfig.begin(), parsedConfig.end());
        }
    }

    std::string getConfigValue(const std::string& key) {
        std::unique_lock<std::mutex> lock(cacheMutex);
        if (cache.find(key) != cache.end()) {
            return cache[key];
        }
        return "";
    }

private:
    ConfigParser* getParserForSourceType(const std::string& sourceType) {
        // Implement logic to select the appropriate parser based on source type
        if (sourceType == "json") return new JsonConfigParser();
        else if (sourceType == "yaml") return new YamlConfigParser();
        return nullptr;
    }
};

int main() {
    DynamicConfigManager configManager;
    std::string jsonConfigData = "{\"key1\":\"value1\", \"key2\":\"value2\"}";
    std::string yamlConfigData = "key3: value3\nkey4: value4";

    configManager.loadConfigFromSource("json", jsonConfigData);
    configManager.loadConfigFromSource("yaml", yamlConfigData);

    std::cout << "Config Value for key1: " << configManager.getConfigValue("key1") << std::endl;
    std::cout << "Config Value for key4: " << configManager.getConfigValue("key4") << std::endl;

    return 0;
}
