from fastapi import FastAPI, File, UploadFile, HTTPException
from pydantic import BaseModel
from typing import List, Optional
import requests
import asyncio

app = FastAPI()

class Document(BaseModel):
    id: str
    format: str
    content: bytes

class MetadataResponse(BaseModel):
    id: str
    metadata: dict

@app.post("/process-document", response_model=MetadataResponse)
async def process_document(document: UploadFile = File(...)):
    try:
        # Simulate document processing with an external API
        response = await asyncio.to_thread(process_with_external_api, document)
        return MetadataResponse(id=document.filename, metadata=response)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

def process_with_external_api(document: UploadFile):
    # Simulate asynchronous processing with retries and error handling
    url = "https://external-api.com/extract-metadata"
    for _ in range(3):  # Retry up to 3 times
        try:
            files = {'file': document.file.read()}
            headers = {'Authorization': 'Bearer YOUR_API_TOKEN'}
            response = requests.post(url, files=files, headers=headers)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error processing document: {e}")
    raise Exception("Failed to process document after multiple attempts")

# Additional code for caching, scaling, and error handling can be added here
```

