import boto3
from chalice import Chalice, Cron
from botocore.exceptions import ClientError

app = Chalice(app_name='news-aggregator')
dynamodb = boto3.resource('dynamodb')
cache = boto3.client('apigatewaymanagementapi')

@app.route('/news', methods=['GET'])
def get_news():
    # Fetch news from various sources
    news_items = fetch_news_from_sources()

    # Cache the results to reduce database load
    cache_news(news_items)

    return {'news': news_items}

@app.schedule(Cron('*/5 * * * *'))  # Run every 5 minutes
def refresh_cache(event):
    clear_cache()

def fetch_news_from_sources():
    # Logic to fetch news from multiple sources
    pass

def cache_news(news_items):
    # Logic to cache news items in DynamoDB
    table = dynamodb.Table('NewsCache')
    for item in news_items:
        table.put_item(Item=item)

def clear_cache():
    # Logic to clear the cache
    table = dynamodb.Table('NewsCache')
    response = table.scan()
    with table.batch_write() as batch:
        for item in response['Items']:
            batch.delete_item(Key={'id': item['id']})

@app.error_handler(ClientError)
def handle_client_error(error):
    # Custom error handler for API Gateway
    return {'message': str(error)}, 400

@app.log_config({
    'version': 1,
    'formatters': {
        'default': {
            'format': '[%(asctime)s] %(levelname)s in %(module)s: %(message)s',
        }
    },
    'handlers': {
        'wsgi': {
            'class': 'logging.StreamHandler',
            'formatter': 'default'
        }
    },
    'root': {
        'level': 'INFO',
        'handlers': ['wsgi']
    }
})
