const express = require('express');
const axios = require('axios');
const jwt = require('jsonwebtoken');
const OAuth2Client = require('google-auth-library').OAuth2Client;
const { RateLimiterRedis } = require('rate-limiter-flexible');

const app = express();
const client = new OAuth2Client(YOUR_GOOGLE_CLIENT_ID);
const redisRateLimiter = new RateLimiterRedis({
  store: redis.createClient(),
  keyPrefix: 'api-gateway',
  points: 10, // max requests per windowMs
  duration: 60 * 1000 // milliseconds
});

app.use(express.json());

async function validateJWT(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (authHeader && authHeader.startsWith('Bearer ')) {
    const token = authHeader.substring(7);
    try {
      const decoded = jwt.verify(token, YOUR_JWT_SECRET);
      req.user = decoded;
      next();
    } catch (err) {
      res.status(403).send('Invalid JWT');
    }
  } else {
    res.status(401).send('No token provided');
  }
}

async function validateOAuth2(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (authHeader && authHeader.startsWith('Bearer ')) {
    const token = authHeader.substring(7);
    try {
      const ticket = await client.verifyIdToken({
        idToken: token,
        audience: YOUR_GOOGLE_CLIENT_ID
      });
      const payload = ticket.getPayload();
      req.user = payload;
      next();
    } catch (err) {
      res.status(403).send('Invalid OAuth2 token');
    }
  } else {
    res.status(401).send('No token provided');
  }
}

app.use('/api/microservice1', validateJWT, async (req, res) => {
  try {
    const response = await axios.get('http://microservice1-service/api', { headers: req.headers });
    res.send(response.data);
  } catch (error) {
    res.status(500).send('Error connecting to microservice1');
  }
});

app.use('/api/microservice2', validateOAuth2, async (req, res) => {
  try {
    const response = await axios.get('http://microservice2-service/api', { headers: req.headers });
    res.send(response.data);
  } catch (error) {
    res.status(500).send('Error connecting to microservice2');
  }
});

app.listen(3000, () => {
  console.log('API Gateway is running on port 3000');
});
