#include <iostream>
#include <unordered_map>
#include <thread>
#include <atomic>
#include <chrono>

class KeyValueStore {
public:
    std::unordered_map<std::string, std::pair<std::string, std::time_t>> store;
    std::mutex mtx;

    void set(const std::string& key, const std::string& value, time_t ttl) {
        std::lock_guard<std::mutex> lock(mtx);
        store[key] = {value, time(nullptr) + ttl};
    }

    std::optional<std::string> get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = store.find(key);
        if (it != store.end() && time(nullptr) < it->second.second) {
            return it->second.first;
        }
        store.erase(it, it);
        return {};
    }

    void remove(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        store.erase(key);
    }

    void refreshTTL(const std::string& key, time_t ttl) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = store.find(key);
        if (it != store.end()) {
            it->second.second = time(nullptr) + ttl;
        }
    }

private:
    void evictLRU() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::lock_guard<std::mutex> lock(mtx);
            auto minIt = store.begin();
            for (auto it = store.begin(); it != store.end(); ++it) {
                if (time(nullptr) > it->second.second) {
                    minIt = it;
                }
            }
            if (minIt != store.end()) {
                store.erase(minIt);
            }
        }
    }

public:
    KeyValueStore() {
        std::thread([this]() { evictLRU(); }).detach();
    }
};

class GeolocationServiceCache {
private:
    KeyValueStore kvStore;
    std::atomic<bool> running{true};

public:
    void start() {
        while (running) {
            // Simulate read/write requests
            // Process geolocation data and update cache accordingly
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

    ~GeolocationServiceCache() {
        running = false;
    }
};

int main() {
    GeolocationServiceCache cache;
    cache.start();
    return 0;
}
