// src/directory_manager.rs

use std::{
    collections::HashMap,
    sync::{Arc, Mutex},
    time::Duration,
};
use tokio::sync::mpsc;
use backoff::{retry, ExponentialBackoff};

pub struct DirectoryManager {
    service_dependencies: Arc<Mutex<HashMap<String, ServiceInfo>>>,
    retry_strategy: ExponentialBackoff,
    message_queue: mpsc::Sender<Message>,
}

struct ServiceInfo {
    max_retries: u32,
    delay: Duration,
}

enum Message {
    CreateDirectory(String),
    RollbackCreate(String),
    NotifySuccess(String),
    NotifyFailure(String, String),
}

impl DirectoryManager {
    pub fn new(retry_strategy: ExponentialBackoff) -> Self {
        DirectoryManager {
            service_dependencies: Arc::new(Mutex::new(HashMap::new())),
            retry_strategy,
            message_queue: mpsc::channel(32).0,
        }
    }

    pub async fn add_service_dependency(&self, name: String, info: ServiceInfo) {
        self.service_dependencies.lock().unwrap().insert(name, info);
    }

    pub async fn create_directory(&self, path: &str) -> Result<(), String> {
        let mut dependencies = self.service_dependencies.lock().unwrap();
        for (name, info) in dependencies.iter() {
            if !self.check_service_availability(name).await {
                return Err(format!("Failed to create directory due to service {} being unavailable", name));
            }
        }

        let retries = self.retry_strategy.max_interval;
        retry(retries, &mut |_| async move {
            // Simulate directory creation
            Ok(())
        })
        .map_err(|_| "Max retries exceeded".to_string())?;

        self.message_queue.send(Message::NotifySuccess(path.to_string())).await.map_err(|_| "Failed to notify success")?;
        Ok(())
    }

    pub async fn rollback_directory(&self, path: &str) -> Result<(), String> {
        // Simulate rollback
        self.message_queue.send(Message::NotifySuccess(path.to_string())).await.map_err(|_| "Failed to notify success")?;
        Ok(())
    }

    async fn check_service_availability(&self, name: &str) -> bool {
        let info = self.service_dependencies.lock().unwrap().get(name).ok_or(format!("Service {} not found", name))?;
        let retries = ExponentialBackoff {
            initial_interval: Duration::from_secs(1),
            max_interval: info.delay,
            ..ExponentialBackoff::default()
        };

        retry(retries, &mut |_| async move {
            // Simulate service availability check
            Ok(true)
        })
        .unwrap_or(false)
    }
}

// src/main.rs

mod directory_manager;

fn main() {
    let retry_strategy = backoff::ExponentialBackoff::default();
    let dir_manager = Arc::new(directory_manager::DirectoryManager::new(retry_strategy));

    // Simulate adding service dependencies
    dir_manager.add_service_dependency("service1".to_string(), directory_manager::ServiceInfo { max_retries: 5, delay: Duration::from_secs(2) }).await;
    dir_manager.add_service_dependency("service2".to_string(), directory_manager::ServiceInfo { max_retries: 3, delay: Duration::from_secs(4) }).await;

    // Simulate creating a directory
    let path = "/path/to/new/directory";
    if dir_manager.create_directory(path).await.is_err() {
        println!("Failed to create directory");
    }

    // Simulate rolling back a directory
    if dir_manager.rollback_directory(path).await.is_err() {
        println!("Failed to rollback directory");
    }
}
