import json
from abc import ABC, abstractmethod
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import Any, Callable, Dict, List, Optional, TypeVar, Union

T = TypeVar('T')

class Serializer(ABC):
    @abstractmethod
    def serialize(self, data: Any) -> str:
        pass

class Deserializer(ABC):
    @abstractmethod
    def deserialize(self, json_str: str) -> Any:
        pass

class CustomTypeSerializer(Serializer):
    def serialize(self, data: Any) -> str:
        return json.dumps(data, cls=CustomTypeEncoder)

class CustomTypeDecoder(json.JSONDecoder):
    def __init__(self, *args, **kwargs):
        json.JSONDecoder.__init__(self, object_hook=self.object_hook, *args, **kwargs)

    def object_hook(self, obj: Dict[str, Any]) -> Any:
        if '_type' in obj and obj['_type'] == 'CustomType':
            return CustomType(obj['data'])
        return obj

class FactoryRegistry:
    _registry = {}

    @classmethod
    def register(cls, name: str, factory_func: Callable[[], T]):
        cls._registry[name] = factory_func

    @classmethod
    def get_factory(cls, name: str) -> Callable[[], T]:
        return cls._registry.get(name)

class ConfigManager:
    def __init__(self):
        self.configurations = {}

