        deserializer = CustomTypeDecoder()

        data = deserializer.decode(json_str)

        factory_name = self.config_manager.get_config('factory')
        factory_func = FactoryRegistry.get_factory(factory_name)
        factory_instance = factory_func()

        return factory_instance.process(data)

class LoadBalancer:
    def __init__(self, clients: List[ExternalAPIClient]):
        self.clients = clients
        self.current_index = 0

    def get_client(self) -> ExternalAPIClient:
        client = self.clients[self.current_index]
        self.current_index = (self.current_index + 1) % len(self.clients)
        return client

# Usage example
