// SQL query to retrieve employee details from a database table named 'Employees'
#include <stdio.h>
#include <sqlite3.h>

int get_employee_details(int supervisor_id) {
    sqlite3 *db;
    char *zErrMsg = 0;
    int rc;

    // Open database
    rc = sqlite3_open("company.db", &db);
    if (rc) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return -1;
    }

    // SQL query to retrieve employee details
    char sql[256];
    snprintf(sql, sizeof(sql), "SELECT name, city, address FROM Employees WHERE supervisor_id = %d;", supervisor_id);

    // Execute the query
    rc = sqlite3_exec(db, sql, callback, 0, &zErrMsg);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", zErrMsg);
        sqlite3_free(zErrMsg);
    }

    // Close database connection
    sqlite3_close(db);
    return rc;
}

static int callback(void *data, int argc, char **argv, char **azColName) {
    for(int i = 0; i < argc; i++) {
        printf("%s = %s\n", azColName[i], argv[i] ? argv[i] : "NULL");
    }
    printf("\n");
    return 0;
}
