namespace fs = std::filesystem;

// Directory processing function
void processDirectory(const std::string& directoryPath) {
    for (const auto& entry : fs::directory_iterator(directoryPath)) {
        if (entry.is_regular_file()) {
            renameFile(entry.path());
        }
    }
}

// File renaming function
void renameFile(const fs::path& filePath) {
    // Generate timestamp and unique sequential number
    std::string newFileName = generateNewFileName();

    // Rename file
    fs::rename(filePath, filePath.parent_path() / newFileName);

    // Update metadata service
    updateMetadataService(newFileName);
}

// Timestamp and unique sequential number generation function
std::string generateNewFileName() {
    static int sequentialNumber = 0;
    auto now = std::chrono::system_clock::now();
    std::time_t time = std::chrono::system_clock::to_time_t(now);
    std::tm tm = *std::localtime(&time);

    std::ostringstream oss;
