class OAuthTokenValidator {
public:
    static bool validateOAuthToken(const std::string& tokenResponse, int maxRetries = 3) {
        for (int i = 0; i <= maxRetries; ++i) {
            try {
                Json::Value tokenData;
                tokenData << tokenResponse;

                if (!tokenData.isMember("access_token") ||
                    !tokenData.isMember("expires_in") ||
                    !tokenData.isMember("token_type")) {
                    return false;
                }

                std::string tokenType = tokenData["token_type"].asString();
                int expiresIn = tokenData["expires_in"].asInt();

                if (tokenType != "Bearer" || expiresIn <= 0) {
                    return false;
                }

                // Optionally check for refresh_token
                if (tokenData.isMember("refresh_token")) {
                    std::string refreshToken = tokenData["refresh_token"].asString();
                    // Validate refresh_token if necessary
                }

                return true;
            } catch (...) {
                // Handle unexpected data formats and invalid token responses
                return false;
            }
        }

        // Network failure or timeout handling
        return false;
    }
};

} // namespace OAuthValidation

int main() {
    std::string tokenResponse = R"({"access_token":"abc123","expires_in":3600,"token_type":"Bearer"})";
    bool isValid = OAuthValidation::OAuthTokenValidator::validateOAuthToken(tokenResponse);
    if (isValid) {
        std::cout << "Token is valid." << std::endl;
    } else {
        std::cout << "Token is invalid." << std::endl;
    }
    return 0;
}
