#include <iostream>
#include <fstream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <atomic>

// Define a simple StockData structure to hold stock price information
struct StockData {
    std::string symbol;
    double price;
    time_t timestamp;
};

// Configurable interface for data sources, time ranges, and storage options
class DataSourceConfig {
public:
    virtual std::vector<StockData> fetchData() = 0;
    virtual ~DataSourceConfig() {}
};

class TimeSeriesDatabase {
public:
    virtual void insertBulk(const std::vector<StockData>& data) = 0;
    virtual ~TimeSeriesDatabase() {}
};

// Asynchronous data retrieval mechanism
class DataFetcher {
private:
    DataSourceConfig* config;
    TimeSeriesDatabase* db;
    std::queue<StockData> buffer;
    std::mutex mtx;
    std::condition_variable cv;
    bool running;

public:
    DataFetcher(DataSourceConfig* config, TimeSeriesDatabase* db)
        : config(config), db(db), running(true) {
        // Start a thread to fetch data asynchronously
        std::thread([this]() { fetchThread(); }).detach();
    }

    ~DataFetcher() {
        {
            std::unique_lock<std::mutex> lock(mtx);
            running = false;
        }
        cv.notify_all();
    }

private:
    void fetchThread() {
        while (true) {
            std::vector<StockData> data = config->fetchData();
            {
                std::lock_guard<std::mutex> lock(mtx);
                for (const auto& stock : data) {
                    buffer.push(stock);
                }
            }
            cv.notify_all();

            // Check if we should stop fetching
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !running || !config->fetchData().empty(); });
            if (!running) break;
        }
    }

public:
    void writeToDB() {
        while (true) {
            std::vector<StockData> batch;
            {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this] { return !buffer.empty(); });
                size_t batchSize = 100; // Batch size for efficiency
                while (!buffer.empty() && batch.size() < batchSize) {
                    batch.push_back(buffer.front());
                    buffer.pop();
                }
            }

            if (!batch.empty()) {
                db->insertBulk(batch);
            }

            // Check if we should stop writing to DB
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !running || buffer.empty(); });
            if (!running) break;
        }
    }
};

// Example DataSourceConfig implementation using a mock data source
class MockDataSourceConfig : public DataSourceConfig {
public:
    std::vector<StockData> fetchData() override {
        // Simulate fetching data from a financial market data feed
        return {{"AAPL", 150.75, time(nullptr)}, {"GOOGL", 2800.50, time(nullptr)}};
    }
};

// Example TimeSeriesDatabase implementation using an in-memory storage
class InMemoryDB : public TimeSeriesDatabase {
public:
    void insertBulk(const std::vector<StockData>& data) override {
        // Simulate bulk insertion into a time-series database
        for (const auto& stock : data) {
            std::cout << "Inserted: " << stock.symbol << ", " << stock.price << ", " << ctime(&stock.timestamp);
        }
    }
};

int main() {
    MockDataSourceConfig config;
    InMemoryDB db;
    DataFetcher fetcher(&config, &db);

    // Start the writer thread
    std::thread writer([&fetcher]() { fetcher.writeToDB(); }).detach();

    // Simulate running for a while and then stopping
    std::this_thread::sleep_for(std::chrono::seconds(5));
    return 0;
}
```

