// C Library Code Snippet
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_RESPONSE_SIZE 1024

typedef struct {
    char response[MAX_RESPONSE_SIZE];
} RACHConfig;

CURL *curl;
struct MemoryStruct chunk;

int init_curl() {
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        chunk.memory = malloc(1);  // will be grown as needed by the realloc above
        chunk.size = 0;    // no data at this point
        return 0;
    }
    return -1;
}

size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

int fetch_rach_config(RACHConfig *config) {
    curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/rach-config");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

    CURLcode res = curl_easy_perform(curl);
    if(res != CURLE_OK) {
        printf("curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        return -1;
    }

    strncpy(config->response, chunk.memory, MAX_RESPONSE_SIZE);
    config->response[MAX_RESPONSE_SIZE-1] = '\0';

    free(chunk.memory);
    curl_easy_cleanup(curl);

    return 0;
}

// C Helper Function
char* append_slash(char *str, size_t max_size) {
    if(str == NULL || strlen(str) >= max_size - 1)
        return NULL;
    str[strlen(str)] = '/';
    str[strlen(str)+1] = '\0';
    return str;
}
