class ResilientHelper {
public:
    static void insertAfterString(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert, bool deepCopy) {
        auto it = list.begin();
        while (it != list.end()) {
            if (*it == target) {
                if (deepCopy) {
                    list.insert_after(it, toInsert);
                } else {
                    list.insert_after(it, toInsert);
                }
                return;
            }
            ++it;
        }
        if (deepCopy) {
            list.push_back(toInsert);
        } else {
            list.push_back(toInsert);
        }
    }
};

int main() {
    std::forward_list<std::string> myList = {"Hello", "World"};
    bool deepCopy = true;
    ResilientHelper::insertAfterString(myList, "World", "Beautiful", deepCopy);

    for (const auto& str : myList) {
        std::cout << str << " ";
    }

    return 0;
}
```

