public class TelemetryKafkaProducer {
    public static void send(String bootstrapServers, String topic, DeviceTelemetryData data) {
        Properties props = KafkaProducerConfig.getProperties(bootstrapServers);
        Producer<String, byte[]> producer = new KafkaProducer<>(props);
        try {
            byte[] dataBytes = // Serialize the data
            producer.send(new ProducerRecord<>(topic, data.getDeviceId(), dataBytes));
        } finally {
            producer.close();
        }
    }
}

// InfluxDB writer to store telemetry data
public class TelemetryInfluxDBWriter {
    public static void write(InfluxDB influxDB, String measurement, DeviceTelemetryData data) {
        Point point = Point.measurement(measurement)
                            .addField("deviceId", data.getDeviceId())
                            .addField("timestamp", data.getTimestamp())
                            .addField("value", data.getValue());
        influxDB.write(point);
    }
}

