// Helper function to process a dynamic array of integers
void processArray(std::vector<int>& arr, int value, bool deepCopy) {
    if (arr.empty()) {
        arr.push_back(value);
        return;
    }

    auto it = std::find(arr.begin(), arr.end(), value);
    if (it == arr.end()) {
        arr.push_back(value);
    } else {
        // If deep copy is required, create a new element and insert
        if (deepCopy) {
            int newValue = *it;
            arr.insert(it + 1, newValue);
        }
    }
}

