#include <stdio.h>
#include <time.h>

// Function to find parent of an element i
int find(int parent[], int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

// Function to union two sets of x and y
void unionSet(int parent[], int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);

    if (xset != yset)
        parent[xset] = yset;
}

// Function to count disjoint pairs using Union-Find
int countDisjointPairs(int arr[], int n) {
    int parent[n];
    for (int i = 0; i < n; i++)
        parent[i] = -1;

    clock_t start, end;
    double cpu_time_used;

    int disjointPairs = 0;

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] != arr[j]) {
                start = clock();
                unionSet(parent, i, j);
                end = clock();

                cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;

                printf("Pair (%d, %d) took %f seconds to process\n", arr[i], arr[j], cpu_time_used);
                disjointPairs++;
            }
        }
    }

    return disjointPairs;
}

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    int n = sizeof(arr) / sizeof(arr[0]);

    printf("Number of disjoint pairs: %d\n", countDisjointPairs(arr, n));

    return 0;
}
