#include <vector>
#include <iostream>
#include <memory>

// Helper function to process a dynamic array of integers
void processIntegers(std::vector<int>& arr, int value, bool deepCopy) {
    if (arr.empty()) {
        std::cout << "Array is empty. Nothing to process." << std::endl;
        return;
    }

    if (!deepCopy) {
        arr.push_back(value);
        std::cout << "Inserted value without deep copy: " << value << std::endl;
    } else {
        std::vector<int> newArr(arr);
        newArr.push_back(value);
        std::cout << "Inserted value with deep copy: " << value << std::endl;
        arr = newArr; // Shallow copy of the new array to original
    }
}

int main() {
    std::vector<int> intArray{1, 2, 3};
    processIntegers(intArray, 4, false);
    processIntegers(intArray, 5, true);

    for (int i : intArray) {
        std::cout << i << " ";
    }
    return 0;
}
