int executeCommandInBackground(const char* command) {
    pid_t pid = fork();
    if (pid == 0) {
        execlp(command, command, NULL);
        exit(1);
    } else if (pid > 0) {
        return 1;
    } else {
        return 0;
    }
}

void initializeTaskManager(TaskManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->active_sessions = 0;
}

int addSessionToPool(TaskManager* manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->active_sessions >= MAX_SESSIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Maximum sessions reached
    }
    // Initialize session and add to pool
    manager->sessions[manager->active_sessions]./* initialize */;
    manager->active_sessions++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

