#include <iostream>
#include <vector>
#include <string>

void processDynamicArray(std::vector<std::string>& dynamicArray, const std::string& value, bool deepCopy) {
    if (value.empty()) return;

    if (deepCopy) {
        std::string* newString = new std::string(value);
        dynamicArray.push_back(*newString);
        delete newString; // Ensure proper memory management
    } else {
        dynamicArray.push_back(value);
    }
}

int main() {
    std::vector<std::string> array;
    processDynamicArray(array, "Hello", true);
    processDynamicArray(array, "World", false);

    for (const auto& str : array) {
        std::cout << str << std::endl;
    }

    return 0;
}
