// Java Microservice: HTTP Client with Retry Mechanism

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class HttpClientWithRetry {
    private static final int MAX_RETRIES = 3;
    private static final long BACKOFF_MS = 1000; // 1 second

    public String sendRequest(String url) throws IOException, InterruptedException {
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .build();

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            try {
                HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
                if (response.statusCode() == 200) {
                    return response.body();
                } else {
                    Thread.sleep(BACKOFF_MS * Math.pow(2, attempt));
                }
            } catch (IOException | InterruptedException e) {
                Thread.sleep(BACKOFF_MS * Math.pow(2, attempt));
            }
        }

        throw new IOException("Failed to send request after " + MAX_RETRIES + " attempts");
    }

    public static void main(String[] args) {
        HttpClientWithRetry client = new HttpClientWithRetry();
        try {
            String result = client.sendRequest("https://api.example.com/data");
            System.out.println(result);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
```

