// Controller for handling HTTP PUT requests to update access tokens
@RestController
@RequestMapping("/api/tokens")
public class TokenController {

    @Autowired
    private RedisTemplate<String, AccessToken> tokenRedisTemplate;

    @PutMapping("/{tenantId}")
    public ResponseEntity<String> updateAccessToken(@PathVariable String tenantId,
                                                   @RequestBody AccessToken newToken) {
        // Validate required fields and token type
        if (newToken.getToken() == null || newToken.getType() == null || newToken.getExpiration() == null) {
            return ResponseEntity.badRequest().body("Invalid access token data");
        }

        // Update the token in Redis with transactional integrity
        DefaultTransactionDefinition def = new DefaultTransactionDefinition();
        TransactionStatus status = tokenRedisTemplate.getConnectionFactory()
                .getConnection().multi();

        try {
            tokenRedisTemplate.opsForValue().set(tenantId, newToken);
            status.commit(status);
            return ResponseEntity.ok("Access token updated successfully");
        } catch (Exception e) {
            status.rollback(status);
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body("Failed to update access token");
        }
    }
}

