class DataCollection {
public:
    DataCollection(std::shared_ptr<TimeSeriesDB> db, size_t memoryPoolSize)
        : db_(db), memoryPool_(memoryPoolSize) {}

    void addItem(const DataItem& item) {
        std::lock_guard<std::mutex> lock(mutex_);
        data_[item.key] = item;
        db_->store(item.key, item);
    }

    bool getItem(const std::string& key, DataItem& item) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = data_.find(key);
        if (it != data_.end()) {
            item = it->second;
            return true;
        }
        return false;
    }

    void removeOldData(const std::chrono::system_clock::time_point& cutoff) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = data_.begin(); it != data_.end();) {
            if (it->second.timestamp < cutoff) {
                db_->removeOldData(it->second.timestamp);
                it = data_.erase(it);
            } else {
                ++it;
            }
        }
    }

private:
    std::shared_ptr<TimeSeriesDB> db_;
    std::unordered_map<std::string, DataItem> data_;
    std::mutex mutex_;
    std::unique_ptr<MemoryPool> memoryPool_;
};

