      return response.data.enhancedData;
    } catch (error) {
      console.error('Validation error:', error);
      throw error;
    }
  }

  async function deserializeBinary(binaryData) {
    try {
      // Simulate deserialization
      const result = await new Promise((resolve, reject) => {
        const worker = new Worker(__filename, { workerData: binaryData });
        worker.on('message', resolve);
        worker.on('error', reject);
        worker.on('exit', (code) => {
          if (code !== 0) reject(new Error(`Worker stopped with exit code ${code}`));
        });
      });
      return result;
    } catch (error) {
      console.error('Deserialization error:', error);
      throw error;
    }
  }

  async function reduceBatch(batch) {
    let accumulator = initialValue;
    for (const dataPoint of batch) {
      accumulator = await callback(accumulator, dataPoint);
    }
    return accumulator;
  }

  numberStream.on('data', async (number) => {
    currentBatch.push(number);
    if (currentBatch.length >= batchSize) {
      try {
        const enhancedData = await Promise.all(
          currentBatch.map(async (dataPoint) => {
            const binaryData = await loadData(`path/to/binary/${dataPoint}`);
            return deserializeBinary(binaryData);
          })
        );
        const result = await reduceBatch(enhancedData);
        console.log('Reduced value:', result);
      } catch (error) {
        console.error('Error processing batch:', error);
      }
      currentBatch = [];
    }
  });

  numberStream.on('end', async () => {
    if (currentBatch.length > 0) {
      try {
        const enhancedData = await Promise.all(
          currentBatch.map(async (dataPoint) => {
            const binaryData = await loadData(`path/to/binary/${dataPoint}`);
            return deserializeBinary(binaryData);
          })
        );
        const result = await reduceBatch(enhancedData);
        console.log('Reduced value:', result);
      } catch (error) {
        console.error('Error processing final batch:', error);
      }
    }
  });
}

// Example usage:
