#include <iostream>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>
#include <functional>

class DistributedCache {
public:
    // Define data types for cache values
    using DataType = std::string;

    // Constructor
    DistributedCache(size_t capacity) : maxCapacity(capacity), evictionPolicy(EvictionPolicy::LRU) {}

    // Add or update a key-value pair in the cache
    void set(const std::string& key, const DataType& value) {
        std::unique_lock<std::mutex> lock(mutex);
        if (cache.find(key) != cache.end()) {
            cache[key] = value;
            // Move to front for LRU policy
            if (evictionPolicy == EvictionPolicy::LRU) {
                cache.erase(cache.find(key));
                cache.insert({key, value});
            }
        } else {
            // Check capacity and evict if necessary
            if (cache.size() >= maxCapacity && evictionPolicy == EvictionPolicy::LFU) {
                evictLeastFrequent();
            }
            cache[key] = value;
            frequencyMap[key] = 1;
        }
    }

    // Retrieve a value by key from the cache
    std::optional<DataType> get(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex);
        if (cache.find(key) != cache.end()) {
            // Update frequency for LFU policy
            if (evictionPolicy == EvictionPolicy::LFU) {
                frequencyMap[key]++;
            }
            return cache[key];
        } else {
            return std::nullopt;
        }
    }

private:
    enum class EvictionPolicy { LRU, LFU };

    size_t maxCapacity;
    EvictionPolicy evictionPolicy;

    std::mutex mutex;
    std::unordered_map<std::string, DataType> cache;
    std::unordered_map<std::string, int> frequencyMap;

    // Evict the least frequently used item for LFU policy
    void evictLeastFrequent() {
        auto minIt = std::min_element(frequencyMap.begin(), frequencyMap.end(),
                                     [](const std::pair<const std::string&, int>& a, const std::pair<const std::string&, int>& b) {
                                         return a.second < b.second;
                                     });
        if (minIt != frequencyMap.end()) {
            cache.erase(minIt->first);
            frequencyMap.erase(minIt->first);
        }
    }
};

int main() {
    DistributedCache cache(100);

    // Simulate setting and getting values
    cache.set("key1", "value1");
    auto value = cache.get("key1");
    if (value.has_value()) {
        std::cout << "Value: " << value.value() << std::endl;
    } else {
        std::cout << "Key not found" << std::endl;
    }

    return 0;
}
