    if env::var(env_var_name).is_err() {
        let dir_path = format!("/tmp/{}", dir_name);
        DirBuilder::new()
            .recursive(true)
            .create(&dir_path)
            .expect("Failed to create directory");
        env::set_var(env_var_name, &dir_path);
    }
}

fn main() {
    // Example usage
    let thread_handles = vec![
        thread::spawn(|| create_directory_and_set_env_var("directory1")),
        thread::spawn(|| create_directory_and_set_env_var("directory2")),
    ];

    for handle in thread_handles {
        handle.join().unwrap();
    }

    if let Ok(path) = env::var("MY_DIRECTORY") {
        println!("Directory path: {}", path);
    } else {
        println!("Environment variable not set");
    }
}
