#include "rapidjson/document.h"
#include "log4cpp/Category.hh"

class LogProcessor {
public:
    LogProcessor(const std::string& configFilePath);
    ~LogProcessor();

    void start();
    void stop();

private:
    void workerThread();
    bool readConfiguration();
    void processFile(const std::string& filePath);

    std::vector<std::string> inputDirectories;
    std::queue<std::string> fileQueue;
    std::mutex queueMutex;
    std::condition_variable conditionVariable;
    std::vector<std::thread> workers;
    bool running;

    log4cpp::Category& logger;
};

LogProcessor::LogProcessor(const std::string& configFilePath) : running(false), logger(log4cpp::Category::getInstance("LogProcessor")) {
    readConfiguration();
}

LogProcessor::~LogProcessor() {
    stop();
}

void LogProcessor::start() {
    running = true;
    for (size_t i = 0; i < inputDirectories.size(); ++i) {
        workers.emplace_back(&LogProcessor::workerThread, this);
    }
}

void LogProcessor::stop() {
    {
        std::unique_lock<std::mutex> lock(queueMutex);
        running = false;
        conditionVariable.notify_all();
    }
    for (auto& worker : workers) {
        worker.join();
    }
}

void LogProcessor::workerThread() {
    while (true) {
        std::string filePath;
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            conditionVariable.wait(lock, [this] { return !running || !fileQueue.empty(); });
            if (!running && fileQueue.empty()) {
                break;
            }
            filePath = fileQueue.front();
            fileQueue.pop();
        }
        processFile(filePath);
    }
}

bool LogProcessor::readConfiguration() {
    std::ifstream configFile("config.json");
    rapidjson::Document doc;
    if (configFile.is_open()) {
        rapidjson::IStreamWrapper iStream(configFile);
        doc.ParseStream(iStream);
        configFile.close();
        if (!doc.HasParseError()) {
            const auto& dirs = doc["input_directories"];
            for (const auto& dir : dirs) {
                inputDirectories.push_back(dir.GetString());
            }
            return true;
        }
    }
    logger.error("Failed to read configuration file");
    return false;
}

void LogProcessor::processFile(const std::string& filePath) {
    // Implement file processing logic here
    logger.info("Processing file: %s", filePath.c_str());
}

int main() {
    LogProcessor processor("config.json");
    processor.start();
    // Simulate running for a while
    std::this_thread::sleep_for(std::chrono::seconds(10));
    processor.stop();
    return 0;
}
