class ImageProcessor {
public:
    void processImage(const std::string& image, const std::string& format) {
        // Simulate image processing
        std::cout << "Processing image: " << image << " in format: " << format << std::endl;
    }
};

class MessageQueue {
private:
    std::queue<std::pair<std::string, std::string>> tasks;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void enqueue(const std::string& image, const std::string& format) {
        std::lock_guard<std::mutex> lock(mtx);
        tasks.emplace(image, format);
        cv.notify_one();
    }

    std::pair<std::string, std::string> dequeue() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]{ return !tasks.empty(); });
        auto task = tasks.front();
        tasks.pop();
        return task;
    }
};

class ImageProcessingLibrary {
public:
    ImageProcessingLibrary(size_t numThreads) : processor(), queue(), threads(numThreads), stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads[i] = std::thread(&ImageProcessingLibrary::worker, this);
        }
    }

    ~ImageProcessingLibrary() {
        {
            std::unique_lock<std::mutex> lock(queue.mtx);
            stop = true;
        }
        queue.cv.notify_all();
        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void processImages(const std::vector<std::pair<std::string, std::string>>& tasks) {
        for (const auto& task : tasks) {
            queue.enqueue(task.first, task.second);
        }
    }

private:
    ImageProcessor processor;
    MessageQueue queue;
    std::vector<std::thread> threads;
    bool stop;

    void worker() {
        while (true) {
            auto task = queue.dequeue();
            if (stop && queue.tasks.empty()) {
                break;
            }
            processor.processImage(task.first, task.second);
        }
    }
};

int main() {
    ImageProcessingLibrary library(4);
    std::vector<std::pair<std::string, std::string>> tasks = {
        {"image1.jpg", "JPEG"},
        {"image2.png", "PNG"},
        {"image3.bmp", "BMP"}
    };
    library.processImages(tasks);
    return 0;
}
