package com.pokemon.report;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.openfeign.EnableFeignClients;
import org.springframework.context.annotation.Bean;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

@SpringBootApplication
@EnableFeignClients
public class PokemonReportServiceApplication {

    public static void main(String[] args) {
        SpringApplication.run(PokemonReportServiceApplication.class, args);
    }

    @Bean
    public WebClient.Builder webClientBuilder() {
        return WebClient.builder();
    }

    public Mono<String> fetchHabitatData(String habitatId) {
        // Implementation to fetch habitat data from an external API
        return WebClient.create()
                .get()
                .uri("https://api.example.com/habitats/{habitatId}", habitatId)
                .retrieve()
                .bodyToMono(String.class);
    }

    public Mono<String> fetchDietData(String dietType) {
        // Implementation to fetch diet data from an external API
        return WebClient.create()
                .get()
                .uri("https://api.example.com/diets/{dietType}", dietType)
                .retrieve()
                .bodyToMono(String.class);
    }

    public Mono<String> fetchNaturalEnvironmentData(String environmentId) {
        // Implementation to fetch natural environment data from an external API
        return WebClient.create()
                .get()
                .uri("https://api.example.com/environments/{environmentId}", environmentId)
                .retrieve()
                .bodyToMono(String.class);
    }

    public Mono<String> fetchTypeSpecificData(String type) {
        // Implementation to fetch type-specific data from an external API
        return WebClient.create()
                .get()
                .uri("https://api.example.com/types/{type}", type)
                .retrieve()
                .bodyToMono(String.class);
    }

    public Flux<String> generateReport(String pokemonId) {
        // Fetching data asynchronously using reactive streams
        Mono<String> habitatData = fetchHabitatData(pokemonId);
        Mono<String> dietData = fetchDietData(pokemonId);
        Mono<String> environmentData = fetchNaturalEnvironmentData(pokemonId);
        Mono<String> typeData = fetchTypeSpecificData(pokemonId);

        return Flux.zip(habitatData, dietData, environmentData, typeData)
                .map(data -> {
                    // Combine data into a comprehensive report
                    return "Pokemon Report for ID " + pokemonId + "\n" +
                            "Habitat: " + data.getT1() + "\n" +
                            "Diet: " + data.getT2() + "\n" +
                            "Environment: " + data.getT3() + "\n" +
                            "Type: " + data.getT4();
                });
    }
}
