#include <random>
#include <mutex>
#include <vector>
#include <string>
#include <chrono>
#include <fstream>

class SimulationEngine {
public:
    struct RandomSequence {
        std::mt19937 gen;
        std::uniform_real_distribution<> dis;
        RandomSequence(uint64_t seed) : gen(seed), dis(0.0, 1.0) {}
        double next() { return dis(gen); }
        void reset(uint64_t seed) {
            gen.seed(seed);
        }
    };

    SimulationEngine(size_t numSequences, size_t logThreshold)
        : sequences(numSequences), logThreshold(logThreshold) {}

    double getRandomNumber(size_t seqIndex) {
        if (seqIndex >= sequences.size()) {
            throw std::out_of_range("Invalid sequence index");
        }
        return sequences[seqIndex].next();
    }

    void resetSequence(size_t seqIndex, uint64_t seed) {
        if (seqIndex >= sequences.size()) {
            throw std::out_of_range("Invalid sequence index");
        }
        sequences[seqIndex].reset(seed);
    }

private:
    std::vector<RandomSequence> sequences;
    size_t logThreshold;

    void logEvent(uint64_t seed, double randomNumber) {
        static std::mutex logMutex;
        std::lock_guard<std::mutex> lock(logMutex);

        // Simulate log file handling
        std::string logEntry = "Seed: " + std::to_string(seed) + ", Number: " + std::to_string(randomNumber) + ", Time: " + std::to_string(std::chrono::system_clock::now().time_since_epoch().count()) + "\n";
        if (logEntries.size() >= logThreshold) {
            flushLogs();
        }
        logEntries.push_back(logEntry);
    }

    void flushLogs() {
        // Simulate flushing logs to disk
        for (const auto& entry : logEntries) {
            std::cout << entry;  // In a real system, this would write to a file
        }
        logEntries.clear();
    }

    std::vector<std::string> logEntries;
};

// Example usage:
int main() {
    SimulationEngine engine(10, 100);  // 10 sequences, log every 100 entries

    uint64_t seed = std::random_device{}();
    engine.resetSequence(0, seed);

    for (size_t i = 0; i < 200; ++i) {
        double randomNumber = engine.getRandomNumber(0);
        engine.logEvent(seed, randomNumber);  // Log each generated number
    }

    return 0;
}
