    public async Task<IDataReader> ExecuteComplexQueryWithDeserialization(byte[] serializedData, Type objectType)
    {
        try
        {
            object deserializedObject = DeserializeFromByteArray(serializedData, objectType);
            ValidateObject(deserializedObject);

            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();
                using (var command = new SqlCommand("ComplexQuery", connection))
                {
                    command.CommandType = CommandType.StoredProcedure;
                    // Add parameters to the command to prevent SQL injection
                    // Example: command.Parameters.AddWithValue("@paramName", paramValue);

                    using (var reader = await command.ExecuteReaderAsync())
                    {
                        return reader;
                    }
                }
            }
        }
        catch (SerializationException ex)
        {
            LogError("Deserialization error: " + ex.Message);
            throw new InvalidOperationException("Invalid data format.", ex);
        }
        catch (Exception ex)
        {
            LogError("General error: " + ex.Message);
            throw;
        }
    }

    private object DeserializeFromByteArray(byte[] bytes, Type objectType)
    {
        using (var ms = new MemoryStream(bytes))
        {
