    {
        // Logic to create and save a custom weather scenario
        return new WeatherScenario { Name = scenarioName, Conditions = conditions };
    }

    public void Dispose()
    {
        _httpClient.Dispose();
        _redisConnection.Close();
        _refreshTimer.Dispose();
    }
}

