using System;
using System.Net.Http;
using System.Threading.Tasks;

public class DynamicRESTClient
{
    private readonly HttpClient _httpClient;
    private readonly ILogger _logger;
    private readonly IConfigurationService _configurationService;

    public DynamicRESTClient(HttpClient httpClient, ILogger logger, IConfigurationService configurationService)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _configurationService = configurationService ?? throw new ArgumentNullException(nameof(configurationService));
    }

    public async Task<TResponse> GetAsync<TResponse>(string url)
    {
        try
        {
            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<TResponse>();
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to retrieve data from {Url}", url);
            throw;
        }
    }

    public async Task PostAsync(string url, object data)
    {
        var content = new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json");
        try
        {
            var response = await _httpClient.PostAsync(url, content);
            response.EnsureSuccessStatusCode();
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to post data to {Url}", url);
            throw;
        }
    }

    public async Task<TResponse> PutAsync<TResponse>(string url, object data)
    {
        var content = new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json");
        try
        {
            var response = await _httpClient.PutAsync(url, content);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<TResponse>();
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to update data at {Url}", url);
            throw;
        }
    }

    public async Task DeleteAsync(string url)
    {
        try
        {
            var response = await _httpClient.DeleteAsync(url);
            response.EnsureSuccessStatusCode();
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to delete data at {Url}", url);
            throw;
        }
    }

    // Add other HTTP methods as needed
}
