class StringArrayManager {
public:
    static void insertString(std::vector<std::string>& array, const std::string* value, bool deepCopy = false) {
        if (value == nullptr) {
            return;
        }
        if (deepCopy) {
            array.push_back(*value);
        } else {
            array.push_back(value->c_str());
        }
    }

    static void insertString(std::vector<std::shared_ptr<std::string>>& array, const std::string* value, bool deepCopy = false) {
        if (value == nullptr) {
            return;
        }
        if (deepCopy) {
            array.push_back(std::make_shared<std::string>(*value));
        } else {
            array.push_back(value);
        }
    }

private:
    StringArrayManager() {}
};

int main() {
    std::vector<std::string> strings;
    StringArrayManager::insertString(strings, new std::string("Hello"), true);
    StringArrayManager::insertString(strings, new std::string("World"), false);

    for (const auto& str : strings) {
        std::cout << str << " ";
    }

    return 0;
}
