# Python Logging Service Implementation

import grpc
from concurrent import futures
from log_pb2 import LogRequest, LogResponse
from log_pb2_grpc import LoggingServiceServicer, add_LoggingServiceServicer_to_server

class LoggingServiceImpl(LoggingServiceServicer):
    def __init__(self):
        self.log_store = {}

    def Log(self, request, context):
        source_id = request.source_id
        if source_id not in self.log_store:
            self.log_store[source_id] = []
        self.log_store[source_id].append(request.log_entry)
        return LogResponse(status="Logged successfully")

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    add_LoggingServiceServicer_to_server(LoggingServiceImpl(), server)
    server.add_insecure_port('[::]:50051')
    server.start()
