#include <string.h>

typedef struct {
    char *language;
    char **messages;
} MessageBundle;

MessageBundle* load_message_bundle(const char *locale) {
    // Simulate loading a message bundle from an external service
    MessageBundle *bundle = malloc(sizeof(MessageBundle));
    bundle->language = strdup(locale);
    bundle->messages = (char **)malloc(2 * sizeof(char *));
    bundle->messages[0] = strdup("Hello");
    bundle->messages[1] = NULL;
    return bundle;
}

void free_message_bundle(MessageBundle *bundle) {
    // Free the memory allocated for a message bundle
    free(bundle->language);
    for (int i = 0; bundle->messages[i] != NULL; i++) {
        free(bundle->messages[i]);
    }
    free(bundle->messages);
    free(bundle);
}

const char* get_message(MessageBundle *bundle, const char *key) {
    // Retrieve a message based on the key
    for (int i = 0; bundle->messages[i] != NULL; i++) {
        if (strcmp(bundle->messages[i], key) == 0) {
            return bundle->messages[i + 1];
        }
    }
    return "Translation not found";
}

int main() {
    MessageBundle *bundle = load_message_bundle("en_US");
    printf("%s\n", get_message(bundle, "Hello"));
    free_message_bundle(bundle);
    return 0;
}
