void init_crc_queue() {
    crc_queue.data = (CRC_INDICATION *)malloc(MAX_UE_INFO * sizeof(CRC_INDICATION));
    crc_queue.size = 0;
    crc_queue.capacity = MAX_UE_INFO;
    pthread_mutex_init(&crc_queue.lock, NULL);
}

void enqueue_crc_indication(CRC_INDICATION indication) {
    pthread_mutex_lock(&crc_queue.lock);
    if (crc_queue.size < crc_queue.capacity) {
        crc_queue.data[crc_queue.size++] = indication;
    } else {
        printf("CRC queue is full\n");
    }
    pthread_mutex_unlock(&crc_queue.lock);
}

CRC_INDICATION dequeue_crc_indication() {
    CRC_INDICATION indication = {0};
    pthread_mutex_lock(&crc_queue.lock);
    if (crc_queue.size > 0) {
        indication = crc_queue.data[0];
        for (size_t i = 1; i < crc_queue.size; ++i) {
            crc_queue.data[i - 1] = crc_queue.data[i];
        }
        crc_queue.size--;
    } else {
