#include <chrono>
#include <cmath>
#include <algorithm>
#include <openssl/ssl.h>

// Define constants and structures
const int MAX_CONNECTION_POOL_SIZE = 10;
const double OUTLIER_THRESHOLD = 3.0;
const int RETRY_ATTEMPTS = 5;
const std::chrono::milliseconds RETRY_JITTER(100);
const std::chrono::seconds PRUNE_INTERVAL(60);

struct DATA_POINT {
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    int sensor_id;
    double measurement_value;
};

enum class DataStatus { OK, OUTLIER, ERROR };

// Forward declarations
class ConnectionPool;
class ExternalSystemManager;

class DynamicStreamingDataProcessor {
public:
    DynamicStreamingDataProcessor(ExternalSystemManager& external_manager);
    ~DynamicStreamingDataProcessor();

    void startProcessing(const std::vector<DATA_POINT>& data_points);
    void stopProcessing();

private:
    ExternalSystemManager& external_manager_;
    std::thread processing_thread_;
    std::atomic<bool> running_{false};
    std::queue<DATA_POINT> data_queue_;
    std::mutex queue_mutex_;
    std::condition_variable data_available_cv_;
    ConnectionPool connection_pool_;

    void processData();
    DataStatus filterOutliers(const DATA_POINT& data_point);
    void normalizeData(DATA_POINT& data_point);
    void storeData(const DATA_POINT& data_point);
};

class ExternalSystemManager {
public:
    // Mock methods for demonstration
    bool sendDataToDatabase(const DATA_POINT& data_point) { return true; }
    bool authenticateWithDatabase() { return true; }
    void logError(const std::string& error_message) {}
};

class ConnectionPool {
public:
    ConnectionPool(int max_size) : max_size_(max_size), current_size_(0) {}

    void acquireConnection() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (current_size_ >= max_size_) {
            cv_.wait(lock);
        }
        ++current_size_;
    }

    void releaseConnection() {
        std::unique_lock<std::mutex> lock(mutex_);
        --current_size_;
        cv_.notify_one();
    }

private:
    int max_size_;
    int current_size_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

DynamicStreamingDataProcessor::DynamicStreamingDataProcessor(ExternalSystemManager& external_manager)
    : external_manager_(external_manager), processing_thread_(&DynamicStreamingDataProcessor::processData, this) {}

DynamicStreamingDataProcessor::~DynamicStreamingDataProcessor() {
    stopProcessing();
}

void DynamicStreamingDataProcessor::startProcessing(const std::vector<DATA_POINT>& data_points) {
    running_.store(true);
    for (const auto& point : data_points) {
        std::unique_lock<std::mutex> lock(queue_mutex_);
        data_queue_.push(point);
        data_available_cv_.notify_one();
    }
}

void DynamicStreamingDataProcessor::stopProcessing() {
    running_.store(false);
    data_available_cv_.notify_all();
    processing_thread_.join();
}

void DynamicStreamingDataProcessor::processData() {
    while (running_) {
        std::unique_lock<std::mutex> lock(queue_mutex_);
        data_available_cv_.wait(lock, [this] { return !data_queue_.empty() || !running_; });

        if (!running_ && data_queue_.empty()) break;

        DATA_POINT data_point = data_queue_.front();
        data_queue_.pop();

        lock.unlock();

        DataStatus status = filterOutliers(data_point);
        if (status == DataStatus::OK) {
            normalizeData(data_point);
            storeData(data_point);
        }
    }
}

DataStatus DynamicStreamingDataProcessor::filterOutliers(const DATA_POINT& data_point) {
    // Implement outlier detection logic
    return DataStatus::OK;
}

void DynamicStreamingDataProcessor::normalizeData(DATA_POINT& data_point) {
    // Implement normalization logic
}

void DynamicStreamingDataProcessor::storeData(const DATA_POINT& data_point) {
    connection_pool_.acquireConnection();
    try {
        if (!external_manager_.sendDataToDatabase(data_point)) {
            throw std::runtime_error("Failed to send data to database");
        }
    } catch (...) {
        external_manager_.logError("Exception occurred while storing data");
    } finally {
        connection_pool_.releaseConnection();
    }
}
