#include <iostream>
#include <semaphore.h>
#include <vector>
#include <thread>
#include <mutex>

class SemaphoreManager {
public:
    SemaphoreManager(int initial_count) : sem_(initial_count) {}

    void acquire() {
        sem_wait(&sem_);
    }

    void release() {
        sem_post(&sem_);
    }

private:
    sem_t sem_;
};

class TransactionAggregator {
public:
    TransactionAggregator(size_t num_threads)
        : transaction_lock_(),
          transaction_data_(num_threads),
          total_volume_(0),
          total_weighted_sum_(0) {}

    void add_transaction(const std::vector<int>& transactions) {
        std::lock_guard<std::mutex> lock(transaction_lock_);
        for (int transaction : transactions) {
            total_volume_ += transaction;
            total_weighted_sum_ += transaction * transaction;
        }
    }

    std::pair<long, long> get_metrics() const {
        return {total_volume_, total_weighted_sum_};
    }

private:
    mutable std::mutex transaction_lock_;
    std::vector<std::vector<int>> transaction_data_;
    long total_volume_;
    long total_weighted_sum_;
};

int main() {
    SemaphoreManager sem(3);
    TransactionAggregator aggregator(4);

    auto worker = [&sem, &aggregator](const std::vector<int>& transactions) {
        sem.acquire();
        try {
            aggregator.add_transaction(transactions);
        } finally {
            sem.release();
        }
    };

    std::vector<std::thread> threads;
    for (int i = 0; i < 10; ++i) {
        std::vector<int> transactions = {rand() % 100, rand() % 100};
        threads.emplace_back(worker, transactions);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    auto metrics = aggregator.get_metrics();
    std::cout << "Total Volume: " << metrics.first << ", Total Weighted Sum: " << metrics.second << std::endl;

    return 0;
}
