<?php

class SecureSessionManager {
    private $sessionStorage;
    private $encryptionKey;
    private $tokenLength = 32; // Length of cryptographically secure session tokens in bytes
    private $tokenExpiration = 86400; // Token validity period in seconds (24 hours)
    private $cleanupInterval = 3600; // Interval for periodic cleanup of expired sessions in seconds

    public function __construct($storage, $key) {
        $this->sessionStorage = $storage;
        $this->encryptionKey = $key;
    }

    public function generateToken() {
        return bin2hex(random_bytes($this->tokenLength));
    }

    public function setSessionData($token, $data) {
        $encryptedData = openssl_encrypt(serialize($data), 'AES-256-CBC', $this->encryptionKey);
        $this->sessionStorage->set($token, $encryptedData, $this->tokenExpiration);
    }

    public function getSessionData($token) {
        if ($this->sessionStorage->exists($token)) {
            $encryptedData = $this->sessionStorage->get($token);
            return unserialize(openssl_decrypt($encryptedData, 'AES-256-CBC', $this->encryptionKey));
        }
        return null;
    }

    public function regenerateToken($oldToken, $newToken) {
        if ($this->sessionStorage->exists($oldToken)) {
            $data = $this->getSessionData($oldToken);
            $this->setSessionData($newToken, $data);
            $this->sessionStorage->delete($oldToken);
        }
    }

    public function invalidateSession($token) {
        if ($this->sessionStorage->exists($token)) {
            $this->sessionStorage->delete($token);
        }
    }

    public function cleanupExpiredSessions() {
        $currentTimestamp = time();
        $expiredTokens = $this->sessionStorage->getKeysByPrefix('*')->filter(function($key) use ($currentTimestamp) {
            return (int)$this->sessionStorage->getExpiration($key) < $currentTimestamp;
        });
        foreach ($expiredTokens as $token) {
            $this->invalidateSession($token);
        }
    }

    public function handleConnectionFailure() {
        // Fallback mechanism for local memory storage
        if (!$this->sessionStorage->isConnected()) {
            return new MemorySessionStorage();
        }
        return null;
    }
}

interface SessionStorage {
    public function set($key, $value, $ttl);
    public function get($key);
    public function exists($key);
    public function delete($key);
    public function isConnected();
    public function getKeysByPrefix($prefix);
    public function getExpiration($key);
}

class RedisSessionStorage implements SessionStorage {
    private $redis;

    public function __construct($host, $port) {
        $this->redis = new Redis();
        $this->redis->connect($host, $port);
    }

    public function set($key, $value, $ttl) {
        return $this->redis->setex($key, $ttl, $value);
    }

    public function get($key) {
        return $this->redis->get($key);
    }

    public function exists($key) {
        return $this->redis->exists($key);
    }

    public function delete($key) {
        return $this->redis->delete($key);
    }

    public function isConnected() {
        return $this->redis->ping();
    }

    public function getKeysByPrefix($prefix) {
        return $this->redis->keys("$prefix*");
    }

    public function getExpiration($key) {
        return $this->redis->ttl($key);
    }
}

class MemorySessionStorage implements SessionStorage {
    private $storage = [];

    public function set($key, $value, $ttl) {
        $this->storage[$key] = ['value' => $value, 'expiration' => time() + $ttl];
        return true;
    }

    public function get($key) {
        if (isset($this->storage[$key]) && $this->storage[$key]['expiration'] > time()) {
            return $this->storage[$key]['value'];
        }
        return null;
    }

    public function exists($key) {
        return isset($this->storage[$key]);
    }

    public function delete($key) {
        unset($this->storage[$key]);
        return true;
    }

    public function isConnected() {
        return true;
    }

    public function getKeysByPrefix($prefix) {
        $keys = [];
        foreach ($this->storage as $key => $value) {
            if (strpos($key, $prefix) === 0) {
                $keys[] = $key;
            }
        }
        return $keys;
    }

    public function getExpiration($key) {
        return isset($this->storage[$key]) ? $this->storage[$key]['expiration'] : null;
    }
}

?>
