<?php

class UserPasswordService {
    private $dao;
    private $policyCache;

    public function __construct(DaoInterface $dao, CacheInterface $policyCache) {
        $this->dao = $dao;
        $this->policyCache = $policyCache;
    }

    public function updatePassword($userId, $newPassword) {
        // Fetch the current policy from cache
        $policy = $this->getPasswordPolicy();
        if (!$policy) {
            return false; // Handle error: Policy fetch failed
        }

        // Validate password against policy
        if (!$this->validatePassword($newPassword, $policy)) {
            return false; // Handle error: Invalid password
        }

        // Update the password in the database
        try {
            $this->dao->updatePassword($userId, $newPassword);
        } catch (DatabaseException $e) {
            // Handle database update failure
            return false;
        }

        return true; // Password updated successfully
    }

    private function getPasswordPolicy() {
        // Attempt to retrieve policy from cache
        if ($this->policyCache->has('password_policy')) {
            return $this->policyCache->get('password_policy');
        }

        try {
            // Fetch policy from third-party API
            $response = file_get_contents('https://api.thirdparty.com/password-policy');
            $policy = json_decode($response, true);

            if ($policy) {
                // Store policy in cache for 5 minutes
                $this->policyCache->set('password_policy', $policy, 300);
            }
        } catch (Exception $e) {
            // Handle API request failure or invalid response
        }

        return $policy;
    }

    private function validatePassword($password, $policy) {
        // Check password length
        if (strlen($password) < $policy['min_length']) {
            return false;
        }

        // Check for required character types
        if (!preg_match('/[a-z]/', $password)) return false;
        if (!preg_match('/[A-Z]/', $password)) return false;
        if (!preg_match('/\d/', $password)) return false;

        // Check against other policy rules
        foreach ($policy['rules'] as $rule) {
            if (!$this->$rule($password)) {
                return false;
            }
        }

        return true;
    }

    private function containsSpecialCharacters($password) {
        return preg_match('/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/', $password);
    }

    // Other validation rules can be added here

}

interface DaoInterface {
    public function updatePassword($userId, $newPassword);
}

class DatabaseException extends Exception {}

interface CacheInterface {
    public function has($key);
    public function get($key);
    public function set($key, $value, $ttl);
}
