	"github.com/aws/aws-lambda-go/lambda"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/cors"
)

type Document struct {
	ID        string `json:"id"`
	Name      string `json:"name"`
	Metadata  Metadata `json:"metadata"`
	Content   []byte `json:"content"`
}

type Metadata struct {
	Type    string `json:"type"`
	Size    int64  `json:"size"`
	Created string `json:"created"`
}

func main() {
	r := chi.NewRouter()
	r.Use(cors.Default())

	r.Post("/process", processDocument)

	lambda.Start(HandleRequest)
}

func HandleRequest(ctx context.Context, req events.APIGatewayProxyRequest) (events.APIGatewayProxyResponse, error) {
	return processDocument(req.Body)
}

func processDocument(body string) (events.APIGatewayProxyResponse, error) {
	var document Document
	if err := json.Unmarshal([]byte(body), &document); err != nil {
		return events.APIGatewayProxyResponse{StatusCode: 400}, fmt.Errorf("invalid request body")
	}

	convertedDocument, err := convertDocument(document)
	if err != nil {
		return events.APIGatewayProxyResponse{StatusCode: 500}, fmt.Errorf("failed to convert document: %w", err)
	}

	metadata, err := extractMetadata(convertedDocument)
	if err != nil {
		return events.APIGatewayProxyResponse{StatusCode: 500}, fmt.Errorf("failed to extract metadata: %w", err)
	}

	document.Metadata = metadata

	responseBody, err := json.Marshal(document)
	if err != nil {
		return events.APIGatewayProxyResponse{StatusCode: 500}, fmt.Errorf("failed to marshal response body: %w", err)
	}

	return events.APIGatewayProxyResponse{
		StatusCode: 200,
		Headers:    map[string]string{"Content-Type": "application/json"},
		Body:       string(responseBody),
	}, nil
}

func convertDocument(document Document) (Document, error) {
	// Implement document conversion logic using external API
	converted := Document{
		ID:   document.ID,
		Name: document.Name + "_converted",
	}
	return converted, nil
}

func extractMetadata(document Document) (Metadata, error) {
	// Implement metadata extraction logic using external API
	metadata := Metadata{
		Type:    "PDF",
		Size:    2048,
		Created: time.Now().Format(time.RFC3339),
	}
	return metadata, nil
}
