// Import necessary modules
const express = require('express');
const axios = require('axios');
const jwt = require('jsonwebtoken');
const OAuth2Strategy = require('passport-oauth2').Strategy;
const Redis = require('ioredis');

// Initialize Express app and Redis client
const app = express();
const redis = new Redis();

// Middleware for authentication using JWT
app.use(express.json());
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (token == null) return res.sendStatus(401);

  jwt.verify(token, 'secret-key', (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// Middleware for OAuth2 authentication
passport.use(new OAuth2Strategy({
  authorizationURL: 'https://authorization-server.com/oauth/authorize',
  tokenURL: 'https://authorization-server.com/oauth/token',
  clientID: '123456789',
  clientSecret: 'shhhhhhhhhhh',
  callbackURL: "http://localhost:3000/auth/callback"
},
function(accessToken, refreshToken, profile, cb) {
  return cb(null, profile);
}
));

app.use(passport.initialize());

// Route to handle OAuth2 authentication
app.get('/auth', passport.authenticate('oauth2'));

app.get('/auth/callback', 
  passport.authenticate('oauth2', { failureRedirect: '/login' }),
  function(req, res) {
    // Successful authentication, redirect home.
    res.redirect('/');
  });

// Function to route requests based on the service name
async function routeRequest(serviceName, req, res) {
  try {
    const serviceUrl = await redis.get(`${serviceName}_url`);
    if (!serviceUrl) return res.status(503).send('Service unavailable');

    const response = await axios({
      method: req.method,
      url: `${serviceUrl}${req.url}`,
      data: req.body
    });

    res.status(response.status).send(response.data);
  } catch (error) {
    if (error.response) {
      res.status(error.response.status).send(error.response.data);
    } else {
      res.status(500).send('Internal Server Error');
    }
  }
}

// Example route for a microservice
app.get('/api/service1', authenticateToken, (req, res) => routeRequest('service1', req, res));
app.post('/api/service2', authenticateToken, (req, res) => routeRequest('service2', req, res));

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`API Gateway listening on port ${PORT}`);
});
```

