using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class SecureAESDecryptor : IDisposable
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly IExternalLoggingService _loggingService;
    private readonly ConcurrentQueue<Action> _requestQueue = new ConcurrentQueue<Action>();

    public SecureAESDecryptor(byte[] key, byte[] iv, IExternalLoggingService loggingService)
    {
        if (key == null) throw new ArgumentNullException(nameof(key));
        if (iv == null) throw new ArgumentNullException(nameof(iv));
        if (loggingService == null) throw new ArgumentNullException(nameof(loggingService));

        _key = key;
        _iv = iv;
        _loggingService = loggingService;

        Task.Run(ProcessRequests);
    }

    public async Task<byte[]> DecryptAsync(byte[] ciphertext)
    {
        if (ciphertext == null) throw new ArgumentNullException(nameof(ciphertext));

        var result = await Task.Run(() => AESDecrypt(ciphertext));
        LogDecryptionEvent(result, true);

        return result;
    }

    private byte[] AESDecrypt(byte[] ciphertext)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = _key;
            aes.IV = _iv;

            using (var ms = new MemoryStream(ciphertext))
            using (var cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Read))
            {
                return cs.ToArray();
            }
        }
    }

    private void LogDecryptionEvent(byte[] decryptedData, bool success)
    {
        var logEntry = new LogEntry
        {
            Timestamp = DateTime.UtcNow,
            OperationId = Guid.NewGuid(),
            Success = success,
            Data = Convert.ToBase64String(decryptedData)
        };

        _loggingService.LogAsync(logEntry).GetAwaiter().GetResult();
    }

    private async Task ProcessRequests()
    {
        while (true)
        {
            if (_requestQueue.TryDequeue(out var request))
            {
                try
                {
                    await request();
                }
                catch (Exception ex)
                {
                    LogDecryptionEvent(null, false);
                    _loggingService.LogErrorAsync(ex.Message).GetAwaiter().GetResult();
                }
            }
            else
            {
                await Task.Delay(100); // Sleep to avoid busy-waiting
            }
        }
    }

    public void Dispose()
    {
        while (_requestQueue.TryDequeue(out var _)) { } // Clear the queue
    }

    public void QueueRequest(Action request)
    {
        if (request == null) throw new ArgumentNullException(nameof(request));

        _requestQueue.Enqueue(request);
    }
}

public interface IExternalLoggingService
{
    Task LogAsync(LogEntry logEntry);
    Task LogErrorAsync(string errorMessage);
}

public class LogEntry
{
    public DateTime Timestamp { get; set; }
    public Guid OperationId { get; set; }
    public bool Success { get; set; }
    public string Data { get; set; }
}
