const express = require('express');
const WebSocket = require('ws');
const { MongoClient } = require('mongodb');
const axios = require('axios');

const app = express();
const wss = new WebSocket.Server({ port: 8080 });
const client = new MongoClient('mongodb://localhost:27017', { useNewUrlParser: true, useUnifiedTopology: true });

app.use(express.json());

client.connect().then(() => {
  console.log('Connected to MongoDB');
}).catch(err => {
  console.error('Failed to connect to MongoDB:', err);
});

wss.on('connection', async ws => {
  ws.on('message', async message => {
    const data = JSON.parse(message);

    switch (data.type) {
      case 'edit':
        // Handle document edit
        await updateDocument(data.documentId, data.changes);
        broadcastEdit(data.documentId, data.changes);
        break;
      case 'chat':
        // Handle chat message
        await storeChatMessage(data.message);
        broadcastChatMessage(data.message);
        break;
    }
  });
});

function broadcastEdit(documentId, changes) {
  wss.clients.forEach(ws => {
    if (ws.readyState === WebSocket.OPEN && ws.documentId === documentId) {
      ws.send(JSON.stringify({ type: 'edit', changes }));
    }
  });
}

function broadcastChatMessage(message) {
  wss.clients.forEach(ws => {
    if (ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify({ type: 'chat', message }));
    }
  });
}

async function updateDocument(documentId, changes) {
  const db = client.db('collaborativeDocs');
  const collection = db.collection('documents');

  await collection.updateOne({ _id: documentId }, { $set: { content: changes } });
}

async function storeChatMessage(message) {
  const db = client.db('collaborativeDocs');
  const collection = db.collection('chatMessages');

  await collection.insertOne(message);
}

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

