type MarketData struct {
    StockSymbol string
    Price       float64
    Timestamp   time.Time
}

func fetchAndProcessLiveMarketData(ctx context.Context, stockSymbols []string) error {
    // Create a channel to receive market data from multiple sources
    dataChan := make(chan *MarketData)

    // Function to fetch data from an external API and send it to the dataChan
    fetchDataFromAPI := func(symbol string) {
        resp, err := http.Get(fmt.Sprintf("https://api.example.com/market/%s", symbol))
        if err != nil {
            log.Printf("Error fetching market data for %s: %v", symbol, err)
            return
        }
        defer resp.Body.Close()

        var md MarketData
        if err := proto.UnmarshalText(resp.Body, &md); err != nil {
            log.Printf("Error unmarshalling market data for %s: %v", symbol, err)
            return
        }

        select {
        case <-ctx.Done():
            return
        case dataChan <- &md:
        }
    }

    // Start fetching data from each stock symbol in a separate goroutine
    for _, symbol := range stockSymbols {
        go fetchDataFromAPI(symbol)
    }

    // Process incoming market data
    for i := 0; i < len(stockSymbols); i++ {
        select {
        case <-ctx.Done():
            return ctx.Err()
        case md := <-dataChan:
            processMarketData(md)
        }
    }

    return nil
}

func processMarketData(md *MarketData) {
    // Implement your data processing logic here
    log.Printf("Processed market data: %+v", md)
}
