#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** buffer;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} ObjectPool;

void init_object_pool(ObjectPool* pool, size_t capacity) {
    pool->buffer = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (size_t i = 0; i < capacity; ++i) {
        pool->buffer[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    pool->capacity = capacity;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_pool(ObjectPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used == pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }
    NFAPI_CRC_INDICATION_PDU_T* item = pool->buffer[pool->used++];
    pthread_mutex_unlock(&pool->lock);
    return item;
}

void free_to_pool(ObjectPool* pool, NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used == 0) {
        pthread_mutex_unlock(&pool->lock);
        free(item); // Free item if pool is empty
        return;
    }
    pool->buffer[--pool->used] = item;
    pthread_mutex_unlock(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_list(size_t N, ObjectPool* pool) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** current = &head;

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* item = get_from_pool(pool);
        if (!item) {
            // Handle pool exhaustion
            fprintf(stderr, "Object pool exhausted\n");
            break;
        }
        item->RX_UE_INFORMATION_TAG = rand() % 1000; // Simulated tag retrieval
        item->RNTI = rand() % 1024; // Simulated RNTI retrieval
        item->CRCFLAG = rand() & 1; // Randomly set CRCFLAG
        item->next = NULL;

        *current = item;
        current = &item->next;
    }

    return head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    while (list) {
        NFAPI_CRC_INDICATION_PDU_T* next = list->next;
        free(list);
        list = next;
    }
}

int main() {
    ObjectPool pool;
    init_object_pool(&pool, 100);

    NFAPI_CRC_INDICATION_PDU_T* list = create_list(50, &pool);
    // Process the list...

    free_list(list);
    free_object_pool(&pool);

    return 0;
}
```

