// Define the NFAPI_CRC_INDICATION_PDU_T structure
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

// Pre-allocated buffer and mutex for object pooling
std::vector<NFAPI_CRC_INDICATION_PDU_T*> pool;
std::mutex poolMutex;

// Queue to manage producer-consumer workload
std::queue<int> rntiQueue;
std::mutex queueMutex;
std::condition_variable notEmpty;
bool done = false;

// Function to fetch RX_UE_INFORMATION_TAG and RNTI from external REST API
NFAPI_CRC_INDICATION_PDU_T* fetchFromAPI(int rnti) {
    // Simulate fetching data with a random delay
    std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 500));
    NFAPI_CRC_INDICATION_PDU_T* pdu = getFromPool();
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rnti;
    pdu->CRCFLAG = (rand() % 2 == 0);
    return pdu;
}

// Function to add elements to the linked list
void buildNfapiCrcList(int N) {
    std::vector<std::thread> threads;

    // Producer thread to enqueue RNTI values
    std::thread producer([&]() {
        for (int i = 0; i < N; ++i) {
            std::unique_lock<std::mutex> lock(queueMutex);
            rntiQueue.push(rand() % 100); // Simulate random RNTI values
            notEmpty.notify_one();
        }
        done = true;
        notEmpty.notify_one();
    });

    // Consumer thread to build the linked list
    std::thread consumer([&]() {
        while (true) {
            int rnti;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                notEmpty.wait(lock, []{ return !rntiQueue.empty() || done; });
                if (done && rntiQueue.empty()) break;
                rnti = rntiQueue.front();
                rntiQueue.pop();
            }

            NFAPI_CRC_INDICATION_PDU_T* pdu = fetchFromAPI(rnti);
            // Add pdu to the linked list
        }
    });

    producer.join();
    consumer.join();

    // Clean up pool
    for (auto& pdu : pool) {
        delete pdu;
    }
}

// Function to get an element from the object pool
NFAPI_CRC_INDICATION_PDU_T* getFromPool() {
    std::unique_lock<std::mutex> lock(poolMutex);
    if (!pool.empty()) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = pool.back();
        pool.pop_back();
        return pdu;
    }
    return new NFAPI_CRC_INDICATION_PDU_T;
}

// Function to return an element to the object pool
void returnToPool(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    std::unique_lock<std::mutex> lock(poolMutex);
    pool.push_back(pdu);
}
