#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define CACHE_SIZE 1024
#define API_TIMEOUT 5
#define GROWTH_STRATEGY 25
#define MAX_FILENAME_LENGTH 256

typedef struct {
    int *data;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray *create_dynamic_array() {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    array->capacity = CACHE_SIZE;
    array->size = 0;
    array->data = (int *)calloc(array->capacity, sizeof(int));
    return array;
}

void resize_dynamic_array(DynamicArray *array) {
    array->capacity += array->capacity * GROWTH_STRATEGY / 100;
    array->data = (int *)realloc(array->data, array->capacity * sizeof(int));
}

void add_to_dynamic_array(DynamicArray *array, int value) {
    if (array->size == array->capacity)
        resize_dynamic_array(array);
    array->data[array->size++] = value;
}

void free_dynamic_array(DynamicArray *array) {
    free(array->data);
    free(array);
}

typedef struct {
    DynamicArray *cache;
    pthread_mutex_t lock;
} Cache;

Cache *create_cache() {
    Cache *cache = (Cache *)malloc(sizeof(Cache));
    cache->cache = create_dynamic_array();
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void add_to_cache(Cache *cache, int value) {
    pthread_mutex_lock(&cache->lock);
    add_to_dynamic_array(cache->cache, value);
    pthread_mutex_unlock(&cache->lock);
}

void free_cache(Cache *cache) {
    pthread_mutex_destroy(&cache->lock);
    free_dynamic_array(cache->cache);
    free(cache);
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    Cache *cache = (Cache *)userp;
    pthread_mutex_lock(&cache->lock);
    if (realsize > cache->cache->capacity - cache->cache->size)
        resize_dynamic_array(cache->cache);
    memcpy(cache->cache->data + cache->cache->size, contents, realsize);
    cache->cache->size += realsize;
    pthread_mutex_unlock(&cache->lock);
    return realsize;
}

void fetch_and_store(Cache *cache, const char *api_url) {
    CURL *curl = curl_easy_init();
    if (curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Accept: application/json");
        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, API_TIMEOUT);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, cache);
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
}

void *worker_thread(void *arg) {
    Cache *cache = (Cache *)arg;
    fetch_and_store(cache, "https://api.example.com/numbers");
    return NULL;
}

int main() {
    Cache *cache = create_cache();
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, worker_thread, cache);
    pthread_create(&thread2, NULL, worker_thread, cache);
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    for (size_t i = 0; i < cache->cache->size; i++) {
        printf("%d\n", cache->cache->data[i]);
    }

    free_cache(cache);
    return 0;
}
