import time
from concurrent.futures import ThreadPoolExecutor
from db_connection_pool import ConnectionPool
from sensor_data_stream import SensorDataStream
from time_series_db_api import TimeSeriesDBApi
from retrying import retry

class StreamProcessor:
    def __init__(self, db_config, stream_config):
        self.db_config = db_config
        self.stream_config = stream_config
        self.db_pool = ConnectionPool(**db_config)
        self.sensor_stream = SensorDataStream(**stream_config)

    @retry(stop_max_attempt_number=3, wait_fixed=2000)
    def process_data(self, data):
        with self.db_pool.get_connection() as conn:
            TimeSeriesDBApi(conn).store_data(data)

    def run(self):
        with ThreadPoolExecutor(max_workers=self.stream_config['num_threads']) as executor:
            for data in self.sensor_stream.read():
                executor.submit(self.process_data, data)

if __name__ == "__main__":
    db_config = {
        'host': 'localhost',
        'port': 5432,
        'user': 'admin',
        'password': 'securepass'
    }
    stream_config = {
        'sensor_id': 'sensor123',
        'num_threads': 10
    }
    processor = StreamProcessor(db_config, stream_config)
    processor.run()
