#include <iostream>
#include <unordered_map>
#include <list>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class GeolocationCache {
private:
    std::unordered_map<std::string, std::pair<std::string, std::time_t>> cache;
    std::list<std::string> lruList;
    std::mutex mutex;
    std::condition_variable cv;
    size_t capacity;
    size_t maxCapacity;

public:
    GeolocationCache(size_t initialCapacity) : capacity(0), maxCapacity(initialCapacity) {}

    void set(const std::string& key, const std::string& value, std::time_t ttl = 3600) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = cache.find(key);

        if (it != cache.end()) {
            lruList.erase(std::find(lruList.begin(), lruList.end(), key));
        }

        cache[key] = {value, ttl + std::time(nullptr)};
        lruList.push_back(key);

        capacity++;
        if (capacity > maxCapacity) {
            evict();
        }
    }

    std::string get(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = cache.find(key);

        if (it != cache.end() && std::time(nullptr) < it->second.second) {
            lruList.erase(std::find(lruList.begin(), lruList.end(), key));
            lruList.push_back(key);
            return it->second.first;
        } else if (it != cache.end()) {
            cache.erase(it);
            capacity--;
        }

        cv.notify_one();
        return "";
    }

private:
    void evict() {
        std::unique_lock<std::mutex> lock(mutex);
        while (!lruList.empty() && std::time(nullptr) >= cache[lruList.front()].second) {
            auto key = lruList.front();
            cache.erase(key);
            lruList.pop_front();
            capacity--;
        }

        if (capacity > maxCapacity) {
            cv.notify_one();
        }
    }
};

int main() {
    GeolocationCache cache(10);
    cache.set("user1", "New York");
    std::cout << "Geolocation for user1: " << cache.get("user1") << std::endl;
    return 0;
}
