    private readonly Dictionary<string, string> _apiKeys;
    private readonly ILogger _logger;

    public EventProcessorService(HttpClient httpClient, IDictionary<string, string> apiKeys, ILogger logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _apiKeys = apiKeys ?? new Dictionary<string, string>();
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task ProcessEventStreamsAsync()
    {
        try
        {
            var streams = GetEventStreams();
            await Task.WhenAll(streams.Select(ProcessStreamAsync));
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing event streams");
        }
    }

    private IEnumerable<Task> GetEventStreams()
    {
        // Simulate getting event stream URLs
        return Enumerable.Range(1, 5).Select(i => $"https://api.example.com/stream{i}");
    }

    private async Task ProcessStreamAsync(string url)
    {
        try
        {
            var response = await _httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead);
            response.EnsureSuccessStatusCode();

            var content = await response.Content.ReadAsStringAsync();
            var events = ParseJsonEvents(content);

            foreach (var event in events)
            {
                var transformedEvent = TransformEvent(event);
                var aggregatedData = AggregateData(transformedEvent);

                // Process aggregated data
                await ProcessAggregatedDataAsync(aggregatedData);
            }
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Error processing event stream from {Url}", url);
            // Implement retry logic here
        }
