#include <atomic>

// Define the DataItem structure
struct DataItem {
    std::chrono::system_clock::time_point timestamp;
    std::string key;
    std::vector<int> values;

    DataItem(std::chrono::system_clock::time_point ts, const std::string& k, std::vector<int>&& v)
        : timestamp(ts), key(k), values(std::move(v)) {}
};

// Forward declaration of the DatabaseManager class
class DatabaseManager;

// Define a shared pointer to DataItem for thread-safe access
using DataItemPtr = std::shared_ptr<DataItem>;

// Memory pool class for efficient memory management
class MemoryPool {
public:
    using DataItemAllocator = std::allocator<DataItem>;
    using DataItemDeleter = std::function<void(DataItem*)>;

    DataItem* allocate(std::size_t n) {
        return m_allocator.allocate(n);
    }

    void deallocate(DataItem* p, std::size_t n) {
        m_allocator.deallocate(p, n);
    }

private:
    DataItemAllocator m_allocator;
};

// Message queue class for asynchronous processing
class MessageQueue {
public:
    void enqueue(const DataItemPtr& item) {
        std::lock_guard<std::mutex> lock(m_mutex);
        m_queue.push(item);
        m_cv.notify_one();
    }

    void dequeue(DataItemPtr& item) {
        std::unique_lock<std::mutex> lock(m_mutex);
        m_cv.wait(lock, [this]{ return !m_queue.empty(); });
        item = m_queue.front();
        m_queue.pop();
    }

private:
    std::queue<DataItemPtr> m_queue;
    std::mutex m_mutex;
    std::condition_variable m_cv;
};

// DatabaseManager class for interacting with the external time-series database
class DatabaseManager {
public:
    void insert(const DataItemPtr& item) {
        // Simulate database insertion
        std::cout << "Inserting data at " << std::chrono::system_clock::to_time_t(item->timestamp) << std::endl;
    }

    void deleteData(const std::string& key) {
        // Simulate database deletion
        std::cout << "Deleting data with key: " << key << std::endl;
    }
};

// Main class for managing the dynamic collection of DataItem objects
class DataItemManager {
public:
    DataItemManager(std::shared_ptr<DatabaseManager> dbManager)
        : m_dbManager(dbManager), m_shutdown(false) {}

    void addData(const DataItemPtr& item) {
        std::lock_guard<std::mutex> lock(m_mutex);
        m_dataItems.push_back(item);
    }

    void startProcessing() {
        for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
            m_threads.emplace_back([this] { processQueue(); });
        }
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(m_mutex);
            m_shutdown = true;
        }
        for (auto& thread : m_threads) {
            thread.join();
        }
    }

private:
    void processQueue() {
        while (true) {
            DataItemPtr item;
            m_queue.dequeue(item);
            if (!item) break;
            m_dbManager->insert(item);
        }
    }

    std::shared_ptr<DatabaseManager> m_dbManager;
    std::vector<DataItemPtr> m_dataItems;
    MessageQueue m_queue;
    std::vector<std::thread> m_threads;
    std::atomic<bool> m_shutdown;
};

int main() {
    auto dbManager = std::make_shared<DatabaseManager>();
    DataItemManager manager(dbManager);

    // Simulate adding data
    for (size_t i = 0; i < 10000; ++i) {
        std::vector<int> values = {i, i * 2, i * 3};
        auto item = std::make_shared<DataItem>(std::chrono::system_clock::now(), "key" + std::to_string(i), std::move(values));
        manager.addData(item);
    }

    // Start processing
    manager.startProcessing();

    // Stop processing after some time
    std::this_thread::sleep_for(std::chrono::seconds(10));
    manager.stopProcessing();

    return 0;
}
