    std::string format(const std::string& message, LogLevel level) const override {
        // Implement file formatting logic
    }
};

// Network Output Format
class NetworkFormat : public IOutputFormat {
public:
    std::string format(const std::string& message, LogLevel level) const override {
        // Implement network formatting logic
    }
};

// Log Sink Interface
class ISink {
public:
    virtual void log(const std::string& message, LogLevel level) = 0;
    virtual ~ISink() {}
};

// Console Sink
class ConsoleSink : public ISink {
public:
    void log(const std::string& message, LogLevel level) override {
        // Implement console logging logic
    }
};

// File Sink
class FileSink : public ISink {
public:
    void log(const std::string& message, LogLevel level) override {
        // Implement file logging logic
    }
};

// Network Sink
class NetworkSink : public ISink {
public:
    void log(const std::string& message, LogLevel level) override {
        // Implement network logging logic
    }
};

// Logger Class
class Logger {
private:
    IOutputFormat* outputFormat;
    ISink* sink;
    LogLevel currentLevel;

public:
    Logger(IOutputFormat* format, ISink* sink, LogLevel level)
        : outputFormat(format), sink(sink), currentLevel(level) {}

    ~Logger() {
        delete outputFormat;
        delete sink;
    }

    void setFormat(IOutputFormat* newFormat) {
        outputFormat = newFormat;
    }

    void setSink(ISink* newSink) {
        sink = newSink;
    }

    void log(const std::string& message, LogLevel level) {
        if (level >= currentLevel) {
            std::string formattedMessage = outputFormat->format(message, level);
            sink->log(formattedMessage, level);
        }
    }
};

// Example Usage
int main() {
    IOutputFormat* consoleFormat = new ConsoleFormat();
    ISink* consoleSink = new ConsoleSink();

    Logger logger(consoleFormat, consoleSink, LogLevel::Info);

    logger.log("This is an info message.", LogLevel::Info);
    logger.log("This is a warning message.", LogLevel::Warning);

    delete consoleFormat;
    delete consoleSink;

    return 0;
}
```

