#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} record;

void* bulk_record_initializer(void* arg) {
    int count = *(int*)arg;
    if (count <= 0) {
        fprintf(stderr, "Invalid count\n");
        return NULL;
    }

    // Dynamically allocate memory for arrays
    long* offsets = (long*)malloc(count * sizeof(long));
    int* keys = (int*)malloc(count * sizeof(int));
    record* records = (record*)malloc(count * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize arrays with sample data
    for (int i = 0; i < count; i++) {
        offsets[i] = i * 10L;
        keys[i] = i + 1;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Simulate thread-safe operations
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    // Perform operations with offsets, keys, and records
    pthread_mutex_unlock(&mutex);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    int count = 1000;
    pthread_t thread;

    if (pthread_create(&thread, NULL, bulk_record_initializer, &count) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        return 1;
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Thread join failed\n");
        return 1;
    }

    return 0;
}
```

