void* generate_and_store_pdus(void* arg) {
    ConfigParams* config = (ConfigParams*)arg;
    size_t N = config->N;
    int batch_size = config->batch_size;

    pthread_mutex_lock(&global_mutex);

    NFAPI_CRC_INDICATION_PDU_T** pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdus) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for PDUs");
        pthread_mutex_unlock(&global_mutex);
        return NULL;
    }

    int retry_count = 0;
    while (retry_count < config->max_retries) {
        for (size_t i = 0; i < N; i += batch_size) {
            size_t end = (i + batch_size > N) ? N : i + batch_size;

            for (size_t j = i; j < end; ++j) {
                pdus[j] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!pdus[j]) {
                    log_message(LOG_LEVEL_ERROR, "Memory allocation failed for PDU");
                    goto cleanup;
                }

                // Populate the PDU structure with valid values
                pdus[j]->RX_UE_INFORMATION_TAG = j % 100; // Example value
                pdus[j]->RNTI = j % 1024; // Example value
                pdus[j]->CRC_INDICATION_REL8_TAG = (rand() % 2); // Random CRC flag
            }

            if (write_to_database(pdus, end - i) != 0) {
                log_message(LOG_LEVEL_WARNING, "Database write failed. Retrying...");
                retry_count++;
                usleep(config->retry_delay_ms * 1000);
                continue;
            } else {
                retry_count = 0; // Reset retry count on successful write
            }
        }

        break; // Exit loop if all PDUs are successfully written
    }

cleanup:
    for (size_t i = 0; i < N; ++i) {
        free(pdus[i]);
    }
    free(pdus);

    pthread_mutex_unlock(&global_mutex);
    return NULL;
}

int main() {
    ConfigParams config_params = {
        .N = 1000,
        .batch_size = 500,
        .max_retries = 3,
        .retry_delay_ms = 200,
        .log_level = LOG_LEVEL_INFO
    };

    pthread_t thread;
    if (pthread_create(&thread, NULL, generate_and_store_pdus, &config_params) != 0) {
        log_message(LOG_LEVEL_ERROR, "Failed to create thread");
        return -1;
    }

    pthread_join(thread, NULL);

    return 0;
}
