#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <functional>

class NetworkEventLogger {
public:
    struct Event {
        std::time_t timestamp;
        std::string eventType;
        int cellID;
        std::string imsi;
        std::optional<std::string> payload;
    };

    NetworkEventLogger(std::vector<std::function<void(const Event&)>> loggers)
        : loggers_(loggers), should_stop_(false) {
        for (int i = 0; i < loggers_.size(); ++i) {
            worker_threads_.emplace_back([this, i]() { worker(i); });
        }
    }

    ~NetworkEventLogger() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            should_stop_ = true;
        }
        cv_.notify_all();
        for (auto& thread : worker_threads_) {
            thread.join();
        }
    }

    void log(const Event& event) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            event_queue_.push(event);
        }
        cv_.notify_one();
    }

private:
    void worker(int loggerIndex) {
        while (true) {
            Event event;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return !event_queue_.empty() || should_stop_; });
                if (should_stop_ && event_queue_.empty()) break;
                event = event_queue_.front();
                event_queue_.pop();
            }
            try {
                loggers_[loggerIndex](event);
            } catch (...) {
                std::cerr << "Error processing event" << std::endl;
            }
        }
    }

    std::vector<std::function<void(const Event&)>> loggers_;
    std::queue<Event> event_queue_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool should_stop_;
    std::vector<std::thread> worker_threads_;
};
