	queueURL := "https://sqs.us-west-2.amazonaws.com/123456789012/my-payment-queue"

	// Process messages from the SQS queue
	for {
		select {
		case <-time.After(time.Second * 5):
			processMessages(sqsClient, queueURL)
		}
	}
}

func processMessages(sqsClient *sqs.Client, queueURL string) {
	// Receive messages from the SQS queue
	output, err := sqsClient.ReceiveMessage(context.TODO(), &sqs.ReceiveMessageInput{
		QueueUrl:            &queueURL,
		AttributeNames:      []string{"All"},
		MessageAttributeNames: []string{"All"},
		MaxNumberOfMessages: 10,
	})
	if err != nil {
		fmt.Println("Error receiving messages:", err)
		return
	}

	for _, message := range output.Messages {
		// Process each message (e.g., payment processing logic)
		processPayment(message.Body)

		// Delete the message from the queue after processing
		_, err = sqsClient.DeleteMessage(context.TODO(), &sqs.DeleteMessageInput{
			QueueUrl:      &queueURL,
			ReceiptHandle: message.ReceiptHandle,
		})
		if err != nil {
			fmt.Println("Error deleting message:", err)
		}
	}
}

