#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int cell_id;
    void* payload;
    size_t payload_size;
} MobileEvent;

typedef struct Node {
    MobileEvent event;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} EventList;

void init_event_list(EventList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_event_list(EventList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->event.payload);
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void insert_event(EventList* list, MobileEvent event) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        return;
    }
    new_node->event = event;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

MobileEvent* retrieve_event(EventList* list, int cell_id) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (current->event.cell_id == cell_id) {
            MobileEvent* event_copy = (MobileEvent*)malloc(sizeof(MobileEvent));
            if (event_copy == NULL) {
                perror("Failed to allocate memory for event copy");
                pthread_mutex_unlock(&list->lock);
                return NULL;
            }
            memcpy(event_copy, &current->event, sizeof(MobileEvent));
            pthread_mutex_unlock(&list->lock);
            return event_copy;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int delete_event(EventList* list, int cell_id) {
    pthread_mutex_lock(&list->lock);
    Node** current_ptr = &list->head;
    while (*current_ptr != NULL) {
        if ((*current_ptr)->event.cell_id == cell_id) {
            Node* node_to_delete = *current_ptr;
            *current_ptr = (*current_ptr)->next;
            free(node_to_delete->event.payload);
            free(node_to_delete);
            pthread_mutex_unlock(&list->lock);
            return 0; // Successfully deleted
        }
        current_ptr = &(*current_ptr)->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Event not found
}
