typedef struct {
    int id;
    time_t timestamp;
    char *json_payload;
} MobileEvent;

MobileEvent* bulk_event_initializer(int num_events) {
    if (num_events > MAX_EVENTS) {
        fprintf(stderr, "Error: Number of events exceeds maximum limit.\n");
        return NULL;
    }

    MobileEvent *events = malloc(num_events * sizeof(MobileEvent));
    if (!events) {
        perror("Failed to allocate memory for events.");
        return NULL;
    }

    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_events; i++) {
        events[i].id = i + 1;
        events[i].timestamp = time(NULL) - rand() % 86400; // Random timestamp within last day
        events[i].json_payload = malloc(256 * sizeof(char)); // Allocate memory for JSON payload

        if (!events[i].json_payload) {
            perror("Failed to allocate memory for JSON payload.");
            free(events);
            return NULL;
        }

        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/generate_json");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, JSON_SCHEMA);
        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "Failed to generate JSON payload for event %d: %s\n", i + 1, curl_easy_strerror(res));
            free(events[i].json_payload);
            continue;
        }

        // Assuming the server returns a valid JSON payload
        strcpy(events[i].json_payload, "Generated JSON payload here");
    }

    if (curl) {
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return events;
}

int main() {
    MobileEvent *events = bulk_event_initializer(50);

    if (events) {
        for (int i = 0; i < 50; i++) {
            printf("Event %d: ID=%d, Timestamp=%ld, JSON Payload=%s\n", i + 1, events[i].id, events[i].timestamp, events[i].json_payload);
            free(events[i].json_payload);
        }
        free(events);
    }

    return 0;
}
