#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define structures for mobile network traffic events
typedef struct {
    long timestamp;
    int cell_id;
    char *json_payload;
} MobileEvent;

// Define a simple linked list for managing the dynamic list of events
typedef struct EventNode {
    MobileEvent event;
    struct EventNode *next;
} EventNode;

EventNode *event_list_head = NULL;

// Function to add an event to the list (thread-safe with mutex)
void add_event(MobileEvent event) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    EventNode *new_node = (EventNode *)malloc(sizeof(EventNode));
    new_node->event = event;
    new_node->next = event_list_head;
    event_list_head = new_node;

    pthread_mutex_unlock(&lock);
}

// Function to remove an event from the list (thread-safe with mutex)
void remove_event(MobileEvent event) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    EventNode *current = event_list_head;
    EventNode *previous = NULL;

    while (current != NULL) {
        if (memcmp(&current->event, &event, sizeof(MobileEvent)) == 0) {
            if (previous == NULL) {
                event_list_head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

// Function to find an event in the list (thread-safe with mutex)
MobileEvent *find_event(long timestamp) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    EventNode *current = event_list_head;

    while (current != NULL) {
        if (current->event.timestamp == timestamp) {
            MobileEvent *found_event = &current->event;
            pthread_mutex_unlock(&lock);
            return found_event;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

// Function to clean up the event list (thread-safe with mutex)
void cleanup_events() {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    EventNode *current = event_list_head;
    while (current != NULL) {
        EventNode *next = current->next;
        free(current);
        current = next;
    }
    event_list_head = NULL;

    pthread_mutex_unlock(&lock);
}

// Example usage
int main() {
    MobileEvent event1 = {time(NULL), 123, "{\"message_type\":\"RRC\", \"data\":\"...\"}"};
    add_event(event1);

    MobileEvent *found_event = find_event(event1.timestamp);
    if (found_event != NULL) {
        printf("Found event: %ld\n", found_event->timestamp);
    }

    remove_event(event1);
    cleanup_events();

    return 0;
}
```

