NFAPI_CRC_INDICATION_PDU_T* process_json_config(const char* json_string) {
    // Parse JSON string to extract required fields
    struct json_object *parsed_json, *access_token_obj, *expires_in_obj, *token_type_obj;
    if (!json_object_from_json_string(json_string, &parsed_json)) {
        fprintf(stderr, "Failed to parse JSON\n");
        return NULL;
    }

    access_token_obj = json_object_object_get_ex(parsed_json, "access_token", NULL);
    expires_in_obj = json_object_object_get_ex(parsed_json, "expires_in", NULL);
    token_type_obj = json_object_object_get_ex(parsed_json, "token_type", NULL);

    if (!access_token_obj || !expires_in_obj || !token_type_obj) {
        fprintf(stderr, "Missing required fields in JSON\n");
        json_object_put(parsed_json);
        return NULL;
    }

    const char* access_token = json_object_get_string(access_token_obj);
    int expires_in = json_object_get_int(expires_in_obj);
    const char* token_type = json_object_get_string(token_type_obj);

    if (strcmp(token_type, "Bearer") != 0 || expires_in <= 0) {
        fprintf(stderr, "Invalid token type or expires_in value\n");
        json_object_put(parsed_json);
        return NULL;
    }

    // Validate optional fields
    const char* scope = NULL;
    const char* audience = NULL;

    struct json_object *scope_obj = json_object_object_get_ex(parsed_json, "scope", NULL);
    if (scope_obj) {
        scope = json_object_get_string(scope_obj);
    }

    struct json_object *audience_obj = json_object_object_get_ex(parsed_json, "audience", NULL);
    if (audience_obj) {
        audience = json_object_get_string(audience_obj);
    }

    // Generate NFAPI_CRC_INDICATION_PDU_T structure
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    strcpy(pdu->access_token, access_token);
    pdu->expires_in = expires_in;
    strcpy(pdu->token_type, token_type);

    if (scope) {
        strcpy(pdu->scope, scope);
    } else {
        strcpy(pdu->scope, "");
    }

    if (audience) {
        strcpy(pdu->audience, audience);
    } else {
        strcpy(pdu->audience, "");
    }

    json_object_put(parsed_json);

    return pdu;
}

void refresh_token(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    CURL *curl = curl_easy_init();
    if(curl) {
        struct json_object *payload_obj = json_object_new_object();
        json_object_object_add(payload_obj, "grant_type", json_object_new_string("refresh_token"));
        json_object_object_add(payload_obj, "refresh_token", json_object_new_string(pdu->access_token));

