NFAPI_CRC_INDICATION_PDU_T* process_json_config(const char* json_str) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
    // Parse JSON and validate fields
    json_error_t error;
    json_t* root = json_loads(json_str, 0, &error);
    if (!root || !json_is_object(root)) {
        log_error("Invalid JSON format");
        return pdu_list;
    }

    // Extract required fields and validate them
    const char* access_token = json_string_value(json_object_get(root, "access_token"));
    int expires_in = json_integer_value(json_object_get(root, "expires_in"));
    const char* token_type = json_string_value(json_object_get(root, "token_type"));

    if (!access_token || !token_type || expires_in <= 0 || strcmp(token_type, "Bearer") != 0) {
        log_error("Invalid or missing required fields");
        json_decref(root);
        return pdu_list;
    }

    // Check cache for token
    pthread_mutex_lock(&cache_lock);
    time_t current_time = time(NULL);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (token_cache[i].expires_at > current_time && strcmp(token_cache[i].pdu.access_token, access_token) == 0) {
            pthread_mutex_unlock(&cache_lock);
            pdu_list = &token_cache[i].pdu;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    if (pdu_list != NULL) {
        return pdu_list;
    }

    // Fetch token from OAuth2 service
    oauth2_token* token = oauth2_session_fetch_token(oauth2_session, "authorization_code", access_token);
    if (!token) {
        log_error("Failed to fetch token");
        json_decref(root);
        return pdu_list;
    }

    // Convert token to NFAPI structure and store in cache
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (token_cache[i].expires_at <= current_time) {
            pdu_list = &token_cache[i];
            break;
        }
    }

    if (pdu_list == NULL) {
        // Cache is full, overwrite the oldest entry
        int oldest_index = 0;
        for (int i = 1; i < CACHE_SIZE; ++i) {
            if (token_cache[i].expires_at < token_cache[oldest_index].expires_at) {
                oldest_index = i;
            }
        }
        pdu_list = &token_cache[oldest_index];
    }

    // Populate NFAPI structure
    strcpy(pdu_list->access_token, access_token);
    pdu_list->expiry_time = expires_in;
    pthread_mutex_unlock(&cache_lock);

    json_decref(root);
    return pdu_list;
}

void* worker_thread(void* arg) {
    // Process JSON strings from a queue using the process_json_config function
    while (1) {
        // Wait for work from the queue and process it
        char* json_str = get_work_from_queue();
        if (!json_str) break;

        NFAPI_CRC_INDICATION_PDU_T* pdu_list = process_json_config(json_str);
        free(json_str);

        if (pdu_list) {
            // Handle the PDU list as needed
            handle_pdu_list(pdu_list);
        }
    }

    return NULL;
}

void start_token_processor(int num_threads, const char* oauth2_client_id, const char* oauth2_client_secret) {
    // Initialize OAuth2 session
    oauth2_config config = {0};
    oauth2_config_init(&config);
    config.client_id = oauth2_client_id;
    config.client_secret = oauth2_client_secret;
    oauth2_session = oauth2_session_new("https://oauth2.example.com", &config);

    // Create worker threads
    pthread_t* threads = malloc(num_threads * sizeof(pthread_t));
    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, worker_thread, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    oauth2_session_free(oauth2_session);
}
