    for (size_t i = 0; i < count; ++i) {
        NAS_Signaling_Message* msg = messages[i];
        // Process each message in a thread-safe manner
        process_message(msg);
    }
}

void free_nas_messages(NAS_Signaling_Message** messages, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        NAS_Signaling_Message* msg = messages[i];
