// Thread-safe queue for batch processing
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** pdu_queue;
    size_t front;
    size_t rear;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} PDU_Queue;

void init_pdu_queue(PDU_Queue* queue, size_t capacity) {
    queue->pdu_queue = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * capacity);
    if (queue->pdu_queue == NULL) {
        return;
    }
    queue->front = 0;
    queue->rear = -1;
    queue->capacity = capacity;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

void enqueue_pdu(PDU_Queue* queue, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&queue->mutex);
    while ((queue->rear + 1) % queue->capacity == queue->front) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }
    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->pdu_queue[queue->rear] = pdu;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* dequeue_pdu(PDU_Queue* queue) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    pthread_mutex_lock(&queue->mutex);
    while (queue->front == queue->rear) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }
    pdu = queue->pdu_queue[queue->front];
    queue->front = (queue->front + 1) % queue->capacity;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->mutex);
    return pdu;
}

void destroy_pdu_queue(PDU_Queue* queue) {
    for (size_t i = queue->front; i != queue->rear;) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = dequeue_pdu(queue);
        free_pdu(pdu);
    }
    free(queue->pdu_queue);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
}

int main() {
    // Example usage
    PDU_Queue queue;
    init_pdu_queue(&queue, 10);

    NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(12345, 67890);
    enqueue_pdu(&queue, pdu);

    NFAPI_CRC_INDICATION_PDU_T* dequeued_pdu = dequeue_pdu(&queue);
    free_pdu(dequeued_pdu);

    destroy_pdu_queue(&queue);
    return 0;
}
