// Define the structure for CRC indication
typedef struct {
    int rx_ue_info;
    int rnti;
    int crc_flags;
} CrcIndication;

// Shared buffer to store CRC indications
#define BUFFER_SIZE 1024
CrcIndication shared_buffer[BUFFER_SIZE];
int head = 0, tail = 0, count = 0;

// Semaphore for thread-safe access to the shared buffer
sem_t buffer_sem;

// Mutex for protecting critical sections
pthread_mutex_t buffer_mutex;

// Function to simulate processing CRC indications
void* process_crc_indications(void* arg) {
    while (1) {
        // Wait for data in the buffer
        sem_wait(&buffer_sem);

        pthread_mutex_lock(&buffer_mutex);
        if (count > 0) {
            CrcIndication indication = shared_buffer[head];
            head = (head + 1) % BUFFER_SIZE;
            count--;
            pthread_mutex_unlock(&buffer_mutex);

            // Process the CRC indication
            process_indication(indication);
        } else {
            pthread_mutex_unlock(&buffer_mutex);
        }
    }

    return NULL;
}

// Function to simulate processing a single CRC indication
void process_indication(CrcIndication indication) {
    // Placeholder for actual processing logic
    printf("Processing indication: RX UE = %d, RNTI = %d, Flags = %d\n",
           indication.rx_ue_info, indication.rnti, indication.crc_flags);
}

// Function to add a CRC indication to the shared buffer
void add_crc_indication(CrcIndication indication) {
    pthread_mutex_lock(&buffer_mutex);
    if (count < BUFFER_SIZE) {
        shared_buffer[tail] = indication;
        tail = (tail + 1) % BUFFER_SIZE;
        count++;
        sem_post(&buffer_sem);
    } else {
        // Handle buffer overflow, e.g., log an error or drop the packet
        printf("Buffer overflow: Dropping CRC indication\n");
        pthread_mutex_unlock(&buffer_mutex);
    }
}

// Function to initialize the system
void init_system() {
    sem_init(&buffer_sem, 0, 0);
    pthread_mutex_init(&buffer_mutex, NULL);

    // Start processing thread
    pthread_t process_thread;
    pthread_create(&process_thread, NULL, process_crc_indications, NULL);
}

// Function to clean up the system
void cleanup_system() {
    sem_destroy(&buffer_sem);
    pthread_mutex_destroy(&buffer_mutex);
}
