// Forward declarations for protocol handlers
namespace RTP {
    class Handler;
}

namespace RTMP {
    class Handler;
}

namespace WebRTC {
    class Handler;
}

namespace HLS {
    class Handler;
}

class MediaPacket {
public:
    std::string msid;
    uint32_t timestamp;
    uint16_t sequenceNumber;
    uint8_t payloadType;
    // Other packet fields
};

class MediaManager {
private:
    std::queue<MediaPacket> packetQueue;
    std::mutex queueMutex;
    std::condition_variable notEmpty;
    bool running;

public:
    MediaManager() : running(false) {}

    void start() {
        running = true;
        std::thread([this]() {
            while (running) {
                std::unique_lock<std::mutex> lock(queueMutex);
                notEmpty.wait(lock, [this] { return !packetQueue.empty(); });
                MediaPacket packet = packetQueue.front();
                packetQueue.pop();
                lock.unlock();

                // Process the packet
                processPacket(packet);
            }
        }).detach();
    }

    void stop() {
        running = false;
        notEmpty.notify_all();
    }

    void enqueue(const MediaPacket& packet) {
        std::lock_guard<std::mutex> lock(queueMutex);
        packetQueue.push(packet);
        notEmpty.notify_one();
    }

private:
    void processPacket(const MediaPacket& packet) {
        // Determine the protocol based on the payload type
        if (packet.payloadType == 103 || packet.payloadType == 96) { // Example H.264/VP9
            RTP::Handler::process(packet);
        } else if (packet.payloadType == 97) { // Example custom codec
            RTP::Handler::process(packet);
        }

        // Additional protocol handlers can be added here
    }
};

int main() {
    MediaManager manager;
    manager.start();

    // Simulate incoming packets
    for (int i = 0; i < 10; ++i) {
        MediaPacket packet;
        packet.msid = "example";
        packet.timestamp = i * 1000;
        packet.sequenceNumber = i;
        packet.payloadType = i % 4 + 96; // Example payload types
        manager.enqueue(packet);
    }

    // Stop the manager after processing
    std::this_thread::sleep_for(std::chrono::seconds(5));
    manager.stop();

    return 0;
}
