#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sqlite3.h>

#define MAX_UE_INFO 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint64_t rnti;
    // Other fields...
} UE_Info;

struct ListNode {
    UE_Info data;
    struct ListNode* next;
};

struct LinkedList {
    struct ListNode* head;
    pthread_mutex_t mutex;
};

void init_linkedList(struct LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

int insert_unique_UE_info(struct LinkedList* list, UE_Info new_info) {
    pthread_mutex_lock(&list->mutex);
    struct ListNode* current = list->head;
    while (current != NULL) {
        if (current->data.rnti == new_info.rnti) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Duplicate RNTI found
        }
        current = current->next;
    }
    struct ListNode* new_node = (struct ListNode*)malloc(sizeof(struct ListNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }
    new_node->data = new_info;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void free_linkedList(struct LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    struct ListNode* current = list->head;
    while (current != NULL) {
        struct ListNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
}

int main() {
    struct LinkedList ue_list;
    init_linkedList(&ue_list);

    // Example usage
    UE_Info info1 = {12345, /* other fields */};
    insert_unique_UE_info(&ue_list, info1);

    free_linkedList(&ue_list);

    return 0;
}
