        {
            std::unique_lock<std::mutex> lock(mutex_);
            running_ = false;
        }
        condition_.notify_all();
        if (processing_thread_.joinable()) {
            processing_thread_.join();
        }
    }

    void processPacket(const SensorPacket& packet) {
        // Simulate data processing
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }

    State* createStateList(const std::vector<SensorPacket>& packets, int last_state_id) {
        // Create a new state list and process packets
        State* newState = new State(last_state_id);
        for (const auto& packet : packets) {
            processPacket(packet);
            newState->addPacket(packet);
        }
        return newState;
    }

private:
