#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_FILENAME_LENGTH 256

typedef struct {
    char filename[MAX_FILENAME_LENGTH];
    int version;
} VersionedFile;

typedef struct {
    sem_t lock;
    VersionedFile *files;
    int count;
} FileCache;

void initialize_cache(FileCache *cache, int initial_size) {
    cache->lock = (sem_t)SEM_INIT(&cache->lock, 0, 1);
    cache->files = malloc(initial_size * sizeof(VersionedFile));
    cache->count = 0;
}

void add_file_to_cache(FileCache *cache, const char *filename, int version) {
    sem_wait(&cache->lock);
    strncpy(cache->files[cache->count].filename, filename, MAX_FILENAME_LENGTH - 1);
    cache->files[cache->count].version = version;
    cache->count++;
    sem_post(&cache->lock);
}

int get_latest_version(FileCache *cache, const char *filename) {
    int latest_version = -1;
    sem_wait(&cache->lock);
    for (int i = 0; i < cache->count; i++) {
        if (strcmp(cache->files[i].filename, filename) == 0) {
            if (cache->files[i].version > latest_version) {
                latest_version = cache->files[i].version;
            }
        }
    }
    sem_post(&cache->lock);
    return latest_version;
}

void *worker_thread(void *arg) {
    FileCache *cache = (FileCache *)arg;
    char filename[MAX_FILENAME_LENGTH];
    int version;

    // Simulate work
    pthread_sleep(1);

    // Generate unique filename and version
    sprintf(filename, "file%d.txt", rand() % 100);
    version = get_latest_version(cache, filename) + 1;

    add_file_to_cache(cache, filename, version);

    return NULL;
}

int main() {
    FileCache cache;
    initialize_cache(&cache, 100);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, worker_thread, &cache);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Cache contents:\n");
    for (int i = 0; i < cache.count; i++) {
        printf("%s - Version %d\n", cache.files[i].filename, cache.files[i].version);
    }

    sem_destroy(&cache.lock);
    free(cache.files);

    return 0;
}
