public:
    void set(const std::string& key, const std::string& value, std::chrono::seconds ttl) {
        std::lock_guard<std::mutex> lock(mutex_);
        data_[key] = {value, std::chrono::steady_clock::now() + ttl};
        cv_.notify_all();
    }

    std::optional<std::string> get(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this, &key] { return data_.find(key) != data_.end() || !data_.empty(); });
        auto it = data_.find(key);
        if (it == data_.end()) {
            return {};
        }
        if (std::chrono::steady_clock::now() > it->second.expire_time) {
            data_.erase(it);
            cv_.notify_all();
            return {};
        }
        return it->second.value;
    }

private:
    struct DataEntry {
        std::string value;
        std::chrono::time_point<std::chrono::steady_clock> expire_time;
    };

    std::unordered_map<std::string, DataEntry> data_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
};

class GeoLocationCache {
public:
    void addClient(std::thread client) {
        clients_.push_back(client);
    }

    void run() {
        for (auto& client : clients_) {
            if (client.joinable()) {
                client.join();
            }
        }
    }

private:
    std::vector<std::thread> clients_;
};

int main() {
    KeyValueStore kv_store;
    GeoLocationCache cache;

    auto client = std::thread([&kv_store]() {
        for (int i = 0; i < 100; ++i) {
            auto value = kv_store.get("key_" + std::to_string(i));
            if (!value) {
                kv_store.set("key_" + std::to_string(i), "value_" + std::to_string(i), std::chrono::seconds(5));
            }
        }
    });

    cache.addClient(client);
    cache.run();

    return 0;
}
```

This code snippet provides a basic implementation of a key-value store and a simple client that interacts with it. It demonstrates the use of mutexes, condition variables, and threads to handle concurrent operations efficiently. The `KeyValueStore` class manages data entries with time-to-live (TTL) support, ensuring that stale data is automatically removed. The `GeoLocationCache` class represents a modular component that can manage multiple clients, allowing for concurrent access and cache management.']

