    std::optional<std::string> refresh_token;
};

bool validateJSON(const Json::Value& json, const std::vector<std::string>& requiredFields) {
    for (const auto& field : requiredFields) {
        if (!json.isMember(field)) {
            return false;
        }
    }
    return true;
}

NFAPI_CRC_INDICATION_PDU_T processConfig(const std::string& jsonString) {
    Json::Value root;
    Json::CharReaderBuilder builder;
    const std::unique_ptr<Json::CharReader> reader(builder.newCharReader());
    std::string errs;

    if (!reader->parse(jsonString.c_str(), jsonString.c_str() + jsonString.size(), &root, &errs)) {
        std::cerr << "Failed to parse JSON: " << errs << std::endl;
        return {};
    }

    const std::vector<std::string> requiredFields = {"access_token", "expires_in", "token_type"};
    if (!validateJSON(root, requiredFields) || root["token_type"].asString() != "Bearer" || !root["expires_in"].isUInt()) {
        std::cerr << "Invalid JSON configuration" << std::endl;
        return {};
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.access_token = root["access_token"].asString();
    pdu.expires_in = root["expires_in"].asInt();
    pdu.token_type = root["token_type"].asString();
    if (root.isMember("refresh_token")) {
        pdu.refresh_token = root["refresh_token"].asString();
    }

    return pdu;
}

int main() {
    std::string configString = R"({"access_token": "abc123", "expires_in": 3600, "token_type": "Bearer"})";
    NFAPI_CRC_INDICATION_PDU_T result = processConfig(configString);

    if (!result.access_token.empty()) {
        std::cout << "Processed config: access_token=" << result.access_token << ", expires_in=" << result.expires_in << ", token_type=" << result.token_type;
        if (result.refresh_token) {
            std::cout << ", refresh_token=" << *result.refresh_token;
        }
        std::cout << std::endl;
    }

    return 0;
}
