#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/ssl.h>

#define MAX_LOCALES 1024
#define MAX_CACHE_SIZE 65536

typedef struct {
    char locale[10];
    char *message;
} MessageBundle;

typedef struct {
    pthread_mutex_t lock;
    MessageBundle cache[MAX_CACHE_SIZE];
    int size;
} Cache;

Cache message_cache;

void init_cache() {
    pthread_mutex_init(&message_cache.lock, NULL);
    message_cache.size = 0;
}

int load_message_bundle(const char *locale, char **bundle) {
    // Simulate loading from remote server or local cache
    if (strcmp(locale, "en_US") == 0) {
        *bundle = strdup("Hello, World!");
    } else if (strcmp(locale, "es_ES") == 0) {
        *bundle = strdup("¡Hola, Mundo!");
    } else {
        return -1; // Locale not found
    }
    return 0;
}

void update_cache(const char *locale) {
    pthread_mutex_lock(&message_cache.lock);
    for (int i = 0; i < message_cache.size; i++) {
        if (strcmp(message_cache.cache[i].locale, locale) == 0) {
            free(message_cache.cache[i].message);
            break;
        }
    }
    char *bundle;
    if (load_message_bundle(locale, &bundle) == 0) {
        strncpy(message_cache.cache[message_cache.size].locale, locale, sizeof(message_cache.cache[message_cache.size].locale) - 1);
        message_cache.cache[message_cache.size].message = bundle;
        message_cache.size++;
    }
    pthread_mutex_unlock(&message_cache.lock);
}

void *cache_worker(void *arg) {
    while (1) {
        // Simulate update frequency and priority
        for (int i = 0; i < MAX_LOCALES; i++) {
            char locale[10];
            snprintf(locale, sizeof(locale), "en_%d", i);
            update_cache(locale);
        }
        sleep(60); // Update every minute
    }
    return NULL;
}

void *get_message_bundle(const char *locale) {
    pthread_mutex_lock(&message_cache.lock);
    for (int i = 0; i < message_cache.size; i++) {
        if (strcmp(message_cache.cache[i].locale, locale) == 0) {
            char *bundle = strdup(message_cache.cache[i].message);
            pthread_mutex_unlock(&message_cache.lock);
            return bundle;
        }
    }
    pthread_mutex_unlock(&message_cache.lock);
    return NULL;
}

int main() {
    init_cache();
    pthread_t worker_thread;
    pthread_create(&worker_thread, NULL, cache_worker, NULL);

    // Simulate getting message bundles
    char *bundle = get_message_bundle("en_US");
    if (bundle != NULL) {
        printf("%s\n", bundle);
        free(bundle);
    }

    pthread_join(worker_thread, NULL);
    return 0;
}
```

