#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>

// Define a simple data structure for sensor data packets
struct SensorData {
    std::string did;          // Device Identifier
    long timestamp;            // Timestamp of the event
    std::string eventType;     // Type of event
    std::string payload;       // Payload data (could be JSON, Protocol Buffers, or custom)
};

// Define a class to handle sensor data processing
class SensorDataProcessor {
public:
    void process(const SensorData& data) {
        // Simulate data processing logic
        std::cout << "Processing data for DID: " << data.did << ", Timestamp: " << data.timestamp 
                  << ", Event Type: " << data.eventType << std::endl;
    }
};

// Define a class to manage the sensor data queue and process threads
class SensorDataQueue {
private:
    std::queue<SensorData> dataQueue;
    std::mutex mtx;
    std::condition_variable cv;
    bool stop = false;
    std::vector<std::thread> workers;

public:
    void start(int numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            workers.emplace_back(&SensorDataQueue::workerThread, this);
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mtx);
            stop = true;
        }
        cv.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void addData(const SensorData& data) {
        std::unique_lock<std::mutex> lock(mtx);
        dataQueue.push(data);
        cv.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !dataQueue.empty() || stop; });
            if (stop && dataQueue.empty()) {
                break;
            }
            SensorData data = dataQueue.front();
            dataQueue.pop();
            lock.unlock();

            // Process the sensor data
            SensorDataProcessor processor;
            processor.process(data);
        }
    }
};

int main() {
    SensorDataQueue queue;
    queue.start(4);  // Start with 4 worker threads

    // Simulate adding sensor data to the queue
    for (int i = 0; i < 10; ++i) {
        SensorData data = {"DID" + std::to_string(i), time(nullptr), "Event" + std::to_string(i), "Payload" + std::to_string(i)};
        queue.addData(data);
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    queue.stop();
    return 0;
}
```

