    std::optional<std::pair<int, std::string>> dequeue() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (queue_.empty()) {
            cond_.wait(lock);
        }
        auto [priority, message] = queue_.front();
        queue_.pop();
        return {std::make_pair(priority, message)};
    }

private:
    struct Notification {
        int priority;
        std::string message;
        bool operator<(const Notification& other) const {
            return priority > other.priority; // Max-heap based on priority
        }
    };

    std::priority_queue<Notification> queue_;
    std::mutex mutex_;
    std::condition_variable cond_;
};

class NotificationProcessor {
public:
    NotificationProcessor(size_t num_threads, NotificationQueue& queue)
        : queue_(queue), stop_(false) {
        for (size_t i = 0; i < num_threads; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    auto notification = queue_.dequeue();
                    if (!notification.has_value()) break;
                    processNotification(notification.value().second);
                }
            });
        }
    }

    ~NotificationProcessor() {
        {
            std::unique_lock<std::mutex> lock(queue_.mutex_);
            stop_ = true;
        }
        queue_.cond_.notify_all();
        for (auto& worker : workers_) {
            worker.join();
        }
    }

private:
    void processNotification(const std::string& message) {
        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Processed notification: " << message << std::endl;
    }

    NotificationQueue& queue_;
    bool stop_;
    std::vector<std::thread> workers_;
};

int main() {
    NotificationQueue queue;
    NotificationProcessor processor(4, queue);

    // Simulate incoming notifications
    for (int i = 0; i < 10; ++i) {
        queue.enqueue("Notification " + std::to_string(i), i % 3);
    }

    return 0;
}
