package main

import (
	"fmt"
	"net/http"
	"sync"
)

type AuthSystem struct {
	users       map[string]string
	userMutex   sync.Mutex
	authProviders []AuthProvider
}

func (as *AuthSystem) RegisterUser(username, password string) error {
	as.userMutex.Lock()
	defer as.userMutex.Unlock()
	if _, exists := as.users[username]; exists {
		return fmt.Errorf("user already exists")
	}
	as.users[username] = password
	return nil
}

func (as *AuthSystem) AuthenticateUser(username, password string) (bool, error) {
	as.userMutex.Lock()
	defer as.userMutex.Unlock()
	storedPassword, exists := as.users[username]
	if !exists || storedPassword != password {
		return false, fmt.Errorf("invalid credentials")
	}
	return true, nil
}

func (as *AuthSystem) AddAuthProvider(provider AuthProvider) {
	as.authProviders = append(as.authProviders, provider)
}

func (as *AuthSystem) AuthenticateWithIdP(username, idpToken string) (bool, error) {
	for _, provider := range as.authProviders {
		if provider.ProviderName() == "google" || provider.ProviderName() == "facebook" {
			return provider.Authenticate(username, idpToken)
		}
	}
	return false, fmt.Errorf("provider not supported")
}

type AuthProvider interface {
	Authenticate(username string, token string) (bool, error)
	ProviderName() string
}

type GoogleAuthProvider struct{}

func (g *GoogleAuthProvider) Authenticate(username, token string) (bool, error) {
	// Simulate authentication with Google's IDP
	return true, nil
}

func (g *GoogleAuthProvider) ProviderName() string {
	return "google"
}

type FacebookAuthProvider struct{}

func (f *FacebookAuthProvider) Authenticate(username, token string) (bool, error) {
	// Simulate authentication with Facebook's IDP
	return true, nil
}

func (f *FacebookAuthProvider) ProviderName() string {
	return "facebook"
}

func main() {
	authSystem := &AuthSystem{
		users: make(map[string]string),
	}
	authSystem.AddAuthProvider(&GoogleAuthProvider{})
	authSystem.AddAuthProvider(&FacebookAuthProvider{})

	http.HandleFunc("/register", func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodPost {
			username := r.FormValue("username")
			password := r.FormValue("password")
			err := authSystem.RegisterUser(username, password)
			if err != nil {
				http.Error(w, err.Error(), http.StatusConflict)
				return
			}
			w.WriteHeader(http.StatusOK)
		} else {
			http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
		}
	})

	http.HandleFunc("/login", func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodPost {
			username := r.FormValue("username")
			password := r.FormValue("password")
			isAuthenticated, err := authSystem.AuthenticateUser(username, password)
			if err != nil {
				http.Error(w, err.Error(), http.StatusUnauthorized)
				return
			}
			if isAuthenticated {
				w.WriteHeader(http.StatusOK)
			} else {
				http.Error(w, "Invalid credentials", http.StatusUnauthorized)
			}
		} else {
			http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
		}
	})

	http.HandleFunc("/login-idp", func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodPost {
			username := r.FormValue("username")
			idpToken := r.FormValue("idp_token")
			isAuthenticated, err := authSystem.AuthenticateWithIdP(username, idpToken)
			if err != nil {
				http.Error(w, err.Error(), http.StatusUnauthorized)
				return
			}
			if isAuthenticated {
				w.WriteHeader(http.StatusOK)
			} else {
				http.Error(w, "Invalid credentials", http.StatusUnauthorized)
			}
		} else {
			http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
		}
	})

	fmt.Println("Starting auth system server...")
	err := http.ListenAndServe(":8080", nil)
	if err != nil {
		panic(err)
	}
}
