#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <memory>

class NotificationSystem {
public:
    NotificationSystem(size_t maxUsers) : max_users(maxUsers), active_users(0) {}

    void addUser() {
        std::unique_lock<std::mutex> lock(mutex);
        while (active_users >= max_users) {
            cv.wait(lock, [this] { return active_users < max_users; });
        }
        ++active_users;
        cv.notify_all();
    }

    void removeUser() {
        std::unique_lock<std::mutex> lock(mutex);
        --active_users;
        cv.notify_all();
    }

    template<typename F>
    void processNotification(F&& notification) {
        std::unique_lock<std::mutex> lock(mutex);
        if (active_users > 0) {
            notifications.emplace(std::forward<F>(notification));
            cv.notify_one();
        } else {
            // Handle no users scenario
        }
    }

private:
    size_t max_users;
    size_t active_users;
    std::queue<std::function<void()>> notifications;
    std::mutex mutex;
    std::condition_variable cv;
};

int main() {
    NotificationSystem system(10000000);

    // Simulate user registration and notification processing
    for (size_t i = 0; i < 5000000; ++i) {
        system.addUser();
        system.processNotification([i] { std::cout << "Processing notification " << i << std::endl; });
    }

    // Simulate user unregistration
    for (size_t i = 0; i < 5000000; ++i) {
        system.removeUser();
    }

    return 0;
}
