// cache_manager.h
#ifndef CACHE_MANAGER_H
#define CACHE_MANAGER_H

#include <string>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <atomic>
#include <chrono>

class CacheManager {
public:
    // Add data to the cache with a specific expiration time
    void addData(const std::string& key, const std::string& data, std::chrono::seconds expiry);

    // Retrieve data from the cache
    std::string getData(const std::string& key) const;

    // Remove data from the cache
    void removeData(const std::string& key);

    // Set a custom refresh policy for data
    void setRefreshPolicy(std::function<void()> policy);

private:
    mutable std::mutex cacheMutex;
    std::unordered_map<std::string, CacheEntry> cache;
    std::condition_variable cv;
    std::thread evictionThread;
    std::atomic<bool> running{true};

    struct CacheEntry {
        std::string data;
        std::chrono::time_point<std::chrono::system_clock> expirationTime;
    };

    void evictionLoop();
};

#endif // CACHE_MANAGER_H

// cache_manager.cpp
#include "cache_manager.h"
#include <iostream>
#include <fstream>

CacheManager::CacheManager() {
    evictionThread = std::thread(&CacheManager::evictionLoop, this);
}

CacheManager::~CacheManager() {
    running.store(false);
    cv.notify_all();
    if (evictionThread.joinable()) {
        evictionThread.join();
    }
}

void CacheManager::addData(const std::string& key, const std::string& data, std::chrono::seconds expiry) {
    std::lock_guard<std::mutex> lock(cacheMutex);
    cache[key] = {data, std::chrono::system_clock::now() + expiry};
}

std::string CacheManager::getData(const std::string& key) const {
    std::lock_guard<std::mutex> lock(cacheMutex);
    auto it = cache.find(key);
    if (it != cache.end() && it->second.expirationTime > std::chrono::system_clock::now()) {
        return it->second.data;
    }
    return "";
}

void CacheManager::removeData(const std::string& key) {
    std::lock_guard<std::mutex> lock(cacheMutex);
    cache.erase(key);
}

void CacheManager::setRefreshPolicy(std::function<void()> policy) {
    // Set the refresh policy
}

void CacheManager::evictionLoop() {
    while (running.load()) {
        cv.wait_for(lock, 1s, [this] { return !cache.empty(); });
        std::lock_guard<std::mutex> lock(cacheMutex);
        for (auto it = cache.begin(); it != cache.end();) {
            if (it->second.expirationTime <= std::chrono::system_clock::now()) {
                it = cache.erase(it);
            } else {
                ++it;
            }
        }
    }
}

// main.cpp
#include "cache_manager.h"
#include <iostream>

int main() {
    CacheManager cm;
    cm.addData("ip1", "data1", std::chrono::seconds(60));
    std::cout << cm.getData("ip1") << std::endl;

    return 0;
}
