#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define PORT 8080
#define MAX_CLIENTS 10

typedef struct {
    int client_socket;
    pthread_t thread_id;
} ClientHandler;

void *handle_client(void *arg) {
    ClientHandler *client = (ClientHandler *)arg;
    char buffer[1024] = {0};

    // Read request from the client
    read(client->client_socket, buffer, sizeof(buffer));

    // Process the request and send response back to the client
    if (strcmp(buffer, "GET") == 0) {
        write(client->client_socket, "Filename: version1.ext", 23);
    } else if (strcmp(buffer, "PUT") == 0) {
        write(client->client_socket, "File saved successfully", 26);
    }

    // Close the client socket
    close(client->client_socket);
    return NULL;
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    ClientHandler clients[MAX_CLIENTS];

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Setting up the server address structure
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Binding the socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listening for incoming connections
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    int client_count = 0;
    while (client_count < MAX_CLIENTS) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        // Create a new thread to handle the client
        clients[client_count].client_socket = new_socket;
        pthread_create(&clients[client_count].thread_id, NULL, handle_client, &clients[client_count]);
        client_count++;
    }

    return 0;
}
