import random

class GeolocationService:
    def __init__(self, api_providers, cache_size=100):
        self.api_providers = api_providers
        self.cache = Cache(cache_size)
        self.load_balancer = LoadBalancer(self.api_providers)

    async def get_location_by_ip(self, ip_address):
        if ip_address in self.cache:
            return self.cache.get(ip_address)

        provider = self.load_balancer.select_provider()
        try:
            location = await provider.get_location(ip_address)
            self.cache.set(ip_address, location)
            return location
        except Exception as e:
            print(f"Failed to get location for {ip_address}: {e}")
            return None

class Cache:
    def __init__(self, max_size):
        self.max_size = max_size
        self.data = {}

    def get(self, key):
        return self.data.get(key)

    def set(self, key, value):
        if len(self.data) >= self.max_size:
            oldest_key = next(iter(self.data))
            del self.data[oldest_key]
        self.data[key] = value

class LoadBalancer:
    def __init__(self, providers):
        self.providers = providers
        self.provider_queue = deque(providers)

    def select_provider(self):
        return self.provider_queue.popleft()
        # Implement a more sophisticated load balancing strategy here

class APIProvider:
