fn main() {
    let matches = App::new("Rust Parser Framework")
        .version("1.0")
        .author("Your Name <you@example.com>")
        .about("A modular Rust-based parser framework for generating optimized LLVM IR code")
        .arg(Arg::with_name("architecture")
