#include <iostream>
#include <random>
#include <vector>
#include <thread>

class RandomNumberGenerator {
public:
    RandomNumberGenerator(uint64_t seed) : gen(seed) {}

    int32_t generateInt(int32_t min, int32_t max) {
        std::uniform_int_distribution<int32_t> dist(min, max);
        return dist(gen);
    }

    float generateFloat(float min, float max) {
        std::uniform_real_distribution<float> dist(min, max);
        return dist(gen);
    }

    bool generateBool() {
        std::bernoulli_distribution dist;
        return dist(gen);
    }

private:
    std::mt19937_64 gen;
};

int main() {
    std::vector<RandomNumberGenerator> rngs(1000); // Example with 1000 RNG instances
    for (size_t i = 0; i < rngs.size(); ++i) {
        rngs[i] = RandomNumberGenerator(i);
    }

    std::thread threads[10];
    for (size_t i = 0; i < 10; ++i) {
        threads[i] = std::thread([&, i]() {
            for (int j = 0; j < 1000000; ++j) {
                int32_t randInt = rngs[i].generateInt(0, 100);
                float randFloat = rngs[i].generateFloat(0.0f, 1.0f);
                bool randBool = rngs[i].generateBool();
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
```

