using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

public class DynamicRESTClient
{
    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, string> _apiVersionMapping;
    private readonly ILogger _logger;
    private readonly IConfigurationService _configurationService;
    private readonly ICacheService _cacheService;

    public DynamicRESTClient(HttpClient httpClient, Dictionary<string, string> apiVersionMapping, ILogger logger, IConfigurationService configurationService, ICacheService cacheService)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _apiVersionMapping = apiVersionMapping ?? throw new ArgumentNullException(nameof(apiVersionMapping));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _configurationService = configurationService ?? throw new ArgumentNullException(nameof(configurationService));
        _cacheService = cacheService ?? throw new ArgumentNullException(nameof(cacheService));
    }

    public async Task<string> GetAsync(string endpoint, string apiVersion)
    {
        var url = GenerateUrl(endpoint, apiVersion);
        var response = await _httpClient.GetAsync(url);

        if (response.IsSuccessStatusCode)
        {
            var content = await response.Content.ReadAsStringAsync();
            return content;
        }
        else
        {
            _logger.LogError($"Failed to fetch data from {url}. Status code: {response.StatusCode}");
            throw new HttpRequestException($"Error fetching data from {url}: {response.ReasonPhrase}");
        }
    }

    public async Task PostAsync(string endpoint, string apiVersion, object content)
    {
        var url = GenerateUrl(endpoint, apiVersion);
        var httpContent = SerializeContent(content);

        var response = await _httpClient.PostAsync(url, httpContent);

        if (!response.IsSuccessStatusCode)
        {
            _logger.LogError($"Failed to post data to {url}. Status code: {response.StatusCode}");
            throw new HttpRequestException($"Error posting data to {url}: {response.ReasonPhrase}");
        }
    }

    private string GenerateUrl(string endpoint, string apiVersion)
    {
        if (!_apiVersionMapping.ContainsKey(apiVersion))
        {
            _logger.LogWarning($"API version {apiVersion} is deprecated. Using default version.");
            apiVersion = "default";
        }

        var baseUri = _configurationService.GetBaseUri();
        return $"{baseUri}/{_apiVersionMapping[apiVersion]}/{endpoint}";
    }

    private HttpContent SerializeContent(object content)
    {
        // Implement serialization logic based on the media type
        throw new NotImplementedException();
    }
}
