# Python logging service implementation

from typing import Any, Callable, Dict, List, Optional, Union
import asyncio
import aiohttp
import json

class LogAggregator:
    def __init__(self, url: str):
        self.url = url

    async def send_log(self, log_data: Dict[str, Any]) -> None:
        async with aiohttp.ClientSession() as session:
            async with session.post(self.url, data=json.dumps(log_data)) as response:
                if response.status != 200:
                    raise Exception(f"Failed to send log to aggregator: {response.text}")

class Logger:
    def __init__(self, aggregators: List[LogAggregator], retry_strategy: Callable):
        self.aggregators = aggregators
        self.retry_strategy = retry_strategy

    async def log(self, log_data: Dict[str, Any]) -> None:
        for aggregator in self.aggregators:
            try:
                await aggregator.send_log(log_data)
            except Exception as e:
                await self.retry_strategy(e)

async def exponential_backoff_retry(exception: Exception, attempt_number: int) -> None:
    delay = 2 ** attempt_number + random.uniform(0, 1)
    await asyncio.sleep(delay)

# Usage
aggregators = [LogAggregator("http://agg1.com"), LogAggregator("http://agg2.com")]
logger = Logger(aggregators, exponential_backoff_retry)
log_data = {"message": "Test log", "level": "info"}
asyncio.run(logger.log(log_data))
