// Microservices-based API Gateway Design

import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.github.resilience4j.retry.Retry;
import org.springframework.cloud.gateway.route.RouteLocator;
import org.springframework.cloud.gateway.route.builder.RouteLocatorBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class ApiGatewayConfig {

    @Bean
    public RouteLocator customRouteLocator(RouteLocatorBuilder builder) {
        return builder.routes()
            .route("service1", r -> r.path("/service1/**")
                .filters(f -> f.rewritePath("/service1/(?<segment>.*?)/?(?<remainder>?.*)", "/${segment}/${remainder}")
                    .circuitBreaker(c -> c.setName("service1-cb"))
                    .retry(Retry.fixedDelay(3, Duration.ofMillis(200))))
                .uri("lb://service1"))
            .route("service2", r -> r.path("/service2/**")
                .filters(f -> f.rewritePath("/service2/(?<segment>.*?)/?(?<remainder>?.*)", "/${segment}/${remainder}")
                    .circuitBreaker(c -> c.setName("service2-cb"))
                    .retry(Retry.fixedDelay(3, Duration.ofMillis(200))))
                .uri("lb://service2"))
            .build();
    }

    @Bean
    public CircuitBreaker service1CircuitBreaker() {
        return CircuitBreaker.custom()
            .failureRateThreshold(50)
            .waitDurationInOpenState(Duration.ofSeconds(10))
            .build();
    }

    @Bean
    public CircuitBreaker service2CircuitBreaker() {
        return CircuitBreaker.custom()
            .failureRateThreshold(50)
            .waitDurationInOpenState(Duration.ofSeconds(10))
            .build();
    }
}
