import java.util.HashMap;
import java.util.Map;

public class DisjointSetService {
    private Map<Integer, Integer> parent;
    private Map<Integer, Integer> size;
    private Cache cache;
    private Database database;
    private MessageQueue messageQueue;

    public DisjointSetService() {
        parent = new HashMap<>();
        size = new HashMap<>();
        cache = new Cache();
        database = new Database();
        messageQueue = new MessageQueue();
    }

    public void processEvent(int user1, int user2) {
        try {
            if (cache.contains(user1, user2)) {
                System.out.println("Disjoint pair already cached: " + user1 + ", " + user2);
                return;
            }
            boolean isDisjoint = findParent(user1) == findParent(user2);
            if (!isDisjoint) {
                union(user1, user2);
                cache.put(user1, user2);
            }
        } catch (Exception e) {
            logError(e.getMessage());
            handleRetry();
        }
    }

    private int findParent(int u) {
        if (!parent.containsKey(u)) {
            parent.put(u, u);
            size.put(u, 1);
            return u;
        }
        if (parent.get(u) != u) {
            parent.put(u, findParent(parent.get(u)));
        }
        return parent.get(u);
    }

    private void union(int user1, int user2) {
        int root1 = findParent(user1);
        int root2 = findParent(user2);
        if (root1 == root2) return;
        if (size.get(root1) > size.get(root2)) {
            parent.put(root2, root1);
            size.put(root1, size.get(root1) + size.get(root2));
        } else {
            parent.put(root1, root2);
            size.put(root2, size.get(root1) + size.get(root2));
        }
    }

