#include <openssl/sha.h>

typedef struct {
    char *password;
} User;

void validate_password(User *user) {
    unsigned char sha256[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256_context;
    SHA256_Init(&sha256_context);
    SHA256_Update(&sha256_context, user->password, strlen(user->password));
    SHA256_Final(sha256, &sha256_context);

    printf("SHA-256: ");
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        printf("%02x", sha256[i]);
    }
    printf("\n");

    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5_CTX md5_context;
    MD5_Init(&md5_context);
    MD5_Update(&md5_context, user->password, strlen(user->password));
    MD5_Final(md5, &md5_context);

    printf("MD5: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", md5[i]);
    }
    printf("\n");
}

int main() {
    User user;
    user.password = "securePassword123";

    validate_password(&user);

    return 0;
}
