from flask import Flask, request, jsonify
from flask_session import Session
import redis
import jwt
import requests
from functools import wraps
import time

app = Flask(__name__)
app.config['SESSION_TYPE'] = 'redis'
app.config['SESSION_PERMANENT'] = False
app.config['SESSION_USE_SIGNER'] = True
app.config['SESSION_REDIS'] = redis.from_url('redis://localhost:6379')

session = Session(app)

# Configuration for external identity providers and authentication service
AUTH_SERVICE_URL = "https://auth.example.com"
ID_PROVIDERS = {
    'google': {'url': 'https://accounts.google.com/o/oauth2/auth', 'client_id': 'your_google_client_id'},
    'facebook': {'url': 'https://www.facebook.com/dialog/oauth', 'client_id': 'your_facebook_client_id'}
}

# JWT configuration
SECRET_KEY = "your_secret_key"
ALGORITHM = "HS256"

def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token is missing!'}), 403
        try:
            data = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        except:
            return jsonify({'message': 'Token is invalid!'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/login', methods=['POST'])
def login():
    provider = request.form.get('provider')
    if provider not in ID_PROVIDERS:
        return jsonify({'message': 'Invalid provider!'}), 400

    id_provider_config = ID_PROVIDERS[provider]
    auth_url = f"{id_provider_config['url']}?response_type=code&client_id={id_provider_config['client_id']}&redirect_uri=http://localhost:5000/callback"

    return jsonify({'auth_url': auth_url})

@app.route('/callback', methods=['GET'])
def callback():
    code = request.args.get('code')
    provider = request.args.get('provider')
    if not code or provider not in ID_PROVIDERS:
        return jsonify({'message': 'Invalid parameters!'}), 400

    id_provider_config = ID_PROVIDERS[provider]
    token_url = f"{id_provider_config['url']}/token"

    response = requests.post(token_url, data={
        'code': code,
        'client_id': id_provider_config['client_id'],
        'redirect_uri': 'http://localhost:5000/callback',
        'grant_type': 'authorization_code'
    })

    if response.status_code != 200:
        return jsonify({'message': 'Failed to get token from identity provider!'}), 502

    access_token = response.json().get('access_token')
    user_info = requests.get(f"{id_provider_config['url']}/userinfo", headers={'Authorization': f'Bearer {access_token}'}).json()

    if not access_token or not user_info:
        return jsonify({'message': 'Failed to retrieve user info!'}), 502

    token = jwt.encode({'user_id': user_info.get('id'), 'exp': time.time() + 3600}, SECRET_KEY, algorithm=ALGORITHM)

    session['token'] = token
    return jsonify({'message': 'Login successful!', 'token': token})

@app.route('/protected', methods=['GET'])
@token_required
def protected():
    return jsonify({'message': 'This is a protected resource!'})

if __name__ == '__main__':
    app.run(debug=True, threaded=True)
