class DistributedCache {
public:
    using GeolocationData = std::map<std::string, std::string>;
    using APIResponse = std::pair<int, GeolocationData>;

    void addAPI(const std::string& apiName, std::function<APIResponse()> callback) {
        std::lock_guard<std::mutex> lock(mutex_);
        apis_[apiName] = callback;
    }

    GeolocationData getGeolocationData(const std::string& location) {
        std::lock_guard<std::mutex> lock(mutex_);

        // Try to fetch from cache
        auto it = cache_.find(location);
        if (it != cache_.end()) {
            return it->second;
        }

        // Fetch from API and update cache
        for (const auto& api : apis_) {
            auto response = api.second();
            if (response.first == 200) {
                cache_[location] = response.second;
                return response.second;
            }
        }

        // Return empty data if all APIs fail
        return {};
    }

private:
    std::mutex mutex_;
    std::unordered_map<std::string, GeolocationData> cache_;
    std::unordered_map<std::string, std::function<APIResponse()>> apis_;
};

int main() {
    DistributedCache cache;

    // Add APIs to the cache
    cache.addAPI("Google", []() {
        // Simulate API call and response
        return {200, {{"latitude", "37.4221"}, {"longitude", "-122.0847"}}};
    });

    cache.addAPI("Mapbox", []() {
        // Simulate API call and response
        return {500, {}};
    });

    // Get geolocation data for a location
    auto data = cache.getGeolocationData("San Francisco");
    if (!data.empty()) {
        std::cout << "Latitude: " << data["latitude"] << ", Longitude: " << data["longitude"] << std::endl;
