    public GeolocationService() {
        this.executorService = Executors.newFixedThreadPool(MAX_CONNECTIONS);
        this.queue = new LinkedBlockingQueue<>();
        this.cache = Collections.synchronizedMap(new LinkedHashMap<>());
        this.circuitBreaker = new CircuitBreaker();
    }

    public void handleRequest(String uuid, String json) {
        queue.add(uuid);
        circuitBreaker.execute(() -> processRequest(uuid, json));
    }

    private void processRequest(String uuid, String json) {
        try {
            Resource resource = fetchResourceFromCache(uuid);
            if (resource == null) {
                resource = fetchResourceFromApi(uuid, json);
                cache.put(uuid, resource);
            } else {
                updateResource(resource, json);
            }
        } catch (Exception e) {
            handleFailure(e);
        }
    }

    private Resource fetchResourceFromCache(String uuid) {
        return cache.get(uuid);
    }

    private Resource fetchResourceFromApi(String uuid, String json) throws Exception {
        // Simulate API call
        Thread.sleep(100);
        if (circuitBreaker.isOpen()) throw new RuntimeException("API is unavailable");
        return new Resource(computeMd5Hash(uuid), json);
    }

    private void updateResource(Resource resource, String json) {
        // Update resource in cache
    }

    private void handleFailure(Exception e) {
        // Log and retry logic with exponential backoff
    }

    private String computeMd5Hash(String uuid) {
        return UUID.nameUUIDFromBytes(uuid.getBytes()).toString();
    }

    private static class Resource {
        private final String id;
        private final String data;

        public Resource(String id, String data) {
            this.id = id;
            this.data = data;
        }

        // Getters and setters
    }

    private static class CircuitBreaker {
        private final AtomicBoolean open;
        private final long resetTimeout;

        public CircuitBreaker() {
            this.open = new AtomicBoolean(false);
            this.resetTimeout = 10_000; // 10 seconds
        }

        public void execute(Runnable action) throws Exception {
            if (open.get()) throw new RuntimeException("Circuit is open");
            try {
                action.run();
            } catch (Exception e) {
                open.set(true);
                Thread.sleep(resetTimeout);
            }
        }

        // Getters and setters
    }
}
