use futures::stream::{StreamExt, TryStreamExt};
use kafka::consumer::{Consumer, FetchOffset, GroupOffsetStorage};
use kafka::error::Error as KafkaError;
use kafka::producer::{Producer, ProducerConfig};
use kafka::topic_partition_list::TopicPartitionList;
use log::{debug, error, info};
use std::time::Duration;

struct MessageBrokerConsumer {
    consumer: Consumer,
    producer: Producer,
    metadata_service_url: String,
    max_retries: usize,
}

impl MessageBrokerConsumer {
    fn new(broker_addrs: Vec<String>, group_id: &str, metadata_service_url: String) -> Self {
        let mut config = kafka::consumer::Config::new();
        config.set("bootstrap.servers", &broker_addrs.join(","));
        config.set("group.id", group_id);
        config.set("enable.auto.commit", "false");
        config.set("auto.offset.reset", "earliest");
        config.set("session.timeout.ms", "6000");

        let consumer = Consumer::from_config(config).unwrap();

        let mut producer_config = ProducerConfig::new();
        producer_config.set("bootstrap.servers", &broker_addrs.join(","));
        producer_config.set("message.max.bytes", "1048576"); // 1MB
        producer_config.set("acks", "all");

        let producer = Producer::from_config(producer_config).unwrap();

        MessageBrokerConsumer {
            consumer,
            producer,
            metadata_service_url,
            max_retries: 5,
        }
    }

    async fn start(&mut self) {
        loop {
            match self.fetch_messages().await {
                Ok(messages) => {
                    for message in messages {
                        if let Err(err) = self.process_message(message).await {
                            error!("Error processing message: {:?}", err);
                            self.dead_letter_queue(message).await;
                        }
                    }
                }
                Err(err) => {
                    error!("Failed to fetch messages: {:?}", err);
                }
            }

            tokio::time::sleep(Duration::from_secs(1)).await;
        }
    }

    async fn fetch_messages(&mut self) -> Result<Vec<kafka::message::Message>, KafkaError> {
        let mut topics = TopicPartitionList::new();
        topics.add_partition("topic1", FetchOffset::Latest);
        topics.add_partition("topic2", FetchOffset::Latest);

        self.consumer.fetch_stream(topics, GroupOffsetStorage::Kafka).try_collect().await
    }

    async fn process_message(&self, message: kafka::message::Message) -> Result<(), KafkaError> {
        let metadata = self.get_metadata(message.key.clone()).await?;
        // Process message with context from metadata

        if message.value.is_some() {
            self.acknowledge_message(&message).await;
        }

        Ok(())
    }

    async fn get_metadata(&self, key: Option<&[u8]>) -> Result<String, reqwest::Error> {
        let mut url = self.metadata_service_url.clone();
        url.push_str("/metadata");
        if let Some(key) = key {
            url.push_str(&format!("?key={}", std::str::from_utf8(key).unwrap()));
        }

        reqwest::get(url)
            .await?
            .text()
            .await
    }

    async fn acknowledge_message(&self, message: &kafka::message::Message) -> Result<(), KafkaError> {
        self.consumer.commit_message(message)?;
        Ok(())
    }

    async fn dead_letter_queue(&self, message: kafka::message::Message) -> Result<(), KafkaError> {
        let mut tpls = TopicPartitionList::new();
        tpls.add_partition("dead_letter_topic", FetchOffset::Latest);

        let producer_record = kafka::producer::ProducerRecord::to_topic_partition_list(
            "dead_letter_topic",
            message.key.clone(),
            message.value.clone(),
            None,
        );

        self.producer.send_all(&mut futures::stream::iter(vec![Ok(producer_record)]), tpls).await?;

        Ok(())
    }
}

#[tokio::main]
async fn main() {
    env_logger::init();

    let mut consumer = MessageBrokerConsumer::new(
        vec!["kafka://localhost:9092".to_string()],
        "my_group",
        "http://metadata-service:8080".to_string(),
    );

    consumer.start().await;
}
