struct BuildService {
    services: HashMap<String, Service>,
    dependencies: HashMap<String, Vec<String>>,
}

impl BuildService {
    fn new() -> Self {
        BuildService {
            services: HashMap::new(),
            dependencies: HashMap::new(),
        }
    }

    fn add_service(&mut self, name: String, service: Service) {
        self.services.insert(name, service);
    }

    fn add_dependency(&mut self, service_name: &str, dependency_name: &str) {
        self.dependencies.entry(service_name.to_string()).or_insert_with(Vec::new).push(dependency_name.to_string());
    }

    async fn build(&self, service_name: &str) -> i32 {
        if let Some(service) = self.services.get(service_name) {
            if let Some(dependencies) = self.dependencies.get(service_name) {
                for dependency in dependencies {
                    let result = task::spawn(async move { self.build(dependency).await }).await.unwrap();
                    if result != 0 {
                        return result;
                    }
                }
            }
            service.compile().await
        } else {
            eprintln!("Service not found: {}", service_name);
            1
        }
    }
}

struct Service {
    name: String,
    version: String,
    dependencies: HashSet<String>,
}

impl Service {
