    pub async fn process_images(&self, jobs: Vec<ImageJob>, concurrency: usize) -> Result<Vec<Result<Vec<u8>, String>>, String> {
        let mut handles = vec![];
        let sem = Semaphore::new(concurrency);

        for job in jobs {
            let permit = sem.acquire().await.map_err(|_| "Semaphore acquisition failed")?;
            let api = self.api.clone();
            let cache = self.cache.clone();
            let logger = self.logger.clone();
            let metrics = self.metrics.clone();

            handles.push(tokio::spawn(async move {
                let result = process_image(api, cache, logger, metrics, &job).await;
                drop(permit);
                result
            }));
