        $this->logger = new Logger('payment_service');
        $this->logger->pushHandler(new StreamHandler(__DIR__.'/logs/payment_service.log', Logger::DEBUG));

        $dsn = "mysql:host=localhost;dbname=payments";
        $options = [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            PDO::ATTR_EMULATE_PREPARES => false
        ];
        $this->pdo = new PDO($dsn, 'user', 'password', $options);
    }

    public function processTransaction($transaction) {
        $retryCount = 0;
        $maxRetries = 5;

        while ($retryCount < $maxRetries) {
            try {
                // Simulate currency conversion
                $convertedAmount = $this->convertCurrency($transaction['amount'], $transaction['currency']);

                // Start transaction
                $this->pdo->beginTransaction();

                // Call third-party payment gateway API
                $response = $this->httpClient->request('POST', 'process', [
                    'json' => [
                        'amount' => $convertedAmount,
                        'currency' => $transaction['target_currency'],
                        'reference_id' => $transaction['id']
                    ]
                ]);

                // Check response status and process
                if ($response->getStatusCode() == 200) {
                    // Update payment status in database
                    $stmt = $this->pdo->prepare("UPDATE transactions SET status = 'processed', gateway_response = :response WHERE id = :id");
                    $stmt->execute(['response' => json_encode($response->getBody()), 'id' => $transaction['id']]);

                    $this->pdo->commit();
                    return true;
                } else {
                    throw new \Exception('Third-party payment gateway returned an error');
                }
            } catch (\Exception $e) {
                if ($retryCount == $maxRetries - 1) {
                    // Log failure and retry
                    $this->logger->error("Transaction {$transaction['id']} failed after $maxRetries retries: " . $e->getMessage());
                    throw $e;
                }

                // Exponential backoff before retrying
                sleep(pow(2, $retryCount));
                $retryCount++;
            }
        }

        return false;
    }

    private function convertCurrency($amount, $fromCurrency) {
        try {
            // Simulate currency conversion using an external service
            $response = $this->httpClient->request('GET', "convert?from=$fromCurrency&to=USD");
            $body = json_decode((string)$response->getBody(), true);
            return $amount * $body['rate'];
        } catch (\Exception $e) {
            // Handle currency conversion errors
            $this->logger->warning("Failed to convert currency for amount {$amount} from $fromCurrency: " . $e->getMessage());
            throw $e;
        }
    }
}

// Example usage:
$processor = new PaymentProcessor();
$transaction = [
    'id' => uniqid(),
    'amount' => 100,
    'currency' => 'EUR',
    'target_currency' => 'USD'
];
$success = $processor->processTransaction($transaction);
if ($success) {
    echo "Transaction processed successfully";
} else {
    echo "Failed to process transaction";
}
?>
```

