        super().put(item, block, timeout)
        self.notify()

class LogAnalyzerService:
    def __init__(self):
        self.processors = {
            'json': JSONLogProcessor(),
            'csv': CSVLogProcessor(),
            'xml': XMLLogProcessor()
        }
        self.queue = LogQueue()
        self.threads = [threading.Thread(target=self.worker) for _ in range(3)]
        for thread in self.threads:
            thread.start()

    def worker(self) -> None:
        while True:
            entry = self.queue.get()
            if entry is None:
                break
            processor = self.processors.get(entry.type)
            if processor:
                processor.process(entry)

