class DataStoreManager {
private:
    std::vector<std::unique_ptr<DataStoreInterface>> dataStores;

public:
    void addDataStore(std::unique_ptr<DataStoreInterface> store) {
        dataStores.push_back(std::move(store));
    }

    void storeData(const std::vector<TimeSeriesData>& data) {
        for (auto& store : dataStores) {
            store->store(data);
        }
    }

    std::vector<TimeSeriesData> queryData(std::function<bool(const TimeSeriesData&)> condition) {
        std::vector<TimeSeriesData> results;
        for (const auto& store : dataStores) {
            auto storeResults = store->query(condition);
            results.insert(results.end(), storeResults.begin(), storeResults.end());
        }
        return results;
    }
};

class TimeSeriesManager {
private:
    DataStoreManager dataStoreManager;
    std::queue<TimeSeriesData> incomingDataQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondition;
    bool stopFlag = false;

public:
    void addDataStore(std::unique_ptr<DataStoreInterface> store) {
        dataStoreManager.addDataStore(std::move(store));
    }

    void processData() {
        while (!stopFlag || !incomingDataQueue.empty()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCondition.wait(lock, [this] { return !incomingDataQueue.empty() || stopFlag; });

            if (stopFlag && incomingDataQueue.empty()) break;

            TimeSeriesData data = incomingDataQueue.front();
            incomingDataQueue.pop();
            lock.unlock();

            // Process the data
            std::vector<TimeSeriesData> results = performAggregations(data);
            dataStoreManager.storeData(results);
        }
    }

    void enqueueData(const TimeSeriesData& data) {
        std::unique_lock<std::mutex> lock(queueMutex);
        incomingDataQueue.push(data);
        queueCondition.notify_one();
    }

    void stop() {
        stopFlag = true;
        queueCondition.notify_all();
    }

private:
    std::vector<TimeSeriesData> performAggregations(const TimeSeriesData& data) {
        // Implement aggregation logic
        return {};
    }
};

int main() {
    TimeSeriesManager manager;
    manager.addDataStore(std::make_unique<CassandraDataStore>());
    manager.addDataStore(std::make_unique<TimescaleDBDataStore>());

    std::thread processor([&manager] { manager.processData(); });

    for (int i = 0; i < 100000; ++i) {
        TimeSeriesData data;
        manager.enqueueData(data);
    }

    manager.stop();
    processor.join();

    return 0;
}
