package com.filemonitor.service;

import org.springframework.stereotype.Service;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

@Service
public class FileService {

    @Autowired
    private ExternalApiService externalApiService;

    @Autowired
    private PersistenceRepository persistenceRepository;

    public Mono<Void> processPendingDeletions() {
        return Flux.fromStream(externalApiService.getPendingDeletionRequests())
                .flatMap(this::processDeletion)
                .then();
    }

    private Mono<Void> processDeletion(String fileIdentifier) {
        return externalApiService.validateFile(fileIdentifier)
                .doOnSuccess(validationResult -> {
                    if (validationResult.isValid()) {
                        executeShellCommand("rm " + fileIdentifier);
                        persistenceRepository.logOperation(fileIdentifier, "DELETED");
                    } else {
                        persistenceRepository.logOperation(fileIdentifier, "INVALID");
                    }
                })
                .onErrorResume(throwable -> {
                    persistenceRepository.logOperation(fileIdentifier, "ERROR", throwable.getMessage());
                    return Mono.empty();
                });
    }

    private void executeShellCommand(String command) {
        // Execute the shell command using ProcessBuilder or similar
    }
