// C-based function create_and_log_crc_indications in a separate C file
#include <stdio.h>
#include <time.h>

typedef struct {
    int crc_value;
} NFAPI_CRC_INDICATION_PDU_T;

void create_and_log_crc_indications(int N) {
    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        perror("Failed to allocate memory for CRC indications");
        return;
    }

    // Generate and populate the indications array
    for (int i = 0; i < N; i++) {
        // Simulate generating a CRC value
        indications[i].crc_value = rand() % 10000;
    }

    FILE* logFile = fopen("crc_log.txt", "a");
    if (!logFile) {
        perror("Failed to open log file");
        free(indications);
        return;
    }

    // Log the indications
    for (int i = 0; i < N; i++) {
        fprintf(logFile, "CRC Indication %d: %d\n", i, indications[i].crc_value);
    }

    fclose(logFile);
    free(indications);
}
