// Function prototypes
void* validate_token(void* arg);
int parse_json(const char* json_str, json_t** token);
void log_error(const char* message);

// Global variables
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
json_error_t error;

// Configuration
#define MAX_TOKENS 1000
#define THREAD_POOL_SIZE 5

// Thread pool data structure
typedef struct {
    int id;
    pthread_t thread_id;
    int active;
} WorkerThread;

WorkerThread workers[THREAD_POOL_SIZE];

// Function to initialize the worker threads
void init_worker_threads() {
    for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
        workers[i].id = i;
        workers[i].active = 1;
        pthread_create(&workers[i].thread_id, NULL, validate_token, &workers[i]);
    }
}

// Function to submit a token validation task to the worker threads
void submit_task(const char* token_json) {
    for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
        if (!workers[i].active) continue;
        // Submit task to worker thread i
        printf("Submitting task %s to worker %d\n", token_json, workers[i].id);
        break;
    }
}

// Function to validate an OAuth2 access token
void* validate_token(void* arg) {
    WorkerThread* worker = (WorkerThread*)arg;
    while (1) {
        // Wait for a token validation task
        const char* token_json;
        // Get the next token from a queue or other source
        // For simplicity, assume we get it directly from an external API response
        // Example: token_json = fetch_next_token();

        if (!token_json) break;

        pthread_mutex_lock(&lock);
        printf("Worker %d processing token: %s\n", worker->id, token_json);
        json_t* token;
        int result = parse_json(token_json, &token);
        if (result != 0) {
            log_error("Failed to parse JSON");
        } else {
            // Validate token fields
            const char* access_token = json_string_value(json_object_get(token, "access_token"));
            int expires_in = json_integer_value(json_object_get(token, "expires_in"));
            const char* token_type = json_string_value(json_object_get(token, "token_type"));
            const char* refresh_token = json_string_value(json_object_get(token, "refresh_token"));

            if (!access_token || strlen(access_token) == 0 || expires_in <= 0 || strcmp(token_type, "Bearer") != 0) {
                log_error("Invalid token fields");
            } else {
                printf("Token validation successful\n");
            }

            json_decref(token);
        }
        pthread_mutex_unlock(&lock);

        // Sleep to simulate processing time
        sleep(1);
    }
    return NULL;
}

// Function to parse JSON data
int parse_json(const char* json_str, json_t** token) {
    *token = json_loads(json_str, 0, &error);
    if (!*token) {
        fprintf(stderr, "Failed to parse JSON: %s\n", error.text);
        return -1;
    }
    return 0;
}

// Function to log errors
void log_error(const char* message) {
    printf("ERROR: %s\n", message);
}

int main() {
    init_worker_threads();

    // Simulate receiving tokens from external APIs
    const char* token_json = "{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    submit_task(token_json);

    // Wait for all worker threads to finish (in a real scenario, this would be more complex)
    for (int i = 0; i < THREAD_POOL_SIZE; ++i) {
        pthread_join(workers[i].thread_id, NULL);
    }

    return 0;
}
