public class DataProcessingService
{
    private readonly IAmazonS3 _s3Client;
    private readonly MyDbContext _dbContext;

    public DataProcessingService(IAmazonS3 s3Client, MyDbContext dbContext)
    {
        _s3Client = s3Client;
        _dbContext = dbContext;
    }

    public async Task ProcessDataAsync(string bucketName, string keyPrefix)
    {
        var paginator = new ListObjectsV2Paginator(_s3Client, new ListObjectsV2Request
        {
            BucketName = bucketName,
            Prefix = keyPrefix
        });

        foreach (var response in paginator.Responses)
        {
            foreach (var s3Object in response.S3Objects)
            {
                var data = await _s3Client.GetObjectAsync(bucketName, s3Object.Key);
                using (var stream = new MemoryStream())
                {
                    await data.ResponseStream.CopyToAsync(stream);
                    var binaryData = stream.ToArray();
                    var entity = DeserializeBinary(binaryData);
                    _dbContext.Entities.Add(entity);
                }
            }
        }

        await _dbContext.SaveChangesAsync();
    }

