using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace VideoAnalyticsMicroservice
{
    public class VideoFrameProcessor
    {
        private readonly IVideoProcessingPipeline _videoProcessingPipeline;
        private readonly ITimeseriesDatabase _timeseriesDatabase;
        private readonly ILogger _logger;
        private readonly IMemoryCache _memoryCache;
        private readonly IQueueManager _queueManager;

        public VideoFrameProcessor(IVideoProcessingPipeline videoProcessingPipeline, 
                                   ITimeseriesDatabase timeseriesDatabase, 
                                   ILogger logger, 
                                   IMemoryCache memoryCache, 
                                   IQueueManager queueManager)
        {
            _videoProcessingPipeline = videoProcessingPipeline;
            _timeseriesDatabase = timeseriesDatabase;
            _logger = logger;
            _memoryCache = memoryCache;
            _queueManager = queueManager;
        }

        public async Task ProcessFrameAsync(byte[] frameData, string tenantId)
        {
            try
            {
                // Apply customizable filters and transformations
                var processedFrame = await _videoProcessingPipeline.ApplyFiltersAsync(frameData);

                // Detect and classify activities
                var activityMetadata = await _videoProcessingPipeline.ClassifyActivityAsync(processedFrame);

                // Store metadata in time-series database
                await _timeseriesDatabase.StoreMetadataAsync(activityMetadata, tenantId);

                // Cache frequently accessed metadata
                if (_memoryCache.Get(activityMetadata.ActivityId) == null)
                {
                    _memoryCache.Set(activityMetadata.ActivityId, activityMetadata, TimeSpan.FromMinutes(5));
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing video frame");
                // Handle error, implement retry logic if necessary
            }
        }

        public async Task ArchiveHistoricalDataAsync(string activityId, string storagePath)
        {
            try
            {
                // Retrieve metadata from cache or database
                var activityMetadata = await _memoryCache.GetOrCreateAsync(activityId, entry =>
                {
                    entry.SlidingExpiration = TimeSpan.FromMinutes(5);
                    return _timeseriesDatabase.RetrieveMetadataAsync(activityId);
                });

                if (activityMetadata != null)
                {
                    // Archive data to cloud storage
                    await _videoProcessingPipeline.ArchiveDataAsync(activityMetadata, storagePath);

                    // Optionally, remove from cache if archived successfully
                    _memoryCache.Remove(activityId);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error archiving historical video data");
                // Handle error, implement retry logic with backoff if necessary
                _queueManager.EnqueueTask(new RetryTask { TaskName = nameof(ArchiveHistoricalDataAsync), ActivityId = activityId, StoragePath = storagePath });
            }
        }
    }
}
