    // Simulate receiving messages from sensors
    std::vector<std::future<void>> futures;
    for (int i = 0; i < 1000000; ++i) {
        auto future = std::async(std::launch::async, [&strategy]() {
            GeoRegion region = {"region" + std::to_string(rand() % 5)};
            strategy.routeMessage(region.id, rand() % 100);
        });
