#define CACHE_SIZE 100

typedef struct {
    json_object *config;
} RACHConfig;

typedef struct {
    pthread_mutex_t lock;
    RACHConfig *cache[CACHE_SIZE];
    int cache_size;
} RACHCache;

// Function prototypes
void* fetch_config(void* arg);
int parse_json(json_object* jso, RACHConfig* config);
void update_cache(RACHCache* cache, json_object* jso);

int main() {
    pthread_t threads[MAX_THREADS];
    RACHCache cache = {0};
    pthread_mutex_init(&cache.lock, NULL);

    // Create worker threads
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, fetch_config, &cache)) {
            fprintf(stderr, "Error creating thread %d\n", i);
            return EXIT_FAILURE;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    pthread_mutex_destroy(&cache.lock);
    for (int i = 0; i < cache.cache_size; ++i) {
        json_object_put(cache.cache[i]->config);
        free(cache.cache[i]);
    }

    return EXIT_SUCCESS;
}

void* fetch_config(void* arg) {
    RACHCache *cache = (RACHCache*)arg;
    CURL *curl;
    CURLcode res;
    char buffer[1024];

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, API_URL);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, (void*)CURL_CALLBACK_WRITEFUNCTION);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, buffer);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        else {
            json_object *jso = json_tokener_parse(buffer);
            if (jso) {
                pthread_mutex_lock(&cache->lock);
                update_cache(cache, jso);
                pthread_mutex_unlock(&cache->lock);
                json_object_put(jso); // Free the JSON object after parsing
            } else {
                fprintf(stderr, "Failed to parse JSON\n");
            }
        }

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    return NULL;
}

int parse_json(json_object* jso, RACHConfig* config) {
    // Parse JSON and populate config object
    // Example: json_object_object_get_ex(jso, "param", &value)
    // Return 0 on success, non-zero on failure
    return 0; // Placeholder
}

void update_cache(RACHCache* cache, json_object* jso) {
    // Update the cache with new configuration data
    RACHConfig *new_config = malloc(sizeof(RACHConfig));
    new_config->config = jso;

    pthread_mutex_lock(&cache->lock);
    if (cache->cache_size < CACHE_SIZE) {
        cache->cache[cache->cache_size++] = new_config;
    } else {
        // Handle cache overflow
        free(new_config); // Free the allocated memory for the new config
    }
    pthread_mutex_unlock(&cache->lock);
