        for (int i = 0; i <= retries; i++) {
            try {
                return task.call();
            } catch (Exception e) {
                if (i == retries) throw e;
                Thread.sleep((long) Math.pow(2, i) * 100);
            }
        }
        return null;
    }

    // Implement circuit breakers to handle partial failures
    private final AtomicBoolean circuitOpen = new AtomicBoolean(false);

    public <T> T callWithCircuitBreaker(Callable<T> task) throws Exception {
