typedef struct {
    char* access_token;
    int expires_in;
    char* token_type;
    char* refresh_token;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* process_json_config(const char* json_str) {
    // Parse JSON string
    struct json_object* parsed_json = json_tokener_parse(json_str);
    if (!parsed_json) {
        fprintf(stderr, "Failed to parse JSON\n");
        return NULL;
    }

    // Validate required fields
    struct json_object* access_token_obj;
    if (json_object_object_get_ex(parsed_json, "access_token", &access_token_obj)) {
        NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memset(result, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Extract access_token
        if (!json_object_is_type(access_token_obj, json_type_string)) {
            fprintf(stderr, "Invalid type for access_token\n");
            free(result);
            return NULL;
        }
        result->access_token = strdup(json_object_get_string(access_token_obj));

        // Extract expires_in
        struct json_object* expires_in_obj;
        if (json_object_object_get_ex(parsed_json, "expires_in", &expires_in_obj)) {
            if (!json_object_is_type(expires_in_obj, json_type_int) || json_object_get_int(expires_in_obj) <= 0) {
                fprintf(stderr, "Invalid type or value for expires_in\n");
                free(result->access_token);
                free(result);
                return NULL;
            }
            result->expires_in = json_object_get_int(expires_in_obj);
        } else {
            fprintf(stderr, "Missing required field: expires_in\n");
            free(result->access_token);
            free(result);
            return NULL;
        }

        // Extract token_type
        struct json_object* token_type_obj;
        if (json_object_object_get_ex(parsed_json, "token_type", &token_type_obj)) {
            if (!json_object_is_type(token_type_obj, json_type_string) || strcmp(json_object_get_string(token_type_obj), "Bearer") != 0) {
                fprintf(stderr, "Invalid type or value for token_type\n");
                free(result->access_token);
                free(result);
                return NULL;
            }
            result->token_type = strdup(json_object_get_string(token_type_obj));
        } else {
            fprintf(stderr, "Missing required field: token_type\n");
            free(result->access_token);
            free(result);
            return NULL;
        }

        // Extract optional refresh_token
        if (json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token_obj)) {
            if (!json_object_is_type(refresh_token_obj, json_type_string)) {
                fprintf(stderr, "Invalid type for refresh_token\n");
                free(result->access_token);
                free(result->token_type);
                free(result);
                return NULL;
            }
            result->refresh_token = strdup(json_object_get_string(refresh_token_obj));
        }

        // Clean up
        json_object_put(parsed_json);

        return result;
    } else {
        fprintf(stderr, "Missing required field: access_token\n");
        if (parsed_json) {
            json_object_put(parsed_json);
        }
        return NULL;
    }
}

int main() {
    const char* json_str = "{\"access_token\":\"example_token\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    NFAPI_CRC_INDICATION_PDU_T* result = process_json_config(json_str);
    if (result) {
        printf("Access Token: %s\n", result->access_token);
        printf("Expires In: %d\n", result->expires_in);
        printf("Token Type: %s\n", result->token_type);
        if (result->refresh_token) {
            printf("Refresh Token: %s\n", result->refresh_token);
        }
        free(result->access_token);
        free(result->token_type);
        if (result->refresh_token) {
            free(result->refresh_token);
        }
        free(result);
    } else {
        printf("Failed to process JSON configuration\n");
    }
    return 0;
}
