// Include necessary headers and libraries
#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <atomic>

// Define the Notification struct
struct Notification {
    std::string message;
    bool isCritical;
};

// Define the NotificationQueue class
class NotificationQueue {
private:
    std::queue<Notification> queue;
    mutable std::mutex mutex;
    std::condition_variable cond_var;
    std::atomic<bool> running{true};

public:
    void add(const Notification& notification) {
        std::lock_guard<std::mutex> lock(mutex);
        queue.push(notification);
        cond_var.notify_one();
    }

    Notification get() {
        std::unique_lock<std::mutex> lock(mutex);
        cond_var.wait(lock, [this] { return !queue.empty() || !running; });
        if (!running) throw std::runtime_error("Queue has been stopped");
        auto notification = queue.front();
        queue.pop();
        return notification;
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(mutex);
            running = false;
        }
        cond_var.notify_all();
    }
};

// Define the NotificationProcessor class
class NotificationProcessor {
private:
    NotificationQueue& queue;

public:
    NotificationProcessor(NotificationQueue& q) : queue(q) {}

    void operator()() {
        while (true) {
            try {
                auto notification = queue.get();
                if (!notification.isCritical) {
                    std::this_thread::sleep_for(std::chrono::seconds(5));
                }
                // Process the notification here
                std::cout << "Processed: " << notification.message << std::endl;
            } catch (const std::runtime_error& e) {
                if (e.what() == "Queue has been stopped") break;
                std::cerr << "Error processing notification: " << e.what() << std::endl;
            }
        }
    }
};

// Define the main function
int main() {
    NotificationQueue queue;

    // Start notification processors
    std::thread processor1(queue);
    std::thread processor2(queue);

    // Simulate adding notifications
    for (int i = 0; i < 100; ++i) {
        queue.add({std::to_string(i), i % 3 == 0});
    }

    // Stop the processors gracefully
    queue.stop();
    processor1.join();
    processor2.join();

    return 0;
}
