typedef struct {
    long offset;
    int key;
    float timestamp;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t lock;

void* load_records(void* arg) {
    FILE* file = fopen("data.csv", "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        Record record;
        sscanf(line, "%ld,%d,%f", &record.offset, &record.key, &record.timestamp);

        pthread_mutex_lock(&lock);
        if (record_count < MAX_RECORDS) {
            records[record_count++] = record;
        }
        pthread_mutex_unlock(&lock);
    }

    fclose(file);
    return NULL;
}

void* process_records(void* arg) {
    for (int i = 0; i < record_count; i++) {
        // Process each record
    }
    return NULL;
}

int main() {
    pthread_t load_thread, process_thread;

    if (pthread_mutex_init(&lock, NULL) != 0) {
        perror("Failed to initialize mutex");
        return 1;
    }

    if (pthread_create(&load_thread, NULL, load_records, NULL) != 0) {
        perror("Failed to create load thread");
        pthread_mutex_destroy(&lock);
        return 1;
    }

    if (pthread_create(&process_thread, NULL, process_records, NULL) != 0) {
        perror("Failed to create process thread");
        pthread_join(load_thread, NULL);
        pthread_mutex_destroy(&lock);
        return 1;
    }

    pthread_join(load_thread, NULL);
    pthread_join(process_thread, NULL);

    pthread_mutex_destroy(&lock);
    return 0;
}
