import os
import time
from multiprocessing import Pool, Process, Queue
import requests

class TaskManager:
    def __init__(self, api_url, num_workers):
        self.api_url = api_url
        self.num_workers = num_workers
        self.pool = Pool(num_workers)
        self.tasks_queue = Queue()

    def submit_task(self, task_id):
        try:
            response = requests.post(f"{self.api_url}/submit", json={"task_id": task_id})
            if response.status_code == 200:
                print(f"Task {task_id} submitted successfully.")
            else:
                print(f"Failed to submit task {task_id}. Status code: {response.status_code}")
        except requests.RequestException as e:
            print(f"Network error while submitting task {task_id}: {e}")

    def fetch_result(self, task_id):
        try:
            response = requests.get(f"{self.api_url}/result", params={"task_id": task_id})
            if response.status_code == 200:
                result = response.json()
                print(f"Result for task {task_id}: {result}")
                return result
            else:
                print(f"Failed to fetch result for task {task_id}. Status code: {response.status_code}")
        except requests.RequestException as e:
            print(f"Network error while fetching result for task {task_id}: {e}")
        return None

    def worker(self):
        while True:
            task_id = self.tasks_queue.get()
            if task_id is None:
                break
            try:
                self.submit_task(task_id)
                time.sleep(1)  # Simulate task execution time
                result = self.fetch_result(task_id)
                print(f"Processed task {task_id} with result: {result}")
            except Exception as e:
                print(f"Error processing task {task_id}: {e}")

    def scale_workers(self, new_num_workers):
        if new_num_workers < self.num_workers:
            for _ in range(new_num_workers - self.num_workers):
                self.pool.apply_async(self.worker)
        elif new_num_workers > self.num_workers:
            for _ in range(new_num_workers - self.num_workers):
                p = Process(target=self.worker)
                p.start()
                self.pool._processes.add(p)
                self.pool._inqueue.put((None, None))
        self.num_workers = new_num_workers

    def manage_tasks(self, task_ids):
        for task_id in task_ids:
            self.tasks_queue.put(task_id)

# Example usage
api_url = "http://example.com/api"
task_manager = TaskManager(api_url, 3)
task_manager.scale_workers(5)
task_manager.manage_tasks(["task1", "task2", "task3"])
time.sleep(10)  # Allow some time for tasks to complete
