# metrics_collection.py

import time
from abc import ABC, abstractmethod

class MetricSource(ABC):
    @abstractmethod
    def fetch_data(self):
        pass

class Microservice(MetricSource):
    def fetch_data(self):
        # Simulate fetching data from a microservice
        return {"cpu_usage": 85, "memory_usage": 60}

class RelationalDatabase(MetricSource):
    def fetch_data(self):
        # Simulate fetching data from a relational database
        return {"disk_space": 75, "transaction_rate": 120}

class NoSQLStore(MetricSource):
    def fetch_data(self):
        # Simulate fetching data from a NoSQL store
        return {"cache_hit_ratio": 90}

class ExternalAPI(MetricSource):
    def fetch_data(self):
        # Simulate fetching data from an external API endpoint
        return {"api_response_time": 150, "error_rate": 2}

# metrics_aggregation.py

class MetricAggregator:
    def __init__(self, sources):
        self.sources = sources

    def aggregate_metrics(self):
        aggregated_data = {}
        for source in self.sources:
            data = source.fetch_data()
            for key, value in data.items():
                if key in aggregated_data:
                    aggregated_data[key].append(value)
                else:
                    aggregated_data[key] = [value]
        return {key: sum(values) / len(values) for key, values in aggregated_data.items()}

# metrics_monitoring.py

class MetricsMonitor:
    def __init__(self, aggregator):
        self.aggregator = aggregator
        self.thresholds = {
            "cpu_usage": 90,
            "memory_usage": 75,
            "disk_space": 80,
            "transaction_rate": 100,
            "cache_hit_ratio": 85,
            "api_response_time": 200,
            "error_rate": 3
        }

    def monitor(self):
        metrics = self.aggregator.aggregate_metrics()
        for key, value in metrics.items():
            if value > self.thresholds[key]:
                print(f"Alert: {key} exceeds threshold. Current value: {value}")

# main.py

from metrics_collection import Microservice, RelationalDatabase, NoSQLStore, ExternalAPI
from metrics_aggregation import MetricAggregator
from metrics_monitoring import MetricsMonitor

def main():
    sources = [
        Microservice(),
        RelationalDatabase(),
        NoSQLStore(),
        ExternalAPI()
    ]
    aggregator = MetricAggregator(sources)
    monitor = MetricsMonitor(aggregator)

    while True:
        monitor.monitor()
        time.sleep(60)  # Monitor every minute

if __name__ == "__main__":
    main()
```']

