package main

import (
	"context"
	"log"
	"sync"
	"time"

	"github.com/go-redis/redis/v8"
	"google.golang.org/grpc"
	pb "github.com/example/messaging/proto"
)

type MessageBroker struct {
	ctx       context.Context
	cancel    context.CancelFunc
	msgQueue  *redis.Client
	workerPool chan func()
}

func NewMessageBroker() (*MessageBroker, error) {
	ctx, cancel := context.WithCancel(context.Background())
	broker := &MessageBroker{
		ctx:      ctx,
		cancel:   cancel,
		msgQueue: redis.NewClient(&redis.Options{Addr: "localhost:6379"}),
		workerPool: make(chan func(), 100),
	}

	go broker.startWorkerPool()
	return broker, nil
}

func (b *MessageBroker) startWorkerPool() {
	for {
		select {
		case worker := <-b.workerPool:
			go worker()
		case <-b.ctx.Done():
			log.Println("Worker pool shutting down")
			return
		}
	}
}

func (b *MessageBroker) SendMessage(msg *pb.Message, platform string) error {
	// Route message based on policy and send to appropriate queue
