	// Subscribe to the platform's queue and handle incoming messages
	// Implement message acknowledgment, retries, and dead-letter queues
	for {
		select {
		case <-b.ctx.Done():
			log.Println("Message receiving stopped")
			return
		default:
			msg, err := b.msgQueue.BLPop(b.ctx, 0, "queue:"+platform).Result()
			if err != nil {
				log.Printf("Error popping message: %v", err)
				continue
			}
			go handler(&pb.Message{Data: msg[1]})
		}
	}
}

func (b *MessageBroker) Stop() {
	b.cancel()
	close(b.workerPool)
	log.Println("Message broker stopped")
}

