import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ConcurrentHashMap;

public class DataIngestionPipeline {

    private final ConcurrentHashMap<String, Boolean> fileLocks = new ConcurrentHashMap<>();

    public void processFile(String inputFilename) {
        String versionedFilename = generateVersionedFilename(inputFilename);
        Path path = Paths.get(versionedFilename);

        if (fileLocks.putIfAbsent(path.toString(), true) == null) {
            try {
                Files.copy(Paths.get(inputFilename), path);
                // Process the file
            } catch (IOException e) {
                handleException(e);
            } finally {
                fileLocks.remove(path.toString());
            }
        } else {
            System.out.println("File is currently being processed.");
        }
    }

    private String generateVersionedFilename(String inputFilename) {
        int version = 1;
        Path directoryPath = Paths.get(inputFilename).getParent();
        String baseName = Paths.get(inputFilename).getFileName().toString();

        while (true) {
            String proposedFilename = directoryPath.resolve(baseName + "_" + version + ".txt").toString();
            if (!Files.exists(Paths.get(proposedFilename))) {
                return proposedFilename;
            }
            version++;
        }
    }

    private void handleException(Exception e) {
        System.err.println("An error occurred: " + e.getMessage());
        // Log the exception or take other appropriate actions
    }
}
