#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Define NFAPI_CRC_INDICATION_PDU_T structure fields here
    int crc_value;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} UplinkCrcArray;

UplinkCrcArray* uplink_crc_array_create(size_t initial_capacity) {
    UplinkCrcArray *array = (UplinkCrcArray*)malloc(sizeof(UplinkCrcArray));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(array);
        return NULL;
    }
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void uplink_crc_array_destroy(UplinkCrcArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->array);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int uplink_crc_array_add(UplinkCrcArray *array, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size++] = item;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int uplink_crc_array_get(UplinkCrcArray *array, size_t index, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->size) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    *item = array->array[index];
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int uplink_crc_array_remove(UplinkCrcArray *array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->size) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    for (size_t i = index; i < array->size - 1; i++) {
        array->array[i] = array->array[i + 1];
    }
    array->size--;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

