#include <stdlib.h>
#include <pthread.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_Crc_Indication_Library;

NFAPI_Crc_Indication_Library* nfapi_crc_indication_lib_init(size_t initial_capacity) {
    NFAPI_Crc_Indication_Library *lib = malloc(sizeof(NFAPI_Crc_Indication_Library));
    if (!lib) return NULL;

    lib->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!lib->data) {
        free(lib);
        return NULL;
    }

    lib->capacity = initial_capacity;
    lib->size = 0;
    pthread_mutex_init(&lib->mutex, NULL);

    return lib;
}

void nfapi_crc_indication_lib_destroy(NFAPI_Crc_Indication_Library *lib) {
    if (lib->data) free(lib->data);
    pthread_mutex_destroy(&lib->mutex);
    free(lib);
}

int nfapi_crc_indication_lib_push(NFAPI_Crc_Indication_Library *lib, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&lib->mutex);

    if (lib->size >= lib->capacity) {
        size_t new_capacity = lib->capacity ? lib->capacity * 2 : 1;
        void *new_data = realloc(lib->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&lib->mutex);
            return -1; // Out of memory
        }

        lib->data = new_data;
        lib->capacity = new_capacity;
    }

    lib->data[lib->size++] = item;

    pthread_mutex_unlock(&lib->mutex);
    return 0;
}

int nfapi_crc_indication_lib_pop(NFAPI_Crc_Indication_Library *lib, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&lib->mutex);

    if (lib->size == 0) {
        pthread_mutex_unlock(&lib->mutex);
        return -1; // Empty library
    }

    *item = lib->data[--lib->size];

    pthread_mutex_unlock(&lib->mutex);
    return 0;
}
```

