        return NULL;
    }
    lib->capacity = initial_capacity;
    lib->count = 0;
    pthread_mutex_init(&lib->lock, NULL);
    return lib;
}

void add_crc_indication(CRC_Indication_Library* lib, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&lib->lock);
    if (lib->count == lib->capacity) {
        size_t new_capacity = lib->capacity * 2;
        Buffer** new_buffers = realloc(lib->buffers, new_capacity * sizeof(Buffer*));
        if (!new_buffers) {
            pthread_mutex_unlock(&lib->lock);
            return; // Handle allocation failure
        }
        lib->buffers = new_buffers;
        lib->capacity = new_capacity;
    }
    Buffer* buffer = allocate_buffer(NFAPI_CRC_INDICATION_PDU_T_SIZE);
    if (buffer) {
        serialize_crc_indication(pdu, buffer);
        lib->buffers[lib->count++] = buffer;
    }
    pthread_mutex_unlock(&lib->lock);
}

void free_crc_indication_library(CRC_Indication_Library* lib) {
    for (size_t i = 0; i < lib->count; ++i) {
        free_buffer(lib->buffers[i]);
    }
    free(lib->buffers);
    pthread_mutex_destroy(&lib->lock);
    free(lib);
}
