class GeoDataAggregator {
public:
    void processSensorData(const std::string& region, const std::vector<double>& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        regions_[region].insert(regions_[region].end(), data.begin(), data.end());
    }

    std::map<std::string, StatisticalData> getAggregatedData() const {
        std::map<std::string, StatisticalData> result;
        for (const auto& pair : regions_) {
            StatisticalData stats = calculateStatistics(pair.second);
            result[pair.first] = stats;
        }
        return result;
    }

    void updateAggregationAlgorithm(const std::string& region, const AggregationAlgorithm& newAlgorithm) {
        std::lock_guard<std::mutex> lock(mutex_);
        regions_[region].algorithm_ = newAlgorithm;
    }

private:
    struct StatisticalData {
        double mean;
        double median;
        // Add other statistical measures here
    };

    struct AggregationAlgorithm {
        // Define the aggregation algorithm parameters here
    };

    StatisticalData calculateStatistics(const std::vector<double>& data) const {
        StatisticalData stats;
        if (!data.empty()) {
            stats.mean = std::accumulate(data.begin(), data.end(), 0.0) / data.size();
            std::sort(data.begin(), data.end());
            size_t size = data.size();
            if (size % 2 == 0) {
                stats.median = (data[size / 2 - 1] + data[size / 2]) / 2;
            } else {
                stats.median = data[size / 2];
            }
            // Calculate other statistical measures here
        }
        return stats;
    }

    std::map<std::string, std::vector<double>> regions_;
    mutable std::mutex mutex_;
};

