void initNFAPIArray(NFAPIArray* array, size_t initialCapacity) {
    array->data = (UEInformation*)malloc(initialCapacity * sizeof(UEInformation));
    pthread_mutex_init(&array->lock, NULL);
    array->size = 0;
    array->capacity = initialCapacity;
}

void destroyNFAPIArray(NFAPIArray* array) {
    pthread_mutex_destroy(&array->lock);
    free(array->data);
}

void resizeNFAPIArray(NFAPIArray* array, size_t newCapacity) {
    UEInformation* newData = (UEInformation*)realloc(array->data, newCapacity * sizeof(UEInformation));
    if (newData) {
        array->data = newData;
        array->capacity = newCapacity;
    }
}

void addNFAPIElement(NFAPIArray* array, int value) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        resizeNFAPIArray(array, array->capacity * 2);
    }
    array->data[array->size].NFAPI_CRC_INDICATION_PDU_T = value;
    array->size++;
    pthread_mutex_unlock(&array->lock);
}

void removeNFAPIElement(NFAPIArray* array, int index) {
    pthread_mutex_lock(&array->lock);
    if (index >= 0 && index < array->size) {
        memmove(&array->data[index], &array->data[index + 1], (array->size - index - 1) * sizeof(UEInformation));
        array->size--;
    }
    pthread_mutex_unlock(&array->lock);
}

int getNFAPIElement(NFAPIArray* array, int index) {
    if (index >= 0 && index < array->size) {
        return array->data[index].NFAPI_CRC_INDICATION_PDU_T;
    }
