class BatchProcessor {
public:
    BatchProcessor(std::vector<std::unique_ptr<CatalogAPI>> catalogs, CustomMemoryPool& pool)
        : catalogs(catalogs), metadataPool(pool) {}

    void batchProcessAndCache(const std::vector<std::string>& filePaths,
                               const std::function<void(const std::string&, const FileMetadata&)>& callback) {
        for (const auto& path : filePaths) {
            processFile(path, callback);
        }
    }

private:
    std::vector<std::unique_ptr<CatalogAPI>> catalogs;
    CustomMemoryPool& metadataPool;

    void processFile(const std::string& path, const std::function<void(const std::string&, const FileMetadata&)>& callback) {
        for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
            for (auto& catalog : catalogs) {
                if (catalog->getFileMetadata(path, metadataPool)) {
                    callback(path, metadata);
                    return;
                }
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(2 << attempt));
        }

        // Log failure
    }

    static const int MAX_RETRIES = 5;
};

