#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    // Define the structure for NFAPI_CRC_INDICATION_PDU_T here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    pthread_cond_init(&array->cond, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        free(array->array);
        pthread_mutex_destroy(&array->mutex);
        pthread_cond_destroy(&array->cond);
        free(array);
    }
}

int add_to_dynamic_array(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T item) {
    if (!array || !item) return -1;

    pthread_mutex_lock(&array->mutex);

    while (array->size == array->capacity) {
        pthread_cond_wait(&array->cond, &array->mutex);
    }

    if (array->size >= array->capacity) {
        // Handle out-of-memory condition
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }

    array->array[array->size++] = item;

    pthread_cond_signal(&array->cond);
    pthread_mutex_unlock(&array->mutex);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T get_from_dynamic_array(DynamicArray* array, size_t index) {
    NFAPI_CRC_INDICATION_PDU_T result = {0};
    if (!array || index >= array->size) return result;

    pthread_mutex_lock(&array->mutex);

    while (index >= array->size) {
        pthread_cond_wait(&array->cond, &array->mutex);
    }

    if (index < array->size) {
        result = array->array[index];
    }

    pthread_mutex_unlock(&array->mutex);
    return result;
}
