// C++ Code for Scalable Financial Trading Platform

#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <queue>
#include <functional>
#include <memory>
#include <chrono>

class OrderBook {
public:
    OrderBook() : is_running_(true) {
        worker_thread_ = std::thread(&OrderBook::WorkerThread, this);
    }

    ~OrderBook() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            is_running_ = false;
        }
        condition_.notify_all();
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
    }

    void AddOrder(std::shared_ptr<Order> order) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            orders_.push(order);
        }
        condition_.notify_one();
    }

private:
    void WorkerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this]{ return !orders_.empty() || !is_running_; });
            if (!is_running_ && orders_.empty()) {
                break;
            }
            auto order = orders_.front();
            orders_.pop();
            lock.unlock();

            // Process the order
            std::cout << "Processing order: " << *order << std::endl;

            // Simulate processing time
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

    bool is_running_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::queue<std::shared_ptr<Order>> orders_;
    std::thread worker_thread_;
};

class Order {
public:
    Order(int id, double price, int quantity) : id_(id), price_(price), quantity_(quantity) {}

    friend std::ostream& operator<<(std::ostream& os, const Order& order) {
        return os << "Order ID: " << order.id_ << ", Price: " << order.price_ << ", Quantity: " << order.quantity_;
    }

private:
    int id_;
    double price_;
    int quantity_;
};

int main() {
    OrderBook book;
    book.AddOrder(std::make_shared<Order>(1, 150.75, 10));
    book.AddOrder(std::make_shared<Order>(2, 151.25, 20));

    return 0;
}
