#include <thread>
#include <mutex>

class KeyValueStore {
private:
    std::unordered_map<std::string, std::pair<std::string, time_t>> store;
    std::mutex mtx;

public:
    void set(const std::string& key, const std::string& value, time_t ttl) {
        std::lock_guard<std::mutex> lock(mtx);
        store[key] = {value, time(NULL) + ttl};
    }

    std::optional<std::string> get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = store.find(key);
        if (it != store.end() && time(NULL) < it->second.second) {
            return it->second.first;
        }
        return std::nullopt;
    }

    void remove(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        store.erase(key);
    }
};

int main() {
    KeyValueStore kvstore;

    kvstore.set("user1", "data1", 60);
    auto value = kvstore.get("user1");
    if (value) {
        std::cout << "Value: " << *value << std::endl;
    } else {
        std::cout << "Key not found or expired" << std::endl;
    }

    kvstore.remove("user1");

    return 0;
}
