        # Simulate authentication with Microsoft API
        time.sleep(random.uniform(0.2, 0.6))
        return True

class AppleIdP(IdentityProvider):
    def authenticate(self, credentials: Dict[str, Any]) -> bool:
        # Simulate authentication with Apple API
        time.sleep(random.uniform(0.4, 0.8))
        return True

class AuthSystem:
    def __init__(self, idps: List[IdentityProvider]):
        self.idps = idps

    def authenticate_user(self, credentials: Dict[str, Any]) -> bool:
