UeCrcData* ue_crc_data[MAX_UE];
pthread_mutex_t mutexes[MAX_UE];

void init_library() {
    for (int i = 0; i < MAX_UE; i++) {
        ue_crc_data[i] = malloc(sizeof(UeCrcData));
        pthread_mutex_init(&mutexes[i], NULL);
    }
}

void process_crc(int ue_id, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&mutexes[ue_id]);
    ue_crc_data[ue_id]->ue_id = ue_id;
    memcpy(&ue_crc_data[ue_id]->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&mutexes[ue_id]);
}

void* crc_processor(void* arg) {
    int thread_id = *(int*)arg;
    while (1) {
        for (int i = 0; i < MAX_UE; i++) {
            pthread_mutex_lock(&mutexes[i]);
            if (ue_crc_data[i] != NULL) {
                // Process CRC data for UE i
                printf("Processing CRC for UE %d\n", ue_crc_data[i]->ue_id);
                free(ue_crc_data[i]);
                ue_crc_data[i] = NULL;
            }
            pthread_mutex_unlock(&mutexes[i]);
        }
    }
    return NULL;
}

int main() {
    init_library();

    pthread_t threads[MAX_UE];
    int thread_ids[MAX_UE];

    for (int i = 0; i < MAX_UE; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, crc_processor, &thread_ids[i]);
    }

    // Simulate CRC processing
    NFAPI_CRC_INDICATION_PDU_T pdu;
    for (int i = 0; i < MAX_UE; i++) {
        process_crc(i, &pdu);
    }

    for (int i = 0; i < MAX_UE; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
