        data_sources.push_back({url, format});
    }

    void startProcessing() {
        std::thread([this]() {
            while (running.load()) {
                processNextData();
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        }).detach();
    }

    void stop() {
        running.store(false);
    }

private:
    struct DataSource {
        std::string url;
        CompressionFormat format;
    };

    std::vector<DataSource> data_sources;
    std::atomic<bool> running;
    int retry_count;

    void processNextData() {
        if (retry_count >= 5) {
            logError("Max retry attempts reached");
            return;
        }

        DataSource source = getNextDataSource();
        try {
            fetchData(source);
            processData(source.data);
            storeData(source.data);
            retry_count = 0; // Reset retry count on success
        } catch (...) {
            logError("Failed to process data from source: " + source.url);
            std::this_thread::sleep_for(std::chrono::seconds(1 << retry_count));
            retry_count++;
        }
    }

    DataSource getNextDataSource() {
        static int index = 0;
        return data_sources[index++ % data_sources.size()];
    }

    void fetchData(DataSource& source) {
