async function asyncReduce(array, initialValue, reducerGenerator) {
    let accumulator = initialValue;

    try {
        for (let value of array) {
            const nextValue = await reducerGenerator.next({ accumulator, value });
            if (nextValue.done) break;
            accumulator = nextValue.value;
        }

        return accumulator;
    } catch (error) {
        console.error("Error during reduction:", error);
        throw error;
    }
}

