class ImageProcessor {
public:
    void process_image(const std::string& image_data) {
        // Simulate image processing
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        std::cout << "Processed image: " << image_data << std::endl;
    }
};

class TaskQueue {
public:
    void enqueue(const std::string& task) {
        std::unique_lock<std::mutex> lock(mutex_);
        tasks_.push(task);
        condition_.notify_one();
    }

    std::string dequeue() {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this] { return !tasks_.empty(); });
        std::string task = tasks_.front();
        tasks_.pop();
        return task;
    }

private:
    std::queue<std::string> tasks_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

class ImageProcessingService {
public:
    ImageProcessingService(size_t num_threads) : stop_(false) {
        for (size_t i = 0; i < num_threads; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    std::string task;
                    {
                        std::unique_lock<std::mutex> lock(mutex_);
                        condition_.wait(lock, [this] { return stop_ || !tasks_.empty(); });
                        if (stop_ && tasks_.empty()) {
                            break;
                        }
                        task = tasks_.front();
                        tasks_.pop();
                    }
                    processor_.process_image(task);
                }
            });
        }
    }

    ~ImageProcessingService() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        condition_.notify_all();
        for (std::thread& worker : workers_) {
            worker.join();
        }
    }

    void submit_task(const std::string& task) {
        std::lock_guard<std::mutex> lock(mutex_);
        tasks_.push(task);
        condition_.notify_one();
    }

private:
    ImageProcessor processor_;
    std::vector<std::thread> workers_;
    std::queue<std::string> tasks_;
    std::mutex mutex_;
    std::condition_variable condition_;
    bool stop_;
};

int main() {
    ImageProcessingService service(4);
    std::vector<std::string> image_data = {"image1", "image2", "image3"};

    for (const auto& data : image_data) {
        service.submit_task(data);
    }

    return 0;
}
