#include <iostream>
#include <string>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <condition_variable>

// Define a simple LRU Cache using an unordered map and a doubly linked list for order tracking
class LRUCache {
private:
    struct Node {
        std::string key;
        int value;
        Node* prev;
        Node* next;
        Node(std::string k, int v) : key(k), value(v), prev(nullptr), next(nullptr) {}
    };

    std::unordered_map<std::string, Node*> cache;
    Node* head;
    Node* tail;
    size_t capacity;
    std::mutex mtx;

public:
    LRUCache(size_t cap) : capacity(cap), head(new Node("", 0)), tail(new Node("", 0)) {
        head->next = tail;
        tail->prev = head;
    }

    ~LRUCache() {
        for (auto& entry : cache) {
            delete entry.second;
        }
        delete head;
        delete tail;
    }

    int get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        if (cache.find(key) == cache.end()) return -1;

        Node* node = cache[key];
        moveToHead(node);
        return node->value;
    }

    void put(const std::string& key, int value) {
        std::lock_guard<std::mutex> lock(mtx);
        if (cache.find(key) != cache.end()) {
            Node* node = cache[key];
            node->value = value;
            moveToHead(node);
            return;
        }

        if (cache.size() >= capacity) {
            Node* last = tail->prev;
            cache.erase(last->key);
            delete last;
            removeNode(last);
        }

        Node* newNode = new Node(key, value);
        cache[key] = newNode;
        addToHead(newNode);
    }

private:
    void moveToHead(Node* node) {
        removeNode(node);
        addToHead(node);
    }

    void addToHead(Node* node) {
        node->prev = head;
        node->next = head->next;
        head->next->prev = node;
        head->next = node;
    }

    void removeNode(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
};

int main() {
    LRUCache cache(2);
    cache.put("key1", 100);
    std::cout << "Get key1: " << cache.get("key1") << std::endl; // Output: 100
    cache.put("key2", 200);
    std::cout << "Get key2: " << cache.get("key2") << std::endl; // Output: 200
    cache.put("key3", 300); // Evicts key1
    std::cout << "Get key1: " << cache.get("key1") << std::endl; // Output: -1
    return 0;
}
```

This code provides a basic implementation of an LRU Cache in C++. It includes methods for getting and putting values, as well as moving nodes to the head of the list when accessed. The `LRUCache` class uses a combination of an unordered map and a doubly linked list to achieve efficient cache management.']

