import logging
from queue import Queue
from threading import Thread

class LogEntry:
    def __init__(self, source, content):
        self.source = source
        self.content = content

class LogIngestor:
    def __init__(self, queue):
        self.queue = queue

    def ingest(self, log_entry):
        # Simulate log ingestion from various sources
        print(f"Ingesting log from {log_entry.source}: {log_entry.content}")
        self.queue.put(log_entry)

class LogProcessor:
    def process(self, log_entry):
        # Simulate log processing
        print(f"Processing log: {log_entry.content}")

class LogStorage:
    def store(self, log_entry):
        # Simulate storing log entries in a database or file
        print(f"Storing log entry from {log_entry.source}: {log_entry.content}")

class LogSystem:
    def __init__(self):
        self.queue = Queue()
        self.ingestor = LogIngestor(self.queue)
        self.processors = [LogProcessor() for _ in range(3)]  # Example of dynamic scaling
        self.storers = [LogStorage() for _ in range(2)]    # Example of dynamic scaling

        for processor in self.processors:
            Thread(target=self._process_logs, args=(processor,)).start()

    def _process_logs(self, processor):
        while True:
            log_entry = self.queue.get()
            processor.process(log_entry)
            for storer in self.storers:
                storer.store(log_entry)

    def ingest_log(self, source, content):
        log_entry = LogEntry(source, content)
        self.ingestor.ingest(log_entry)

# Example usage
log_system = LogSystem()
log_system.ingest_log("file1.log", "Error: Disk space low")
log_system.ingest_log("network2.log", "Info: User logged in")
