// Filename management tool class
class FileNameManager {
public:
    void addVCS(VCS* vcs) {
        std::lock_guard<std::mutex> lock(mutex_);
        vcs_.push_back(vcs);
    }

    std::string generateFilename(const std::string& basename, const std::string& extension) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& vcs : vcs_) {
            if (vcs->isAvailable()) {
                return vcs->generateUniqueFilename(basename, extension);
            }
        }
        throw std::runtime_error("No available VCS to generate filename");
    }

private:
    std::mutex mutex_;
    std::vector<VCS*> vcs_;
};

// Base class for VCS interfaces
class VCS {
public:
    virtual ~VCS() {}
    virtual bool isAvailable() const = 0;
    virtual std::string generateUniqueFilename(const std::string& basename, const std::string& extension) = 0;
};

// Example implementation of GitVCS
