import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.github.resilience4j.circuitbreaker.CircuitBreakerConfig;
import io.github.resilience4j.retry.Retry;
import io.github.resilience4j.retry.RetryConfig;

@SpringBootApplication
@EnableFeignClients
public class OAuth2TokenManagerApplication {

    public static void main(String[] args) {
        SpringApplication.run(OAuth2TokenManagerApplication.class, args);
    }

    @Bean
    public CircuitBreaker circuitBreaker() {
        return CircuitBreaker.of("oauthService", CircuitBreakerConfig.custom()
                .failureRateThreshold(50)
                .waitDurationInOpenState(Duration.ofMillis(1000))
                .build());
    }

    @Bean
    public Retry retry() {
        return Retry.of("oauthRetry", RetryConfig.custom()
                .maxAttempts(3)
                .waitDuration(Duration.ofMillis(200))
                .jitter(Duration.ofMillis(50))
                .build());
    }
}
