#include <stdio.h>
#include <string.h>

void renameFile(const char *filename) {
    char newFilename[256];
    int numDigits = 0;
    char fileType[10];

    // Calculate number of digits in the filename
    for (int i = 0; i < strlen(filename); i++) {
        if (filename[i] >= '0' && filename[i] <= '9') {
            numDigits++;
        }
    }

    // Determine file type based on filename extension
    const char *dotPos = strrchr(filename, '.');
    if (dotPos != NULL) {
        strncpy(fileType, dotPos + 1, sizeof(fileType));
        fileType[sizeof(fileType) - 1] = '\0';
    } else {
        strcpy(fileType, "unknown");
    }

    // Generate new filename with modified extension
    sprintf(newFilename, "%s_%d.%s", filename, numDigits, fileType);

    // Rename the file using the system call
    rename(filename, newFilename);
}
