// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create a new PDU with random CRCFLAG
NFAPI_CRC_INDICATION_PDU_T* create_random_pdu(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

// Function to encode the PDU using a standard codec
void encode_pdu_standard(NFAPI_CRC_INDICATION_PDU_T* pdu, uint8_t** buffer, size_t* length) {
    *length = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *buffer = (uint8_t*)malloc(*length);
    memcpy(*buffer, pdu, *length);
}

// Function to decode the PDU using a standard codec
NFAPI_CRC_INDICATION_PDU_T* decode_pdu_standard(uint8_t* buffer, size_t length) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(pdu, buffer, length);
    return pdu;
}

// Function to free the memory allocated for a PDU
void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    free(pdu);
}
