#include <pthread.h>
#include <sys/time.h>

#define MAX_BUFFER_SIZE 1024
#define MAX_VALID_INT 1000

typedef struct {
    int value;
    pthread_mutex_t lock;
} ValidInt;

ValidInt* valid_ints[MAX_VALID_INT] = {NULL};
int next_valid_int_index = 0;

void initialize_valid_int(int value) {
    if (value < 1 || value > MAX_VALID_INT) return;
    if (valid_ints[value-1] != NULL) return;
    valid_ints[value-1] = malloc(sizeof(ValidInt));
    pthread_mutex_init(&valid_ints[value-1]->lock, NULL);
    valid_ints[value-1]->value = value;
}

void* socket_listener(void* arg) {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[MAX_BUFFER_SIZE] = {0};

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8080);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) >= 0) {
        int valread;
        char* data;

        if ((valread = read(new_socket, buffer, MAX_BUFFER_SIZE)) > 0) {
            data = strtok(buffer, " ");
            while (data != NULL) {
                int num = atoi(data);
                if (num > 0 && num <= MAX_VALID_INT) {
                    initialize_valid_int(num);
                }
                data = strtok(NULL, " ");
            }
        }
    }

    return NULL;
}

void* dns_resolver(void* arg) {
    // DNS resolution logic here
    return NULL;
}

void* log_service(void* arg) {
    // Log service interaction logic here
    return NULL;
}

int main() {
    pthread_t socket_thread, dns_thread, log_thread;

    if (pthread_create(&socket_thread, NULL, socket_listener, NULL) != 0) {
        perror("Failed to create socket thread");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&dns_thread, NULL, dns_resolver, NULL) != 0) {
        perror("Failed to create DNS resolver thread");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&log_thread, NULL, log_service, NULL) != 0) {
        perror("Failed to create log service thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(socket_thread, NULL);
    pthread_join(dns_thread, NULL);
    pthread_join(log_thread, NULL);

    return 0;
}
