#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    float timestamp;
} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (collection == NULL) return NULL;

    collection->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    if (collection->records == NULL) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_record(RecordCollection* collection, Record* record) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
        if (new_records == NULL) {
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->size++] = record;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

void* data_ingestion_thread(void* arg) {
    RecordCollection* collection = (RecordCollection*)arg;

    // Simulate data ingestion from an external source
    for (int i = 0; i < 1000; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->offset = i;
        record->key = i * 2;
        record->timestamp = i * 3.0f;

        add_record(collection, record);
    }

    return NULL;
}

int main() {
    RecordCollection* collection = create_record_collection(10);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, data_ingestion_thread, collection) != 0) {
        destroy_record_collection(collection);
        return -1;
    }

    pthread_join(thread_id, NULL);

    destroy_record_collection(collection);
    return 0;
}
