#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include "key_exchange_api.h"

typedef struct {
    EVP_CIPHER_CTX *ctx;
    int key_len;
    int iv_len;
} EncryptionContext;

EncryptionContext* create_encryption_context(const char *algorithm, const char *mode) {
    EncryptionContext *ctx = (EncryptionContext*)malloc(sizeof(EncryptionContext));
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }
    int cipher_nid = OBJ_sn2nid(algorithm);
    if (cipher_nid == NID_undef) {
        fprintf(stderr, "Unknown algorithm: %s\n", algorithm);
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }
    int mode_nid = OBJ_sn2nid(mode);
    if (mode_nid == NID_undef) {
        fprintf(stderr, "Unknown mode: %s\n", mode);
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
        fprintf(stderr, "Failed to initialize encryption context\n");
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }
    ctx->key_len = EVP_CIPHER_key_length(EVP_aes_256_cbc());
    ctx->iv_len = EVP_CIPHER_iv_length(EVP_aes_256_cbc());
    return ctx;
}

void destroy_encryption_context(EncryptionContext *ctx) {
    if (ctx->ctx) EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}

int encrypt_data(EncryptionContext *ctx, const unsigned char *key, const unsigned char *iv,
                 const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    if (!EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, key, iv)) return -1;
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) return -1;
    int final_len = 0;
    if (!EVP_EncryptFinal_ex(ctx->ctx, ciphertext + ciphertext_len, &final_len)) return -1;
    ciphertext_len += final_len;
    return ciphertext_len;
}

int decrypt_data(EncryptionContext *ctx, const unsigned char *key, const unsigned char *iv,
                 const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    if (!EVP_DecryptInit_ex(ctx->ctx, NULL, NULL, key, iv)) return -1;
    if (!EVP_DecryptUpdate(ctx->ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len)) return -1;
    int final_len = 0;
    if (!EVP_DecryptFinal_ex(ctx->ctx, plaintext + plaintext_len, &final_len)) return -1;
    plaintext_len += final_len;
    return plaintext_len;
}

void generate_key(unsigned char *key, size_t key_len) {
    if (!RAND_bytes(key, key_len)) {
        fprintf(stderr, "Failed to generate random key\n");
    }
}

void generate_iv(unsigned char *iv, size_t iv_len) {
    if (!RAND_bytes(iv, iv_len)) {
        fprintf(stderr, "Failed to generate random IV\n");
    }
}
```

