using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.IO;
using System.Security.Cryptography;

public class EncryptionService : IDisposable
{
    private readonly Dictionary<string, Aes> _aesCache = new Dictionary<string, Aes>();
    private readonly Dictionary<string, ChaCha20Poly1305> _chacha20Cache = new Dictionary<string, ChaCha20Poly1305>();

    public byte[] EncryptAES(byte[] data, string key)
    {
        if (!_aesCache.TryGetValue(key, out var aes))
        {
            aes = Aes.Create();
            aes.Key = Convert.FromBase64String(key);
            _aesCache[key] = aes;
        }

        using (var ms = new MemoryStream())
        {
            using (var cs = new CryptoStream(ms, aes.CreateEncryptor(), CryptoStreamMode.Write))
            {
                cs.Write(data, 0, data.Length);
            }
            return ms.ToArray();
        }
    }

    public byte[] DecryptAES(byte[] data, string key)
    {
        if (!_aesCache.TryGetValue(key, out var aes))
        {
            aes = Aes.Create();
            aes.Key = Convert.FromBase64String(key);
            _aesCache[key] = aes;
        }

        using (var ms = new MemoryStream(data))
        {
            using (var cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Read))
            {
                using (var resultMs = new MemoryStream())
                {
                    cs.CopyTo(resultMs);
                    return resultMs.ToArray();
                }
            }
        }
    }

    public byte[] EncryptChaCha20(byte[] data, string key)
    {
        if (!_chacha20Cache.TryGetValue(key, out var chacha20))
        {
            chacha20 = ChaCha20Poly1305.Create();
            chacha20.Key = Convert.FromBase64String(key);
            _chacha20Cache[key] = chacha20;
        }

        using (var nonce = GenerateNonce())
        {
            return chacha20.Encrypt(data, nonce);
        }
    }

    public byte[] DecryptChaCha20(byte[] data, string key)
    {
        if (!_chacha20Cache.TryGetValue(key, out var chacha20))
        {
            chacha20 = ChaCha20Poly1305.Create();
            chacha20.Key = Convert.FromBase64String(key);
            _chacha20Cache[key] = chacha20;
        }

        using (var nonce = GenerateNonce())
        {
            return chacha20.Decrypt(data, nonce);
        }
    }

    private byte[] GenerateNonce()
    {
        var nonce = new byte[16]; // ChaCha20 nonce is 12 bytes
        using (var rng = RandomNumberGenerator.Create())
        {
            rng.GetBytes(nonce);
        }
        return nonce;
    }

    public void Dispose()
    {
        foreach (var aes in _aesCache.Values)
        {
            aes.Dispose();
        }
        foreach (var chacha20 in _chacha20Cache.Values)
        {
            chacha20.Dispose();
        }
        _aesCache.Clear();
        _chacha20Cache.Clear();
    }
}

public class SQLParameterizedQuery
{
    public static IDataReader ExecuteQuery(string connectionString, string query, List<SqlParameter> parameters)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            connection.Open();

            using (var command = new SqlCommand(query, connection))
            {
                foreach (var parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }

                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
        }
    }
}

