#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_SIZE 2 * 1024 * 1024 * 1024 // 2 GB
#define NUM_DATA_CENTERS 50

typedef struct {
    char* log_data;
    int data_size;
} LogData;

void* process_log(void* arg) {
    LogData* log = (LogData*)arg;
    time_t current_time = time(NULL);
    char filename[100];
    snprintf(filename, sizeof(filename), "log_%ld.txt", current_time);

    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open log file");
        return NULL;
    }

    fwrite(log->log_data, 1, log->data_size, file);
    fclose(file);

    free(log->log_data);
    free(log);

    return NULL;
}

int main() {
    pthread_t threads[NUM_DATA_CENTERS];
    LogData logs[NUM_DATA_CENTERS];

    for (int i = 0; i < NUM_DATA_CENTERS; i++) {
        logs[i].data_size = rand() % MAX_LOG_SIZE;
        logs[i].log_data = (char*)malloc(logs[i].data_size);
        memset(logs[i].log_data, 'A' + (i % 26), logs[i].data_size);

        if (pthread_create(&threads[i], NULL, process_log, &logs[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_DATA_CENTERS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Log data processed and files generated successfully.\n");

    return EXIT_SUCCESS;
}
