#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <thread>
#include <mutex>

// Define a simple caching interface
class Cache {
public:
    virtual ~Cache() {}
    virtual void set(const std::string& key, const std::string& value) = 0;
    virtual std::string get(const std::string& key) const = 0;
};

// Implement a thread-safe cache using an unordered_map and mutex
class ThreadSafeCache : public Cache {
public:
    void set(const std::string& key, const std::string& value) override {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[key] = value;
    }

    std::string get(const std::string& key) const override {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            return it->second;
        }
        return "";
    }

private:
    mutable std::mutex mutex_;
    std::unordered_map<std::string, std::string> cache_;
};

// Implement a caching strategy using least recently used eviction
class LRUCache : public Cache {
public:
    LRUCache(size_t capacity) : capacity_(capacity), size_(0) {}

    void set(const std::string& key, const std::string& value) override {
        if (cache_.find(key) != cache_.end()) {
            move_to_front(key);
        } else {
            if (size_ >= capacity_) {
                evict();
            }
            insert_at_front(key, value);
        }
    }

    std::string get(const std::string& key) const override {
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            move_to_front(key);
            return it->second;
        }
        return "";
    }

private:
    size_t capacity_;
    size_t size_;
    mutable std::mutex mutex_;
    std::unordered_map<std::string, std::string> cache_;
    std::vector<std::string> order_;

    void insert_at_front(const std::string& key, const std::string& value) {
        order_.push_back(key);
        cache_[key] = value;
        ++size_;
    }

    void move_to_front(const std::string& key) {
        auto it = std::find(order_.begin(), order_.end(), key);
        if (it != order_.end()) {
            order_.erase(it);
            order_.push_back(key);
        }
    }

    void evict() {
        if (!order_.empty()) {
            cache_.erase(order_[0]);
            order_.erase(order_.begin());
            --size_;
        }
    }
};

int main() {
    Cache* cache = new LRUCache(100);

    cache->set("key1", "value1");
    std::cout << "Get key1: " << cache->get("key1") << std::endl;

    delete cache;
    return 0;
}
