    if (collection->count < MAX_RECORDS) {
        collection->records[collection->count++] = new_record;
    } else {
        fprintf(stderr, "Record collection is full\n");
    }
}

record get_record(record_collection* collection, int index) {
    if (index >= 0 && index < collection->count) {
        return collection->records[index];
    } else {
        record null_record = {-1, -1, -1};
        return null_record;
    }
}

void free_record_collection(record_collection* collection) {
    free(collection);
}
