function reduceAsync(numbers, initialValue, reducerGenerator) {
    let result = initialValue;

    for (const number of numbers) {
        try {
            result = yield reducerGenerator.next(result, number).value;
        } catch (error) {
            console.error("Error during reduction:", error);
            return null;
        }
    }

    return result;
}

async function runReduceAsync() {
    const numbers = [1, 2, 3, 4, 5];
    const initialValue = 0;

    const reducerGenerator = (function* (accumulator, currentValue) {
        return accumulator + currentValue;
    }).bind(null);

    try {
        const result = await reduceAsync(numbers, initialValue, reducerGenerator);
        console.log("Reduced value:", result);
    } catch (error) {
        console.error("Error during async reduction:", error);
    }
}

runReduceAsync();
