#define MAX_STRUCTS 10000

typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data[MAX_STRUCTS];
    int count;
    sem_t mutex;
} DataQueue;

void initialize_queue(DataQueue* queue) {
    queue->count = 0;
    sem_init(&queue->mutex, 0, 1);
}

int enqueue(DataQueue* queue, NFAPI_CRC_INDICATION_PDU_T* item) {
    if (sem_wait(&queue->mutex) != 0) {
        return -1; // Handle error
    }
    if (queue->count >= MAX_STRUCTS) {
        sem_post(&queue->mutex);
        return -2; // Queue is full
    }
    queue->data[queue->count++] = item;
    sem_post(&queue->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* dequeue(DataQueue* queue) {
    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    if (sem_wait(&queue->mutex) != 0) {
        return NULL; // Handle error
    }
    if (queue->count > 0) {
        result = queue->data[--queue->count];
    }
    sem_post(&queue->mutex);
    return result;
}

void* worker_thread(void* arg) {
    DataQueue* queue = (DataQueue*)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = dequeue(queue);
        if (pdu == NULL) {
            break; // Exit thread
        }
        // Process the PDU here
        free(pdu); // Free the memory when done processing
    }
    return NULL;
}

int main() {
    DataQueue queue;
    initialize_queue(&queue);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, worker_thread, &queue) != 0) {
            // Handle error
        }
    }

    for (int i = 0; i < MAX_STRUCTS; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            printf("Out of memory\n");
            break;
        }
        // Initialize the PDU here
        enqueue(&queue, pdu);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
