    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures[MAX_STRUCTURES];
    int count;
    pthread_mutex_t mutex;
} CacheNode;

CacheNode cache[NUM_NODES];

void* worker_thread(void* arg) {
    while (1) {
        for (int i = 0; i < NUM_NODES; i++) {
            pthread_mutex_lock(&cache[i].mutex);
            if (cache[i].count > 0) {
                NFAPI_CRC_INDICATION_PDU_T *pdu = cache[i].structures[--cache[i].count];
                // Process the PDU
                printf("Processed PDU with RNTI: %d\n", pdu->RNTI);
                free(pdu);
            }
            pthread_mutex_unlock(&cache[i].mutex);
        }
    }
    return NULL;
}

void initialize_cache() {
    for (int i = 0; i < NUM_NODES; i++) {
        cache[i].count = 0;
        pthread_mutex_init(&cache[i].mutex, NULL);
    }
}

