// Define a simple circular buffer for memory management
#define BUFFER_SIZE 10000
NFAPI_CRC_INDICATION_PDU_T buffer[BUFFER_SIZE];
int head = 0, tail = 0, count = 0;

// Function to add an element to the buffer
void addToBuffer(NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (count < BUFFER_SIZE) {
        buffer[head] = pdu;
        head = (head + 1) % BUFFER_SIZE;
        count++;
    } else {
        printf("Buffer overflow!\n");
    }
}

// Function to remove an element from the buffer
NFAPI_CRC_INDICATION_PDU_T removeFromBuffer() {
    if (count > 0) {
        NFAPI_CRC_INDICATION_PDU_T pdu = buffer[tail];
        tail = (tail + 1) % BUFFER_SIZE;
        count--;
        return pdu;
    } else {
        printf("Buffer underflow!\n");
        exit(1); // Exit if buffer is empty
    }
}

// Function to simulate processing of CRC indications
