#define MAX_UE_INFOS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T ue_infos[MAX_UE_INFOS];
int current_index = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* process_data(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        if (current_index > 0) {
            // Process data
            printf("Processing data for UE: %d, RNTI: %d\n", ue_infos[current_index - 1].RX_UE_INFORMATION_TAG, ue_infos[current_index - 1].RNTI);
            current_index--;
        } else {
            pthread_mutex_unlock(&mutex);
            pthread_cond_wait(&cond_var, &mutex); // Wait for new data
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int insert_data(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&mutex);
    if (current_index < MAX_UE_INFOS) {
        ue_infos[current_index++] = *pdu;
        pthread_cond_signal(&cond_var); // Notify waiting thread
        pthread_mutex_unlock(&mutex);
        return 0;
    } else {
        pthread_mutex_unlock(&mutex);
        return -1; // Queue full
    }
}

int main() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_data, NULL);

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, 4};
    insert_data(&pdu);

    pthread_join(thread_id, NULL);
    return 0;
}
