#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <semaphore.h>

#define MAX_STRUCTURES 10000
#define NUM_WORKER_NODES 4

typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* shared_memory;
sem_t* semaphores[NUM_WORKER_NODES];

void* worker_thread(void* arg) {
    int node_id = *(int*)arg;
    while (1) {
        sem_wait(&semaphores[node_id]);
        // Process the structures in shared memory
        sem_post(&semaphores[node_id]);
    }
}

int main() {
    key_t key = ftok("shmfile", 65);
    if ((shared_memory = shmat(key, (void*)0, 0)) == (char*)-1) {
        perror("shmat");
        exit(1);
    }

    for (int i = 0; i < NUM_WORKER_NODES; i++) {
        semaphores[i] = sem_open("/semaphore", O_CREAT, 0666, 1);
        if (semaphores[i] == SEM_FAILED) {
            perror("sem_open");
            exit(1);
        }
    }

    pthread_t threads[NUM_WORKER_NODES];
    int thread_ids[NUM_WORKER_NODES];
    for (int i = 0; i < NUM_WORKER_NODES; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]) != 0) {
            perror("pthread_create");
            exit(1);
        }
    }

    for (int i = 0; i < NUM_WORKER_NODES; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_unlink("/semaphore");
    shmdt(shared_memory);

    return 0;
}
