typedef struct {
    long offset;
    int key;
    float timestamp;
} record;

typedef struct {
    record *records;
    size_t count;
    size_t capacity;
    sem_t lock;
} record_collection;

record_collection* create_record_collection() {
    record_collection *collection = malloc(sizeof(record_collection));
    collection->records = NULL;
    collection->count = 0;
    collection->capacity = 0;
    sem_init(&collection->lock, 0, 1);
    return collection;
}

void destroy_record_collection(record_collection *collection) {
    free(collection->records);
    sem_destroy(&collection->lock);
    free(collection);
}

void add_record(record_collection *collection, record new_record) {
    sem_wait(&collection->lock);
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity == 0 ? 16 : collection->capacity * 2;
        collection->records = realloc(collection->records, new_capacity * sizeof(record));
        collection->capacity = new_capacity;
    }
    collection->records[collection->count++] = new_record;
    sem_post(&collection->lock);
}

void remove_record(record_collection *collection, int key) {
    sem_wait(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            for (size_t j = i + 1; j < collection->count; ++j) {
                collection->records[j - 1] = collection->records[j];
            }
            --collection->count;
            break;
        }
    }
    sem_post(&collection->lock);
}

record* find_record(record_collection *collection, int key) {
    sem_wait(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            record *result = &collection->records[i];
            sem_post(&collection->lock);
            return result;
        }
    }
    sem_post(&collection->lock);
    return NULL;
}
