// custom_allocator.c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    size_t allocated;
    size_t max_size;
    void* pool;
    pthread_mutex_t lock;
} CustomAllocator;

CustomAllocator* create_custom_allocator(size_t initial_size, size_t max_size) {
    CustomAllocator* allocator = malloc(sizeof(CustomAllocator));
    if (!allocator) return NULL;

    allocator->allocated = 0;
    allocator->max_size = max_size;
    allocator->pool = malloc(initial_size);
    if (!allocator->pool) {
        free(allocator);
        return NULL;
    }

    pthread_mutex_init(&allocator->lock, NULL);
    return allocator;
}

void* custom_malloc(CustomAllocator* allocator, size_t size) {
    pthread_mutex_lock(&allocator->lock);

    void* ptr = (char*)allocator->pool + allocator->allocated;
    if (allocator->allocated + size > allocator->max_size) {
        pthread_mutex_unlock(&allocator->lock);
        return NULL;
    }

    allocator->allocated += size;

    pthread_mutex_unlock(&allocator->lock);
    return ptr;
}

void custom_free(CustomAllocator* allocator, void* ptr) {
    // This is a simplified example. In a real scenario, you would need to manage the free list.
    pthread_mutex_lock(&allocator->lock);
    allocator->allocated -= size(ptr); // Assume a function size() that returns the allocated size of a block
    pthread_mutex_unlock(&allocator->lock);
}

void destroy_custom_allocator(CustomAllocator* allocator) {
    pthread_mutex_destroy(&allocator->lock);
    free(allocator->pool);
    free(allocator);
}
