// SensorDataProcessor.cs
using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

public class SensorDataProcessor
{
    private readonly ConcurrentDictionary<string, int> _cache = new ConcurrentDictionary<string, int>();
    private readonly HttpClient _httpClient;
    private readonly CustomMemoryPool _memoryPool;

    public SensorDataProcessor()
    {
        _httpClient = new HttpClient();
        _memoryPool = new CustomMemoryPool(1024 * 1024); // 1 MB
    }

    public async Task ProcessSensorDataAsync(string sensorId, int data)
    {
        lock (_cache)
        {
            _cache[sensorId] = data;
        }
    }

    private void EvictOldData()
    {
        var now = DateTimeOffset.UtcNow;
        lock (_cache)
        {
            foreach (var key in _cache.Keys.ToList())
            {
                if ((now - _cache[key]).TotalSeconds > 3600) // Example eviction policy: evict data older than 1 hour
                {
                    _cache.TryRemove(key, out _);
                }
            }
        }
    }

    private async Task<int> FetchDataFromApiAsync(string url)
    {
        try
        {
            var response = await _httpClient.GetAsync(url);
            if (response.IsSuccessStatusCode)
            {
                return await response.Content.ReadAsAsync<int>();
            }
        }
        catch (Exception ex)
        {
            // Log and handle exception
        }

        // Handle failure gracefully
        return default;
    }
}
