### Custom Memory Pool Class

```csharp
// CustomMemoryPool.cs
using System;
using System.Collections.Concurrent;

public class CustomMemoryPool : IDisposable
{
    private readonly ConcurrentBag<byte[]> _pool = new ConcurrentBag<byte[]>();
    private readonly int _blockSize;

    public CustomMemoryPool(int blockSize)
    {
        _blockSize = blockSize;
        PreallocateBlocks();
    }

    private void PreallocateBlocks()
    {
        for (int i = 0; i < 100; i++) // Preallocate 100 blocks
        {
            _pool.TryAdd(new byte[_blockSize]);
        }
    }

    public byte[] RentBlock()
    {
        if (_pool.TryTake(out var block))
        {
            return block;
        }

        // If no blocks available, allocate a new one
        return new byte[_blockSize];
    }

    public void ReturnBlock(byte[] block)
    {
        _pool.TryAdd(block);
    }

    public void Dispose()
    {
        foreach (var block in _pool)
        {
            Array.Clear(block, 0, block.Length);
        }
        _pool.Dispose();
    }
}
