// RateLimiter.cs
using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public class RateLimiter
{
    private readonly ConcurrentDictionary<string, DateTimeOffset> _rateLimits = new ConcurrentDictionary<string, DateTimeOffset>();

    public async Task<bool> TryExecuteAsync(string key, Func<Task> action, int limitPerMinute = 60)
    {
        var now = DateTimeOffset.UtcNow;
        if (!_rateLimits.TryGetValue(key, out var lastExecuted) || (now - lastExecuted).TotalMinutes >= 1.0 / limitPerMinute)
        {
            await action();
            _rateLimits[key] = now;
            return true;
        }

        Logger.LogError("Rate limit exceeded", null);
        return false;
    }
}
