// Define the structure for CRC indication PDU
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the list structure
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

// Function to initialize the list
void initList(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to insert a new node at the end of the list
void insertNode(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to deserialize the binary file and insert data into the list
void deserializeFile(List* list, const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp) == 1) {
        insertNode(list, pdu);
    }

    fclose(fp);
}

// Function to free the list and its nodes
void freeList(List* list) {
    pthread_mutex_lock(&list->lock);
    Node* temp = list->head;
    while (temp != NULL) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    List myList;
    initList(&myList);

    deserializeFile(&myList, "binary_file.bin");

    // Use the data in myList as needed

    freeList(&myList);
    return 0;
}
