    uint32_t timestamp;
    // Add other necessary fields
} NFAPI_CRC_INDICATION_PDU_T;

// Define a custom memory pool allocator structure
typedef struct MemoryPool {
    size_t block_size;
    size_t num_blocks;
    void *blocks;
    int *free_blocks;
} MemoryPool;

// Initialize the memory pool
MemoryPool *init_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = malloc(block_size * num_blocks);
    pool->free_blocks = (int *)calloc(num_blocks, sizeof(int));

    if (!pool->blocks || !pool->free_blocks) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < num_blocks; ++i) {
        pool->free_blocks[i] = 1;
    }

    return pool;
}

// Allocate memory from the custom memory pool
void *allocate_memory(MemoryPool *pool) {
    if (!pool) return NULL;

    for (size_t i = 0; i < pool->num_blocks; ++i) {
        if (pool->free_blocks[i]) {
            pool->free_blocks[i] = 0;
            return ((char *)pool->blocks) + (i * pool->block_size);
        }
    }

    return NULL;
}

// Free memory back to the custom memory pool
void free_memory(MemoryPool *pool, void *ptr) {
