#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define NFAPI_CRC_INDICATION_PDU_T structure here

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t length;
} Fragment;

typedef struct {
    Fragment **fragments;
    size_t capacity;
    size_t size;
    sem_t semaphore;
    pthread_mutex_t mutex;
} ReassemblyBuffer;

ReassemblyBuffer* create_reassembly_buffer(size_t initial_capacity) {
    ReassemblyBuffer *buffer = (ReassemblyBuffer*) malloc(sizeof(ReassemblyBuffer));
    buffer->fragments = (Fragment**) malloc(initial_capacity * sizeof(Fragment*));
    buffer->capacity = initial_capacity;
    buffer->size = 0;
    sem_init(&buffer->semaphore, 0, 1);
    pthread_mutex_init(&buffer->mutex, NULL);
    return buffer;
}

void destroy_reassembly_buffer(ReassemblyBuffer *buffer) {
    for (size_t i = 0; i < buffer->size; ++i) {
        free(buffer->fragments[i]->data);
        free(buffer->fragments[i]);
    }
    free(buffer->fragments);
    sem_destroy(&buffer->semaphore);
    pthread_mutex_destroy(&buffer->mutex);
    free(buffer);
}

void add_fragment(ReassemblyBuffer *buffer, Fragment *fragment) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->size == buffer->capacity) {
        buffer->capacity *= 2;
        buffer->fragments = (Fragment**) realloc(buffer->fragments, buffer->capacity * sizeof(Fragment*));
    }
    buffer->fragments[buffer->size++] = fragment;
    sem_post(&buffer->semaphore);
    pthread_mutex_unlock(&buffer->mutex);
}

void process_buffer(ReassemblyBuffer *buffer) {
    Fragment *fragment;
    while (1) {
        sem_wait(&buffer->semaphore);
        pthread_mutex_lock(&buffer->mutex);
        if (buffer->size == 0) {
            pthread_mutex_unlock(&buffer->mutex);
            break;
        }
        fragment = buffer->fragments[--buffer->size];
        // Process the fragment here
        free(fragment->data);
        free(fragment);
        pthread_mutex_unlock(&buffer->mutex);
    }
}

// Add more functions and data structures as needed

int main() {
    ReassemblyBuffer *buffer = create_reassembly_buffer(1024);

    // Simulate adding fragments
    Fragment *fragment = (Fragment*) malloc(sizeof(Fragment));
    fragment->data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    fragment->length = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    add_fragment(buffer, fragment);

    // Process the buffer
    process_buffer(buffer);

    destroy_reassembly_buffer(buffer);

    return 0;
}
