using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class ApiClientConfig
{
    public Dictionary<string, string> Endpoints { get; set; }
    public Dictionary<string, string> Headers { get; set; }
    public JsonSchema Schema { get; set; }
}

public class BatchedRequestResponse
{
    public string Endpoint { get; set; }
    public object Response { get; set; }
    public Exception Error { get; set; }
}

public delegate void PostProcessCallback(List<BatchedRequestResponse> results);

public interface IMessageBroker
{
    Task PublishAsync(string topic, BatchedRequestResponse response);
}

public class ApiClient
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<ApiClient> _logger;
    private readonly IMessageBroker _messageBroker;

    public ApiClient(HttpClient httpClient, ILogger<ApiClient> logger, IMessageBroker messageBroker)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _messageBroker = messageBroker ?? throw new ArgumentNullException(nameof(messageBroker));
    }

    public async Task<List<BatchedRequestResponse>> ProcessBatchedRequestsAsync(ApiClientConfig config, List<string> requestBodies, PostProcessCallback postProcessCallback = null)
    {
        if (config == null) throw new ArgumentNullException(nameof(config));
        if (requestBodies == null) throw new ArgumentNullException(nameof(requestBodies));

        var tasks = new List<Task<BatchedRequestResponse>>();
        foreach (var requestBody in requestBodies)
        {
            var task = ProcessSingleRequestAsync(config, requestBody);
            tasks.Add(task);
        }

        try
        {
            var results = await Task.WhenAll(tasks);
            if (postProcessCallback != null)
                postProcessCallback(results);

            return results;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while processing batched requests.");
            throw;
        }
    }

    private async Task<BatchedRequestResponse> ProcessSingleRequestAsync(ApiClientConfig config, string requestBody)
    {
        var endpoint = SelectEndpoint(config.Endpoints, requestBody);
        if (endpoint == null)
        {
            _logger.LogError("No matching endpoint found for request body.");
            return new BatchedRequestResponse { Endpoint = "", Error = new InvalidOperationException("No matching endpoint found.") };
        }

        using var content = new StringContent(requestBody, System.Text.Encoding.UTF8, "application/json");
        foreach (var header in config.Headers)
        {
            content.Headers.Add(header.Key, header.Value);
        }

        try
        {
            var response = await _httpClient.PostAsync(endpoint, content);
            response.EnsureSuccessStatusCode();

            var responseBody = await response.Content.ReadAsStringAsync();
            if (!JsonDocument.Parse(responseBody).Validate(config.Schema))
            {
                _logger.LogError("Response does not match expected schema.");
                return new BatchedRequestResponse { Endpoint = endpoint, Error = new InvalidOperationException("Response schema validation failed.") };
            }

            var result = JsonSerializer.Deserialize<object>(responseBody);
            await _messageBroker.PublishAsync("ApiResponse", new BatchedRequestResponse { Endpoint = endpoint, Response = result });
            return new BatchedRequestResponse { Endpoint = endpoint, Response = result };
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, $"Failed to process request to {endpoint}.");
            await _messageBroker.PublishAsync("ApiError", new BatchedRequestResponse { Endpoint = endpoint, Error = ex });
            return new BatchedRequestResponse { Endpoint = endpoint, Error = ex };
        }
    }

    private string SelectEndpoint(Dictionary<string, string> endpoints, string requestBody)
    {
        // Implement logic to select the appropriate endpoint based on the request body
        // For example, you could use a content-based routing algorithm
        return endpoints.FirstOrDefault(e => e.Key.Contains("default")).Value;
    }
}
