// This code snippet is a high-level overview of how you might approach implementing
// a modular, scalable C library to process binary files containing NFAPI_CRC_INDICATION_PDU_T structures.
// It's intended as a starting point for a detailed implementation.

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_THREADS 10

typedef struct {
    // Define the structure of NFAPI_CRC_INDICATION_PDU_T here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    size_t length;
    int valid;
} PDUChunk;

typedef struct {
    sem_t semaphore;
    PDUChunk buffer[MAX_THREADS];
    int head, tail;
} ThreadSafeBuffer;

void init_buffer(ThreadSafeBuffer *buffer) {
    sem_init(&buffer->semaphore, 0, MAX_THREADS);
    buffer->head = buffer->tail = 0;
}

int enqueue(ThreadSafeBuffer *buffer, PDUChunk item) {
    if ((buffer->tail + 1) % MAX_THREADS == buffer->head) return -1; // Buffer is full
    buffer->buffer[buffer->tail] = item;
    buffer->tail = (buffer->tail + 1) % MAX_THREADS;
    sem_post(&buffer->semaphore);
    return 0;
}

int dequeue(ThreadSafeBuffer *buffer, PDUChunk *item) {
    if (buffer->head == buffer->tail) return -1; // Buffer is empty
    *item = buffer->buffer[buffer->head];
    buffer->head = (buffer->head + 1) % MAX_THREADS;
    sem_wait(&buffer->semaphore);
    return 0;
}

void* process_pdu(void *arg) {
    ThreadSafeBuffer *buffer = (ThreadSafeBuffer*)arg;
    PDUChunk item;

    while (1) {
        if (dequeue(buffer, &item) == 0 && item.valid) {
            // Process the PDU data here
            printf("Processing PDU\n");
        }
    }

    return NULL;
}

int main() {
    ThreadSafeBuffer buffer;
    pthread_t threads[MAX_THREADS];

    init_buffer(&buffer);

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, process_pdu, &buffer);
    }

    // Simulate adding PDU data to the buffer
    PDUChunk item;
    for (int i = 0; i < 100; i++) {
        item.data = (NFAPI_CRC_INDICATION_PDU_T){};
        item.length = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        item.valid = (i % 2 == 0) ? 1 : 0;
        enqueue(&buffer, item);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

