        _transactionManager = transactionManager;
        _queryCache = queryCache;
    }

    public async Task<DbDataReader> ExecuteParameterizedQueryAsync(string sql, object parameters, Func<DbDataReader, Task> callback = null)
    {
        var connectionString = await GetConnectionStringFromPool();
        using (var connection = new SqlConnection(connectionString))
        {
            await connection.OpenAsync();

            if (_transactionManager.IsTransactionActive())
            {
                connection.EnlistTransaction(_transactionManager.GetCurrentTransaction());
            }

            var command = connection.CreateCommand();
            command.CommandText = sql;
            AddParameters(command, parameters);

            var cachedQuery = _queryCache.GetCachedQuery(sql);
            if (cachedQuery != null)
            {
                command.CommandText = cachedQuery.QueryText;
            }

            using (var reader = await command.ExecuteReaderAsync())
            {
                if (_queryCache.IsQueryStale(cachedQuery))
                {
                    _queryCache.CacheQuery(command.CommandText, reader);
                }

                if (callback != null)
                {
                    await callback(reader);
                }
            }

            return reader;
        }
