// C++ Code Block for Log Processing System

#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <queue>
#include <condition_variable>

class OAuthLogProcessor {
private:
    std::vector<std::string> inputDirectories;
    std::mutex directoryMutex;
    std::condition_variable directoryCV;
    std::queue<std::string> logQueue;
    std::mutex queueMutex;
    std::condition_variable queueCV;

public:
    void addInputDirectory(const std::string& dir) {
        std::lock_guard<std::mutex> lock(directoryMutex);
        inputDirectories.push_back(dir);
        directoryCV.notify_all();
    }

    void removeInputDirectory(const std::string& dir) {
        std::lock_guard<std::mutex> lock(directoryMutex);
        inputDirectories.erase(std::remove(inputDirectories.begin(), inputDirectories.end(), dir), inputDirectories.end());
        directoryCV.notify_all();
    }

    void processLogs() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCV.wait(lock, [this] { return !logQueue.empty(); });
            std::string log = logQueue.front();
            logQueue.pop();
            lock.unlock();

            // Process the log
            std::cout << "Processing log: " << log << std::endl;
        }
    }

    void startProcessing() {
        std::thread consumer(&OAuthLogProcessor::processLogs, this);
        consumer.detach();
    }
};

// Java Code Block for OAuth2 Access Token Management Microservice

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;

@SpringBootApplication
public class OAuthTokenManager {

    private static final BlockingQueue<String> logQueue = new LinkedBlockingQueue<>();
    private static final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    @RestController
    public static class LogController {

        @PostMapping("/logs")
        public String addLog(@RequestBody String log) {
            logQueue.add(log);
            return "Log added";
        }
    }

    public static void processLogs() {
        while (true) {
            try {
                String log = logQueue.take();
                // Process the log
                System.out.println("Processing log: " + log);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    public static void main(String[] args) {
        SpringApplication.run(OAuthTokenManager.class, args);

        for (int i = 0; i < Runtime.getRuntime().availableProcessors(); i++) {
            executorService.submit(OAuthTokenManager::processLogs);
        }
    }
}
