package main

import (
	"context"
	"fmt"
	"net/http"
	"sync"

	"github.com/gorilla/mux"
	"go.etcd.io/etcd/clientv3"
)

type File struct {
	ID     string
	Name   string
	Data   []byte
	Version int
}

type UserService interface {
	SyncFile(context.Context, *File) error
	GetFileVersion(context.Context, string) (*File, error)
}

type FileService struct {
	client *clientv3.Client
	mu     sync.Mutex
}

func (fs *FileService) SyncFile(ctx context.Context, file *File) error {
	fs.mu.Lock()
	defer fs.mu.Unlock()

	// Simulate etcd key-value store for file data and versioning
	key := fmt.Sprintf("/file/%s", file.ID)
	resp, err := fs.client.Get(ctx, key)
	if err != nil {
		return err
	}

	if resp.Count == 0 {
		_, err = fs.client.Put(ctx, key, fmt.Sprintf("%s-%d", string(file.Data), file.Version))
	} else {
		for _, ev := range resp.Kvs {
			currentVersion, _ := strconv.Atoi(string(bytes.Split(ev.Value, []byte("-"))[1]))
			if currentVersion < file.Version {
				_, err = fs.client.Put(ctx, key, fmt.Sprintf("%s-%d", string(file.Data), file.Version))
				break
			}
		}
	}

	return err
}

func (fs *FileService) GetFileVersion(ctx context.Context, id string) (*File, error) {
	key := fmt.Sprintf("/file/%s", id)
	resp, err := fs.client.Get(ctx, key)
	if err != nil {
		return nil, err
	}

	if resp.Count == 0 {
		return nil, errors.New("file not found")
	}

	data := bytes.Split(resp.Kvs[0].Value, []byte("-"))
	fileData, _ := base64.StdEncoding.DecodeString(string(data[0]))
	version, _ := strconv.Atoi(string(data[1]))

	return &File{ID: id, Data: fileData, Version: version}, nil
}

func main() {
	r := mux.NewRouter()

	fs := &FileService{
		client: etcdClient(), // Initialize etcd client here
	}

	r.HandleFunc("/sync", func(w http.ResponseWriter, r *http.Request) {
		var file File
		if err := json.NewDecoder(r.Body).Decode(&file); err != nil {
			http.Error(w, "Invalid request body", http.StatusBadRequest)
			return
		}
		if err := fs.SyncFile(r.Context(), &file); err != nil {
			http.Error(w, "Failed to sync file", http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusOK)
	}).Methods("POST")

	r.HandleFunc("/get", func(w http.ResponseWriter, r *http.Request) {
		id := mux.Vars(r)["id"]
		file, err := fs.GetFileVersion(r.Context(), id)
		if err != nil {
			http.Error(w, "File not found", http.StatusNotFound)
			return
		}
		json.NewEncoder(w).Encode(file)
	}).Methods("GET")

	http.ListenAndServe(":8080", r)
}
