class GeoLocationService {
public:
    GeoLocationService() : stop(false) {}

    ~GeoLocationService() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (auto& thread : threads) {
            thread.join();
        }
    }

    void start(int numThreads, int idleTimeout) {
        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back([this, idleTimeout]() {
                while (true) {
                    std::unique_lock<std::mutex> lock(mutex);
                    condition.wait(lock, [this]() { return stop || !cache.empty(); });
                    if (stop && cache.empty()) break;
                    auto now = std::chrono::system_clock::now();
                    for (auto it = cache.begin(); it != cache.end();) {
                        if (it->second.expiry < now) {
                            it = cache.erase(it);
                        } else {
                            ++it;
                        }
                    }
                    lock.unlock();
                    // Perform actual geolocation lookup here
                }
            });
        }
    }

private:
    std::unordered_map<std::string, GeoData> cache;
    std::mutex mutex;
    std::condition_variable condition;
    bool stop;
    std::vector<std::thread> threads;

    struct GeoData {
        std::string location;
        std::chrono::system_clock::time_point expiry;
    };
};

int main() {
    GeoLocationService service;
    service.start(4, 60); // Start with 4 threads and an idle timeout of 60 seconds
    // Simulate usage
    return 0;
}
