from typing import Any, Dict, List, Optional, Union

# Define interfaces for data sources, transformers, and sinks
class DataSource(ABC):
    @abstractmethod
    def fetch(self) -> List[Dict]:
        pass

class DataTransformer(ABC):
    @abstractmethod
    def transform(self, data: List[Dict]) -> List[Dict]:
        pass

class DataSink(ABC):
    @abstractmethod
    def load(self, data: List[Dict]) -> None:
        pass

# Implement concrete data source, transformer, and sink classes
class RESTAPIDataSource(DataSource):
    def fetch(self) -> List[Dict]:
        # Implementation to fetch data from a REST API
        pass

