from flask import Flask, request, jsonify
import requests
from cachetools import TTLCache, cached
from threading import Lock
import time

app = Flask(__name__)
cache = TTLCache(maxsize=100, ttl=3600)  # Cache for 1 hour
lock = Lock()

# Example third-party API URLs
WEATHER_API_URL = "https://api.weatherapi.com/v1/current.json"
FORECAST_API_URL = "https://api.weatherapi.com/v1/forecast.json"

def fetch_weather_data(api_url, api_key, location):
    headers = {
        'Content-Type': 'application/json',
        'Authorization': f'Bearer {api_key}'
    }
    response = requests.get(f"{api_url}?key={api_key}&q={location}", headers=headers)
    return response.json()

@app.route('/weather', methods=['GET'])
@cached(cache=cache, key=lambda: request.args['location'])
def get_weather():
    location = request.args.get('location')
    api_key = "your_api_key_here"  # Replace with actual API key

    if not location:
        return jsonify({"error": "Location is required"}), 400

    try:
        weather_data = fetch_weather_data(WEATHER_API_URL, api_key, location)
        forecast_data = fetch_weather_data(FORECAST_API_URL, api_key, location)

        # Combine and format data as needed
        combined_data = {
            "weather": weather_data,
            "forecast": forecast_data
        }

        return jsonify(combined_data), 200
    except requests.RequestException as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True, threaded=True)
