import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.List;

public class SafeSQLExecutor {

    public static void executePreparedStatement(String sql, List<Object> values, Connection connection) {
        try (PreparedStatement preparedStatement = connection.prepareStatement(sql)) {
            for (int i = 0; i < values.size(); i++) {
                preparedStatement.setObject(i + 1, values.get(i));
            }
            preparedStatement.executeUpdate();
        } catch (SQLException e) {
            // Handle the exception appropriately
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        // Example usage
        String sql = "INSERT INTO users (name, email) VALUES (?, ?)";
        List<Object> values = List.of("John Doe", "john.doe@example.com");

        // Assuming you have a valid database connection
        Connection connection = ...; // Obtain the connection

        executePreparedStatement(sql, values, connection);
    }
}
```

