namespace DynamicRESTClient
{
    public class DynamicRESTClient
    {
        private readonly HttpClient _httpClient;
        private readonly ITokenManager _tokenManager;
        private readonly ILogger _logger;
        private readonly IConfigurationService _configurationService;

        public DynamicRESTClient(ITokenManager tokenManager, ILogger logger, IConfigurationService configurationService)
        {
            _httpClient = new HttpClient();
            _tokenManager = tokenManager;
            _logger = logger;
            _configurationService = configurationService;
        }

        public async Task<HttpResponseMessage> GetAsync(string apiVersion, string endpoint, CancellationToken cancellationToken = default)
        {
            try
            {
                var url = GenerateSecureUrl(apiVersion, endpoint);
                var request = new HttpRequestMessage(HttpMethod.Get, url);

                // Add headers and token if required by the API version
                _configurationService.AddHeaders(request.Headers, apiVersion);
                request.Headers.Authorization = await _tokenManager.GetAuthorizationHeaderAsync(apiVersion);

                using (var response = await _httpClient.SendAsync(request, cancellationToken))
                {
                    return response;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error while making GET request to {Endpoint} in version {ApiVersion}", endpoint, apiVersion);
                throw;
            }
        }

        private string GenerateSecureUrl(string apiVersion, string endpoint)
        {
            var baseUrl = _configurationService.GetBaseUrl(apiVersion);
            return $"{baseUrl}/{endpoint}";
        }
    }
}

public interface ITokenManager
{
    Task<AuthenticationHeaderValue> GetAuthorizationHeaderAsync(string apiVersion);
}

public interface ILogger
{
    void LogError(Exception ex, string message, params object[] args);
}

public interface IConfigurationService
{
    void AddHeaders(HttpRequestHeaders headers, string apiVersion);
    string GetBaseUrl(string apiVersion);
}
