# Python Logging Service Implementation

from asyncio import create_task, gather
from aioredis import Redis
import json
import time

class Logger:
    def __init__(self, redis_url):
        self.redis = await Redis.from_url(redis_url)

    async def log(self, message, level):
        await self.redis.publish(f'log:{level}', json.dumps(message))

class LogAggregator:
    def __init__(self, aggregator_url):
        self.aggregator_url = aggregator_url

    async def transmit_logs(self, logs):
        for log in logs:
            response = requests.post(self.aggregator_url, json=log)
            if response.status_code != 200:
                raise Exception(f"Failed to transmit log: {response.text}")

async def process_logs(logger, aggregator):
    while True:
        logs = await logger.redis.xreadgroup('my_group', 'consumer', streams={'log:*': '>'}, count=10)
        if logs:
            tasks = [aggregator.transmit_logs([json.loads(log[1][0][2]) for log in stream]) for stream in logs]
            await gather(*tasks)

# Usage
logger = Logger('redis://localhost:6379')
aggregator = LogAggregator('http://log-aggregator.com/api/log')

create_task(process_logs(logger, aggregator))
