const express = require('express');
const axios = require('axios');
const Redis = require('ioredis');
const RateLimiterRedis = require('rate-limiter-flexible').RateLimiterRedis;
const CircuitBreaker = require('opossum');

const app = express();
const redisClient = new Redis(); // Initialize Redis connection
const rateLimiter = new RateLimiterRedis({
  storeClient: redisClient,
  keyPrefix: 'rl',
  points: 100, // Allow 100 requests per windowMs
  duration: 60 * 1000 // Per minute
});

app.use(express.json());

// Circuit breaker configuration for backend service A
const backendServiceACircuitBreaker = new CircuitBreaker(axios.get, {
  timeout: 3000, // ms
  errorThresholdPercentage: 50,
  resetTimeout: 60000 // ms
});

backendServiceACircuitBreaker.fallback(() => {
  return Promise.reject(new Error('Backend service A is down'));
});

// Middleware to apply rate limiting
app.use(async (req, res, next) => {
  try {
    await rateLimiter.consume(req.ip);
    next();
  } catch () {
    res.status(429).send('Too many requests from this IP');
  }
});

// Route for example backend service A
app.get('/service-a', async (req, res) => {
  try {
    const response = await backendServiceACircuitBreaker.fire(`http://backend-service-a/api`);
    res.status(response.status).json(response.data);
  } catch (error) {
    res.status(error.response ? error.response.status : 500).send(error.message);
  }
});

// Middleware to handle errors gracefully
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`ServiceOrchestrator listening on port ${PORT}`);
});
```

