package com.ecommerce.interactions.service;

import java.util.concurrent.CompletableFuture;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;
import reactor.core.publisher.Flux;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.micrometer.core.instrument.MeterRegistry;

@Service
public class UserInteractionService {

    @Autowired
    private RestTemplate restTemplate;

    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private MeterRegistry meterRegistry;

    public void processUserInteraction(UserInteraction interaction) {
        Flux.fromStream(Flux.just(interaction))
            .flatMap(this::processEvent)
            .subscribe(
                result -> recordSuccess(result),
                error -> handleError(error)
            );
    }

    private CompletableFuture<EventProcessingResult> processEvent(UserInteraction interaction) {
        CompletableFuture<Void> profileUpdateFuture = updateProfile(interaction.getUserProfileId(), interaction.getProfileUpdates());
        CompletableFuture<Void> paymentGatewayFuture = callPaymentGateway(interaction);
        CompletableFuture<Void> marketingPlatformFuture = callMarketingPlatform(interaction);
        CompletableFuture<Void> fraudDetectionFuture = callFraudDetectionService(interaction);

        return profileUpdateFuture.thenCompose(v -> paymentGatewayFuture)
                                 .thenCompose(v -> marketingPlatformFuture)
                                 .thenCompose(v -> fraudDetectionFuture)
                                 .handle((v, ex) -> new EventProcessingResult(ex == null));
    }

    private CompletableFuture<Void> updateProfile(String userProfileId, UserProfile updates) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        return CompletableFuture.runAsync(() -> restTemplate.postForEntity("https://external-data-source.com/profiles/" + userProfileId, updates, Void.class), 
                                          TaskScheduler.defaultTaskScheduler());
    }

    private CompletableFuture<Void> callPaymentGateway(UserInteraction interaction) {
        PaymentRequest request = new PaymentRequest(interaction.getOrderId(), interaction.getAmount());
        return CompletableFuture.runAsync(() -> restTemplate.postForEntity("https://payment-gateway.com/process", request, Void.class), 
                                          TaskScheduler.paymentTaskScheduler());
    }

    private CompletableFuture<Void> callMarketingPlatform(UserInteraction interaction) {
        MarketingRequest request = new MarketingRequest(interaction.getUserId(), interaction.getBehaviorData());
        return CompletableFuture.runAsync(() -> restTemplate.postForEntity("https://marketing-platform.com/track", request, Void.class), 
                                          TaskScheduler.marketingTaskScheduler());
    }

    private CompletableFuture<Void> callFraudDetectionService(UserInteraction interaction) {
        FraudDetectionRequest request = new FraudDetectionRequest(interaction.getOrderId(), interaction.getUserProfileId());
        return CompletableFuture.runAsync(() -> restTemplate.postForEntity("https://fraud-detection.com/check", request, Void.class), 
                                          TaskScheduler.fraudTaskScheduler());
    }

    private void recordSuccess(EventProcessingResult result) {
        if (result.isSuccessful()) {
            meterRegistry.counter("successes").increment();
        } else {
            meterRegistry.counter("failures").increment();
        }
    }

    private void handleError(Throwable error) {
        meterRegistry.counter("errors").increment();
        // Log the error for investigation
    }
}

class UserInteraction {
    private String userId;
    private String orderId;
    private double amount;
    private UserProfile userProfileUpdates;
    private BehaviorData behaviorData;

    // Getters and setters
}

class UserProfile {
