const express = require('express');
const axios = require('axios');
const Redis = require('redis');
const bodyParser = require('body-parser');

const app = express();
app.use(bodyParser.json());
const redisClient = Redis.createClient();

app.get('/menu', async (req, res) => {
  try {
    // Check cache
    const cachedMenu = await redisClient.get('menu');
    if (cachedMenu) {
      return res.status(200).json(JSON.parse(cachedMenu));
    }

    // Fetch menu data from external APIs
    const api1Data = await axios.get('https://api1.example.com/menu');
    const api2Data = await axios.get('https://api2.example.com/menu');

    // Combine and flatten the data
    const menuData = [...api1Data.data, ...api2Data.data];

    // Store in cache for future requests
    await redisClient.set('menu', JSON.stringify(menuData), 'EX', 3600); // Cache for 1 hour

    res.status(200).json(menuData);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch menu data' });
  }
});

app.listen(3000, () => {
  console.log('Menu service is running on port 3000');
});
```

