    services: Vec<Service>,
    dependencies: HashMap<String, String>,
}

impl MicroserviceFramework {
    // Constructor to initialize the framework with services and dependencies
    fn new(services: Vec<Service>, dependencies: HashMap<String, String>) -> Self {
        MicroserviceFramework { services, dependencies }
    }

    // Method to build microservices in parallel across multiple nodes
    async fn build_services(&self) -> Result<(), BuildError> {
        let mut tasks = vec![];
        for service in &self.services {
            tasks.push(self.build_service(service).boxed());
        }

        let results: Vec<Result<(), BuildError>> = futures::future::try_join_all(tasks).await?;
        if results.iter().any(|r| r.is_err()) {
            Err(BuildError::BuildFailed)
        } else {
            Ok(())
        }
    }

    // Private method to build a single service
    async fn build_service(&self, service: &Service) -> Result<(), BuildError> {
        // Resolve dependencies and handle version conflicts
        let resolved_deps = self.resolve_dependencies(service)?;

        // Compile the service using Rust compiler
        compile_service(service, &resolved_deps)?;

        Ok(())
    }

    // Method to resolve dependencies for a service
    fn resolve_dependencies(&self, service: &Service) -> Result<Vec<String>, BuildError> {
        let mut deps = vec![];
        if let Some(dep) = self.dependencies.get(&service.name) {
            deps.push(dep.clone());
