<?php

class UserTransactionService {
    private $authService;
    private $passwordPolicyApi;
    private $transactionDao;
    private $circuitBreaker;
    private $cache;

    public function __construct($authService, $passwordPolicyApi, $transactionDao, $circuitBreaker, $cache) {
        $this->authService = $authService;
        $this->passwordPolicyApi = $passwordPolicyApi;
        $this->transactionDao = $transactionDao;
        $this->circuitBreaker = $circuitBreaker;
        $this->cache = $cache;
    }

    public function changePassword($userId, $newPassword) {
        $this->circuitBreaker->check('password_policy_api');

        $policy = $this->cache->get('password_policy');
        if (!$policy) {
            $policy = $this->passwordPolicyApi->getPolicy();
            $this->cache->set('password_policy', $policy, 86400); // Cache for 24 hours
        }

        if ($this->isValidPassword($newPassword, $policy)) {
            $this->authService->changePassword($userId, $newPassword);
        } else {
            throw new Exception('Invalid password');
        }
    }

    private function isValidPassword($password, $policy) {
        // Check password against policy
        return preg_match('/' . $policy['regex'] . '/', $password) && strlen($password) >= $policy['min_length'];
    }

    public function processTransaction($userId, $amount) {
        $this->circuitBreaker->check('financial_service_api');

        try {
            $this->authService->authorize($userId);
            $this->transactionDao->saveTransaction($userId, $amount);
        } catch (Exception $e) {
            $this->handleRetryLogic($e);
        }
    }

    private function handleRetryLogic(Exception $e) {
        // Implement retry logic
        if ($e instanceof TransientFailureException) {
            sleep(1); // Wait before retrying
            $this->processTransaction($userId, $amount);
        } else {
            throw $e;
        }
    }

    public function getAggregatedTransactions($userId) {
        return $this->transactionDao->getAggregateTransactions($userId);
    }
}
