    @Autowired
    public TransactionProcessor(TransactionRepository transactionRepository,
                                FraudDetectionService fraudDetectionService,
                                BalanceCalculator balanceCalculator) {
        this.transactionRepository = transactionRepository;
        this.fraudDetectionService = fraudDetectionService;
        this.balanceCalculator = balanceCalculator;
    }

    public void processTransaction(Transaction transaction) {
        // Log transaction details
        System.out.println("Processing transaction: " + transaction.getTransactionId());

        // Save transaction to database
        transactionRepository.save(transaction);

        // Calculate cumulative balance
        double userBalance = balanceCalculator.calculateBalanceForUser(transaction.getUserId());
        System.out.println("User Balance for " + transaction.getUserId() + ": " + userBalance);

        // Detect fraud
