import org.apache.avro.io.DatumReader;
import org.apache.avro.specific.SpecificDatumReader;
import org.json.JSONObject;

public class MessageProcessingPipeline {

    private final KafkaConsumer<String, byte[]> kafkaConsumer;
    private final ExecutorService consumerPool;
    private final BlockingQueue<Message> messageQueue;
    private final ConcurrentHashMap<String, Integer> messageCount;

    public MessageProcessingPipeline(String bootstrapServers) {
        this.kafkaConsumer = new KafkaConsumer<>(createConsumerProps(bootstrapServers));
        this.consumerPool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.messageQueue = new ArrayBlockingQueue<>(1000);
        this.messageCount = new ConcurrentHashMap<>();
    }

    private java.util.Properties createConsumerProps(String bootstrapServers) {
        java.util.Properties props = new java.util.Properties();
        props.put("bootstrap.servers", bootstrapServers);
        props.put("group.id", "message-processing-group");
        props.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        props.put("value.deserializer", "org.apache.kafka.common.serialization.ByteArrayDeserializer");
        return props;
    }

    public void start() {
        kafkaConsumer.subscribe(Arrays.asList("topic1", "topic2"));
        consumerPool.submit(() -> listenForMessages());
        consumerPool.submit(() -> processMessages());
    }

    private void listenForMessages() {
        while (true) {
            for (ConsumerRecord<String, byte[]> record : kafkaConsumer.poll(Duration.ofMillis(100))) {
                try {
                    switch (record.value()[0]) {
                        case 'J':
                            handleJSON(record);
                            break;
                        case 'A':
                            handleAvro(record);
                            break;
                        case 'P':
                            handleProtocolBuffers(record);
                            break;
                        case 'X':
                            handleCustomFormat(record);
                            break;
                    }
                } catch (Exception e) {
                    logError(e, record);
                }
            }
        }
    }

    private void processMessages() {
        while (true) {
            try {
                Message message = messageQueue.take();
                if (message != null) {
                    processMessage(message);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void handleJSON(ConsumerRecord<String, byte[]> record) {
        JSONObject json = new JSONObject(new String(record.value()));
        // Process JSON message
    }

    private void handleAvro(ConsumerRecord<String, byte[]> record) {
        DatumReader<AvroMessage> reader = new SpecificDatumReader<>(AvroMessage.class);
        AvroMessage avroMessage = reader.read(null, DecoderFactory.get().binaryDecoder(record.value(), null));
        // Process Avro message
    }

    private void handleProtocolBuffers(ConsumerRecord<String, byte[]> record) {
        ProtocolBuffersMessage message = ProtocolBuffersMessage.parseFrom(record.value());
        // Process Protocol Buffers message
    }

    private void handleCustomFormat(ConsumerRecord<String, byte[]> record) {
        CustomBinaryMessage customMessage = new CustomBinaryMessage(record.value());
        // Process custom binary message
    }

    private void processMessage(Message message) {
        try {
            switch (message.getType()) {
                case JSON:
                    handleJSONMessage(message);
                    break;
                case AVRO:
                    handleAvroMessage(message);
                    break;
                case PROTOBUF:
                    handleProtocolBuffersMessage(message);
                    break;
                case CUSTOM:
                    handleCustomBinaryMessage(message);
                    break;
            }
        } catch (Exception e) {
            logError(e, message);
        }
    }

    private void handleJSONMessage(Message message) {
        // Process JSON message
    }

    private void handleAvroMessage(Message message) {
        // Process Avro message
    }

    private void handleProtocolBuffersMessage(Message message) {
        // Process Protocol Buffers message
    }

    private void handleCustomBinaryMessage(Message message) {
        // Process custom binary message
    }

    private void logError(Exception e, Object source) {
        System.err.println("Error processing " + source.getClass().getSimpleName() + ": " + e.getMessage());
        e.printStackTrace();
    }
}

class Message {
    private final String type;
    private final byte[] data;

    public Message(String type, byte[] data) {
        this.type = type;
        this.data = data;
    }

    public String getType() {
