    private readonly IServiceProvider _serviceProvider;

    public MicroserviceDeployer(IServiceProvider serviceProvider)
    {
        _serviceProvider = serviceProvider;
    }

    public void DeployService()
    {
        // Resolve dependencies dynamically
        var dependencyResolver = _serviceProvider.GetService<IDependencyResolver>();
        var resourceAllocator = _serviceProvider.GetService<IResourceAllocator>();
        var deploymentManager = _serviceProvider.GetService<IDeploymentManager>();
        var monitoringClient = _serviceProvider.GetService<IMonitoringClient>();

        try
        {
            // Resolve and provision dependencies
            dependencyResolver.ResolveDependencies();

            // Allocate resources based on current load
            resourceAllocator.AllocateResources();

            // Deploy service using Docker containers
            deploymentManager.DeployService();

            // Monitor and log service performance
            monitoringClient.StartMonitoring();
        }
        catch (Exception ex)
        {
            // Handle exceptions gracefully with rollback strategies
            Console.WriteLine($"Deployment failed: {ex.Message}");
            deploymentManager.RollbackPreviousVersion();
        }
    }
}

