#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_THREADS 10

typedef struct {
    char* token;
    int* result;
} TokenValidationTask;

void* validate_oauth_token(void* arg) {
    TokenValidationTask* task = (TokenValidationTask*)arg;
    CURL *curl;
    CURLcode res;
    long response_code;
    char error_buffer[CURL_ERROR_SIZE];

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/validate_token");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, task->token);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);
        curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, error_buffer);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", error_buffer);
            *task->result = -1;
        } else {
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if(response_code == 200) {
                *task->result = 0;
            } else {
                fprintf(stderr, "Validation failed with response code: %ld\n", response_code);
                *task->result = -1;
            }
        }

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    free(task->token);
    free(task);

    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    TokenValidationTask tasks[MAX_THREADS];
    int results[MAX_THREADS];

    for(int i = 0; i < MAX_THREADS; i++) {
        tasks[i].result = &results[i];
        tasks[i].token = strdup("your_access_token_here");

        if(pthread_create(&threads[i], NULL, validate_oauth_token, &tasks[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return 1;
        }
    }

    for(int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
        printf("Validation result %d: %s\n", i, results[i] == 0 ? "Success" : "Failure");
    }

    return 0;
}
