using System;
using System.Data;
using System.Data.Common;
using System.Net.Security;
using System.Security.Authentication;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class AsyncDatabaseService : IAsyncDatabaseService
{
    private readonly DbProviderFactory _dbProviderFactory;
    private readonly string _connectionString;
    private readonly ILogger<AsyncDatabaseService> _logger;
    private readonly MemoryCache _cache;

    public AsyncDatabaseService(DbProviderFactory dbProviderFactory, string connectionString, ILogger<AsyncDatabaseService> logger)
    {
        _dbProviderFactory = dbProviderFactory;
        _connectionString = connectionString;
        _logger = logger;
        _cache = new MemoryCache(new MemoryCacheOptions());
    }

    public async Task<IDataReader> ExecuteQueryAsync(string query, object parameters)
    {
        var cacheKey = $"query:{query}";
        if (_cache.TryGetValue(cacheKey, out IDataReader cachedResult))
        {
            return cachedResult;
        }

        using (var connection = _dbProviderFactory.CreateConnection())
        {
            connection.ConnectionString = _connectionString;
            await connection.OpenAsync();

            using (var command = connection.CreateCommand())
            {
                command.CommandText = query;
                command.Parameters.AddRange(_dbProviderFactory.CreateParameter().CreateParameters(command, parameters));
                command.CommandTimeout = 30;

                var reader = await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
                _cache.Set(cacheKey, reader, new MemoryCacheEntryOptions
                {
                    AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)
                });

                return reader;
            }
        }
    }

    public async Task<int> ExecuteNonQueryAsync(string query, object parameters)
    {
        using (var connection = _dbProviderFactory.CreateConnection())
        {
            connection.ConnectionString = _connectionString;
            await connection.OpenAsync();

            using (var command = connection.CreateCommand())
            {
                command.CommandText = query;
                command.Parameters.AddRange(_dbProviderFactory.CreateParameter().CreateParameters(command, parameters));
                return await command.ExecuteNonQueryAsync();
            }
        }
    }

    public async Task<object> ExecuteScalarAsync(string query, object parameters)
    {
        using (var connection = _dbProviderFactory.CreateConnection())
        {
            connection.ConnectionString = _connectionString;
            await connection.OpenAsync();

            using (var command = connection.CreateCommand())
            {
                command.CommandText = query;
                command.Parameters.AddRange(_dbProviderFactory.CreateParameter().CreateParameters(command, parameters));
                return await command.ExecuteScalarAsync();
            }
        }
    }

    public async Task<int> ExecuteBatchAsync(IEnumerable<string> queries, object[] parameters)
    {
        using (var connection = _dbProviderFactory.CreateConnection())
        {
            connection.ConnectionString = _connectionString;
            await connection.OpenAsync();

            using (var transaction = connection.BeginTransaction())
            {
                try
                {
                    var batchCount = 0;
                    foreach (var query in queries)
                    {
                        using (var command = connection.CreateCommand())
                        {
                            command.CommandText = query;
                            command.Transaction = transaction;
                            command.Parameters.AddRange(_dbProviderFactory.CreateParameter().CreateParameters(command, parameters[batchCount]));
                            await command.ExecuteNonQueryAsync();
                            batchCount++;
                        }
                    }

                    transaction.Commit();
                    return batchCount;
                }
                catch
                {
                    transaction.Rollback();
                    throw;
                }
            }
        }
    }
}
