    def upload_file(self, file_path, storage_system):
        if storage_system == 'S3':
            return S3Storage().upload(file_path)
        elif storage_system == 'GCS':
            return GCSStorage().upload(file_path)
        elif storage_system == 'Azure Blob Storage':
            return AzureBlobStorage().upload(file_path)
        else:
            raise ValueError("Unsupported storage system")

    def download_file(self, file_path, storage_system):
        if storage_system == 'S3':
            return S3Storage().download(file_path)
        elif storage_system == 'GCS':
            return GCSStorage().download(file_path)
        elif storage_system == 'Azure Blob Storage':
            return AzureBlobStorage().download(file_path)
        else:
            raise ValueError("Unsupported storage system")

