    def download(self, file_path):
        pass

class GCSStorage(ABC):
    @abstractmethod
    def upload(self, file_path):
        pass

    @abstractmethod
    def download(self, file_path):
        pass

class AzureBlobStorage(ABC):
    @abstractmethod
    def upload(self, file_path):
        pass

    @abstractmethod
    def download(self, file_path):
        pass

