import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.util.concurrent.ConcurrentHashMap;

public class SerializationService {

    private static final ConcurrentHashMap<String, Class<?>> CLASS_CACHE = new ConcurrentHashMap<>();

    public Object deserialize(byte[] byteArray) throws SerializationException {
        ByteArrayInputStream bais = new ByteArrayInputStream(byteArray);
        try (ObjectInputStream ois = new ObjectInputStream(bais)) {
            Object obj = ois.readObject();
            if (!(obj instanceof MyInterface)) {
                throw new SerializationException("Deserialized object does not implement MyInterface");
            }
            return obj;
        } catch (ClassNotFoundException e) {
            throw new SerializationException("Class not found during deserialization: " + e.getMessage(), e);
        } catch (InvalidClassException e) {
            throw new SerializationException("Incompatible version during deserialization: " + e.getMessage(), e);
        } catch (IOException e) {
            throw new SerializationException("IO error during deserialization: " + e.getMessage(), e);
        }
    }

    private Class<?> loadClass(String className) throws ClassNotFoundException, SerializationException {
        return CLASS_CACHE.computeIfAbsent(className, k -> {
            try {
                return Class.forName(k);
            } catch (ClassNotFoundException e) {
                throw new SerializationException("Failed to load class: " + k, e);
            }
        });
    }

    public static void main(String[] args) {
        // Example usage
        byte[] serializedData = ...; // Obtain serialized data
        try {
            Object deserializedObject = SerializationService.deserialize(serializedData);
            System.out.println("Deserialized object: " + deserializedObject);
        } catch (SerializationException e) {
            System.err.println("Error during deserialization: " + e.getMessage());
        }
    }
}
