# Service Discovery and Circuit Breaker using Flask and Resilience4j

from flask import Flask, jsonify
from resilience4j.circuitbreaker import CircuitBreaker, CircuitBreakerConfig, CircuitBreakerRegistry
from time import sleep
import requests

app = Flask(__name__)
registry = CircuitBreakerRegistry()

def remote_service():
    # Simulate a remote service that can fail
    response = requests.get("http://example.com/api/data")
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception("Failed to fetch data")

circuitbreaker_config = CircuitBreakerConfig(
    failure_rate_threshold=50,
    minimum_number_of_calls=10,
    wait_duration_in_open_state=60
)

circuitbreaker = CircuitBreaker(registry, circuitbreaker_config)

@app.route('/data')
def get_data():
    try:
        result = circuitbreaker.execute(remote_service)
        return jsonify(result)
    except Exception as e:
        return jsonify({"error": str(e)}), 503

