async fn deploy_to_kubernetes(config: DeploymentConfig, client: Client) -> Result<(), Box<dyn Error>> {
    // Implement logic to deploy the containerized application to Kubernetes
    let deployments = Api::<kube::api::Deployment>::namespaced(client.clone(), "default");
    let post_params = PostParams::default();
    deployments.create(&post_params, &config).await?;
    Ok(())
}

async fn main() -> Result<(), Box<dyn Error>> {
    // Initialize the Kubernetes client
    let kube_client = Client::try_default().await?;

    // Define a channel for deployment requests
    let (tx, mut rx) = mpsc::channel(32);

    // Spawn a task to handle incoming deployment requests
    tokio::spawn(async move {
        while let Some(config) = rx.recv().await {
            if let Err(e) = deploy_to_kubernetes(config, kube_client.clone()).await {
                eprintln!("Failed to deploy: {}", e);
            }
        }
    });

    // Simulate fetching and sending deployment requests
    let config1 = DeploymentConfig {
        name: "app1".to_string(),
        replicas: 2,
        image: "image1:latest".to_string(),
    };
    tx.send(config1).await?;

    let config2 = DeploymentConfig {
        name: "app2".to_string(),
        replicas: 3,
        image: "image2:latest".to_string(),
    };
    tx.send(config2).await?;

    Ok(())
}
