#include <iostream>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <functional>

// Define a simple cache entry with TTL
struct CacheEntry {
    std::string data;
    std::time_t expirationTime;
};

class GeolocationCache {
private:
    std::unordered_map<std::string, CacheEntry> cache;
    std::mutex mutex;
    std::condition_variable cv;
    int maxCapacity;

public:
    GeolocationCache(int capacity) : maxCapacity(capacity) {}

    // Add or update an entry in the cache
    void put(const std::string& key, const std::string& data, std::time_t ttl) {
        std::unique_lock<std::mutex> lock(mutex);
        if (cache.size() >= maxCapacity) {
            evict();
        }
        cache[key] = {data, std::time(nullptr) + ttl};
    }

    // Retrieve an entry from the cache
    std::string get(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it != cache.end() && std::time(nullptr) < it->second.expirationTime) {
            return it->second.data;
        }
        return "";
    }

    // Evict expired entries
    void evict() {
        std::unique_lock<std::mutex> lock(mutex);
        auto now = std::time(nullptr);
        for (auto it = cache.begin(); it != cache.end();) {
            if (it->second.expirationTime <= now) {
                it = cache.erase(it);
            } else {
                ++it;
            }
        }
    }

    // Background task to periodically evict expired entries
    void startEvictionThread() {
        std::thread([this]() {
            while (true) {
                cv.wait_for(std::unique_lock<std::mutex>(mutex), std::chrono::seconds(60), [this] { return false; });
                evict();
            }
        }).detach();
    }
};

int main() {
    GeolocationCache cache(100);
    cache.startEvictionThread();

    // Example usage
    cache.put("location1", "New York", 3600);
    std::cout << "Location Data: " << cache.get("location1") << std::endl;

    return 0;
}
```

This code snippet provides a basic implementation of a geolocation services cache in C++. It includes a simple cache entry structure, a `GeolocationCache` class with methods to put and get entries, an eviction method to remove expired entries, and a background thread to periodically evict expired entries. This is just a starting point, and further enhancements are needed to meet the requirements of the task.']

