public class DatabaseExecutor
{
    private readonly IDbConnection _connectionPool;

    public DatabaseExecutor(IDbConnection connectionPool)
    {
        _connectionPool = connectionPool;
    }

    public async Task ExecuteParameterizedQueryAsync(string sql, Dictionary<string, object> parameters)
    {
        using (var command = _connectionPool.CreateCommand())
        {
            command.CommandText = sql;
            foreach (var parameter in parameters)
            {
                var dbParameter = command.CreateParameter();
                dbParameter.ParameterName = parameter.Key;
                dbParameter.Value = parameter.Value;
                command.Parameters.Add(dbParameter);
            }

            await command.ExecuteNonQueryAsync();
        }
    }
}
