    reports->reports = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    reports->count = 0;
    pthread_mutex_init(&reports->lock, NULL);
}

void add_report(UplinkCRCIndicationReports *reports, NFAPI_CRC_INDICATION_PDU_T *report) {
    pthread_mutex_lock(&reports->lock);
    if (reports->count >= capacity) {
        reports->reports = realloc(reports->reports, 2 * capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        capacity *= 2;
    }
    memcpy(&reports->reports[reports->count], report, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    reports->count++;
    pthread_mutex_unlock(&reports->lock);
}

void free_reports(UplinkCRCIndicationReports *reports) {
    pthread_mutex_lock(&reports->lock);
    free(reports->reports);
    pthread_mutex_destroy(&reports->lock);
}

