// Java code for distributed, fault-tolerant cache system
import java.util.concurrent.*;
import javax.cache.Cache;
import javax.cache.Caching;
import javax.cache.configuration.MutableConfiguration;
import javax.cache.expiry.CreatedExpiryPolicy;

public class DistributedCacheSystem {
    private Cache<String, String> cache;

    public DistributedCacheSystem() {
        MutableConfiguration<String, String> config = new MutableConfiguration<>();
        config.setTypes(String.class, String.class);
        config.setStoreByValue(false);
        config.setExpiryPolicyFactory(CreatedExpiryPolicy.factoryOf(Duration.ONE_MINUTE));

        this.cache = Caching.getCachingProvider().getCacheManager()
            .createCache("distributedCache", config);
    }

    public void put(String key, String value) {
        cache.put(key, value);
    }

    public String get(String key) {
        return cache.get(key);
    }

    public void evict(String key) {
        cache.remove(key);
    }
}
