public class BatchRequestProcessor
{
    private readonly List<string> _apiEndpoints;
    private readonly Dictionary<string, string> _requestHeaders;
    private readonly Dictionary<string, string> _expectedResponseFormats;
    private readonly Dictionary<string, AuthenticationDetails> _authDetails;
    private readonly List<HttpRequestBody> _requestBodies;
    private readonly ILogger _logger;
    private readonly IBus _bus;

    public BatchRequestProcessor(List<string> apiEndpoints, 
                                Dictionary<string, string> requestHeaders, 
                                Dictionary<string, string> expectedResponseFormats,
                                Dictionary<string, AuthenticationDetails> authDetails,
                                List<HttpRequestBody> requestBodies,
                                ILogger logger,
                                IBus bus)
    {
        _apiEndpoints = apiEndpoints;
        _requestHeaders = requestHeaders;
        _expectedResponseFormats = expectedResponseFormats;
        _authDetails = authDetails;
        _requestBodies = requestBodies;
        _logger = logger;
        _bus = bus;

        ValidateConfigurations();
    }

    private void ValidateConfigurations()
    {
        // Validation logic here
    }

    public async Task ProcessBatchAsync()
    {
        using (var tracer = TraceOptions.Default.CreateSpan("ProcessBatch"))
        {
            try
            {
                foreach (var requestBody in _requestBodies)
                {
                    var response = await SendRequestAsync(requestBody);
                    await HandleResponseAsync(response, tracer.SpanName);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing batch");
                await _bus.Publish(new BatchProcessingFailedEvent());
            }
        }
    }

    private async Task<HttpResponseMessage> SendRequestAsync(HttpRequestBody requestBody)
    {
        using (var client = new HttpClient())
        {
            SetClientHeaders(client);
            client.Timeout = TimeSpan.FromSeconds(30);

            try
            {
                var response = await client.PostAsJsonAsync(_apiEndpoints[requestBody.ApiIndex], requestBody.Body, cancellationToken: CancellationToken.None);
                return response;
            }
            catch (TaskCanceledException)
            {
                _logger.LogWarning("Request timed out");
                throw; // Rethrow for retry logic
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Network error");
                throw; // Rethrow for retry logic
            }
        }
    }

    private void SetClientHeaders(HttpClient client)
    {
        foreach (var header in _requestHeaders)
        {
            client.DefaultRequestHeaders.Add(header.Key, header.Value);
        }
    }

    private async Task HandleResponseAsync(HttpResponseMessage response, string parentSpanName)
    {
        using (var childSpan = TraceOptions.Default.CreateChildSpan(parentSpanName))
        {
            if (!response.IsSuccessStatusCode)
            {
                _logger.LogError($"API call failed with status code: {response.StatusCode}");
            }

            // Process response logic here
        }
    }
}

