class NFAPICRCProcessor {
private:
    std::queue<NFAPI_CRC_INDICATION_PDU_T> queue;
    std::mutex mutex;
    std::condition_variable cv;
    bool stop = false;

public:
    void push(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(mutex);
        queue.push(pdu);
        cv.notify_one();
    }

    void start(int numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            std::thread([this]() {
                while (true) {
                    NFAPI_CRC_INDICATION_PDU_T pdu;
                    {
                        std::unique_lock<std::mutex> lock(mutex);
                        cv.wait(lock, [this] { return !queue.empty() || stop; });
                        if (stop && queue.empty()) break;
                        pdu = queue.front();
                        queue.pop();
                    }
                    process(pdu); // Implement processing logic here
                }
            }).detach();
        }
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();
    }

private:
    void process(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        // Implement processing logic here
    }
};

