using System;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;

public class QueryExecutionService
{
    private readonly ILogger _logger;

    public QueryExecutionService(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task ExecuteParameterizedQueryAsync(
        string connectionString,
        string sqlCommandString,
        List<SqlParameter> parameters,
        Action<IDataReader>? postExecutionCallback = null)
    {
        try
        {
            // Validate connection string
            using (var connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();
                if (!connection.State.HasFlag(ConnectionState.Open))
                {
                    throw new InvalidOperationException("Invalid or inactive database connection.");
                }
            }

            // Validate SQL command string and parameters
            var commandBuilder = new SqlCommandBuilder();
            var command = commandBuilder.GetInsertCommand();
            command.CommandText = sqlCommandString;
            foreach (var param in parameters)
            {
                if (!command.Parameters.Contains(param.ParameterName))
                    command.Parameters.Add(param);
            }

            // Execute query asynchronously
            using (var connection = new SqlConnection(connectionString))
            {
                await connection.OpenAsync();
                using (var command = connection.CreateCommand())
                {
                    command.CommandText = sqlCommandString;
                    command.CommandType = CommandType.Text;
                    command.Parameters.AddRange(parameters.ToArray());

                    if (command.CommandType == CommandType.Text)
                    {
                        var dataAdapter = new SqlDataAdapter(command);
                        var dataSet = new DataSet();
                        await Task.Run(() => dataAdapter.FillAsync(dataSet));
                        postExecutionCallback?.Invoke(dataSet.Tables[0].CreateDataReader());
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error executing parameterized query.");
            throw new InvalidOperationException("Failed to execute the SQL command.", ex);
        }
    }
}
