import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class DistributedCacheManager {
    private final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public void put(String key, Object value) {
        cache.put(key, new CacheEntry(value));
    }

    public Object get(String key) {
        CacheEntry entry = cache.get(key);
        if (entry != null && !entry.isExpired()) {
            entry.updateAccessTime();
            return entry.getValue();
        }
        return null;
    }

    public void startEvictionScheduler() {
        scheduler.scheduleAtFixedRate(this::evictEntries, 1, 1, TimeUnit.MINUTES);
    }

    private void evictEntries() {
        cache.values().removeIf(entry -> entry.isExpired());
    }

    private static class CacheEntry {
        private final Object value;
        private long lastAccessTime;

        public CacheEntry(Object value) {
            this.value = value;
            this.lastAccessTime = System.currentTimeMillis();
        }

        public Object getValue() {
            return value;
        }

        public boolean isExpired() {
            // Implement TTL logic here
            return false;
        }

        public void updateAccessTime() {
            lastAccessTime = System.currentTimeMillis();
        }
    }

    public static void main(String[] args) {
        DistributedCacheManager cacheManager = new DistributedCacheManager();
        cacheManager.startEvictionScheduler();

        // Example usage
        cacheManager.put("key1", "value1");
        System.out.println(cacheManager.get("key1"));
    }
}
