#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

#define MAX_CONNECTIONS 10000

typedef enum {
    TCP,
    UDP
} ProtocolType;

typedef struct ConnectionMetadata {
    char ip[16];
    int port;
    ProtocolType protocol;
} ConnectionMetadata;

typedef struct Connection {
    ConnectionMetadata metadata;
    pthread_mutex_t lock;
} Connection;

Connection connections[MAX_CONNECTIONS];
pthread_mutex_t pool_lock;
int connection_count = 0;
int max_connections = MAX_CONNECTIONS;

void init_connection_pool(int max_conn) {
    max_connections = max_conn;
    pthread_mutex_init(&pool_lock, NULL);
    for (int i = 0; i < max_connections; i++) {
        pthread_mutex_init(&connections[i].lock, NULL);
    }
}

Connection* get_connection() {
    Connection *conn = NULL;
    pthread_mutex_lock(&pool_lock);
    if (connection_count > 0) {
        conn = &connections[--connection_count];
        pthread_mutex_unlock(&pool_lock);
    } else {
        pthread_mutex_unlock(&pool_lock);
        // Logic to acquire a new connection from external service or wait
        // For simplicity, returning NULL for now
        return NULL;
    }
    return conn;
}

void release_connection(Connection *conn) {
    pthread_mutex_lock(&pool_lock);
    if (connection_count < max_connections) {
        connections[connection_count++] = *conn;
    } else {
        // Logic to close the connection or handle overflow
        printf("Connection pool is full. Dropping connection.\n");
    }
    pthread_mutex_unlock(&pool_lock);
}

void update_connection_metadata(Connection *conn, const ConnectionMetadata *new_meta) {
    pthread_mutex_lock(&conn->lock);
    strcpy(conn->metadata.ip, new_meta->ip);
    conn->metadata.port = new_meta->port;
    conn->metadata.protocol = new_meta->protocol;
    pthread_mutex_unlock(&conn->lock);
}

// Example usage
int main() {
    init_connection_pool(10000);

    ConnectionMetadata metadata = {"192.168.1.1", 80, TCP};
    Connection *conn = get_connection();
    if (conn != NULL) {
        update_connection_metadata(conn, &metadata);
        // Use the connection for network operations
        release_connection(conn);
    }

    return 0;
}
