        std::lock_guard<std::mutex> lock(queueMutex);
        queue.push(msg);
        notEmpty.notify_one();
    }

    Message pop() {
        std::unique_lock<std::mutex> lock(queueMutex);
        notEmpty.wait(lock, [this] { return !queue.empty(); });
