const app = express();
app.use(bodyParser.json());

// Redis client setup
const redisClient = redis.createClient({
  url: 'redis://localhost:6379'
});

redisClient.on('error', (err) => {
  console.error('Redis error:', err);
});

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

app.use(limiter);

// Example payment processing endpoint
app.post('/process-payment', async (req, res) => {
  const { amount, currency, cardNumber } = req.body;

  try {
    // Validate input
    if (!amount || !currency || !cardNumber) {
      return res.status(400).json({ error: 'Invalid payment details' });
    }

    // Check for existing transaction with optimistic locking
    const transactionId = await redisClient.get(cardNumber);
    if (transactionId && transactionId !== req.headers['x-transaction-id']) {
      return res.status(429).json({ error: 'Too many requests' });
    }

    // Simulate payment processing with external API
    const response = await axios.post('https://api.example.com/payments', {
      amount,
      currency,
      cardNumber
    });

    if (response.data.success) {
      // Store transaction in Redis for optimistic locking
      await redisClient.set(cardNumber, req.headers['x-transaction-id']);

      // Simulate settlement and reconciliation
      await axios.post('https://api.example.com/settlement', {
        transactionId: response.data.transactionId,
        amount,
        currency
      });

      return res.status(200).json({ message: 'Payment processed successfully' });
    } else {
      return res.status(response.data.code || 500).json({ error: response.data.message });
    }
  } catch (error) {
    console.error('Error processing payment:', error);
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.stack);
  res.status(err.status || 500).json({ error: err.message });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`PaymentProcessor service listening on port ${PORT}`);
});
