typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[AES_GCM_TAG_LEN];
} aes_gcm_context;

int load_config(const char *filename, json_object **config) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return -1;

    char buffer[1024];
    size_t len = fread(buffer, 1, sizeof(buffer), fp);
    fclose(fp);

    *config = json_tokener_parse(buffer);
    if (!*config || json_object_get_type(*config) != JSON_OBJECT) {
        json_object_put(*config);
        return -1;
    }

    return 0;
}

int validate_config(json_object *config) {
    // Implement schema validation logic here
    // Return 0 for valid, non-zero for invalid
    return 0;
}

int init_context(aes_gcm_context *ctx, const unsigned char *key, const unsigned char *iv) {
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) return -1;

    if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        return -1;
    }

    return 0;
}

int encrypt(aes_gcm_context *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char **ciphertext, size_t *ciphertext_len) {
    if (EVP_EncryptUpdate(ctx->ctx, NULL, ciphertext_len, plaintext, plaintext_len) != 1) return -1;

    *ciphertext = malloc(*ciphertext_len + AES_GCM_TAG_LEN);
    if (!*ciphertext) return -1;

    if (EVP_EncryptUpdate(ctx->ctx, *ciphertext, ciphertext_len, plaintext, plaintext_len) != 1) {
        free(*ciphertext);
        return -1;
    }

    if (EVP_EncryptFinal_ex(ctx->ctx, (*ciphertext + *ciphertext_len), &tag_len) != 1) {
        free(*ciphertext);
        return -1;
    }

    *ciphertext_len += tag_len;
    return 0;
}

int decrypt(aes_gcm_context *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char **plaintext, size_t *plaintext_len) {
    if (EVP_DecryptUpdate(ctx->ctx, NULL, plaintext_len, ciphertext, ciphertext_len) != 1) return -1;

    *plaintext = malloc(*plaintext_len);
    if (!*plaintext) return -1;

    if (EVP_DecryptUpdate(ctx->ctx, *plaintext, plaintext_len, ciphertext, ciphertext_len) != 1) {
        free(*plaintext);
        return -1;
    }

    if (EVP_DecryptFinal_ex(ctx->ctx, (*plaintext + *plaintext_len), &tag_len) != 1) {
        free(*plaintext);
        return -1;
    }

    *plaintext_len += tag_len;
    return 0;
}

void cleanup_context(aes_gcm_context *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    memset(ctx, 0, sizeof(*ctx));
}
