    virtual std::string decrypt(const std::string& data) const = 0;
};

// Concrete implementation of a KMS provider (e.g., AWS KMS)
class AwsKms : public KeyManagementService {
public:
    std::string encrypt(const std::string& data) const override {
        // Implementation for encrypting data using AWS KMS
        return "Encrypted by AWS KMS";
    }

    std::string decrypt(const std::string& data) const override {
        // Implementation for decrypting data using AWS KMS
        return "Decrypted by AWS KMS";
    }

    void rotateKey() override {
        // Implementation for rotating keys in AWS KMS
        std::cout << "Rotating key in AWS KMS" << std::endl;
    }

    void revokeKey() override {
        // Implementation for revoking keys in AWS KMS
        std::cout << "Revoking key in AWS KMS" << std::endl;
    }

    void retireKey() override {
        // Implementation for retiring keys in AWS KMS
        std::cout << "Retiring key in AWS KMS" << std::endl;
    }
};

// Concrete implementation of an encryption algorithm (e.g., AES)
class AesAlgorithm : public EncryptionAlgorithm {
public:
    std::string encrypt(const std::string& data) const override {
        // Implementation for encrypting data using AES
        return "Encrypted by AES";
    }

    std::string decrypt(const std::string& data) const override {
        // Implementation for decrypting data using AES
        return "Decrypted by AES";
    }
};

// Encryption framework class
class EncryptionFramework {
public:
    void setKmsProvider(std::unique_ptr<KeyManagementService> kms) {
        currentKms = std::move(kms);
    }

    void setEncryptionAlgorithm(std::unique_ptr<EncryptionAlgorithm> algorithm) {
        currentAlgorithm = std::move(algorithm);
    }

    std::string encryptData(const std::string& data) const {
        return currentAlgorithm->encrypt(currentKms->encrypt(data));
    }

    std::string decryptData(const std::string& data) const {
        return currentAlgorithm->decrypt(currentKms->decrypt(data));
    }

    void rotateKey() {
        currentKms->rotateKey();
    }

    void revokeKey() {
        currentKms->revokeKey();
    }

    void retireKey() {
        currentKms->retireKey();
    }

private:
    std::unique_ptr<KeyManagementService> currentKms;
    std::unique_ptr<EncryptionAlgorithm> currentAlgorithm;
};

// Example usage
int main() {
    EncryptionFramework framework;
    framework.setKmsProvider(std::make_unique<AwsKms>());
    framework.setEncryptionAlgorithm(std::make_unique<AesAlgorithm>());

    std::string data = "Sensitive information";
    std::string encryptedData = framework.encryptData(data);
    std::string decryptedData = framework.decryptData(encryptedData);

    std::cout << "Original: " << data << std::endl;
    std::cout << "Encrypted: " << encryptedData << std::endl;
    std::cout << "Decrypted: " << decryptedData << std::endl;

    return 0;
}
