using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using RabbitMQ.Client;
using Newtonsoft.Json;

public class BatchProcessingPipeline : IBatchProcessingPipeline
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private readonly IConnection _rabbitMqConnection;
    private readonly ILogger _logger;

    public BatchProcessingPipeline(HttpClient httpClient, IMemoryCache cache, IConnectionFactory rabbitMqFactory, ILogger logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _rabbitMqConnection = rabbitMqFactory.CreateConnection();
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task ProcessBatchAsync(List<ApiRequest> requests)
    {
        var successfulRequests = 0;
        var failedRequests = 0;
        var latencyStats = new Dictionary<string, TimeSpan>();

        foreach (var request in requests)
        {
            try
            {
                if (_cache.TryGetValue(request.CacheKey, out _))
                {
                    _logger.LogInformation($"Cache hit for {request.RequestId}");
                    continue;
                }

                var response = await MakeApiRequestAsync(request);
                _cache.Set(request.CacheKey, true, new MemoryCacheEntryOptions().SetAbsoluteExpirationRelativeToNow(TimeSpan.FromMinutes(10)));
                successfulRequests++;
                latencyStats[request.RequestId] = response.ElapsedTime;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to process request {request.RequestId}");
                failedRequests++;
            }
        }

        await PublishResultsAsync(successfulRequests, failedRequests, latencyStats);
    }

    private async Task<ApiResponse> MakeApiRequestAsync(ApiRequest request)
    {
        var stopwatch = Stopwatch.StartNew();
        try
        {
            var content = new StringContent(JsonConvert.SerializeObject(request.Payload), Encoding.UTF8, "application/json");
            var response = await _httpClient.PostAsync(request.Url, content);
            response.EnsureSuccessStatusCode();
            stopwatch.Stop();
            return new ApiResponse(stopwatch.Elapsed);
        }
        catch (HttpRequestException ex)
        {
            stopwatch.Stop();
            throw new Exception($"Request failed for {request.RequestId}", ex);
        }
    }

    private async Task PublishResultsAsync(int successfulRequests, int failedRequests, Dictionary<string, TimeSpan> latencyStats)
    {
        using var channel = _rabbitMqConnection.CreateModel();
        channel.QueueDeclare(queue: "results_queue", durable: false, exclusive: false, autoDelete: false, arguments: null);

        var message = new
        {
            SuccessfulRequests = successfulRequests,
            FailedRequests = failedRequests,
            LatencyStats = latencyStats
        };

        var body = Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(message));

        channel.BasicPublish(exchange: "", routingKey: "results_queue", basicProperties: null, body: body);
    }
}

public class ApiRequest
{
    public string RequestId { get; set; }
    public string Url { get; set; }
    public object Payload { get; set; }
    public string CacheKey => $"request_{RequestId}";
}

public class ApiResponse
{
    public TimeSpan ElapsedTime { get; }

    public ApiResponse(TimeSpan elapsedTime)
    {
        ElapsedTime = elapsedTime;
    }
}

public interface IBatchProcessingPipeline
{
    Task ProcessBatchAsync(List<ApiRequest> requests);
}
```']

