#include <iostream>
#include <vector>
#include <thread>
#include <mutex>

struct record {
    int data;
    long timestamp;
    std::string key;
};

class BulkRecordInitializer {
private:
    std::vector<long*> offsets;
    std::vector<int*> keys;
    std::vector<record*> records;
    std::mutex mutex;

public:
    void initialize(int numRecords) {
        for (int i = 0; i < numRecords; ++i) {
            offsets.push_back(new long[10]);
            keys.push_back(new int[10]);
            records.push_back(new record[10]);
        }
    }

    void insertRecord(int tenantId, const record& rec) {
        std::lock_guard<std::mutex> lock(mutex);
        // Assuming a simple round-robin strategy for simplicity
        offsets[tenantId % offsets.size()][tenantId] = offsets[tenantId % offsets.size()][tenantId - 1];
        keys[tenantId % keys.size()][tenantId] = keys[tenantId % keys.size()][tenantId - 1];
        records[tenantId % records.size()][tenantId].data = rec.data;
        records[tenantId % records.size()][tenantId].timestamp = rec.timestamp;
        records[tenantId % records.size()][tenantId].key = rec.key;
    }

    ~BulkRecordInitializer() {
        for (auto& offset : offsets) delete[] offset;
        for (auto& key : keys) delete[] key;
        for (auto& record : records) delete[] record;
    }
};

int main(int argc, char* argv[]) {
    BulkRecordInitializer initializer;
    initializer.initialize(10);

    // Example usage
    record rec = {42, 1633075200, "exampleKey"};
    initializer.insertRecord(0, rec);

    return 0;
}
