namespace DynamicMicroservicesHealthMonitor
{
    public interface ICloudHealthChecker
    {
        Task CheckHealthAsync();
    }

    public class CloudHealthChecker : ICloudHealthChecker
    {
        private readonly List<IMonitoringPlugin> _plugins;
        private readonly HttpClient _httpClient;

        public CloudHealthChecker(List<IMonitoringPlugin> plugins)
        {
            _plugins = plugins;
            _httpClient = new HttpClient();
        }

        public async Task CheckHealthAsync()
        {
            foreach (var plugin in _plugins)
            {
                try
                {
                    var healthResult = await plugin.GetHealthStatusAsync();
                    if (!healthResult.IsHealthy)
                    {
                        // Log the issue and take appropriate action
                        Console.WriteLine($"Issue detected: {healthResult.ErrorMessage}");
                    }
                }
                catch (Exception ex)
                {
                    // Handle exceptions gracefully
                    Console.WriteLine($"Error checking health with plugin: {ex.Message}");
                }
            }
        }
    }

    public interface IMonitoringPlugin
    {
        Task<HealthStatus> GetHealthStatusAsync();
    }

    public class PrometheusPlugin : IMonitoringPlugin
    {
        private readonly string _prometheusEndpoint;

        public PrometheusPlugin(string prometheusEndpoint)
        {
            _prometheusEndpoint = prometheusEndpoint;
        }

        public async Task<HealthStatus> GetHealthStatusAsync()
        {
            try
            {
                var response = await _httpClient.GetAsync(_prometheusEndpoint);
                if (response.IsSuccessStatusCode)
                {
                    // Parse the Prometheus response and determine health status
                    return new HealthStatus { IsHealthy = true };
                }
                else
                {
                    return new HealthStatus { IsHealthy = false, ErrorMessage = "Failed to get Prometheus data" };
                }
            }
            catch (Exception ex)
            {
                return new HealthStatus { IsHealthy = false, ErrorMessage = $"Error fetching Prometheus data: {ex.Message}" };
            }
        }
    }

    public class HealthStatus
    {
        public bool IsHealthy { get; set; }
        public string ErrorMessage { get; set; }
    }
}

// Usage example
var plugins = new List<IMonitoringPlugin>
{
    new PrometheusPlugin("http://prometheus-server/api/v1/health")
};
var healthChecker = new CloudHealthChecker(plugins);
await healthChecker.CheckHealthAsync();
