NFAPI_CRC_INDICATION_PDU_T** crc_indication_pdu_array;
int array_size = 0;
pthread_mutex_t mutex;

void initialize_crc_array(int initial_size) {
    pthread_mutex_lock(&mutex);
    if (crc_indication_pdu_array == NULL) {
        array_size = initial_size;
        crc_indication_pdu_array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (crc_indication_pdu_array == NULL) {
            perror("Failed to allocate memory for CRC indication PDU array");
            exit(EXIT_FAILURE);
        }
    } else {
        fprintf(stderr, "CRC indication PDU array is already initialized\n");
    }
    pthread_mutex_unlock(&mutex);
}

void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&mutex);
    if (array_size == 0 || crc_indication_pdu_array[array_size - 1] != NULL) {
        array_size *= 2;
        crc_indication_pdu_array = realloc(crc_indication_pdu_array, array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (crc_indication_pdu_array == NULL) {
            perror("Failed to reallocate memory for CRC indication PDU array");
            exit(EXIT_FAILURE);
        }
    }
    crc_indication_pdu_array[array_size - 1] = pdu;
    pthread_mutex_unlock(&mutex);
}

void free_crc_array() {
    pthread_mutex_lock(&mutex);
    if (crc_indication_pdu_array != NULL) {
        for (int i = 0; i < array_size; i++) {
            free(crc_indication_pdu_array[i]);
        }
        free(crc_indication_pdu_array);
        crc_indication_pdu_array = NULL;
        array_size = 0;
    }
    pthread_mutex_unlock(&mutex);
}

