#define NFAPI_CRC_INDICATION_PDU_T struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
} ThreadSafeNFAPIBuffer;

ThreadSafeNFAPIBuffer* create_buffer(size_t initial_capacity) {
    ThreadSafeNFAPIBuffer *buffer = (ThreadSafeNFAPIBuffer*)malloc(sizeof(ThreadSafeNFAPIBuffer));
    if (!buffer) return NULL;
    buffer->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!buffer->data) {
        free(buffer);
        return NULL;
    }
    buffer->capacity = initial_capacity;
    buffer->size = 0;
    srand(time(NULL)); // Seed for random number generation
    return buffer;
}

void destroy_buffer(ThreadSafeNFAPIBuffer *buffer) {
    if (buffer) {
        free(buffer->data);
        free(buffer);
    }
}

int add_random_pdu(ThreadSafeNFAPIBuffer *buffer) {
    if (!buffer || buffer->size >= buffer->capacity) return -1; // Buffer is full or invalid

    NFAPI_CRC_INDICATION_PDU_T new_pdu;
    new_pdu.RX_UE_INFORMATION_TAG = rand();
    new_pdu.RNTI = rand() % 65536; // RNTI is typically a 16-bit value
    new_pdu.CRC_INDICATION_REL8_TAG = (rand() % 2); // CRCFLAG is either 0 or 1

    buffer->data[buffer->size++] = new_pdu;
    return 0;
}

void *populate_buffer(void *arg) {
    ThreadSafeNFAPIBuffer *buffer = (ThreadSafeNFAPIBuffer*)arg;

    for (int i = 0; i < 1000000; ++i) { // Example: Populate with 1 million PDUs
        if (add_random_pdu(buffer)) {
            perror("Failed to add PDU");
            return NULL;
