#include <fstream>
#include <sstream>
#include <iomanip>

class LogAggregator {
public:
    struct LogEntry {
        std::string level;
        std::string message;
        std::chrono::system_clock::time_point timestamp;
        std::string source;
    };

    enum class Format { JSON, CSV };

    LogAggregator(size_t maxBufferSize = 10000);
    ~LogAggregator();

    void addLog(const LogEntry& entry);
    std::string getLogs(Format format) const;

private:
    std::queue<LogEntry> buffer;
    mutable std::mutex bufferMutex;
    std::condition_variable notEmptyCondVar;
    size_t maxBufferSize;
    std::atomic<bool> running;
    std::thread workerThread;

    void worker();
};

LogAggregator::LogAggregator(size_t maxBufferSize)
    : maxBufferSize(maxBufferSize), running(true) {
    workerThread = std::thread(&LogAggregator::worker, this);
}

LogAggregator::~LogAggregator() {
    {
        std::unique_lock<std::mutex> lock(bufferMutex);
        running = false;
    }
    notEmptyCondVar.notify_all();
    if (workerThread.joinable()) {
        workerThread.join();
    }
}

void LogAggregator::addLog(const LogEntry& entry) {
    {
        std::lock_guard<std::mutex> lock(bufferMutex);
        buffer.push(entry);
    }
    notEmptyCondVar.notify_one();
}

std::string LogAggregator::getLogs(Format format) const {
    if (format == Format::JSON) {
        std::ostringstream oss;
        oss << "[";
        for (const auto& entry : buffer) {
            oss << "{\"level\":\"" << entry.level << "\",\"message\":\""
                << entry.message << "\",\"timestamp\":\""
                << std::put_time(std::chrono::system_clock::to_local(entry.timestamp), "%Y-%m-%d %H:%M:%S")
                << "\",\"source\":\"" << entry.source << "\"},";
        }
        if (!buffer.empty()) {
            oss.seekp(oss.tellp() - 1); // Remove trailing comma
        }
        oss << "]";
        return oss.str();
    } else if (format == Format::CSV) {
        std::ostringstream oss;
        oss << "Level,Message,Timestamp,Source\n";
        for (const auto& entry : buffer) {
            oss << entry.level << "," << entry.message << ","
                << std::put_time(std::chrono::system_clock::to_local(entry.timestamp), "%Y-%m-%d %H:%M:%S")
                << "," << entry.source << "\n";
        }
        return oss.str();
    } else {
        throw std::invalid_argument("Unsupported format");
    }
}

void LogAggregator::worker() {
    while (true) {
        LogEntry entry;
        {
            std::unique_lock<std::mutex> lock(bufferMutex);
            notEmptyCondVar.wait(lock, [this]{ return !buffer.empty() || !running; });
            if (!running && buffer.empty()) {
                break;
            }
            entry = buffer.front();
            buffer.pop();
        }
        // Process the log entry (e.g., send to external service)
    }
}

int main() {
    LogAggregator aggregator;

    // Simulate adding logs
    for (size_t i = 0; i < 10000; ++i) {
        LogAggregator::LogEntry entry{
            "INFO", "This is a log message", std::chrono::system_clock::now(), "SourceA"
        };
        aggregator.addLog(entry);
    }

    // Retrieve logs in JSON format
    std::string jsonLogs = aggregator.getLogs(LogAggregator::Format::JSON);
    std::cout << "JSON Logs:\n" << jsonLogs << std::endl;

    return 0;
}
