class LogEntry {
public:
    std::string message;
    std::chrono::system_clock::time_point timestamp;
};

class LogAggregator {
private:
    struct ServiceConfig {
        // Configuration details for third-party logging services
    };

    struct DatabaseConfig {
        // Configuration details for internal databases
    };

    struct Cache {
        // Caching mechanism to reduce database queries
    };

    struct RetryStrategy {
        // Implement retry logic and exponential backoff strategies
    };

    std::vector<std::unique_ptr<LogService>> logServices;
    std::vector<std::unique_ptr<Database>> databases;
    Cache cache;
    RetryStrategy retryStrategy;

    std::mutex queueMutex;
    std::condition_variable queueCondition;
    std::queue<LogEntry> logQueue;
    std::atomic<bool> running{false};

    void processLogs() {
        while (running) {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCondition.wait(lock, [this] { return !logQueue.empty() || !running; });
            if (!running && logQueue.empty()) break;

            LogEntry entry = logQueue.front();
            logQueue.pop();

            lock.unlock();

            // Process the log entry
            for (auto& service : logServices) {
                try {
                    service->ingest(entry);
                } catch (...) {
                    retryStrategy.handleFailure(service.get());
                }
            }

            // Store the log in databases
            for (auto& db : databases) {
                try {
                    db->store(entry);
                } catch (...) {
                    // Handle database storage failures gracefully
                }
            }

            cache.update(entry);
        }
    }

public:
    LogAggregator(std::vector<ServiceConfig> serviceConfigs, std::vector<DatabaseConfig> dbConfigs)
        : logServices(serviceConfigs.size()), databases(dbConfigs.size()) {
        for (size_t i = 0; i < serviceConfigs.size(); ++i) {
            logServices[i] = std::make_unique<LogService>(serviceConfigs[i]);
        }
        for (size_t i = 0; i < dbConfigs.size(); ++i) {
            databases[i] = std::make_unique<Database>(dbConfigs[i]);
        }

        // Start worker threads
        running.store(true);
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            std::thread(&LogAggregator::processLogs, this).detach();
        }
    }

    ~LogAggregator() {
        running.store(false);
        queueCondition.notify_all();
    }

    void ingest(const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(queueMutex);
        logQueue.push(entry);
        queueCondition.notify_one();
    }

    // Implement methods for retrieving logs in JSON, CSV, and XML formats
};
