package main

import (
	"fmt"
	"sync"
)

// File represents a file with versioning and metadata
type File struct {
	ID         string
	Version    int
	Content    []byte
	Metadata   map[string]string
	History    []File
}

// UserService manages user preferences and settings
type UserService interface {
	GetUserSettings(userID string) (map[string]interface{}, error)
	SetUserSettings(userID string, settings map[string]interface{}) error
}

// FileService manages file operations and synchronization
type FileService struct {
	userService UserService
	files       map[string]*File
	mu          sync.Mutex
}

// NewFileService creates a new FileService instance
func NewFileService(userService UserService) *FileService {
	return &FileService{
		userService: userService,
		files:       make(map[string]*File),
	}
}

// GetFile retrieves a file by ID
func (fs *FileService) GetFile(userID, fileID string) (*File, error) {
	fs.mu.Lock()
	defer fs.mu.Unlock()

	file, exists := fs.files[fileID]
	if !exists {
		return nil, fmt.Errorf("file not found")
	}

	return file, nil
}

// UpdateFile updates a file with new content and metadata
func (fs *FileService) UpdateFile(userID, fileID string, newContent []byte, metadata map[string]string) error {
	fs.mu.Lock()
	defer fs.mu.Unlock()

	file, exists := fs.files[fileID]
	if !exists {
		return fmt.Errorf("file not found")
	}

	newVersion := file.Version + 1
	newHistory := append(file.History, *file)
	newFile := &File{
		ID:        file.ID,
		Version:   newVersion,
		Content:   newContent,
		Metadata:  metadata,
		History:   newHistory,
	}

	fs.files[fileID] = newFile
	return nil
}

// Main function to demonstrate file service usage
func main() {
	userService := &userServiceMock{} // Mock implementation of UserService
	fileService := NewFileService(userService)

	// Simulate user updating a file
	userID := "user123"
	fileID := "file456"
	newContent := []byte("Updated content")
	metadata := map[string]string{"author": "John Doe"}

	err := fileService.UpdateFile(userID, fileID, newContent, metadata)
	if err != nil {
		fmt.Println("Error updating file:", err)
		return
	}

	// Retrieve and print the updated file
	file, err := fileService.GetFile(userID, fileID)
	if err != nil {
		fmt.Println("Error retrieving file:", err)
		return
	}

	fmt.Printf("Updated File: %+v\n", file)
}

// userServiceMock is a mock implementation of UserService for demonstration purposes
