from flask import Flask, request, jsonify
from functools import wraps
import requests
import hashlib
import logging

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

class TenantConfig:
    def __init__(self, client_id, client_secret, issuer_url):
        self.client_id = client_id
        self.client_secret = client_secret
        self.issuer_url = issuer_url

# Singleton pattern for tenant configurations
tenant_configs = {}

def get_tenant_config(tenant_id):
    return tenant_configs.get(tenant_id)

@app.before_request
def authenticate():
    tenant_id = request.headers.get('X-Tenant-ID')
    config = get_tenant_config(tenant_id)
    if not config:
        return jsonify({"error": "Tenant not found"}), 403

    token = request.headers.get('Authorization').split()[1]
    response = requests.post(f"{config.issuer_url}/token/introspection", data={
        'client_id': config.client_id,
        'client_secret': config.client_secret,
        'token': token
    })
    if response.status_code != 200:
        return jsonify({"error": "Token invalid or expired"}), 401

    # Process the token and role information
    user_info = response.json()
    request.user_info = user_info
    return None

def rbac_required(roles):
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            if not all(role in request.user_info['groups'] for role in roles):
                return jsonify({"error": "Forbidden"}), 403
            return f(*args, **kwargs)
        return decorated_function
    return decorator

