#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_LOG_SIZE 2 * 1024 * 1024 // 2 GB/s of log ingestion rate
#define NUM_WORKERS 50

typedef struct {
    int id;
    char* log_data[MAX_LOG_SIZE];
    int log_count;
} LogWorker;

void* log_worker(void* arg) {
    LogWorker* worker = (LogWorker*)arg;
    while (1) {
        for (int i = 0; i < worker->log_count; i++) {
            // Process log data here
            printf("Processing log from server %d: %s\n", worker->id, worker->log_data[i]);
        }
        worker->log_count = 0;
    }
}

void receive_logs(int server_port) {
    int sockfd;
    struct sockaddr_in servaddr, cliaddr;
    socklen_t len;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    memset(&servaddr, 0, sizeof(servaddr));
    memset(&cliaddr, 0, sizeof(cliaddr));

    // Fill server information
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = INADDR_ANY;
    servaddr.sin_port = htons(server_port);

    // Bind the socket with the server address
    if (bind(sockfd, (const struct sockaddr*)&servaddr, sizeof(servaddr)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    LogWorker workers[NUM_WORKERS];
    pthread_t threads[NUM_WORKERS];

    for (int i = 0; i < NUM_WORKERS; i++) {
        workers[i].id = i;
        memset(workers[i].log_data, 0, sizeof(workers[i].log_data));
        workers[i].log_count = 0;

        if (pthread_create(&threads[i], NULL, log_worker, &workers[i]) != 0) {
            perror("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    len = sizeof(cliaddr); //len is value/result
    char buffer[MAX_LOG_SIZE];
    while (1) {
        int n = recvfrom(sockfd, (char*)buffer, MAX_LOG_SIZE, MSG_WAITALL,
                          (struct sockaddr*)&cliaddr, &len);
        if (n < 0) {
            perror("recvfrom failed");
            continue;
        }
        buffer[n] = '\0';

        // Distribute log data to workers
        int worker_index = (workers[0].id + workers[1].log_count) % NUM_WORKERS;
        strncpy(workers[worker_index].log_data[workers[worker_index].log_count], buffer, MAX_LOG_SIZE);
        workers[worker_index].log_count++;
    }

    for (int i = 0; i < NUM_WORKERS; i++) {
        pthread_join(threads[i], NULL);
    }

    close(sockfd);
}

int main() {
    int server_port = 12345;
    receive_logs(server_port);
    return 0;
}
