#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>

// Define a simple order book class
class OrderBook {
public:
    void AddOrder(int price, int volume) {
        std::lock_guard<std::mutex> lock(mutex_);
        orders_.push_back({price, volume});
        cv_.notify_all();
    }

    bool RemoveOrder(int price, int volume) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = orders_.begin(); it != orders_.end(); ++it) {
            if (it->first == price && it->second >= volume) {
                it->second -= volume;
                if (it->second == 0) {
                    orders_.erase(it);
                }
                cv_.notify_all();
                return true;
            }
        }
        return false;
    }

    void ProcessOrders() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return !orders_.empty(); });
        // Process orders logic here
        for (auto& order : orders_) {
            std::cout << "Processing order: Price = " << order.first << ", Volume = " << order.second << std::endl;
        }
        orders_.clear();
    }

private:
    struct Order {
        int price;
        int volume;
    };
    std::vector<Order> orders_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
};

int main() {
    OrderBook orderBook;

    // Example usage
    orderBook.AddOrder(100, 5);
    orderBook.AddOrder(105, 3);
    orderBook.RemoveOrder(100, 2);

    std::thread processor([&orderBook]() { 
        while (true) {
            orderBook.ProcessOrders();
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    });

    // Simulate adding and removing orders
    for (int i = 0; i < 20; ++i) {
        if (i % 2 == 0) {
            orderBook.AddOrder(95 + i, 1);
        } else {
            orderBook.RemoveOrder(95 + i, 1);
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    processor.join();

    return 0;
}
