    NFAPIManager(const std::string& db_url, const std::string& api_url, const std::string& oauth_token)
        : db_url_(db_url), api_url_(api_url), oauth_token_(oauth_token) {}

    void populateArray(size_t N, std::vector<NFAPI_CRC_INDICATION_PDU_T>& array) {
        // Thread pool for parallel processing
        std::vector<std::thread> threads;
        std::mutex queue_mutex;
        std::condition_variable condition;
        bool stop = false;

        auto worker = [&]() {
            while (true) {
                NFAPI_CRC_INDICATION_PDU_T pdu;
                {
                    std::unique_lock<std::mutex> lock(queue_mutex);
                    condition.wait(lock, [this] { return !queue.empty() || stop; });
                    if (stop && queue.empty()) break;
                    pdu = queue.front();
                    queue.pop();
                }
                processPDU(pdu, array);
            }
        };

        // Start worker threads
        for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
            threads.emplace_back(worker);
        }

        // Populate the queue with PDUs
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            for (size_t i = 0; i < N; ++i) {
