#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_STRUCTS 10000
#define CACHE_SIZE 50000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheEntry {
    NFAPI_CRC_INDICATION_PDU_T data;
    int last_accessed;
    pthread_mutex_t lock;
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_cache() {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        pthread_mutex_init(&cache[i].lock, NULL);
        cache[i].last_accessed = -1;
    }
}

CacheEntry* get_from_cache(int RNTI) {
    CacheEntry* entry = NULL;
    int min_access_time = INT_MAX;

    for (int i = 0; i < CACHE_SIZE; ++i) {
        pthread_mutex_lock(&cache[i].lock);
        if (cache[i].last_accessed == -1 || cache[i].last_accessed < min_access_time) {
            entry = &cache[i];
            min_access_time = cache[i].last_accessed;
        }
        pthread_mutex_unlock(&cache[i].lock);
    }

    return entry;
}

void add_to_cache(NFAPI_CRC_INDICATION_PDU_T data) {
    CacheEntry* entry = get_from_cache(data.RNTI);

    if (entry != NULL) {
        pthread_mutex_lock(&entry->lock);
        memcpy(&entry->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        entry->last_accessed = time(NULL);
        pthread_mutex_unlock(&entry->lock);
    } else {
        fprintf(stderr, "Cache is full, cannot add new data.\n");
    }
}

void* process_packets(void* arg) {
    // Simulate processing packets
    for (int i = 0; i < MAX_STRUCTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T packet;
        memset(&packet, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        packet.RX_UE_INFORMATION_TAG = i % 100;
        packet.RNTI = i % 500;
        packet.CRCFLAG = (i % 2 == 0) ? 1 : 0;

        add_to_cache(packet);
    }

    return NULL;
}

int main() {
    initialize_cache();

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, process_packets, NULL);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
