class DistributedNFAPICRCProcessor {
public:
    DistributedNFAPICRCProcessor(size_t maxStructuresPerNode)
        : maxStructuresPerNode(maxStructuresPerNode), currentStructures(0) {}

    void processPDU(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return currentStructures < maxStructuresPerNode; });

        if (currentStructures >= maxStructuresPerNode) {
            // Fallback mechanism: swap to disk or evict LRU entries
            // For simplicity, we'll just log and ignore in this example
            std::cerr << "Too many structures. Dropping PDU." << std::endl;
            return;
        }

        storage.push_back(pdu);
        currentStructures++;
        lock.unlock();
        condition.notify_one();
    }

private:
    size_t maxStructuresPerNode;
    size_t currentStructures;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> storage;
    std::mutex mutex;
    std::condition_variable condition;
};

int main() {
