public class UserSessionManager {
    private Map<String, USER_SESSION_STATE> sessionStore = new HashMap<>();

    public String createSession(USER_SESSION_STATE userSession) {
        synchronized (this) {
            if (sessionStore.containsKey(userSession.getSession_id())) {
                throw new RuntimeException("Session already exists");
            }
            sessionStore.put(userSession.getSession_id(), userSession);
            return userSession.getSession_id();
        }
    }

    public void updateSession(String sessionId, USER_SESSION_STATE updatedUserSession) {
        synchronized (this) {
            if (!sessionStore.containsKey(sessionId)) {
                throw new RuntimeException("Session not found");
            }
            sessionStore.put(sessionId, updatedUserSession);
        }
    }

    public void deleteSession(String sessionId) {
        synchronized (this) {
            if (sessionStore.containsKey(sessionId)) {
                sessionStore.remove(sessionId);
            }
        }
    }

    public USER_SESSION_STATE getSession(String sessionId) {
        return sessionStore.get(sessionId);
    }
}

