#include <pthread.h>
#include <json-c/json.h>

#define MAX_EVENTS 1000

typedef struct {
    time_t timestamp;
    int cell_id;
    char *payload;
} Event;

typedef struct {
    Event events[MAX_EVENTS];
    size_t count;
    pthread_mutex_t lock;
} EventList;

EventList event_list;

void init_event_list() {
    pthread_mutex_init(&event_list.lock, NULL);
}

Event* bulk_event_initializer(size_t num_events) {
    if (num_events > MAX_EVENTS) {
        return NULL;
    }

    pthread_mutex_lock(&event_list.lock);

    for (size_t i = 0; i < num_events; i++) {
        Event *new_event = &event_list.events[i];
        new_event->timestamp = time(NULL);
        new_event->cell_id = rand() % 1000;

        struct json_object *payload_obj = json_object_new_string("Sample payload");
        if (!payload_obj) {
            pthread_mutex_unlock(&event_list.lock);
            return NULL;
        }

        new_event->payload = strdup(json_object_to_json_string(payload_obj));
        json_object_put(payload_obj);

        if (!new_event->payload) {
            pthread_mutex_unlock(&event_list.lock);
            return NULL;
        }
    }

    event_list.count = num_events;

    pthread_mutex_unlock(&event_list.lock);
    return event_list.events;
}

void cleanup_events(Event *events, size_t count) {
    for (size_t i = 0; i < count; i++) {
        free(events[i].payload);
    }
}
