// DES encryption function
void des_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key, unsigned char *ciphertext) {
    DES_key_schedule key_schedule;
    DES_set_odd_parity(key);
    DES_set_key_unchecked(&key_schedule, key);
    for (int i = 0; i < plaintext_len; i += 8) {
        DES_ecb_encrypt((DES_cblock *)plaintext + i, (DES_cblock *)ciphertext + i, &key_schedule, DES_ENCRYPT);
    }
}

// AES encryption function
void aes_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key, unsigned char *ciphertext) {
    AES_KEY key_struct;
    AES_set_encrypt_key(key, 256, &key_struct);
    for (int i = 0; i < plaintext_len; i += AES_BLOCK_SIZE) {
        AES_ecb_encrypt(plaintext + i, ciphertext + i, &key_struct);
    }
}

// ChaCha20 encryption function
void chacha20_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key, unsigned char *ciphertext) {
    chacha20_init(key, 32);
    for (int i = 0; i < plaintext_len; i += CHACHA20_BLOCK_SIZE) {
        chacha20_block(plaintext + i, ciphertext + i);
    }
}

// Null encryption function
void null_encrypt(const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    memcpy(ciphertext, plaintext, plaintext_len);
}

