package main

import (
	"context"
	"crypto/tls"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/gorilla/websocket"
	"github.com/prometheus/client_golang/prometheus/promhttp"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

func main() {
	r := gin.Default()

	// Configure TLS
	tlsConfig := &tls.Config{
		InsecureSkipVerify: true,
	}
	client := &http.Client{Transport: &http.Transport{TLSClientConfig: tlsConfig}}

	// Kubernetes client
	config, err := rest.InClusterConfig()
	if err != nil {
		panic(err)
	}
	k8sClient, err := kubernetes.NewForConfig(config)
	if err != nil {
		panic(err)
	}

	r.GET("/metrics", gin.WrapH(promhttp.Handler()))

	r.Use(func(c *gin.Context) {
		start := time.Now()

		c.Next()

		latency := time.Since(start)
		c.Writer.Header().Set("X-Response-Time", latency.String())
	})

	r.GET("/api/v1/:service/*endpoint", func(c *gin.Context) {
		service := c.Param("service")
		endpoint := c.Param("endpoint")

		// Route to microservice
		serviceURL := fmt.Sprintf("http://%s.%s.svc.cluster.local%s", service, serviceNamespace, endpoint)
		req, err := http.NewRequestWithContext(c.Request.Context(), c.Request.Method, serviceURL, c.Request.Body)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to create request"})
			return
		}
		req.Header = c.Request.Header

		resp, err := client.Do(req)
		if err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": "Backend service unavailable"})
			return
		}
		defer resp.Body.Close()

		c.DataFromResponse(resp)
	})

	r.GET("/ws", func(c *gin.Context) {
		upgrader := websocket.Upgrader{}
		conn, err := upgrader.Upgrade(c.Writer, c.Request, nil)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to upgrade connection"})
			return
		}
		defer conn.Close()

		for {
			messageType, message, err := conn.ReadMessage()
			if err != nil {
				break
			}

			err = conn.WriteMessage(messageType, message)
			if err != nil {
				break
			}
		}
	})

	r.Run(":8080")
}
