DynamicArray* dynamic_array_create(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*) malloc(sizeof(DynamicArray));
    array->data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void dynamic_array_destroy(DynamicArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void dynamic_array_append(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*) realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            // Handle memory allocation failure
            return;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = item;
    pthread_mutex_unlock(&array->lock);
}

void dynamic_array_remove(DynamicArray *array, size_t index) {
    pthread_mutex_lock(&array->lock);
    if (index < array->size) {
        for (size_t i = index; i < array->size - 1; i++) {
            array->data[i] = array->data[i + 1];
        }
        array->size--;
    }
    pthread_mutex_unlock(&array->lock);
}

NFAPI_CRC_INDICATION_PDU_T dynamic_array_get(DynamicArray *array, size_t index) {
    pthread_mutex_lock(&array->lock);
    if (index < array->size) {
        NFAPI_CRC_INDICATION_PDU_T item = array->data[index];
        pthread_mutex_unlock(&array->lock);
        return item;
    }
    pthread_mutex_unlock(&array->lock);
    // Handle out-of-bounds access
    return NULL;
}

void dynamic_array_set(DynamicArray *array, size_t index, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&array->lock);
    if (index < array->size) {
        array->data[index] = item;
    }
    pthread_mutex_unlock(&array->lock);
