const readline = require('readline');

const app = express();
app.use(express.json());

// Regular expression to match book names in Old Testament
const bookRegex = /(?:\b|)(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Ruth|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song\s+of\s+Songs|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)(?:\b|\s+)/ig;

// Function to fetch historical frequency data from third-party API
async function getFrequencyData(bookName) {
  try {
    const response = await axios.get(`https://api.example.com/frequency/${bookName}`);
    return response.data;
  } catch (error) {
    console.error(`Failed to fetch frequency data for ${bookName}:`, error);
    throw error;
  }
}

// Generator function to process text incrementally
function* processText(text) {
  let matches = bookRegex.exec(text);
  while (matches !== null) {
    yield matches[0];
    matches = bookRegex.exec(text);
  }
}

// Route to process incoming text data
app.post('/process-text', async (req, res) => {
  const { text } = req.body;
  if (!text) {
    return res.status(400).json({ error: 'No text provided' });
  }

  const results = {};
  let count = 0;

  // Process the text using the generator
  for (const book of processText(text)) {
    if (!(book in results)) {
      results[book] = 0;
    }
    results[book]++;
    count++;

    try {
      const frequencyData = await getFrequencyData(book);
      // Update result set with frequency data
      results[book] += frequencyData.count;
    } catch (error) {
      console.error(`Error processing book ${book}:`, error);
      // Handle network errors and retry logic here
    }
  }

  res.json({ count, results });
});

// Start the server
app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
