} NFAPI_CRC_INDICATION_PDU_T;

// Define a pool-based allocation strategy for dynamic arrays
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t used;
} CRC_POOL;

CRC_POOL* create_crc_pool(size_t initial_size) {
    CRC_POOL *pool = (CRC_POOL*)malloc(sizeof(CRC_POOL));
    if (!pool) return NULL;
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    pool->size = initial_size;
    pool->used = 0;
    return pool;
}

void destroy_crc_pool(CRC_POOL *pool) {
    free(pool->pool);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu(CRC_POOL *pool) {
    if (pool->used >= pool->size) {
        // Double the size of the pool
        NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(pool->pool, pool->size * 2);
        if (!new_pool) return NULL;
        pool->pool = new_pool;
        pool->size *= 2;
    }
    return &pool->pool[pool->used++];
}

