  const regex = /\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiahu|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b/gi;
  return text.match(regex) || [];
}

// Function to enrich book references with API data
async function enrichBookReferences(bookNames) {
  const results = {};
  for (const bookName of bookNames) {
    if (!cache.has(bookName)) {
      try {
        const response = await axios.get(apiConfig.bookDetails, { params: { name: bookName } });
        cache.set(bookName, response.data);
      } catch (error) {
        console.error(`Error fetching data for ${bookName}:`, error);
      }
    }
    results[bookName] = cache.get(bookName);
  }
  return results;
}

// Route to analyze unstructured text for biblical references
app.post('/analyze', async (req, res) => {
  const { text } = req.body;
  if (!text) {
    return res.status(400).json({ error: 'Text is required' });
  }

  try {
    const bookNames = extractBookNames(text);
    const enrichedData = await enrichBookReferences(bookNames);
    res.json(enrichedData);
  } catch (error) {
    console.error('Error analyzing text:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
