// computeMD5Hash takes a string and returns its MD5 hash as a hexadecimal string.
func computeMD5Hash(input string) (string, error) {
	hash := md5.New()
	if _, err := hash.Write([]byte(input)); err != nil {
		return "", errors.Wrap(err, "failed to write data to hash")
	}
	return hex.EncodeToString(hash.Sum(nil)), nil
}

// Example usage:
func main() {
	hash, err := computeMD5Hash("example string")
	if err != nil {
		panic(err)
	}
	println("MD5 Hash:", hash)
}
