NetworkEvent* bulk_event_initializer(int count, char **events) {
    if (count <= 0 || events == NULL) {
        return NULL;
    }

    NetworkEvent *event_list = malloc(count * sizeof(NetworkEvent));
    if (event_list == NULL) {
        perror("Memory allocation failed for event list");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < count; i++) {
        event_list[i].timestamp = rand() % 86400; // Random timestamp within one day
        event_list[i].cell_id = rand() % 1000;     // Random cell ID

        size_t json_length = snprintf(NULL, 0, "{\"type\": \"%s\", \"data\": \"%d\"}", "event_type", i);
        event_list[i].json_payload = malloc(json_length + 1);
        if (event_list[i].json_payload == NULL) {
            perror("Memory allocation failed for JSON payload");
            free(event_list);
            return NULL;
        }
        snprintf(event_list[i].json_payload, json_length + 1, "{\"type\": \"%s\", \"data\": \"%d\"}", "event_type", i);

        events[i] = event_list[i].json_payload; // Populate the events array
    }

    return event_list;
}

void free_event_list(NetworkEvent *event_list, int count) {
    if (event_list == NULL) {
        return;
    }

    for (int i = 0; i < count; i++) {
        free(event_list[i].json_payload);
    }
    free(event_list);
}
