#include <thread>
#include <atomic>
#include <memory>
#include <fstream>
#include <chrono>

class CustomNetworkEvent {
    // Define your custom network event fields here
};

class NetworkEventCollection {
private:
    std::vector<CustomNetworkEvent> events;
    std::mutex accessMutex;
    std::condition_variable condVar;
    size_t maxSize;
    bool isClosed;

public:
    NetworkEventCollection(size_t initialSize) : maxSize(initialSize), isClosed(false) {}

    void addEvent(const CustomNetworkEvent& event) {
        std::unique_lock<std::mutex> lock(accessMutex);
        while (events.size() >= maxSize && !isClosed) {
            condVar.wait(lock);
        }
        if (!isClosed) {
            events.push_back(event);
            condVar.notify_one();
        }
    }

    CustomNetworkEvent removeEvent() {
        std::unique_lock<std::mutex> lock(accessMutex);
        while (events.empty()) {
            condVar.wait(lock);
        }
        CustomNetworkEvent event = events.back();
        events.pop_back();
        return event;
    }

    void close() {
        {
            std::unique_lock<std::mutex> lock(accessMutex);
            isClosed = true;
        }
        condVar.notify_all();
    }
};

class Logger {
private:
    std::atomic<bool> isAsync;
    std::thread loggerThread;
    std::queue<std::string> logQueue;

public:
    Logger(bool async) : isAsync(async), loggerThread(&Logger::logThread, this) {}

    ~Logger() {
        close();
        if (isAsync) {
            loggerThread.join();
        }
    }

    void log(const std::string& message) {
        if (isAsync) {
            std::lock_guard<std::mutex> lock(logQueueMutex);
            logQueue.push(message);
        } else {
            logMessage(message);
        }
    }

    void close() {
        if (isAsync) {
            std::unique_lock<std::mutex> lock(logQueueMutex);
            isClosed = true;
        }
    }

private:
    static void logThread(Logger* logger) {
        while (true) {
            std::string message;
            {
                std::lock_guard<std::mutex> lock(logger->logQueueMutex);
                if (logger->isClosed && logger->logQueue.empty()) {
                    break;
                }
                message = logger->logQueue.front();
                logger->logQueue.pop();
            }
            logger->logMessage(message);
        }
    }

    void logMessage(const std::string& message) {
        // Implement your logging logic here
        std::cout << message << std::endl;
    }
};

class NetworkEventLibrary {
private:
    NetworkEventCollection eventCollection;
    Logger logger;

public:
    NetworkEventLibrary(size_t initialSize, bool enableAsyncLogging)
        : eventCollection(initialSize), logger(enableAsyncLogging) {}

    void addNetworkEvent(const CustomNetworkEvent& event) {
        eventCollection.addEvent(event);
        logger.log("Event added");
    }

    CustomNetworkEvent removeNetworkEvent() {
        CustomNetworkEvent event = eventCollection.removeEvent();
        logger.log("Event removed");
        return event;
    }

    void close() {
        eventCollection.close();
        logger.close();
    }
};
