        std::lock_guard<std::mutex> lock(queueMutex);
        return requests.size();
    }

private:
    void workerThread() {
        while (isRunning) {
            HTTP_REQUEST_T request;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                requestCondition.wait(lock, [this] { return !requestQueue.empty() || !isRunning; });
                if (!isRunning && requestQueue.empty()) {
                    break;
                }
                request = requestQueue.front();
                requestQueue.pop();
            }

            // Process the request
            processRequest(request);

            // Adjust memory pool and concurrency limits based on real-time load and activity patterns
