    typedef websocketpp::server<websocketpp::config::asio> server;
}

class SensorDataProcessor : public std::enable_shared_from_this<SensorDataProcessor> {
public:
    SensorDataProcessor(server& s) : m_server(s) {}

    void start() {
        m_server.init_asio();
        m_server.set_open_handler(std::bind(&SensorDataProcessor::on_open, shared_from_this(), ::_1));
        m_server.set_close_handler(std::bind(&SensorDataProcessor::on_close, shared_from_this(), ::_1));
        m_server.set_message_handler(std::bind(&SensorDataProcessor::on_message, shared_from_this(), ::_1, ::_2));
        m_server.listen(9002);
        m_server.start_accept();
    }

private:
    server& m_server;
    std::map<std::string, websocketpp::connection_hdl> m_connections;
    std::queue<std::string> m_message_queue;

    void on_open(websocketpp::connection_hdl hdl) {
        m_connections.insert(std::make_pair(m_server.get_con_from_hdl(hdl)->get_remote_endpoint(), hdl));
    }

    void on_close(websocketpp::connection_hdl hdl) {
        m_connections.erase(m_server.get_con_from_hdl(hdl)->get_remote_endpoint());
    }

    void on_message(websocketpp::connection_hdl hdl, server::message_ptr msg) {
        // Process the message
        m_message_queue.push(msg->get_payload());
        // Handle deduplication and filtering
        process_message(msg->get_payload());
    }

    void process_message(const std::string& payload) {
        // Custom rules based on device metadata or user-defined criteria
        std::cout << "Processing message: " << payload << std::endl;
    }
};

int main() {
    server echo_server;

    SensorDataProcessor processor(echo_server);
    processor.start();

    echo_server.run();

    return 0;
}
