#include <iostream>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <queue>
#include <atomic>

class Cache {
private:
    std::unordered_map<std::string, std::pair<int, std::string>> cache;
    std::mutex cache_mutex;
    std::condition_variable cv;
    int max_size;

public:
    Cache(int size) : max_size(size) {}

    void set(const std::string& key, const std::string& value, int ttl) {
        std::unique_lock<std::mutex> lock(cache_mutex);
        if (cache.size() >= max_size) {
            cv.wait(lock, [this] { return cache.size() < max_size; });
        }
        cache[key] = {std::chrono::steady_clock::now().time_since_epoch().count() + ttl, value};
    }

    std::string get(const std::string& key) {
        std::unique_lock<std::mutex> lock(cache_mutex);
        auto it = cache.find(key);
        if (it != cache.end()) {
            long now = std::chrono::steady_clock::now().time_since_epoch().count();
            if (now < it->second.first) {
                return it->second.second;
            } else {
                cache.erase(it);
            }
        }
        return "";
    }

    void remove(const std::string& key) {
        std::unique_lock<std::mutex> lock(cache_mutex);
        cache.erase(key);
    }
};

int main() {
    Cache geo_cache(1000);
    geo_cache.set("user_location_1", "40.7128,-74.0060", 300); // 5 minutes
    std::cout << "Location of user_location_1: " << geo_cache.get("user_location_1") << std::endl;
    return 0;
}
