import logging
from threading import Lock
from requests import get,.exceptions

class KickstartModifier:
    def __init__(self, api_key):
        self.api_key = api_key
        self.lock = Lock()
        self.log_file = 'script_log.txt'

    def early_error(self, message):
        logging.error(message)
        raise Exception(message)

    def encrypt_password(self, password):
        url = "https://api.example.com/encrypt"
        headers = {'Authorization': f'Bearer {self.api_key}'}
        data = {'password': password}
        attempts = 0
        while attempts < 3:
            try:
                response = get(url, headers=headers, json=data)
                response.raise_for_status()
                return response.json()['encrypted_password']
            except (requests.exceptions.RequestException, KeyError) as e:
                attempts += 1
                time.sleep(2**attempts)
        self.early_error(f"Failed to encrypt password after {attempts} attempts")

    def modify_and_encrypt_config(self, config_dict):
        original_file = 'kickstart.cfg'
        backup_file = f'kickstart_{time.strftime("%Y%m%d%H%M%S")}.cfg'

        with open(original_file, 'r') as file:
            content = file.read()

        for placeholder, value in config_dict.items():
            if placeholder == 'password':
                encrypted_value = self.encrypt_password(value)
                content = content.replace(placeholder, encrypted_value)
            else:
                content = content.replace(placeholder, str(value))

        with open(backup_file, 'w') as file:
            file.write(content)

    def log_performance(self):
        with self.lock:
            with open(self.log_file, 'a') as file:
                file.write(f"Performance data logged at {time.ctime()}\n")

    def run_script(self, config_dict):
        start_time = time.time()

        try:
            self.modify_and_encrypt_config(config_dict)
            self.log_performance()
        except Exception as e:
            logging.exception("An error occurred during script execution:")

        end_time = time.time()
        print(f"Script executed in {end_time - start_time:.2f} seconds")

# Example usage
api_key = 'your_api_key_here'
modifier = KickstartModifier(api_key)
config_dict = {
    'placeholder1': 'value1',
    'password': 'user_password'
}
modifier.run_script(config_dict)
