#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>
#include <hiredis/hiredis.h>

#define REDIS_HOST "localhost"
#define REDIS_PORT 6379

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    redisContext *redisCtx;
} LTE_RACH_POOL_T;

LTE_RACH_POOL_T rachPool = {PTHREAD_MUTEX_INITIALIZER, NULL};

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char*)userp)[strlen((char*)userp)] = '\0';
    strncat((char*)userp, (char*)contents, size*nmemb);
    return size*nmemb;
}

NFAPI_CRC_INDICATION_PDU_T* bulk_event_initializer(int N) {
    NFAPI_CRC_INDICATION_PDU_T *events = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&rachPool.lock);
    for (int i = 0; i < N; i++) {
        events[i].RNTI = rand() % 1024;
        events[i].CRCFLAG = rand() & 1;
        char *redisKey = malloc(64);
        sprintf(redisKey, "LTE_RACH_CONFIG_%d", events[i].RNTI);

        redisReply *reply = (redisReply*)redisCommand(rachPool.redisCtx, "HGETALL %s", redisKey);
        if (reply && reply->type == REDIS_REPLY_ARRAY) {
            for (size_t j = 0; j < reply->elements; j += 2) {
                if (strcmp(reply->element[j]->str, "CRCFLAG") == 0) {
                    events[i].CRCFLAG = atoi(reply->element[j+1]->str);
                }
            }
        } else {
            // Handle cache miss or error
        }

        free(redisKey);
    }
    pthread_mutex_unlock(&rachPool.lock);

    return events;
}

void* update_cache(void *arg) {
    CURL *curl;
    CURLcode res;
    char json_response[1024];

    curl = curl_easy_init();
    if(curl) {
        struct MemoryStruct chunk;
        chunk.memory = malloc(1);  // will be grown as needed by the realloc above
        chunk.size = 0;    // no data at this point

        curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/lte_rach_config");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            // Handle error
        } else {
            pthread_mutex_lock(&rachPool.lock);
            redisReply *reply = (redisReply*)redisCommand(rachPool.redisCtx, "FLUSHALL");
            if (reply && reply->type == REDIS_REPLY_STATUS) {
                free(chunk.memory);
                curl_easy_cleanup(curl);
                pthread_mutex_unlock(&rachPool.lock);
                return NULL;
            }

            cJSON *root = cJSON_Parse(chunk.memory);
            cJSON *item = root->child;
            while(item != NULL) {
                int RNTI = item->child->valueint;
                cJSON *crcFlagItem = item->child->next;
                int CRCFLAG = crcFlagItem ? crcFlagItem->valueint : 0;

                char *redisKey = malloc(64);
                sprintf(redisKey, "LTE_RACH_CONFIG_%d", RNTI);
                redisReply *setReply = (redisReply*)redisCommand(rachPool.redisCtx, "HSET %s CRCFLAG %d", redisKey, CRCFLAG);
                free(redisKey);

                if (setReply && setReply->type == REDIS_REPLY_INTEGER) {
                    // Success
                } else {
                    // Handle error
                }

                item = item->next;
            }

            cJSON_Delete(root);
            free(chunk.memory);
            curl_easy_cleanup(curl);
        }

        pthread_mutex_unlock(&rachPool.lock);
    }

    return NULL;
}

int main() {
    rachPool.redisCtx = redisConnect(REDIS_HOST, REDIS_PORT);
    if (rachPool.redisCtx == NULL || rachPool.redisCtx->err) {
        if (rachPool.redisCtx) {
