void handle_file(char* input_file, char* output_file, char** rules, int num_rules) {
    FILE* infile = fopen(input_file, "rb");
    if (!infile) {
        perror("Failed to open input file");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;
    // Dynamically allocate memory for PDUs based on file size

    int num_pdus = fread(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), /* calculate num_PDUs */, infile);
    if (num_pdus == 0) {
        perror("Failed to read from input file");
        fclose(infile);
        return;
    }

    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    for (int i = 0; i < num_pdus; i++) {
        if (thread_count >= MAX_THREADS) {
            // Wait for previous threads to complete
            for (int j = 0; j < MAX_THREADS; j++) {
                pthread_join(threads[j], NULL);
            }
            thread_count = 0;
        }

        int result = pthread_create(&threads[thread_count++], NULL, process_pdu, &pdus[i]);
        if (result != 0) {
            perror("Failed to create thread");
            break;
        }
    }

    // Wait for remaining threads
    for (int j = 0; j < thread_count; j++) {
        pthread_join(threads[j], NULL);
    }

    // Write transformed PDUs to output file

    fclose(infile);
}

