#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <curl/curl.h>
#include <nlohmann/json.hpp>

using json = nlohmann::json;
std::mutex config_mutex;
std::condition_variable config_cv;
std::queue<json> ssid_queue;

void fetch_ssid_configurations() {
    CURL *curl;
    CURLcode res;
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/ssid-configs");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void* contents, size_t size, size_t nmemb, void* userp){
            std::string* buffer = static_cast<std::string*>(userp);
            size_t totalSize = size * nmemb;
            buffer->append(static_cast<char*>(contents), totalSize);
            return totalSize;
        });
        std::string readBuffer;
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
        } else {
            std::unique_lock<std::mutex> lock(config_mutex);
            json new_configs = json::parse(readBuffer);
            for(auto& config : new_configs) {
                ssid_queue.push(config);
            }
            lock.unlock();
            config_cv.notify_all();
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

void apply_ssid_configurations() {
    while(true) {
        std::unique_lock<std::mutex> lock(config_mutex);
        config_cv.wait(lock, []{ return !ssid_queue.empty(); });
        json new_config = ssid_queue.front();
        ssid_queue.pop();
        lock.unlock();

        // Apply the new configuration here
        std::cout << "Applying SSID Configuration: " << new_config.dump(4) << std::endl;

        // Simulate a delay for applying configurations
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }
}

int main() {
    std::thread config_fetcher(fetch_ssid_configurations);
    std::thread config_applier(apply_ssid_configurations);

    config_fetcher.join();
    config_applier.join();

    return 0;
}
