#include <condition_variable>

class OAuthLogProcessor {
public:
    void processLogs(const std::string& directory) {
        // Process logs in the specified directory
    }

    void addDirectory(const std::string& directory) {
        std::lock_guard<std::mutex> lock(mutex_);
        directories_.push_back(directory);
        condition_.notify_one();
    }

    void removeDirectory(const std::string& directory) {
        std::lock_guard<std::mutex> lock(mutex_);
        directories_.erase(std::remove(directories_.begin(), directories_.end(), directory), directories_.end());
        condition_.notify_one();
    }

private:
    std::vector<std::string> directories_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

int main() {
    OAuthLogProcessor processor;
    std::thread worker([&processor]() {
        while (true) {
            std::unique_lock<std::mutex> lock(processor.mutex_);
            if (processor.directories_.empty()) {
                processor.condition_.wait(lock);
            }
            for (const auto& dir : processor.directories_) {
                processor.processLogs(dir);
                processor.directories_.erase(std::remove(processor.directories_.begin(), processor.directories_.end(), dir), processor.directories_.end());
            }
        }
    });

    // Simulate adding and removing directories
    processor.addDirectory("/logs/dir1");
    std::this_thread::sleep_for(std::chrono::seconds(2));
    processor.removeDirectory("/logs/dir1");

    worker.join();
    return 0;
}
