// Java Code for OAuth Log Processing and Token Management

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public class OAuthLogProcessor {
    private final List<String> directories = new ArrayList<>();
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final Object lock = new Object();

    public void processLogs(String directory) {
        // Process logs in the specified directory
    }

    public void addDirectory(String directory) {
        synchronized (lock) {
            directories.add(directory);
            lock.notifyAll();
        }
    }

    public void removeDirectory(String directory) {
        synchronized (lock) {
            directories.remove(directory);
        }
    }

    public static void main(String[] args) {
        OAuthLogProcessor processor = new OAuthLogProcessor();
        executor.submit(() -> {
            while (true) {
                synchronized (processor.lock) {
                    if (processor.directories.isEmpty()) {
                        try {
                            processor.lock.wait();
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                        }
                    }
                    for (String dir : processor.directories) {
                        processor.processLogs(dir);
                        processor.directories.remove(dir);
                    }
                }
            }
        });

        // Simulate adding and removing directories
        processor.addDirectory("/logs/dir1");
        try {
            Thread.sleep(2000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        processor.removeDirectory("/logs/dir1");

        processor.executor.shutdown();
    }
}
