#define MAX_ENTRIES 10000
#define LOG_LEVEL_DEBUG 3
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_ERROR 1

typedef struct {
    uint64_t rx_ue_information_tag;
    uint32_t rnti;
    uint32_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T crc_pool[MAX_ENTRIES];
sem_t pool_semaphore;
int current_entry = 0;

void initialize_crc_library() {
    sem_init(&pool_semaphore, 0, MAX_ENTRIES);
}

void generate_crc_indication(NFAPI_CRC_INDICATION_PDU_T *crc_pdu) {
    sem_wait(&pool_semaphore);
    if (current_entry < MAX_ENTRIES) {
        crc_pdu->rx_ue_information_tag = rand();
        crc_pdu->rnti = rand() % 65536;
        crc_pdu->crc_indication_rel8_tag = rand() & 0xFFFFFFFE; // Even number
        crc_pdu->crcflag = (rand() % 2 == 0) ? 1 : 0; // Randomly set to 0 or 1
        current_entry++;
    } else {
        sem_post(&pool_semaphore);
        fprintf(stderr, "CRC pool full\n");
    }
}

void *process_crc_indications(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T crc_pdu;
    while (1) {
        generate_crc_indication(&crc_pdu);
        // Process the CRC indication here
        sem_post(&pool_semaphore);
    }
    return NULL;
}

void log_message(int level, const char *format, ...) {
    va_list args;
    if (level == LOG_LEVEL_ERROR) {
        fprintf(stderr, "ERROR: ");
    } else if (level == LOG_LEVEL_INFO) {
        fprintf(stdout, "INFO: ");
    } else if (level == LOG_LEVEL_DEBUG) {
        fprintf(stdout, "DEBUG: ");
    }
    va_start(args, format);
    vfprintf(stdout, format, args);
    va_end(args);
    fprintf(stdout, "\n");
}

int main() {
    initialize_crc_library();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_crc_indications, NULL);
    }

    // Simulate some operations
    sleep(5);

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&pool_semaphore);
    return 0;
}
