NFAPI_CRC_INDICATION_PDU_T crc_indications[MAX_UE_INFO];
int num_crc_indications = 0;

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void logCRCIndication(NFAPI_CRC_INDICATION_PDU_T indication) {
    pthread_mutex_lock(&log_mutex);
    char log_buffer[256];
    snprintf(log_buffer, sizeof(log_buffer), "RNTI: %d, CRCFLAG: %s\n", indication.RNTI, indication.CRCFLAG ? "true" : "false");
    printf("%s", log_buffer);
    pthread_mutex_unlock(&log_mutex);
}

void* processAndLogCRCIndications(void* arg) {
    int* index = (int*)arg;
    if (*index >= num_crc_indications) {
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T indication = crc_indications[*index];
    logCRCIndication(indication);
    free(index); // Clean up allocated memory
    return NULL;
}

void simulateNetworkData() {
    srand(time(NULL));
    for (int i = 0; i < MAX_UE_INFO; i++) {
        NFAPI_CRC_INDICATION_PDU_T indication;
        indication.RNTI = rand() % 1024;
        indication.CRCFLAG = rand() % 2 == 0;
        crc_indications[i] = indication;
    }
    num_crc_indications = MAX_UE_INFO;
}

int main() {
    simulateNetworkData();

    pthread_t threads[MAX_UE_INFO];
    for (int i = 0; i < num_crc_indications; i++) {
        int* index = malloc(sizeof(int));
        *index = i;
        pthread_create(&threads[i], NULL, processAndLogCRCIndications, index);
