    if (child_pid == -1) {
        perror("Failed to fork");
        return EXIT_FAILURE;
    } else if (child_pid == 0) {
        // Child process
        FILE *log_file = fopen("output.log", "w");
        if (!log_file) {
            perror("Failed to open log file");
            return EXIT_FAILURE;
        }

        process_records(records, num_keys);

        fclose(log_file);
        exit(EXIT_SUCCESS);
    } else {
        // Parent process
        int status;
        waitpid(child_pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == EXIT_SUCCESS) {
            printf("Child process completed successfully.\n");
        } else {
            printf("Child process failed.\n");
        }
    }

    return EXIT_SUCCESS;
