void logMessage(LoggerContext *logger, const char *format, ...) {
    va_list args;
    pthread_mutex_lock(&logger->log_mutex);
    vfprintf(logger->log_file, format, args);
    va_end(args);
    pthread_mutex_unlock(&logger->log_mutex);
    fflush(logger->log_file);
}

void processAndLogCRCIndications(NFAPI_CRC_INDICATION_PDU_T *crc_indications, int num_indications, LoggerContext *logger) {
    for (int i = 0; i < num_indications; ++i) {
        if (crc_indications[i].RNTI > 0 && crc_indications[i].CRC_INDICATION_REL8_TAG >= 0) {
            char log_message[256];
