#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CACHE_SIZE 1024

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data[MAX_CACHE_SIZE];
    int front, rear;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty, not_full;
} CRC_Cache;

CRC_Cache crc_cache;

void init_crc_cache() {
    crc_cache.front = crc_cache.rear = 0;
    pthread_mutex_init(&crc_cache.mutex, NULL);
    pthread_cond_init(&crc_cache.not_empty, NULL);
    pthread_cond_init(&crc_cache.not_full, NULL);
}

int is_crc_cache_full() {
    return (crc_cache.rear + 1) % MAX_CACHE_SIZE == crc_cache.front;
}

int is_crc_cache_empty() {
    return crc_cache.front == crc_cache.rear;
}

void enqueue(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&crc_cache.mutex);
    while (is_crc_cache_full()) {
        pthread_cond_wait(&crc_cache.not_full, &crc_cache.mutex);
    }
    crc_cache.data[crc_cache.rear] = data;
    crc_cache.rear = (crc_cache.rear + 1) % MAX_CACHE_SIZE;
    pthread_cond_signal(&crc_cache.not_empty);
    pthread_mutex_unlock(&crc_cache.mutex);
}

NFAPI_CRC_INDICATION_PDU_T dequeue() {
    NFAPI_CRC_INDICATION_PDU_T data;
    pthread_mutex_lock(&crc_cache.mutex);
    while (is_crc_cache_empty()) {
        pthread_cond_wait(&crc_cache.not_empty, &crc_cache.mutex);
    }
    data = crc_cache.data[crc_cache.front];
    crc_cache.front = (crc_cache.front + 1) % MAX_CACHE_SIZE;
    pthread_cond_signal(&crc_cache.not_full);
    pthread_mutex_unlock(&crc_cache.mutex);
    return data;
}

void* producer_thread(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (1) {
        // Simulate generating a random CRC_INDICATION_PDU
        pdu.rx_ue_information_tag = rand() % 1000;
        pdu.rnti = rand() % 1024;
        pdu.crc_indication_rel8_tag = rand() % 2;

        enqueue(pdu);
        printf("Produced: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
               pdu.rx_ue_information_tag, pdu.rnti, pdu.crc_indication_rel8_tag);

        // Simulate varying production rate
        sleep(rand() % 2);
    }
}

void* consumer_thread(void* arg) {
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu = dequeue();
        printf("Consumed: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
               pdu.rx_ue_information_tag, pdu.rnti, pdu.crc_indication_rel8_tag);

        // Simulate varying consumption rate
        sleep(rand() % 2);
    }
}

int main() {
    init_crc_cache();

    pthread_t producer, consumer;
    pthread_create(&producer, NULL, producer_thread, NULL);
    pthread_create(&consumer, NULL, consumer_thread, NULL);

    pthread_join(producer, NULL);
    pthread_join(consumer, NULL);

    return 0;
}
