using tcp = boost::asio::ip::tcp;       // from <boost/asio/ip/tcp.hpp>

// Define the encryption structure
struct NFAPI_CRC_INDICATION_PDU_T {
    std::string RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
