// Function to encrypt data using AES
void encryptData(const std::string& data, const std::string& key) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char*)key.c_str(), (unsigned char*)key.c_str());
    unsigned char ciphertext[128];
    int len;
    EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*)data.c_str(), data.size());
    int ciphertext_len = len;
    EVP_EncryptFinal_ex(ctx, ciphertext + len, &len);
    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx);
}

// Function to handle HTTP requests
void handleRequest(beast::http::request<beast::http::string_body>& req, beast::http::response<beast::http::string_body>& res) {
    if (req.method() == http::verb::get && req.target() == "/encrypt") {
        std::string data = req[http::field::content_type];
        std::string key = req[http::field::authorization];
        encryptData(data, key);
        res.result(http::status::ok);
        res.set(http::field::content_type, "application/json");
        res.body() = "{\"message\": \"Encryption successful\"}";
    } else {
        res.result(http::status::bad_request);
        res.set(http::field::content_type, "text/plain");
        res.body() = "Bad request";
    }
}

// Main function to run the encryption service
int main() {
    try {
        net::io_context ioc{1};
        tcp::acceptor acceptor{ioc, {tcp::v4(), 8080}};
        while (true) {
            beast::flat_buffer buffer;
            http::request<http::string_body> req;
            http::read(acceptor.accept(), buffer, req);
            beast::http::response<beast::http::string_body> res;
            handleRequest(req, res);
            http::write(acceptor.accept(), res);
        }
    } catch (std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
