type LoggingService interface {
	Log(ctx context.Context, source string, message string) error
}

type loggingService struct {
	logger log.Logger
	db     *gocql.Session
	metricCounter metrics.Counter
}

func NewLoggingService(logger log.Logger, db *gocql.Session, metricCounter metrics.Counter) LoggingService {
	return &loggingService{logger: logger, db: db, metricCounter: metricCounter}
}

func (s *loggingService) Log(ctx context.Context, source string, message string) error {
	s.metricCounter.With("source", source).Add(1)
	err := s.db.Query(`INSERT INTO logs(source, message) VALUES (?, ?)`, source, message).Exec()
	if err != nil {
		return err
	}
	return nil
}

func main() {
	cluster := gocql.NewCluster("localhost")
	cluster.Keyspace = "logsdb"
	db, err := cluster.CreateSession()
	if err != nil {
		log.Fatalf("Failed to create session: %v", err)
	}
	defer db.Close()

	logger := log.NewLogfmtLogger(os.Stdout)

	metricCounter := prometheus.NewCounterFrom(prometheus.CounterOpts{
		Name:    "log_count",
		Help:    "Number of logs ingested",
	}, []string{"source"})

	service := NewLoggingService(logger, db, metricCounter)

	httpServer := http.Server{
		Addr: ":8080",
		Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ctx := context.Background()
			source := r.URL.Query().Get("source")
			message := r.FormValue("message")
			if err := service.Log(ctx, source, message); err != nil {
				http.Error(w, fmt.Sprintf("Failed to log: %v", err), http.StatusInternalServerError)
				return
			}
			w.WriteHeader(http.StatusOK)
			fmt.Fprintf(w, "Log ingested successfully")
		}),
	}

	go func() {
		if err := httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Failed to start HTTP server: %v", err)
		}
	}()

	// Add more code to handle other components and features as per the requirements
}
