// C# Code Block - Distributed Fault-Tolerant Library Component

using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public record Record(long Offset, int Key, float Timestamp);

public class VersionedRecordManager : IDisposable
{
    private readonly ConcurrentDictionary<int, List<Record>> _recordStore = new();
    private readonly AsyncRetryPolicy _retryPolicy;
    private readonly ILogger _logger;

    public VersionedRecordManager(ILogger logger)
    {
        _retryPolicy = AsyncRetryPolicy.Default;
        _logger = logger;
    }

    public async Task AddRecordsAsync(int key, IEnumerable<Record> records)
    {
        await _retryPolicy.ExecuteAsync(async () =>
        {
            if (!_recordStore.TryGetValue(key, out var existingRecords))
            {
                existingRecords = new List<Record>();
                _recordStore[key] = existingRecords;
            }
            existingRecords.AddRange(records);
        });

        _logger.LogInformation($"Added {records.Count()} records for key {key}");
    }

    public async Task<IEnumerable<Record>> GetRecordsAsync(int key)
    {
        await _retryPolicy.ExecuteAsync(async () =>
        {
            if (!_recordStore.TryGetValue(key, out var records))
                return Enumerable.Empty<Record>();

            return records;
        });

        _logger.LogInformation($"Retrieved {records.Count()} records for key {key}");
        return records;
    }

    public void Dispose()
    {
        _recordStore.Clear();
        _retryPolicy.Dispose();
    }
}

// JavaScript Code Block - Asynchronous Generator for Reduce Operation

async function* reduceAsync(array, initialValue, reducer) {
    let accumulator = initialValue;

    for (const item of array) {
        accumulator = await reducer(accumulator, item);
        yield accumulator;
    }

    return accumulator;
}
