void initialize_system() {
    session_pool = (SessionPool *)malloc(sizeof(SessionPool));
    pthread_mutex_init(&session_pool->lock, NULL);
    memset(session_pool->states, 0, sizeof(session_pool->states));
    session_pool->session_count = 0;

    kv_store = (KeyValueStore *)malloc(sizeof(KeyValueStore));
    db = (RelationalDB *)malloc(sizeof(RelationalDB));
}

void finalize_system() {
    pthread_mutex_destroy(&session_pool->lock);
    free(session_pool);
    // Free other resources
}

int get_new_session_id() {
    pthread_mutex_lock(&session_pool->lock);
    if (session_pool->session_count < MAX_SESSIONS) {
        int id = session_pool->session_count++;
        memset(&session_pool->states[id], 0, sizeof(SessionState));
        return id;
    }
    pthread_mutex_unlock(&session_pool->lock);
    return -1; // No more sessions available
}

void release_session(int session_id) {
    pthread_mutex_lock(&session_pool->lock);
    if (session_id >= 0 && session_id < MAX_SESSIONS) {
        memset(&session_pool->states[session_id], 0, sizeof(SessionState));
        session_pool->session_count--;
    }
    pthread_mutex_unlock(&session_pool->lock);
}

void update_state(int session_id, const char *new_state) {
