#include <iostream>
#include <forward_list>
#include <string>

void insertAfter(std::forward_list<std::string>& fl, const std::string& target, const std::string& toInsert) {
    auto it = fl.begin();
    while (it != fl.end() && *it != target) {
        ++it;
    }
    if (it != fl.end()) {
        fl.insert_after(it, toInsert);
    } else {
        std::cerr << "Target string not found in forward list." << std::endl;
    }
}

int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    insertAfter(myList, "banana", "orange");

    for (const auto& item : myList) {
        std::cout << item << " ";
    }
    return 0;
}
