struct NetworkMetricPDU {
    int PID;
    std::chrono::time_point<std::chrono::system_clock> Timestamp;
    int ProtocolVersion;
    struct {
        double Throughput;
        double Latency;
        double PacketLossRate;
    } PIs;
};

class NetworkMetricsProcessor {
public:
    static void processNetworkMetrics(const std::vector<NetworkMetricPDU>& metrics) {
        // Thread-safe aggregation mechanism
        std::mutex mutex;
        for (const auto& metric : metrics) {
            std::lock_guard<std::mutex> lock(mutex);
            aggregateMetrics(metric);
        }
    }

private:
    static void aggregateMetrics(const NetworkMetricPDU& metric) {
        // Aggregate logic here
        std::cout << "Processing metric with PID: " << metric.PID << std::endl;
    }
};

int main() {
    std::vector<NetworkMetricPDU> metrics = generateRandomMetrics(10);
    NetworkMetricsProcessor::processNetworkMetrics(metrics);
    return 0;
}

std::vector<NetworkMetricPDU> generateRandomMetrics(int count) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> pidDist(1, 1000);
    std::uniform_int_distribution<> protocolDist(4, 6); // IPv4, IPv6
    std::uniform_real_distribution<double> piDist(0.0, 100.0);

    std::vector<NetworkMetricPDU> metrics;
    for (int i = 0; i < count; ++i) {
        NetworkMetricPDU metric;
        metric.PID = pidDist(gen);
        metric.Timestamp = std::chrono::system_clock::now();
        metric.ProtocolVersion = protocolDist(gen);
        metric.PIs.Throughput = piDist(gen);
        metric.PIs.Latency = piDist(gen);
        metric.PIs.PacketLossRate = piDist(gen) / 100.0; // Convert to percentage
        metrics.push_back(metric);
    }
    return metrics;
}
