// frame_stats.c
#include "frame_stats.h"
#include <stdlib.h>
#include <stdio.h>

void stats_manager_init(StatsManager *manager, size_t initial_capacity) {
    manager->stats_array = malloc(initial_capacity * sizeof(FrameStats));
    if (!manager->stats_array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void stats_manager_add_stats(StatsManager *manager, const FrameStats *new_stats) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= initial_capacity) {
        // Handle capacity increase
        fprintf(stderr, "Capacity exceeded\n");
    } else {
        manager->stats_array[manager->count++] = *new_stats;
    }
    pthread_mutex_unlock(&manager->lock);
}

void stats_manager_destroy(StatsManager *manager) {
    free(manager->stats_array);
    pthread_mutex_destroy(&manager->lock);
}
