class MessageQueueHandler {
private:
    std::queue<NFAPI_RX_FRAME_T> queue_;
    std::vector<std::thread> threads_;
    std::atomic<bool> running_{true};
    std::mutex mutex_;
    std::condition_variable cv_;

public:
    MessageQueueHandler(size_t numThreads) : threads_(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads_.emplace_back([this] { processMessages(); });
        }
    }

    ~MessageQueueHandler() {
        running_ = false;
        cv_.notify_all();
        for (auto& t : threads_) {
            t.join();
        }
    }

    void enqueue(const NFAPI_RX_FRAME_T& frame) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(frame);
        cv_.notify_one();
    }

private:
    void processMessages() {
        while (running_) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !queue_.empty() || !running_; });
            if (!running_ && queue_.empty()) break;

            NFAPI_RX_FRAME_T frame = queue_.front();
            queue_.pop();
            lock.unlock();

            processAndPersist(frame);
