```cpp
// SessionManager.cpp
#include "SessionManager.h"
#include "UserSession.h"

std::mutex SessionManager::mutex_;
std::unordered_map<std::string, UserSession*> SessionManager::sessions_;
std::atomic<bool> SessionManager::running_(true);

SessionManager& SessionManager::getInstance() {
    static SessionManager instance;
    return instance;
}

bool SessionManager::createSession(const std::string& userId) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (sessions_.find(userId) == sessions_.end()) {
        sessions_[userId] = new UserSession(userId);
        return true;
    }
    return false;
}

void SessionManager::validateSessions() {
    while (running_) {
        std::this_thread::sleep_for(std::chrono::minutes(1));
        validateAndRemoveExpiredSessions();
    }
}

void SessionManager::removeExpiredSessions() {
    std::lock_guard<std::mutex> lock(mutex_);
    auto now = std::chrono::steady_clock::now();
    for (auto it = sessions_.begin(); it != sessions_.end(); ) {
        if (!it->second->validate()) {
            delete it->second;
            it = sessions_.erase(it);
        } else {
            ++it;
        }
    }
}

void SessionManager::sessionCleanupTask() {
    while (running_) {
        validateSessions();
    }
}
