UserSession::UserSession(const std::string& userId) : userId_(userId), lastActivityTime_(std::chrono::steady_clock::now()) {}

UserSession::~UserSession() {}

bool UserSession::validate() const {
    auto now = std::chrono::steady_clock::now();
    return (now - lastActivityTime_) < std::chrono::hours(1);
}

void UserSession::invalidate() {
    delete this;
}

void UserSession::renew() {
    lastActivityTime_ = std::chrono::steady_clock::now();
}
