typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **pool;
    size_t used;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} NFAPI_CRC_INDICATION_POOL_T;

NFAPI_CRC_INDICATION_POOL_T *create_pool(size_t capacity) {
    NFAPI_CRC_INDICATION_POOL_T *pool = (NFAPI_CRC_INDICATION_POOL_T *)malloc(sizeof(NFAPI_CRC_INDICATION_POOL_T));
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T **)calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->not_full, NULL);
    pthread_cond_init(&pool->not_empty, NULL);
    return pool;
}

void destroy_pool(NFAPI_CRC_INDICATION_POOL_T *pool) {
    for (size_t i = 0; i < pool->used; ++i) {
        free(pool->pool[i]->crc_indication);
        free(pool->pool[i]);
    }
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->not_full);
    pthread_cond_destroy(&pool->not_empty);
    free(pool);
}

int allocate_pdu(NFAPI_CRC_INDICATION_POOL_T *pool) {
    pthread_mutex_lock(&pool->lock);
    while (pool->used == MAX_ALLOCATION) {
        pthread_cond_wait(&pool->not_full, &pool->lock);
    }
    if (pool->used >= MAX_ALLOCATION) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Allocation failed
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_pdu->crc_indication = (CRC_INDICATION_REL8_TAG *)malloc(sizeof(CRC_INDICATION_REL8_TAG));
    new_pdu->crc_indication->CRCFLAG = rand() % 2; // Randomly set CRC flag
    // Fetch RX_UE_INFORMATION_TAG and RNTI from external data source with retry logic
    pool->pool[pool->used++] = new_pdu;
    pthread_cond_signal(&pool->not_empty);
    pthread_mutex_unlock(&pool->lock);
    return 0; // Allocation successful
}

void free_pdu(NFAPI_CRC_INDICATION_POOL_T *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->used; ++i) {
        if (pool->pool[i] == pdu) {
            free(pool->pool[i]->crc_indication);
            free(pool->pool[i]);
            pool->pool[i] = pool->pool[--pool->used];
            break;
        }
    }
    pthread_cond_signal(&pool->not_full);
    pthread_mutex_unlock(&pool->lock);
}
