#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_ALLOCATION 1024
#define N 50

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pool[MAX_ALLOCATION];
int pool_size = 0;
pthread_mutex_t pool_lock;

void initialize_pool() {
    pthread_mutex_init(&pool_lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    int attempt = 0;

    while (attempt < 10) {
        pthread_mutex_lock(&pool_lock);
        if (pool_size > 0) {
            pdu = pool[--pool_size];
            pthread_mutex_unlock(&pool_lock);
            break;
        }
        pthread_mutex_unlock(&pool_lock);
        usleep(1 << attempt); // Exponential backoff
        attempt++;
    }

    if (!pdu) {
        return NULL; // Allocation failed after retries
    }

    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 500;
    pdu->CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 1 : 0;

    return pdu;
}

void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool_lock);
    if (pool_size < MAX_ALLOCATION) {
        pool[pool_size++] = pdu;
    }
    pthread_mutex_unlock(&pool_lock);
}

void *monitor_and_reclaim() {
    while (1) {
        sleep(60); // Reclaim every minute
        pthread_mutex_lock(&pool_lock);
        if (pool_size < MAX_ALLOCATION / 2) { // Threshold for reclamation
            int reclaim_count = 0;
            for (int i = pool_size - 1; i >= 0 && reclaim_count < pool_size / 2; i--) {
                free(pool[i]);
                pool[i] = NULL;
                reclaim_count++;
            }
            pool_size -= reclaim_count;
        }
        pthread_mutex_unlock(&pool_lock);
    }
}

int main() {
    initialize_pool();

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_structure();
        if (pdu) {
            // Use the pdu here
            deallocate_structure(pdu);
        }
    }

    pthread_t reclaim_thread;
    pthread_create(&reclaim_thread, NULL, monitor_and_reclaim, NULL);

    // Join the reclaim thread to wait for it to finish (if needed)
    pthread_join(reclaim_thread, NULL);

    return 0;
}
