int tail = 0;
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_not_full = PTHREAD_COND_INITIALIZER;
pthread_cond_t queue_not_empty = PTHREAD_COND_INITIALIZER;

// Function to add an NFAPI_CRC_INDICATION_PDU_T structure to the buffer
void enqueue(NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&queue_mutex);
    while ((tail + 1) % BUFFER_SIZE == head) {
        pthread_cond_wait(&queue_not_full, &queue_mutex);
    }
    buffer[tail] = *item;
    tail = (tail + 1) % BUFFER_SIZE;
    pthread_cond_signal(&queue_not_empty);
    pthread_mutex_unlock(&queue_mutex);
}

// Function to remove an NFAPI_CRC_INDICATION_PDU_T structure from the buffer
