    NFAPI_CRC_INDICATION_PDU_T item;
    pthread_mutex_lock(&queue_mutex);
    while (head == tail) {
        pthread_cond_wait(&queue_not_empty, &queue_mutex);
    }
    item = buffer[head];
    head = (head + 1) % BUFFER_SIZE;
    pthread_cond_signal(&queue_not_full);
    pthread_mutex_unlock(&queue_mutex);
