// This is a high-level skeleton of a scalable C++ application for real-time sensor data processing
#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>

class SensorDataProcessor {
public:
    void start() {
        // Start data ingestion and processing threads
        ingestionThread = std::thread(&SensorDataProcessor::ingestData, this);
        processingThread = std::thread(&SensorDataProcessor::processData, this);
    }

    void stop() {
        // Stop data ingestion and processing gracefully
        running.store(false);
        ingestionCondition.notify_all();
        processingCondition.notify_all();
        if (ingestionThread.joinable()) ingestionThread.join();
        if (processingThread.joinable()) processingThread.join();
    }

private:
    std::thread ingestionThread;
    std::thread processingThread;
    std::queue<std::vector<uint8_t>> dataQueue;
    std::mutex queueMutex;
    std::condition_variable ingestionCondition;
    std::atomic<bool> running{true};

