            // Simulate data ingestion from sensors
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            std::vector<uint8_t> newData = generateSensorData();
            std::lock_guard<std::mutex> lock(queueMutex);
            dataQueue.push(newData);
            ingestionCondition.notify_one();
        }
    }

    void processData() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            ingestionCondition.wait(lock, [this]{ return !dataQueue.empty(); });
            std::vector<uint8_t> data = dataQueue.front();
            dataQueue.pop();
            lock.unlock();

            // Process the data
            processSensorData(data);
        }
    }

    std::vector<uint8_t> generateSensorData() {
        // Placeholder for actual sensor data generation logic
