// UserSession.cpp
#include "UserSession.h"

UserSession::UserSession(const std::string& userId, int sessionId)
    : userId_(userId), sessionId_(sessionId) {
    extendSession(30); // Default session expiration time
}

UserSession::~UserSession() {}

bool UserSession::isExpired() const {
    return std::chrono::system_clock::now() > expirationTime_;
}

void UserSession::extendSession(int minutes) {
    expirationTime_ = std::chrono::system_clock::now() + std::chrono::minutes(minutes);
}
