```cpp
// SessionManager.cpp
#include "SessionManager.h"

UserSession* SessionManager::createUserSession(const std::string& userId, int sessionId) {
    auto session = new UserSession(userId, sessionId);
    sessions_[sessionId] = session;
    return session;
}

bool SessionManager::validateSession(int sessionId) const {
    if (sessions_.find(sessionId) != sessions_.end()) {
        return !sessions_[sessionId]->isExpired();
    }
    return false;
}

void SessionManager::removeExpiredSessions() {
    auto now = std::chrono::system_clock::now();
    for (auto it = sessions_.begin(); it != sessions_.end(); ) {
        if (it->second->isExpired()) {
            delete it->second;
            it = sessions_.erase(it);
        } else {
            ++it;
        }
    }
}
```

