package main

import (
	"context"
	"crypto/rand"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"time"

	"github.com/gorilla/mux"
	"k8s.io/client-go/kubernetes"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

type CRC_INDICATION struct {
	RX_UE_INFORMATION_TAG string `json:"rx_ue_information_tag"`
	RNTI                   int    `json:"rnti"`
	CRC_INDICATION_TAG      string `json:"crc_indication_tag"`
	CRCFLAG                bool   `json:"crcflag"`
}

func generateCRCIndications(indications []CRC_INDICATION) ([]CRC_INDICATION, error) {
	for i := range indications {
		randomFlag := rand.Intn(2)
		indications[i].CRCFLAG = randomFlag == 1
	}
	return indications, nil
}

func main() {
	r := mux.NewRouter()

	r.HandleFunc("/api/crc-indications", func(w http.ResponseWriter, r *http.Request) {
		var indications []CRC_INDICATION
		err := json.NewDecoder(r.Body).Decode(&indications)
		if err != nil {
			http.Error(w, "Invalid request body", http.StatusBadRequest)
			return
		}

		newIndications, err := generateCRCIndications(indications)
		if err != nil {
			http.Error(w, "Failed to generate CRC indications", http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(newIndications)
	})

	clientset, err := kubernetes.NewForConfig(context.Background(), &rest.Config{})
	if err != nil {
		fmt.Println("Failed to create Kubernetes client:", err)
		return
	}

	route := r.Path("/api/routes").Methods("POST")
	route.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var routeData struct {
			Name       string `json:"name"`
			Target     string `json:"target"`
			Region     string `json:"region"`
			AuthMethod string `json:"auth_method"`
		}

		err := json.NewDecoder(r.Body).Decode(&routeData)
		if err != nil {
			http.Error(w, "Invalid request body", http.StatusBadRequest)
			return
		}

		_, err = clientset.CoreV1().Services(routeData.Region).Get(context.Background(), routeData.Name, metav1.GetOptions{})
		if err != nil {
			http.Error(w, "Service not found in specified region", http.StatusNotFound)
			return
		}

		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(map[string]string{"message": "Route created successfully"})
	})

	server := &http.Server{
		Addr:    ":8080",
		Handler: r,
	}

	fmt.Println("Starting server on :8080")
	if err := server.ListenAndServe(); err != nil {
		fmt.Println("Server failed to start:", err)
	}
}
```']

