public class DynamicEventProcessor
{
    private readonly IMongoClient _mongoClient;
    private readonly IConnectionMultiplexer _redis;
    private readonly IModel _channel;
    private readonly EventQueue _eventQueue;

    public DynamicEventProcessor(string mongoConnectionString, string redisConnectionString)
    {
        _mongoClient = new MongoClient(mongoConnectionString);
        _redis = ConnectionMultiplexer.Connect(redisConnectionString);
        var factory = new ConnectionFactory { HostName = "localhost" };
        _channel = factory.CreateConnection().CreateModel();
        _eventQueue = new EventQueue(_channel);
    }

    public async Task ProcessEventsAsync(List<Event> events)
    {
        foreach (var event in events)
        {
            await _eventQueue.EnqueueEventAsync(event);
        }
    }

    private class EventQueue
    {
        private readonly IModel _channel;
        private const string QueueName = "events";

        public EventQueue(IModel channel)
        {
            _channel = channel;
            _channel.QueueDeclare(QueueName, true, false, false, null);
        }

        public async Task EnqueueEventAsync(Event @event)
        {
            var body = JsonConvert.SerializeObject(@event);
            await _channel.BasicPublishAsync("", QueueName, null, Encoding.UTF8.GetBytes(body));
        }
    }
}

public class Event
{
    public string Id { get; set; }
    public object Data { get; set; }
