typedef struct {
    record* records;
    size_t capacity;
    size_t size;
} dynamic_collection;

dynamic_collection* create_dynamic_collection(size_t initial_capacity) {
    dynamic_collection* collection = malloc(sizeof(dynamic_collection));
    if (!collection) return NULL;
    collection->records = malloc(initial_capacity * sizeof(record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->size = 0;
    return collection;
}

void destroy_dynamic_collection(dynamic_collection* collection) {
    free(collection->records);
    free(collection);
}

int add_record(dynamic_collection* collection, record new_record) {
    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        record* new_records = realloc(collection->records, new_capacity * sizeof(record));
        if (!new_records) return -1;
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    collection->records[collection->size++] = new_record;
    return 0;
}

