#include <iostream>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <string>
#include <chrono>
#include <memory>

class Message {
public:
    std::string payload;
    std::chrono::system_clock::time_point timestamp;
    int priority;

    Message(std::string p, std::chrono::system_clock::time_point ts, int pr)
        : payload(p), timestamp(ts), priority(pr) {}
};

class MessageQueue {
private:
    std::queue<std::shared_ptr<Message>> queue_;
    mutable std::mutex mutex_;
    std::condition_variable cond_var_;

public:
    void push(const std::shared_ptr<Message>& message) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(message);
        cond_var_.notify_one();
    }

    std::shared_ptr<Message> pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        cond_var_.wait(lock, [this] { return !queue_.empty(); });
        auto message = queue_.front();
        queue_.pop();
        return message;
    }
};

class MessageProcessor {
private:
    MessageQueue& queue_;
    std::thread worker_thread_;

public:
    MessageProcessor(MessageQueue& q)
        : queue_(q) {
        worker_thread_ = std::thread(&MessageProcessor::process, this);
    }

    ~MessageProcessor() {
        worker_thread_.join();
    }

    void process() {
        while (true) {
            auto message = queue_.pop();
            // Process the message
            std::cout << "Processing message: " << message->payload << std::endl;
        }
    }
};

int main() {
    MessageQueue message_queue;
    MessageProcessor processor(message_queue);

    // Simulate adding messages to the queue
    for (int i = 0; i < 10; ++i) {
        auto timestamp = std::chrono::system_clock::now();
        auto message = std::make_shared<Message>("Message " + std::to_string(i), timestamp, i);
        message_queue.push(message);
    }

    return 0;
}
