```python
import json

class JsonParser:
    _registry = {}

    @classmethod
    def add_factory(cls, factory_id, factory_func):
        cls._registry[factory_id] = factory_func

    @classmethod
    def create_instance(cls, data):
        factory_id = data.get('type')
        if factory_id in cls._registry:
            return cls._registry[factory_id](data)
        else:
            raise ValueError(f"Unknown type: {factory_id}")

    def __init__(self, data):
        self.data = data

    def to_json(self):
        return json.dumps(self.data)

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        return cls(data)

# Example usage
class Person(JsonParser):
    @classmethod
    def create_instance(cls, data):
        if data.get('type') == 'Person':
            return super().create_instance(data)
        else:
            raise ValueError("Invalid type")

JsonParser.add_factory('Person', Person.create_instance)

person_data = {"type": "Person", "name": "John", "age": 30}
person_json = person_data.to_json()
new_person = JsonParser.from_json(person_json)
