using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

public record struct VersionedRecord(long Offset, int Key, float Timestamp);

public interface IDistributedVersionedCollection
{
    Task Add(VersionedRecord record);
    Task<List<VersionedRecord>> GetAll();
}

public class DistributedVersionedCollection : IDistributedVersionedCollection
{
    private readonly HttpClient _httpClient;
    private readonly string _apiUrl;

    public DistributedVersionedCollection(HttpClient httpClient, string apiUrl)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _apiUrl = apiUrl ?? throw new ArgumentNullException(nameof(apiUrl));
    }

    public async Task Add(VersionedRecord record)
    {
        var response = await ExecuteAsync(() => _httpClient.PostAsJsonAsync(_apiUrl, record), "Add");
        if (!response.IsSuccessStatusCode)
            throw new InvalidOperationException($"Failed to add record: {await response.Content.ReadAsStringAsync()}");
    }

    public async Task<List<VersionedRecord>> GetAll()
    {
        var response = await ExecuteAsync(() => _httpClient.GetAsync(_apiUrl), "GetAll");
        if (!response.IsSuccessStatusCode)
            throw new InvalidOperationException($"Failed to get all records: {await response.Content.ReadAsStringAsync()}");

        return (await response.Content.ReadAsAsync<IEnumerable<VersionedRecord>>()).ToList();
    }

    private async Task<HttpResponseMessage> ExecuteAsync(Func<Task<HttpResponseMessage>> action, string operation)
    {
        var retryCount = 0;
        while (true)
        {
            try
            {
                return await action();
            }
            catch (HttpRequestException ex) when (ex.InnerException is TimeoutException)
            {
                if (++retryCount >= 5) throw;
                await Task.Delay((int)Math.Pow(2, retryCount) * 100); // Exponential backoff
            }
        }
    }
}
