#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <uuid/uuid.h>

typedef struct {
    uuid_t device_id;
    int connected;
    struct RecentTraffic {
        time_t timestamp;
        size_t data_size;
    } recent_traffic[10];
    char last_error[256];
} DeviceState;

typedef struct {
    DeviceState* states;
    size_t count;
    pthread_mutex_t lock;
} DeviceManager;

DeviceManager* device_manager_init(size_t initial_capacity) {
    DeviceManager* manager = (DeviceManager*)malloc(sizeof(DeviceManager));
    if (!manager) return NULL;

    manager->states = (DeviceState*)calloc(initial_capacity, sizeof(DeviceState));
    if (!manager->states) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void device_manager_add_device(DeviceManager* manager, DeviceState* state) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= initial_capacity) {
        // Handle capacity overflow
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    manager->states[manager->count++] = *state;
    pthread_mutex_unlock(&manager->lock);
}

void device_manager_update_device(DeviceManager* manager, uuid_t device_id, int new_status) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (memcmp(manager->states[i].device_id, device_id, sizeof(uuid_t)) == 0) {
            manager->states[i].connected = new_status;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void device_manager_cleanup_old_traffic(DeviceManager* manager, time_t threshold) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        for (int j = 0; j < 10; ++j) {
            if (manager->states[i].recent_traffic[j].timestamp < threshold) {
                memset(&manager->states[i].recent_traffic[j], 0, sizeof(manager->states[i].recent_traffic[j]));
            }
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void device_manager_free(DeviceManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->states);
    free(manager);
}
