        size_t size;
    };

    using Callback = std::function<void(const std::string&)>;

    FileStorageManager(std::string apiEndpoint, int maxConnections)
        : apiEndpoint(apiEndpoint), maxConnections(maxConnections) {}

    void readFileAsync(const std::string& filePath, Callback callback) {
        auto task = [this, filePath, callback]() {
            try {
                std::ifstream file(filePath);
                if (!file.is_open()) {
                    throw std::runtime_error("Failed to open file: " + filePath);
                }
                std::string content((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
                callback(content);
            } catch (const std::exception& e) {
                std::cerr << "Error reading file: " << e.what() << std::endl;
                callback("");
            }
        };
        queue.push(task);
        cv.notify_one();
    }

    void writeFileAsync(const std::string& filePath, const std::string& content, Callback callback) {
        auto task = [this, filePath, content, callback]() {
            try {
                std::ofstream file(filePath);
                if (!file.is_open()) {
                    throw std::runtime_error("Failed to open file for writing: " + filePath);
                }
                file << content;
                callback("");
            } catch (const std::exception& e) {
                std::cerr << "Error writing file: " << e.what() << std::endl;
                callback("");
            }
        };
        queue.push(task);
        cv.notify_one();
    }

    void start() {
        for (int i = 0; i < maxConnections; ++i) {
            workers.emplace_back([this]() {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(mutex);
                        cv.wait(lock, [this] { return !queue.empty(); });
                        task = queue.front();
                        queue.pop();
                    }
                    task();
                }
            });
        }
    }

private:
    std::string apiEndpoint;
    int maxConnections;
    std::queue<std::function<void()>> queue;
    std::vector<std::thread> workers;
    std::mutex mutex;
    std::condition_variable cv;
};
