// Forward declarations
class FileStorageManager;
class AsyncIOHandler;

// Interface for file operations
class IFileOperation {
public:
    virtual ~IFileOperation() = default;
    virtual std::string Execute(const std::string& filePath) = 0;
};

// Implementation of plain text read operation
class PlainTextRead : public IFileOperation {
public:
    std::string Execute(const std::string& filePath) override {
        // Implement file reading logic here
        return "PlainTextContent";
    }
};

// Implementation of JSON read operation
class JSONRead : public IFileOperation {
public:
    std::string Execute(const std::string& filePath) override {
        // Implement JSON parsing logic here
        return "JSONContent";
    }
};

// Implementation of CSV read operation
class CSVRead : public IFileOperation {
public:
    std::string Execute(const std::string& filePath) override {
        // Implement CSV parsing logic here
        return "CSVContent";
    }
};

// Factory to create file operations based on file type
class FileOperationFactory {
public:
    static std::unique_ptr<IFileOperation> CreateOperation(const std::string& fileType) {
        if (fileType == "plain") return std::make_unique<PlainTextRead>();
        else if (fileType == "json") return std::make_unique<JSONRead>();
        else if (fileType == "csv") return std::make_unique<CSVRead>();
        else throw std::invalid_argument("Unsupported file type");
    }
};

// Asynchronous IO handler
class AsyncIOHandler {
public:
    void AddOperation(const std::string& filePath, const std::string& fileType) {
        auto operation = FileOperationFactory::CreateOperation(fileType);
        operations.emplace(filePath, std::move(operation));
    }

    std::future<std::string> ExecuteOperations() {
        return std::async(std::launch::async, [this]() mutable -> std::string {
            std::string results;
            for (auto& [filePath, operation] : operations) {
                results += "Result for " + filePath + ": " + operation->Execute(filePath) + "\n";
            }
            operations.clear();
            return results;
        });
    }

private:
    std::unordered_map<std::string, std::unique_ptr<IFileOperation>> operations;
};

// File storage manager class
class FileStorageManager {
public:
    void AddReadRequest(const std::string& filePath, const std::string& fileType) {
        ioHandler.AddOperation(filePath, fileType);
    }

    std::future<std::string> ProcessRequests() {
        return ioHandler.ExecuteOperations();
    }

private:
    AsyncIOHandler ioHandler;
};

// Example usage
int main() {
    FileStorageManager manager;
    manager.AddReadRequest("example.txt", "plain");
    manager.AddReadRequest("data.json", "json");
    manager.AddReadRequest("info.csv", "csv");

    auto results = manager.ProcessRequests().get();
    std::cout << results;

    return 0;
}
```

