// Function to fetch metadata from external REST API
int fetchMetadata(Record* record) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if(curl) {
        // Set up the request URL with placeholders for offset and key
        char url[256];
        sprintf(url, "http://api.example.com/metadata?offset=%ld&key=%d", record->offset, record->key);

        // Perform the request
        curl_easy_setopt(curl, CURLOPT_URL, url);
        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return -1;
        }

        curl_easy_cleanup(curl);
    }

    // Simulate metadata fetching
    record->id = (char*)malloc(256 * sizeof(char));
    sprintf(record->id, "ID_%ld_%d", record->offset, record->key);

    return 0;
}

// Function to process records
int processRecords(Record* records, size_t numRecords) {
    for(size_t i = 0; i < numRecords; i++) {
        if(fetchMetadata(&records[i]) != 0) {
            fprintf(stderr, "Failed to fetch metadata for record %zu\n", i);
            // Handle error (e.g., free allocated memory)
            return -1;
        }
    }

    // Sort records by key
    qsort(records, numRecords, sizeof(Record), compareRecords);

    return 0;
}

// Comparator function for qsort
int compareRecords(const void* a, const void* b) {
    Record* recordA = (Record*)a;
    Record* recordB = (Record*)b;
    if(recordA->key < recordB->key) return -1;
    if(recordA->key > recordB->key) return 1;
    return 0;
}

// Function to clean up allocated memory
void cleanupRecords(Record* records, size_t numRecords) {
    for(size_t i = 0; i < numRecords; i++) {
        free(records[i].id);
    }
    free(records);
}

int main() {
    Record* records = (Record*)malloc(10 * sizeof(Record));
    // Initialize records with offsets and keys

    size_t numRecords = 10;

    if(processRecords(records, numRecords) == 0) {
        for(size_t i = 0; i < numRecords; i++) {
            printf("Offset: %ld, Key: %d, ID: %s\n", records[i].offset, records[i].key, records[i].id);
        }
    } else {
        fprintf(stderr, "Failed to process records.\n");
    }

    cleanupRecords(records, numRecords);

    return 0;
}
