        fprintf(stderr, "Failed to fetch and process data.\n");
        return 1;
    }

    void *data = allocate_memory(1024 * 1024, &config);  // Allocate memory
    if (data == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    // Use the allocated memory for data processing

    free_memory(data, &config);  // Free memory and perform garbage collection

    printf("Data processed successfully.\n");

    return 0;
}
