MemoryPool* init_memory_pool(size_t size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->size = size;
    pool->records = (Record*)calloc(size, sizeof(Record));
    if (!pool->records) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Function to release the memory pool
void release_memory_pool(MemoryPool *pool) {
    if (pool && pool->records) {
        free(pool->records);
    }
    free(pool);
}

// Function to add a record to the memory pool
bool add_record_to_pool(MemoryPool *pool, Record *record) {
    for (size_t i = 0; i < pool->size; ++i) {
        if (!pool->records[i].key && !pool->records[i].offset) {
            pool->records[i] = *record;
            return true;
        }
    }
    return false;
}

// Function to process the memory pool
void* process_memory_pool(void *arg) {
    MemoryPool *pool = (MemoryPool*)arg;
    Record current_record;
    for (size_t i = 0; i < pool->size; ++i) {
