#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <chrono>
#include <mutex>
#include <atomic>
#include <thread>
#include <condition_variable>

struct Location {
    double latitude;
    double longitude;
};

struct Sensor {
    double value;
    std::string label;
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    Location location;
};

class SensorManager {
public:
    void addSensor(const Sensor& sensor) {
        std::lock_guard<std::mutex> lock(mutex_);
        sensors_.push_back(sensor);
    }

    void loadFromBinaryFile(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file: " + filename);
        }

        while (true) {
            Sensor sensor;
            if (!readSensorFromStream(file, sensor)) {
                break;
            }
            addSensor(sensor);
        }
    }

    void processSensors() {
        for (auto& sensor : sensors_) {
            // Process each sensor
            std::cout << "Processing sensor: " << sensor.label << std::endl;
        }
    }

private:
    std::vector<Sensor> sensors_;
    std::mutex mutex_;

    bool readSensorFromStream(std::ifstream& file, Sensor& sensor) {
        // Read sensor data from binary stream
        if (file.read(reinterpret_cast<char*>(&sensor.value), sizeof(double)).gcount() != sizeof(double)) return false;
        if (!std::getline(file, sensor.label)) return false;

        char timestamp_buffer[sizeof(sensor.timestamp)];
        if (file.read(timestamp_buffer, sizeof(timestamp_buffer)).gcount() != sizeof(timestamp_buffer)) return false;
        std::memcpy(&sensor.timestamp, timestamp_buffer, sizeof(sensor.timestamp));

        if (file.read(reinterpret_cast<char*>(&sensor.location.latitude), sizeof(double)).gcount() != sizeof(double)) return false;
        if (file.read(reinterpret_cast<char*>(&sensor.location.longitude), sizeof(double)).gcount() != sizeof(double)) return false;

        return true;
    }
};

int main() {
    SensorManager manager;
    try {
        manager.loadFromBinaryFile("sensor_log.bin");
        manager.processSensors();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
