#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <future>
#include <chrono>
#include <atomic>

class DataStoragePlatform {
public:
    void write(const std::string& data, const std::string& format) {
        std::lock_guard<std::mutex> lock(mutex);
        write_queue.push({data, format});
        condition.notify_one();
    }

    void read(const std::string& id, std::future<std::string>& result) {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return !read_queue.empty(); });
        auto data = read_queue.front();
        read_queue.pop();
        lock.unlock();
        // Simulate async operation
        std::async(std::launch::async, [&data](std::future<std::string>& result) {
            // Process the data and return the result
            result.set_value(data);
        }, std::ref(result));
    }

private:
    struct Data {
        std::string data;
        std::string format;
    };

    std::mutex mutex;
    std::condition_variable condition;
    std::queue<Data> write_queue;
    std::queue<std::pair<std::string, std::future<std::string>>> read_queue;
};
```

