    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CRC_Queue;

CRC_Queue *crc_queue_create() {
    CRC_Queue *queue = (CRC_Queue *)malloc(sizeof(CRC_Queue));
    if (!queue) return NULL;

    queue->count = 0;
    if (pthread_mutex_init(&queue->lock, NULL) != 0 ||
        pthread_cond_init(&queue->not_full, NULL) != 0 ||
        pthread_cond_init(&queue->not_empty, NULL) != 0) {
        free(queue);
        return NULL;
    }

    return queue;
}

void crc_queue_destroy(CRC_Queue *queue) {
    if (queue) {
        pthread_mutex_destroy(&queue->lock);
        pthread_cond_destroy(&queue->not_full);
        pthread_cond_destroy(&queue->not_empty);
        free(queue);
    }
}

bool crc_queue_enqueue(CRC_Queue *queue, NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (!queue || !entry) return false;

    pthread_mutex_lock(&queue->lock);
    while (queue->count == MAX_ENTRIES)
        pthread_cond_wait(&queue->not_full, &queue->lock);

    queue->entries[queue->count++] = *entry;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);

    return true;
}

bool crc_queue_dequeue(CRC_Queue *queue, NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (!queue || !entry) return false;

    pthread_mutex_lock(&queue->lock);
    while (queue->count == 0)
        pthread_cond_wait(&queue->not_empty, &queue->lock);

    *entry = queue->entries[--queue->count];
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);

    return true;
}

